import { sp, tween, UIOpacity, UITransform, Vec3, type Node, type Tween } from 'cc';
import type { GameViewAdapter } from './GameViewAdapter';
import { tryClearAnimation, trySetAnimation } from '../utils/SpineSafe';

/**
 * 罩在某一軸上的 `slowmotion` 聽牌框（機台 `Layer_Mi` 底下的 spine，`SlotMachineView.miSkel`），兩種情況會用到：
 *
 * - **免費遊戲的瞇牌**：每一局照轉輪節奏的時間點蓋上（`MiGoldIntro.startMiGoldConversion()`），第一軸準備停輪時
 *   淡出收掉（`CascadeReelsTask.clearFocusWhenFirstReelStops()`）。
 * - **聽牌**（只有主遊戲）：已落定的 Scatter 只差一顆就觸發時，罩在正在聽牌的那一軸，前一軸落定就移到下一軸、最後一軸
 *   落定時收掉（見 `tasks/TenpaiPlan.ts` 與 `CascadeReelsTask.runCascadeReels()`）。
 *
 * 兩者共用同一個節點：聽牌經過第三軸時直接接手，畫面上不會疊兩個框，也不會被「第三軸停了就收掉」關掉。
 * 罩在哪一軸由程式決定——prefab 上擺在第三軸，罩到別軸時只跟著那一軸左右移動，y 與縮放都維持 prefab 的值。
 * 最右軸雖然少一列，框也不縮（2026-10-20 前會依軸高比例縮成 0.8）。
 *
 * 罩上時那一軸會搬進 `Layer_Mi`、其他軸壓黑，那一段由呼叫端處理（`CascadeReelsTask.focusReel()`），
 * 這支只管框本身。框一直留在 `Layer_Mi`，不換父節點：跟聚焦的那一軸同一層、排在它前面，所以畫在那一軸之下，
 * 整層又在外框之下，層級見 `SlotMachineView` 的類別說明（2026-11-03 前是掛在 `GameViewH/MiNode`、執行時搬進
 * `Layer_Mi` 最上面；11-03～11-05 在 `Layer_Spine`）。
 *
 * 動畫以 loop 播放、軸一停就收掉或移走，所以它本來就會在中途被切斷——`slowmotion/animation` 是 2 秒。
 * 那是期待感特效的常態，不是漏了收尾。
 *
 * 框在機台 prefab 裡，橫直兩台都有。「每一個 view 都沒接」是漏接，那種情況會印一次警告——不印的話畫面上
 * 只是沒反應，跟 spine 沒載到、節點被別的東西蓋住完全分不出來。
 */

/** `slowmotion` 骨架唯一的動畫名 */
const MI_ANIM = 'animation';

/** prefab 上聽牌框對齊的那一軸（0 起算）；罩到別軸時照它相對這一軸的水平位移換算 */
const PREFAB_REEL_INDEX = 2;

/** 漏接警告只印一次：這支掛在每一局輪轉上，每局印一次會把 console 洗掉 */
let warnedMissing = false;

/** 聽牌框在 prefab 上相對 {@link PREFAB_REEL_INDEX} 那一軸的擺法，用父節點的區域座標記，view 縮放後照樣成立 */
interface MiLayout {
    /** 相對那一軸中心的水平位移 */
    readonly offsetX: number;
}

/** 每個聽牌框節點第一次用到時記下的 prefab 擺法 */
const layouts = new WeakMap<Node, MiLayout>();

/** 每個聽牌框節點目前罩在第幾軸；收掉時清掉 */
const shownReel = new WeakMap<Node, number>();

/** 正在淡出的聽牌框與它的淡出補間；淡完或被重新蓋上時清掉 */
const fading = new WeakMap<Node, Tween<UIOpacity>>();

/**
 * 取這個 view 的聽牌框 spine（機台的 `SlotMachineView.miSkel`）。
 *
 * @param view 要查的 view。
 * @returns 骨架；沒接或節點已銷毀時回 null。
 */
function miSkelOf(view: GameViewAdapter): sp.Skeleton | null {
    const skel = view.slotMachineView?.miSkel ?? null;
    return skel?.isValid && skel.node.isValid ? skel : null;
}

/**
 * 某一軸的中心換算成聽牌框父節點的區域座標。
 *
 * @param node 聽牌框節點。
 * @param reelNode 那一軸的節點。
 * @returns 區域座標；聽牌框沒有父節點或父節點沒有 UITransform 時為 null。
 */
function reelCenterInParent(node: Node, reelNode: Node): Vec3 | null {
    const parent = node.parent?.getComponent(UITransform);
    return parent ? parent.convertToNodeSpaceAR(reelNode.worldPosition, new Vec3()) : null;
}

/**
 * 取聽牌框的 prefab 擺法，第一次呼叫時從節點目前的位置記下來。
 *
 * 必須在聽牌框還沒被搬動之前第一次呼叫——{@link showMiEffect} 每次都會先呼叫，第一次一定是在 prefab 原位。
 *
 * @param view 聽牌框所在的 view。
 * @param node 聽牌框節點。
 * @returns 擺法；那一軸找不到時為 null。
 */
function layoutOf(view: GameViewAdapter, node: Node): MiLayout | null {
    const cached = layouts.get(node);
    if (cached) return cached;

    const reel = view.slotMachineView?.reelViews[PREFAB_REEL_INDEX];
    const center = reel && reelCenterInParent(node, reel.node);
    if (!reel || !center) return null;

    const layout: MiLayout = { offsetX: node.position.x - center.x };
    layouts.set(node, layout);
    return layout;
}

/**
 * 把聽牌框水平搬到指定的軸：x 照 prefab 上相對第三軸的位移換算，y 與縮放不動。
 *
 * @param view 聽牌框所在的 view。
 * @param node 聽牌框節點。
 * @param reelIndex 要罩的軸（0 起算）。
 * @returns 有搬成功為 true；那一軸不存在時為 false，節點維持原位。
 */
function placeOnReel(view: GameViewAdapter, node: Node, reelIndex: number): boolean {
    const layout = layoutOf(view, node);
    const reel = view.slotMachineView?.reelViews[reelIndex];
    const center = reel && reelCenterInParent(node, reel.node);
    if (!layout || !reel || !center) return false;

    node.setPosition(center.x + layout.offsetX, node.position.y, node.position.z);
    return true;
}

/**
 * 把聽牌框罩到指定的軸上，從頭開始循環播放；已經罩在那一軸時什麼都不做，動畫不會被切回開頭。
 *
 * 動畫一律自己 `setAnimation()` 重新播，不靠 prefab 上的 `defaultAnimation`——那只在元件第一次
 * 啟用時套用，第二局再開節點會接在上一局停下的進度上，看起來像動畫缺頭。
 *
 * 循環播放沒有「播完」這回事，收掉的時機完全由呼叫端決定（見 {@link hideMiEffect}），所以這支
 * 不掛任何 complete 監聽或保底計時器。還在淡出中的框被重新蓋上時，停掉淡出、透明度回到全亮，從頭播。
 *
 * @param views 要蓋的 view，通常是 `game.allViews`。
 * @param reelIndex 要罩的軸（0 起算）；免費遊戲的瞇牌是第三軸（2）。
 */
export function showMiEffect(views: readonly GameViewAdapter[], reelIndex: number): void {
    let shown = 0;

    for (const view of views) {
        const skel = miSkelOf(view);
        if (!skel) continue;
        const node = skel.node;
        shown++;
        cancelFade(node);
        if (node.active && shownReel.get(node) === reelIndex) continue;

        if (!placeOnReel(view, node, reelIndex)) {
            console.warn(`[MiEffect] ${view.node.name} 找不到第 ${reelIndex + 1} 軸，聽牌框留在原位`);
        }
        node.active = true;
        shownReel.set(node, reelIndex);
        trySetAnimation(skel, MI_ANIM, true, 'MiEffect');
    }

    if (shown === 0 && !warnedMissing) {
        warnedMissing = true;
        console.warn('[MiEffect] 沒有任何 view 接上瞇牌特效：SlotMachineView_1003.prefab 的 SlotMachineView 上 miSkel 是空的');
    }
}

/**
 * 收掉聽牌框：`fadeSec` 秒內用 `UIOpacity` 淡出，淡完才關節點、清動畫；0 是當下就關。
 *
 * 已經關著就直接返回，所以呼叫端不必先判斷是不是免費局——主遊戲每一局無條件收一次的成本是零，
 * 還順便擋掉「輪轉中途切換模式」那種開了收不掉的邊界。已經在淡出時再收一次不會重來，給 0 則當下收完。
 *
 * 一開始收就不再算「罩在某一軸上」，淡出途中被 {@link showMiEffect} 重新蓋上會從頭播。
 *
 * @param views 要收的 view，通常是 `game.allViews`。
 * @param fadeSec 淡出秒數；0 或不給是當下就關。
 */
export function hideMiEffect(views: readonly GameViewAdapter[], fadeSec: number = 0): void {
    for (const view of views) {
        const skel = miSkelOf(view);
        const node = skel?.node;
        if (!skel || !node || !node.active) continue;
        shownReel.delete(node);

        const finish = (): void => {
            fading.delete(node);
            if (skel.isValid) tryClearAnimation(skel, 'MiEffect');
            if (!node.isValid) return;
            node.active = false;
            const opacity = node.getComponent(UIOpacity);
            if (opacity) opacity.opacity = 255;
        };

        const running = fading.get(node);
        if (running) {
            if (fadeSec > 0) continue;
            running.stop();
            finish();
            continue;
        }
        if (fadeSec <= 0) {
            finish();
            continue;
        }
        const opacity = node.getComponent(UIOpacity) ?? node.addComponent(UIOpacity);
        fading.set(node, tween(opacity).to(fadeSec, { opacity: 0 }).call(finish).start());
    }
}

/**
 * 停掉聽牌框的淡出，透明度回到全亮；沒在淡出時什麼都不做。
 *
 * @param node 聽牌框節點。
 */
function cancelFade(node: Node): void {
    const running = fading.get(node);
    if (!running) return;
    running.stop();
    fading.delete(node);
    const opacity = node.getComponent(UIOpacity);
    if (opacity) opacity.opacity = 255;
}
