import { getSpinSkipScope, type SpinSkipScope } from '../config/SpinSkipConfig';

/**
 * 跳過報獎前的等待。這裡只記錄跳過要求並通知監聽者，要不要跳、怎麼跳由各段演出自己決定；
 * 目前只有 Scatter 中獎演出的等待（`skipWait`）會跳，消除演出照常速播（範圍見 `SpinSkipConfig`）。
 *
 * 照 1001 的 `controllers/SpinSkipController.ts`。
 */
export class SpinSkipController {
    /** 這一轉可跳過 */
    private armed = false;
    private skipped = false;
    /** 已經到贏獎彈窗 */
    private reachedPopup = false;
    private readonly listeners = new Set<() => void>();

    /**
     * 測試時可固定範圍，不傳就每次讀設定。
     *
     * @param fixedScope 固定的範圍；省略時讀 {@link getSpinSkipScope}。
     */
    constructor(private readonly fixedScope?: SpinSkipScope) { }

    /**
     * 這一轉採用的範圍。
     *
     * @returns 固定的範圍，沒有就讀設定。
     */
    private get scope(): SpinSkipScope {
        return this.fixedScope ?? getSpinSkipScope();
    }

    /**
     * 轉輪落定之後，接點擊的節點是否繼續開著：`toWinPopup` 整轉都要能點。
     *
     * @returns 範圍是 `toWinPopup` 時為 true。
     */
    get keepsTouch(): boolean {
        return this.scope === 'toWinPopup';
    }

    /**
     * 這一轉是否已經被要求跳過。
     *
     * @returns 已跳過時為 true。
     */
    get isSkipped(): boolean {
        return this.skipped;
    }

    /** 一轉開始：可以跳過，清掉上一轉的狀態。 */
    arm(): void {
        this.armed = true;
        this.skipped = false;
        this.reachedPopup = false;
    }

    /** 一轉結束：不再接受跳過。 */
    release(): void {
        this.armed = false;
        this.skipped = false;
    }

    /** 要求跳過並通知監聽者。`dropOnly`、還沒開始、已經跳過或已經到彈窗時都不處理。 */
    request(): void {
        if (this.scope !== 'toWinPopup') return;
        if (!this.armed || this.skipped || this.reachedPopup) return;
        this.skipped = true;
        for (const listener of Array.from(this.listeners)) listener();
    }

    /** 贏獎彈窗即將出現：之後的點擊交給彈窗自己處理，不再跳過。 */
    reachPopup(): void {
        this.reachedPopup = true;
        this.skipped = false;
    }

    /**
     * 訂閱跳過要求。
     *
     * @param listener 被要求跳過時呼叫。
     * @returns 取消訂閱。
     */
    subscribe(listener: () => void): () => void {
        this.listeners.add(listener);
        return () => this.listeners.delete(listener);
    }
}
