import { DEFAULT_PRESENTATION_CONFIG, type PresentationConfig } from './PresentationConfig';
import type { WinTier, WinTierThreshold } from './GameConst';

/**
 * 演出設定（presentation.json）的執行期副本：遊戲載入時整份寫入，DebugPanel 拖動時只改這一份、只在這次有效。
 * 不寫進共用的 SlotGameStore。
 */
export default class PresentationStore {
    private static instance: PresentationStore;
    /**
     * @returns 全域唯一的 PresentationStore；第一次呼叫時建立。
     */
    static getInstance(): PresentationStore {
        if (!PresentationStore.instance) {
            PresentationStore.instance = new PresentationStore();
        }
        return PresentationStore.instance;
    }

    private _config: PresentationConfig = DEFAULT_PRESENTATION_CONFIG;
    /**
     * 目前的演出設定。
     *
     * @returns 演出設定。
     */
    get config(): PresentationConfig {
        return this._config;
    }
    /**
     * 整份換成 presentation.json 解析出來的設定；`GameMain_1003` 載入設定檔時呼叫，會蓋掉 DebugPanel 先前的調整。
     *
     * @param config 解析後的演出設定。
     */
    setConfig(config: PresentationConfig): void {
        this._config = config;
    }
    private _winTiers: readonly WinTierThreshold[] = [];
    /**
     * 目前的大獎演出門檻，進場前是空的。
     *
     * @returns 由大到小的門檻。
     */
    get winTiers(): readonly WinTierThreshold[] {
        return this._winTiers;
    }
    /**
     * 進場時寫入後端給的大獎演出門檻。
     *
     * @param tiers 由大到小的門檻。
     */
    setWinTiers(tiers: readonly WinTierThreshold[]): void {
        this._winTiers = tiers;
    }
    /**
     * 開關免費遊戲逐局報獎。DebugPanel 專用，只在這次有效。
     *
     * @param enabled true = 每局報獎，false = 原本的流程（出來才報）。
     */
    setFeatureRoundWinPresentationEnabled(enabled: boolean): void {
        this._config = { ...this._config, featureRoundWinPresentationEnabled: enabled };
    }
    /**
     * 設定免費局單局贏分要達到哪一階才播報獎。
     *
     * @param minTier 門檻等級。
     */
    setFeatureRoundWinPresentationMinTier(minTier: WinTier): void {
        this._config = { ...this._config, featureRoundWinPresentationMinTier: minTier };
    }
    /**
     * 設定 FG 結算面板（TOTAL WIN）停留幾秒才自動關閉。DebugPanel 專用，只在這次有效。
     *
     * @param sec 停留秒數，必須大於 0。
     */
    setTotalWinDwellSec(sec: number): void {
        this._config = { ...this._config, totalWinDwellSec: sec };
    }
}
