import { GameTaskHandler } from '../tasks/GameTaskHandler';
import { GameTaskQueue } from '../tasks/GameTaskQueue';
import { GameTaskFn, GameTaskPromise, type GameTask } from '../tasks/GameTask';
import type { ISlotGameMain } from '../types/ISlotGameMain';
import type { GameViewAdapter } from '../ui/GameViewAdapter';
import type { SlotRoundResult } from '../models/SlotRound';
import { planSpinFlow, type SpinFlowStep } from './SpinFlowPlanner';
import { CascadeReelsTask } from '../tasks/CascadeReelsTask';
import { ScatterWinTask } from '../tasks/ScatterWinTask';
import { FinishSpinTask } from '../tasks/FinishSpinTask';
import { WinAnimationTask } from '../tasks/WinAnimationTask';
import { EndSpinTask } from '../tasks/EndSpinTask';
import { EnterFreeGameTask } from '../tasks/EnterFreeGameTask';
import { WinFreeGamePopupTask } from '../tasks/WinFreeGamePopupTask';
import { PlayFreeRoundTask } from '../tasks/PlayFreeRoundTask';
import { ExitFreeGameTask } from '../tasks/ExitFreeGameTask';

/**
 * SpinResultHandler（1003）
 *
 * 比照舊專案（Cocos_2022）SGEngine 的 GameNetHandler 模式：收到 spin 結果後，
 * 在 handle() 當下依條件動態組裝一串具名 GameTask 塞進共用佇列
 * （對應 SGNetHandler 在解析封包當下組裝 Task 鏈的模式）。entry 這裡的共用基底
 * 已改名為 GameTaskHandler（見該檔案說明）。
 *
 * 各步驟的實際演出/資料操作邏輯都已搬進 Net/Task/ 底下對應的 GameTask 子類別
 * （CascadeReelsTask/ScatterWinTask/FinishSpinTask/WinAnimationTask/
 * EndSpinTask/EnterFreeGameTask/PlayFreeRoundTask/ExitFreeGameTask），不再寫在
 * GameMain_1003 或這個檔案裡——這裡只負責「決定順序、組裝 Task」，跟 GameMain_1003
 * 之間只透過建構子傳入的 game 參考互動（沿用共用能力，如 view 存取、win-bar 等）。
 */
export class SpinResultHandler extends GameTaskHandler<SlotRoundResult> {
    /**
     * @param game GameMain_1003，供各 Task 取用共用能力（view 存取、win-bar、免費遊戲狀態等）。
     */
    constructor(private readonly game: ISlotGameMain<GameViewAdapter>) {
        super(new GameTaskQueue({ debugName: '1003-cascade' }));
    }

    /**
     * 對應 SGTask_NGSpin：轉輪停止 + 消去落下迴圈。
     * 結果出來後在同一顆 Task 內依條件（有沒有觸發免費遊戲）動態
     * addTask() 組裝後續任務——分支判斷在「解析當下」就決定好要塞哪些 Task，
     * 而不是在後面用 if/return 中斷 async 函式。
     *
     * @param roundResult 主遊戲那一轉的結果（HttpClientStore 已經轉好）。
     */
    public handle(roundResult: SlotRoundResult): void {
        this.game.resetWinBar();
        if (roundResult.maxWin.applied) console.log('[MaxWin] 達到贏分上限', { totalWin: roundResult.totalWin });

        const ctx: { currentCols: number[][] | null } = { currentCols: null };

        this.addTask(new CascadeReelsTask(this.game, roundResult.mainSteps, (cols) => (ctx.currentCols = cols)));

        // 沒有有效盤面（例如資料異常）就在這裡整串中止，比照原本 `if (!currentCols) return;`
        this.addTask(
            new GameTaskFn(() => {
                if (!ctx.currentCols) return;
                const currentCols = ctx.currentCols;

                // 是否進 FG 還要看當下盤面實際 scatter 數，這個依賴即時畫面的條件規劃器管不到，只能在這裡先算好再傳進去。
                // 盤面湊滿 Scatter 但這一轉已經到單局上限（後端 FB）時不進，不能只看 Scatter 數
                const willEnterFreeGame = !roundResult.freeGameBlocked && this.game.shouldEnterFreeGame(roundResult.freeSpinTriggered, currentCols);
                const steps = planSpinFlow(roundResult, willEnterFreeGame);
                this.runSpinFlowSteps(steps, roundResult, currentCols);
            })
        );
    }

    /**
     * 依 SpinFlowPlanner 規劃好的步驟依序組裝實際 Task；這裡才是唯一會 new Task／碰 Cocos 相關參數的地方。
     *
     * @param steps 規劃好的流程步驟。
     * @param roundResult 主遊戲那一轉的結果，Task 需要的資料都從這裡取。
     * @param currentCols 轉輪停止當下的盤面，ScatterWinTask 用來標中獎的 scatter。
     */
    private runSpinFlowSteps(steps: readonly SpinFlowStep[], roundResult: SlotRoundResult, currentCols: number[][]): void {
        for (const step of steps) {
            switch (step.kind) {
                case 'scatterWin':
                    // 對應 SGTask_Scatter（觸發免費遊戲）
                    this.addTask(new ScatterWinTask(this.game, currentCols));
                    break;
                case 'finishSpin':
                    this.addTask(new FinishSpinTask(this.game, roundResult, step.spinWin));
                    break;
                case 'winAnimation':
                    this.addTask(new WinAnimationTask(this.game, step.spinWin));
                    break;
                case 'endSpin':
                    this.addTask(new EndSpinTask(this.game));
                    break;
                case 'winFreeGamePopup':
                    this.addTask(new WinFreeGamePopupTask(this.game, step.freeRoundCount));
                    break;
                case 'enterFreeGame':
                    this.addTask(new EnterFreeGameTask(this.game, step.freeRoundCount));
                    break;
                case 'playFreeGame':
                    this.addTask(new GameTaskPromise(() => this.playFreeGame(roundResult)));
                    break;
            }
        }
    }

    /**
     * 進場時免費遊戲打到一半：直接接著向後端要下一轉，打到局結束再收尾（走跟一般流程同一個 {@link playFreeGame}）。
     *
     * 畫面（FG 狀態、轉數、階梯、Win）由 `GameMain_1003.resumeFreeGame()` 先還原好才呼叫這裡。
     *
     * @param result 還原用的局資料（`SlotRoundMapper.toResume()` 的 `freeGame.result`），只用來收尾。
     */
    public resumeFreeGame(result: SlotRoundResult): void {
        this.addTask(new GameTaskPromise(() => this.playFreeGame(result)));
    }

    /**
     * 播免費遊戲：每一轉在播放時才向後端要（`nextFreeSpin()`），播完這一轉再要下一轉，直到局結束；
     * 最後排 ExitFreeGameTask 收尾。
     *
     * 剩餘／總轉數每播完一轉以後端的 `fs` 為準：加局的演出在 PlayFreeRoundTask 裡先把數字加上去，
     * 這裡再對齊一次。後端失敗時 `nextFreeSpin()` 已顯示錯誤並回 null，這裡就用手上的結果收尾，
     * 免得畫面卡在免費遊戲。
     *
     * @param mainResult 觸發免費遊戲的主遊戲那一轉。
     * @returns 最後一轉播完（或中途失敗）之後 resolve。
     */
    private async playFreeGame(mainResult: SlotRoundResult): Promise<void> {
        const store = this.game.storeManager.getHttpClientStore();
        let totalWin = mainResult.totalWin;
        let balance = mainResult.balanceAfter;
        let capStop = false;
        try {
            for (let round = 0; ; round++) {
                const spin = await store.nextFreeSpin();
                if (!spin) break;
                const ladder = spin.steps[spin.steps.length - 1]?.multiplier ?? 0;
                await runTask(new PlayFreeRoundTask(this.game, spin.steps, { round, multiplier: ladder, accumulated: ladder, win: spin.win }, spin.awardedRounds));
                this.game.freeSpinsTotal = spin.total;
                // 局結束後不會再有下一轉 提前到頂時 fg_remain 可能大於 0
                this.game.freeSpinsRemaining = spin.finished ? 0 : spin.remain;
                this.game.updateFgUi();
                totalWin = spin.roundWin;
                balance = spin.balance;
                capStop ||= spin.endReason === 'cap_stop';
                if (spin.finished) break;
                await new Promise<void>((resolve) => this.game.scheduleOnce(resolve, this.game.cascadeTiming().fgDelay / 1000));
            }
        } finally {
            if (capStop) console.log('[MaxWin] 免費遊戲達到贏分上限', { totalWin });
            // 不論正常結束或中途出錯都要收尾，畫面才不會卡在免費遊戲
            this.addTask(new ExitFreeGameTask(this.game, { ...mainResult, totalWin, balanceAfter: balance }, Number(totalWin) || 0));
        }
    }
}

/**
 * 在佇列之外直接跑一顆 Task，等它 finish。
 *
 * @param task 要跑的 Task。
 * @returns Task 完成之後 resolve。
 */
function runTask(task: GameTask): Promise<void> {
    return new Promise<void>((resolve) => task.execute(resolve));
}
