const { ccclass, property } = _decorator;

@ccclass('1003/GameMain_1003')
export class GameMain_1003 extends SlotGameMain<GameViewAdapter> {
    /**
     * 1003 的符號與賠付定義，共用層靠它解析符號種類與圖名。
     *
     * @returns 1003 的遊戲定義。
     */
    public get definition(): typeof SLOT_GAME_DEFINITION {
        return SLOT_GAME_DEFINITION;
    }

    private sceneSpeedUnsubscribe: (() => void) | null = null;
    // === 透過 GameViewAdapter 存取視覺節點 ===
    @property(GameViewAdapter)
    viewH: GameViewAdapter = null!;

    @property(GameViewAdapter)
    viewV: GameViewAdapter = null!;

    /**
     * 目前方向的轉輪 view，經由共用基底的 dualView 取得。
     *
     * @returns 轉輪 view。
     */
    private get slotMachineView() {
        return this.dualView.slotMachineView;
    }

    /** 報獎彈窗的載入與顯示；public 供 Net/Task 系列呼叫 */
    public popups: PopupManager = new PopupManager(this, () => this.allViews);

    /**
     * SlotGameMain 抽象成員：中獎連線音效路徑，供共用的 WinAnimationController 使用。
     *
     * 音效規格表沒有連線中獎音（中獎外框亮起時播的是 win_1～win_3），2026-10-22 起回空字串、不播。
     *
     * @returns 音效路徑；空字串代表不播。
     */
    protected get lineWinEffect(): string {
        return '';
    }

    /**
     * SlotGameMain 抽象成員：各遊戲自己的 static FG_TRIGGER_SCATTERS，供共用的 ScatterFreeGameController 使用。
     *
     * @returns 觸發免費遊戲需要的 Scatter 顆數。
     */
    protected get fgTriggerScatters(): number {
        return GameMain_1003.FG_TRIGGER_SCATTERS;
    }

    /**
     * 1001 倍率球「角色舉手 → 落盤打雷」之間的延遲。1003 依 GDD 沒有倍率球（2026-09-14 移除），
     * 已經沒有程式讀它；保留只因為共用介面 ISlotGameMain 規定每款遊戲都要有這個欄位。
     */
    @property({ tooltip: '1003 未使用（ISlotGameMain 介面要求保留）' })
    public charMulLeadMs: number = 250;

    /**
     * 把關閉網路的收尾掛到大廳傳進來的 `__subGameData__.beforeExit` 上。
     *
     * 大廳要離開子遊戲前會先呼叫這個鉤子，讓 WebSocket 有機會乾淨關閉；沒有這份資料
     * （例如獨立 Preview）就什麼都不做。
     */
    private registerBeforeExitHook(): void {
        const data = getSubGameData();
        if (data) {
            data.beforeExit = () => this.storeManager?.getHttpClientStore()?.shutdown() ?? Promise.resolve();
        }
    }

    /** 離開遊戲收尾（比照舊專案 SGEngine GameMain 的 exitGame()/gameFini()） */
    protected override exitGame(): void {
        this.spinShortcut.unbind();
        super.exitGame();
    }

    /** spin 回應的解析與 GameTask 組裝（比照舊專案 1109 GameNetHandler 模式，entry 共用基底已改名 GameTaskHandler，從 GameMain 抽離出去） */
    private readonly spinResultHandler = new SpinResultHandler(this);

    /**
     * 遊戲初始化（比照舊專案 SGEngine GameMain 的 gameInit()）：讀取表演與轉輪設定、註冊 NG／FG 狀態、
     * 建立各 view 的轉輪 model、綁定 spin 快捷鍵，以及各項事件訂閱。
     */
    protected override gameInit(): void {
        this.initSharedControllers();
        this.storeManager = StoreManager.getInstance();
        this.registerBeforeExitHook();
        AppAudio.getInstance().preloadAll([...Object.values(EFFECTSMAP), ...Object.values(VOICEMAP)]);
        this.loadPresentationConfig();
        this.sceneSpeedUnsubscribe = SceneSpeedStore.subscribe(GameConfigManager.GAMEID, (config) =>
            this.onSceneSpeedChanged(config)
        );
        this.loadReelConfig();
        installDirectorSpeedHook();

        // 狀態機（比照舊專案 GameMain.InitStates()）：註冊 NG/FG 兩個狀態，預設進入 NG
        this.registerState(GameStateKey.NG, new NGState_1003());
        this.registerState(GameStateKey.FG, new FGState_1003());
        this.changeState(GameStateKey.NG);

        // 每個 view 各自建立 model — reelCount 從 prefab 的 reelViews.length 動態取
        this.forEachView((v) => {
            const sm = new SlotMachineModel({ reelCount: v.slotMachineView.reelViews.length });
            sm.initReelModels();
            this.registerSlotMachineModel(sm);
            v.slotMachineView.init(sm);
            v.slotMachineModel = sm;
        });

        // viewH 的 model 作為向下相容欄位
        this.slotMachineModel = this.viewH.slotMachineModel;

        this.spinShortcut.bind();

        // 快停（slotgame docs/快停.md）：轉動中點畫面空白處；報獎彈窗出現後就不再跳過
        this.setupQuickStopTouch();
        this.popups.onWinPopup = () => this.spinSkip.reachPopup();

        // 1003 依 GDD 沒有 Jackpot，不訂閱獎池（2026-09-14 移除）

        // [EVT-GAME-004] 改由 EventBus 觸發
        this.subscribeEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.GAME_SPIN_DATA_CHANGED, (event) => {
            if (event.spinData) this.onSpinResultReceived(event.spinData);
        });

        this.mainCamera =
            director.getScene()?.getChildByName('Canvas')?.getChildByName('Camera')?.getComponent(Camera) ?? null;

        // 直橫版切換：透過 layer 過濾，讓非當前方向的子樹完全不被 camera 渲染
        const device = StoreManager.getInstance().getDeviceStore();
        this.orientation.init(device.isLandscape);
        // [EVT-GAME-008] 裝置直橫版切換改由 EventBus 觸發
        this.subscribeEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.DEVICE_ORIENTATION_CHANGED, () => {
            this.orientation.applyOrientation(device.isLandscape);
        });

        // 這裡原本每次 stateChanged 都把所有符號 spine 的 timeScale 設成 0（"凍住 idle 動畫"）。
        // 改成物件池之後不需要了：沒被租用的狀態其顯示物件是關著的，sp.Skeleton.update() 只看
        // 元件 enabled 與節點 active，關著就不吃每幀 CPU；活著的 spine 剛好就是當下狀態需要的那一支。
        //
        // 而且留著會出事。改版前這條路走的是 ReelView_1003.symbolSpines，那個陣列從來沒被 push 過，
        // 所以這行一直是空操作；改版把 setSymbolSpinesTimeScale() 接到每個格子上之後它就真的生效了，
        // 會在 stateChanged 的時機把正在播的中獎／爆破 spine 凍住。見 entry docs/agent-pitfalls.md 坑 #37。

        this.initReactions();
    }

    /**
     * 讀取這款遊戲的演出設定（resources/config/presentation.json）寫進 PresentationStore；讀不到時留一行 warn、沿用預設。
     *
     * @returns 讀完（或失敗改用預設）之後 resolve，不會 reject。
     */
    private async loadPresentationConfig(): Promise<void> {
        try {
            const asset = await AppAssetBundle.getInstance(GameConfigManager.GAMEID).loadAsset(
                PRESENTATION_CONFIG_PATH,
                JsonAsset
            );
            PresentationStore.getInstance().setConfig(parsePresentationConfig(asset.json));
        } catch (error) {
            console.warn('[GameMain_1003] 讀取 presentation.json 失敗 使用預設值', error);
        }
    }

    /**
     * 讀取轉輪節奏＋整體 scene 加速倍率的本地端預設值（共用同一份 jsons/reelConfig.json），
     * 分別設進 ReelTimingDebugStore／SceneSpeedStore 的 local default 層。
     *
     * PM 透過 DebugPanel 調整的值只留在記憶體、優先權比這層高，但不寫進 localStorage，
     * 所以每次進遊戲都是從這份 json 開始。
     *
     * @returns 讀完（或失敗沿用 Editor 基準值）之後 resolve，不會 reject。
     */
    private async loadReelConfig(): Promise<void> {
        try {
            const asset = await AppAssetBundle.getInstance(GameConfigManager.GAMEID).loadAsset(
                REEL_CONFIG_PATH,
                JsonAsset
            );
            ReelTimingDebugStore.setLocalDefault(GameConfigManager.GAMEID, parseReelConfig(asset.json));
            SceneSpeedStore.setLocalDefault(GameConfigManager.GAMEID, parseSceneSpeedConfig(asset.json));
        } catch (error) {
            console.warn('[GameMain_1003] 讀取 reelConfig.json 失敗，沿用 Editor 基準值', error);
        }
    }

    /** 進入遊戲：啟動音樂、背景與 UI 呈現（比照舊專案 SGEngine GameMain 的 doEnterGame()/onEnterGame()） */
    protected override enterGame(): void {
        this.popups.preloadAll();

        this.applyGameModeUi(false);
        // transition spine 預設關（prefab 可能留 active），只在播放時開
        this.forEachView((v) => {
            if (v.transitionSkel?.isValid) v.transitionSkel.node.active = false;
        });
        // 瞇牌特效同理，而且它的 skeleton 設了 loop：不先關掉會從進遊戲就一直播在盤面上
        hideMiEffect(this.allViews);
        // 倍率飛行的 collect 特效也是 active ＋ loop，同樣要先關
        this.forEachView((v) => hideMulFlyCollect(v));
        // 加局特效（AddNode）同理
        this.forEachView((v) => hideAddFly(v));
        this.resetWinBar();
    }

    /** GDD：3 顆 Scatter 觸發免費遊戲（1001 是 4 顆，複製骨架時沿用了 1001 的值） */
    private static readonly FG_TRIGGER_SCATTERS = 3;

    /**
     * 播放轉場 音效與全螢幕轉場動畫一起進行 背景本身由 applyGameModeUi() 在切模式時開關
     *
     * @param direction 進入或離開
     * @returns 轉場動畫播完時完成
     */
    public playTransition(direction: TransitionDirection): Promise<void> {
        AppAudio.getInstance().playEffect(EFFECTSMAP.TRANSITION);
        return playTransitionSpine(this.allViews, direction === 'enter', this);
    }

    // applyGameModeUi/setNodeActiveByPrefix 方法本體在共用的 SlotGameMain 基底
    /**
     * 切換主遊戲／免費遊戲的介面。在共用基底的行為之外，切換 NG／FG 兩組背景；
     * 回主遊戲時把階梯倍數面板換回主遊戲那張表（GDD 4.1 x1/x2/x3/x5）。
     *
     * 進 FG、出 FG、進遊戲三條路徑都會經過這裡（EnterFreeGameTask／ExitFreeGameTask／enterGame）。
     * 唯一的例外是進 FG 的換表（GDD 4.3 x2/x4/x6/x10）：它要在換表演出 `levelup` 播放中由下往上逐階換，
     * 而這裡是在轉場中段被呼叫的，所以交給 EnterFreeGameTask 在轉場播完後呼叫
     * `TimesController.switchToFreeLadder()`。
     *
     * 直版目前沒有 FG／NG 節點，也沒有階梯面板（fgNode／ngNode／timesPanel 都是 null）。
     * 兩者各自判斷、互不影響——背景缺了就留一行 warn 跳過那一段，不要連帶讓階梯也一起被略過。
     *
     * @param toFree true = 切到免費遊戲。
     */
    override applyGameModeUi(toFree: boolean): void {
        super.applyGameModeUi(toFree);
        director.getScene()?.getComponentInChildren(GameRoot)?.setBackdropFree(toFree);
        this.forEachView((v) => {
            if (v.fgNode && v.ngNode) {
                v.fgNode.active = toFree;
                v.ngNode.active = !toFree;
            } else {
                console.warn(`[GameMain_1003] ${v.node.name} 沒接 fgNode／ngNode，略過背景切換`);
            }

            // 進 FG 的換表由 EnterFreeGameTask 跟 levelup 一起做，見上方說明
            if (!toFree) v.timesPanel?.setMode(false);
        });
        // 人物跟 NG／FG 同層、不會跟著上面一起開關：這裡顯示新模式的那位並從頭播 idle，另一位隱藏
        showCharacterForMode(this.allViews, toFree);
        // 轉輪兩側霓虹框在 FG 底下，跟著上面的 fgNode 開關；進 FG 時從頭循環 fg_idle
        if (toFree) playFgReelFxIdle(this.allViews);
    }

    /** configData + gameInitData 都到了才能還原盤面
     *  configData 更新 strip 後，用 gameInitData 的 icon_indexes 設 currentRng
     *  [EVT-GAME-006][EVT-GAME-007] 兩者任一變動都要重跑一次，因此各自訂閱同一個 handler */
    private applyConfigAndInit(): void {
        const config: any = this.storeManager.getGameStore().configData;
        const init: any = this.storeManager.getGameStore().gameInitData;

        const iconMatrix = config?.base?.icon_matrix;
        if (iconMatrix) this.slotMachineView.updateStrips(iconMatrix);

        // 擺盤面一定要排在更新 strip 之後：隨機盤面的 icon_indexes 是輪帶上的位置、後端盤面要寫進輪帶，
        // strip 還是舊的就對到錯的符號或被換掉。兩份資料任一還沒到就直接等下一次事件。
        if (!init?.machine_info || !iconMatrix) return;
        this.applyEntryBoard(init.machine_info);
    }

    /** 進場還原做過了：只做一次，後面的事件不能蓋掉正在玩的盤面 */
    private entryRestored = false;

    /**
     * 進場盤面：後端有給（`machine_info.resume.grid`，來源是 entry 的 `ls.r`）就直接擺好、不播落下，
     * 免費遊戲打到一半時再切回免費遊戲接著打；沒給（解碼失敗、後端沒有預設盤面）才退回隨機輪帶位置。
     *
     * 進場時 console 印 `[進場盤面]`／`[進場免費遊戲]`：初始或重進、後端或 mock、擺上的盤面與後端原始 `rl`，
     * 對照用（格式照 1001／1002，`docs/api-v8.1-遷移.md` §9.3）。
     *
     * @param machineInfo gameInitData 的 `machine_info`（`toSlotInitData()` 產生，`resume`／`mock` 由 HttpClientStore 填入）。
     */
    private applyEntryBoard(machineInfo: any): void {
        const resume: SlotResume | null = machineInfo.resume ?? null;
        const ls = this.storeManager.getGameStore().entryData?.ls;
        const kind = ls && isRoundInProgress(ls) ? '重進' : '初始';
        if (!resume?.grid) {
            console.log(`[進場盤面] ${kind} 隨機盤面（沒有後端盤面或解析失敗）nst=${ls?.nst}`, { icon_indexes: machineInfo.icon_indexes });
            this.restoreBoard(machineInfo.icon_indexes);
            return;
        }
        if (this.entryRestored) return;
        this.entryRestored = true;

        const origin = machineInfo.mock ? 'mock' : '後端';
        const raw = ls?.r?.sg[ls.r.sg.length - 1]?.rl;
        console.log(
            `[進場盤面] ${kind} ${origin}盤面 nst=${ls?.nst} sid=${ls?.sid || '空'}\n` +
                `擺上的盤面（共 ${resume.grid.columns.length} 軸）\n${AppUtility.formatBoard(resume.grid.columns.map((c) => c.symbolIds))}\n` +
                `${origin}原始 rl\n${raw ? AppUtility.formatBoard(raw) : '（無 rl）'}\n` +
                `${origin}原始 ls.r`,
            ls?.r
        );
        const free = resume.freeGame;
        console.log(free ? `[進場免費遊戲] 有 剩 ${free.remain}/${free.total} 轉 贏分 ${free.totalWin}` : `[進場免費遊戲] 無 nst=${ls?.nst}`);

        this.drawBoard(resume.grid);
        if (free) this.resumeFreeGame(free);
    }

    /**
     * 進場盤面直接擺好，不轉、不播落下（`ReelView_1003.snapToBoard()`）。
     *
     * @param grid 後端給的進場盤面（可見盤，damp 已扣掉）。
     */
    private drawBoard(grid: SlotGrid): void {
        this.forEachView((v) => {
            const reels = v.slotMachineView.reelViews;
            const colCount = Math.min(grid.columns.length, reels.length);
            for (let col = 0; col < colCount; col++) {
                const reel = reels[col];
                const frames = grid.columns[col].symbolIds.map((id) => Math.max(0, reel.frameIdxByName(this.definition.symbols.frameName(id))));
                if (!reel.snapToBoard(frames)) console.warn(`[GameMain_1003] ${v.node.name} 第 ${col + 1} 軸擺不上進場盤面（正在轉、輪帶沒建好或列數不符），維持原畫面`);
            }
        });
    }

    /**
     * 免費遊戲打到一半：不播轉場，直接回到免費遊戲畫面，接著向後端要下一轉。
     *
     * 畫面還原的項目照 `EnterFreeGameTask.switchToFreeGame()`（狀態含背景音樂、轉數、NG／FG 節點與人物、win bar），
     * 階梯面板直接換成免費遊戲的表（`TimesController.setMode(true)`，不播換表演出 `levelup`）。
     * Win 顯示到目前為止的整局贏分（`ls.aw`），之後每一轉照常往上加；收尾時 `ExitFreeGameTask` 再用後端的總額校正。
     * spin 狀態設成 SPIN_START：跟一般流程一樣整段免費遊戲都在同一轉裡，按鈕維持鎖住（{@link onSpinStart} 在 FG 中不動作）。
     *
     * @param free 轉數、贏分與收尾用的局資料。
     */
    private resumeFreeGame(free: SlotFreeResume): void {
        console.log(`[免費遊戲續打] 進場還原，直接切到免費遊戲畫面 剩 ${free.remain}/${free.total} 轉 贏分 ${free.totalWin}，接著用 sid=${free.result.betId} 向後端要下一轉`);
        this.changeState(GameStateKey.FG);
        this.storeManager.getGameStore().setSpinStatus(GAMESTOREMAP.SPIN_START);
        this.freeSpinsTotal = free.total;
        this.freeSpinsRemaining = free.remain;
        this.fgTotalWin = Number(free.totalWin) || 0;
        this.updateFgUi();
        this.applyGameModeUi(true);
        this.forEachView((v) => v.timesPanel?.setMode(true));
        this.resetWinBar();
        this.storeManager.getModel('TemplateStore').setWinBalance(this.fgTotalWin);
        this.spinResultHandler.resumeFreeGame(free.result);
    }

    /**
     * 後端沒給盤面時的退路：依開局資料的輪帶位置鋪一個隨機盤面。
     *
     * @param iconIndexes 每一輪的輪帶位置；沒有或長度不足時退回預設符號鋪滿。
     */
    private restoreBoard(iconIndexes: number[] | null | undefined): void {
        this.forEachView((v) => {
            const reelCount = v.slotMachineModel.reelCount;
            if (iconIndexes && iconIndexes.length >= reelCount) {
                GameMain_1003.restoreReelsFromIconIndexes(v, reelCount, iconIndexes);
            } else {
                GameMain_1003.fillBoardWithDefaultSymbol(v, reelCount);
            }
        });
    }

    /**
     * 用後端給的輪帶位置還原每一輪的畫面。
     *
     * 位置要減掉頭部的 2 格緩衝才是輪帶索引，再取模避免負數。
     *
     * @param view 要還原的 View。
     * @param reelCount 輪數。
     * @param iconIndexes 每一輪的輪帶位置。
     */
    private static restoreReelsFromIconIndexes(view: GameViewAdapter, reelCount: number, iconIndexes: number[]): void {
        for (let i = 0; i < reelCount; i++) {
            const reelView = view.slotMachineView.reelViews[i];
            const rng = (iconIndexes[i] - 2 + reelView.strip.length) % reelView.strip.length;
            view.slotMachineModel.reelModels[i].setCurrentRng(rng);
            reelView.refreshDisplay();
        }
    }

    /**
     * 後端沒給可用的輪帶位置時的退路：整個盤面鋪同一個符號。
     *
     * 寧可鋪一個明顯是預設值的畫面，也不要讓盤面留空——空盤面看起來像載入失敗。
     *
     * @param view 要填的 View。
     * @param reelCount 輪數。
     */
    private static fillBoardWithDefaultSymbol(view: GameViewAdapter, reelCount: number): void {
        for (let col = 0; col < reelCount; col++) {
            for (let row = 0; row < 3; row++) {
                view.slotMachineView.reelViews[col]?.setInitialSymbol(row, 'caishen');
            }
        }
    }

    /** 訂閱各項全域狀態（轉速、自動、場景速度等）的變化，把它們接到畫面反應上。 */
    private initReactions(): void {
        this.subscribeEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.GAME_CONFIG_DATA_CHANGED, () => {
            this.applyConfigAndInit();
        });
        this.subscribeEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.GAME_INIT_DATA_CHANGED, () => {
            this.applyConfigAndInit();
        });
        this.applyConfigAndInit();

        // [EVT-GAME-001] 取代原本監聽 GameStore.spinStatus 的 MobX reaction（Producer：GameStore.setSpinStatus()）
        this.subscribeEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.SPIN_STATUS_CHANGED, (event) => {
            console.log(`[EVT-GAME-001][CONSUMER][GameMain_1003] event received`, event);
            this.onSpinStatusChanged(event.status);
        });
        this.subscribeEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.TURBO_STATUS_CHANGED, () => {
            this.onTurboStatusChanged();
        });

        // MobX reaction 原本 fireImmediately=true
        this.onSpinStatusChanged(this.storeManager.getGameStore().spinStatus);
    }

    /**
     * [EVT-GAME-004 consumer] 收到 spin 結果：確認有主遊戲盤面、轉輪還在轉，才交給 SpinResultHandler 組裝演出。
     *
     * @param data 主遊戲那一轉的結果。
     */
    private onSpinResultReceived(data: SlotRoundResult): void {
        try {
            console.log(`[EVT-GAME-004][CONSUMER][GameMain_1003] onSpinResultReceived start`, {
                operationId: data.operationId
            });

            if (!data.mainSteps.length) {
                console.log(`[EVT-GAME-004][CONSUMER][GameMain_1003] ignored: no main result`);
                // 轉輪在按下 spin 時就起轉了，這一局不會再有人來停，原地停回原盤面
                void stopReelSpinInPlace(this);
                return;
            }
            if (this.slotMachineModel.state !== SlotMachineState.SPINNING) {
                console.log(`[EVT-GAME-004][CONSUMER][GameMain_1003] ignored: reel is not spinning`);
                return;
            }

            console.log(`[EVT-GAME-004][CONSUMER][GameMain_1003] spinResultHandler.handle`);
            this.spinResultHandler.handle(data);
        } catch (error) {
            console.warn(`[EVT-GAME-004][CONSUMER][GameMain_1003] cascade failed`, error);
        }
    }

    /**
     * 1003 專屬 Spin request。共用 HttpClientStore 只處理網路與保存 response，不判斷遊戲、不派發遊戲事件。
     *
     * @param bet 下注金額。
     */
    private requestSpin(bet: number | string): void {
        const httpClientStore = this.storeManager.getModel('HttpClientStore');
        httpClientStore.spin(bet).catch((error: unknown) => {
            // error 已在 HttpClientStore 處理
            console.error(`[EVT-GAME-004][PRODUCER][GameMain_1003] unexpected request error`, error);
        });
    }

    /**
     * [EVT-GAME-001 consumer] spin 狀態變化，依狀態分給 {@link onSpinStart}、{@link onNewGame}、{@link onSpinEnd}。
     *
     * 前身是 spinStatus reaction 的 effect，三個分支的內容原封不動拆成三支方法。
     *
     * @param status GAMESTOREMAP 裡的 spin 狀態。
     */
    private onSpinStatusChanged(status: string): void {
        console.log(`[EVT-GAME-001][CONSUMER][GameMain_1003] onSpinStatusChanged start`, status);
        if (status === GAMESTOREMAP.SPIN_START) {
            this.onSpinStart();
        } else if (status === GAMESTOREMAP.NEW_GAME) {
            this.onNewGame();
        } else if (status === GAMESTOREMAP.SPIN_END) {
            this.onSpinEnd();
        } else {
            console.log(`[EVT-GAME-001][CONSUMER][GameMain_1003] no 1003 action for status`, status);
        }
        console.log(`[EVT-GAME-001][CONSUMER][GameMain_1003] onSpinStatusChanged end`, status);
    }

    /**
     * 按下 SPIN：扣款、清掉上一轉的贏分演出、開快停窗口並送出 spin。
     *
     * 免費遊戲中不動作；餘額不夠扣這一注時也不動作（{@link SlotGameStore.spinCheck} 會彈儲值提示）。
     */
    private onSpinStart(): void {
        console.log(`[EVT-GAME-001][CONSUMER][GameMain_1003] branch=SPIN_START`);
        if (this.getCurStateKey() === GameStateKey.FG) {
            console.log(`[EVT-GAME-001][CONSUMER][GameMain_1003] SPIN_START ignored: free game active`);
            return;
        }
        if (!this.storeManager.getGameStore().spinCheck()) {
            console.log(`[EVT-GAME-001][CONSUMER][GameMain_1003] SPIN_START blocked: spinCheck=false`);
            return;
        }
        const userStore = this.storeManager.getModel('UserStore');
        const bet = this.storeManager.getModel('TemplateStore').betBalance;
        userStore.setBalance(Number((userStore.balance - bet).toFixed(2)));
        this.storeManager.getModel('TemplateStore').setWinBalance(0);
        this.win.stopAnimations();
        this.win.stopWinScore();

        EagleTracker.getInstance().trackerTotalBet(bet);
        // 這一轉的速度檔位在 openSpinWindow() 鎖定並套用，轉動中不隨 Turbo 鈕變動
        this.openSpinWindow();
        this.requestSpin(bet);
        this.spinClick();
        console.log(`[EVT-GAME-001][CONSUMER][GameMain_1003] SPIN_START completed`, { bet });
    }

    /**
     * 回到可以下注的狀態：關快停窗口、還原播放速度；spin 失敗時把已經起轉的轉輪停回原盤面。
     */
    private onNewGame(): void {
        console.log(`[EVT-GAME-001][CONSUMER][GameMain_1003] branch=NEW_GAME`);
        this.closeSpinWindow();
        this.spinTurboIndex = null;
        const sceneSpeed = SceneSpeedStore.get(GameConfigManager.GAMEID);
        if (sceneSpeed?.activationMode !== SceneSpeedActivationMode.GAME_WIDE) {
            this.resetPlaybackSpeed();
        } else {
            this.applyPlaybackSpeed(sceneSpeed.speedFactors[this.getTurboIndex()] ?? 1);
        }
        // spin 失敗：機台照舊當下拉回 IDLE，轉輪在按下時就起轉了，要停回起轉前那一盤。
        // 正常結束的局在 runCascadeReels() 裡就收回 IDLE 了，走到這裡不會是 SPINNING。
        if (this.allViews.some((v) => v.slotMachineModel.state === SlotMachineState.SPINNING)) {
            void stopReelSpinInPlace(this);
        }
    }

    /**
     * 轉動中再按 SPIN：快停；正在演可跳過的贏分段落時一併跳過。
     *
     * 自動轉中按 SPIN 是停止自動，不會走到這裡。
     */
    private onSpinEnd(): void {
        console.log(`[EVT-GAME-001][CONSUMER][GameMain_1003] branch=SPIN_END`);
        this.requestQuickStop();
        if (!this.win.winPhaseSkipFn) return;

        const scene = this.storeManager.getGameStore().winAnimationData != null ? 'BigWin' : 'FeatureEntry';
        EagleTracker.trackerEvent(TrackerMap.ANIMATION_SKIP, { scene });
        this.win.stopAnimations();
        this.win.stopWinScore();
        this.storeManager.getGameStore().setWinAnimationData(null);
        const skip = this.win.winPhaseSkipFn;
        this.win.winPhaseSkipFn = null;
        skip();
    }

    /** DebugPanel 用的入口：等同玩家按下 spin。 */
    public spinClick(): void {
        this.onNormalSpin();
    }

    /** 這一轉開始時鎖定的速度檔位；沒在轉時是 null，轉動中不隨 Turbo 鈕變動 */
    private spinTurboIndex: number | null = null;

    /**
     * 一轉開始（主遊戲按 SPIN、免費遊戲每一局）：鎖定當下的速度檔位並套用播放倍率。
     *
     * 照 1001 的做法。免費遊戲每一局都會重新鎖一次，所以免費遊戲中切 Turbo 下一局就生效。
     */
    public override openSpinWindow(): void {
        super.openSpinWindow();
        this.spinTurboIndex = this.liveTurboIndex();
        const sceneSpeed = SceneSpeedStore.get(GameConfigManager.GAMEID);
        this.applyPlaybackSpeed(sceneSpeed?.speedFactors[this.spinTurboIndex] ?? 1);
    }

    /**
     * 目前生效的速度檔位：轉動中是這一轉鎖定的檔位，沒在轉時是 Turbo 鈕當下的檔位。
     *
     * @returns 0 = 一般、1 = 快速、2 = 極速。
     */
    private getTurboIndex(): number {
        return this.spinTurboIndex ?? this.liveTurboIndex();
    }

    /**
     * 把 Turbo 鈕當下的狀態轉成三段速的索引。
     *
     * @returns 0 = 一般、1 = 快速、2 = 極速。
     */
    private liveTurboIndex(): number {
        const turbo = this.storeManager.getGameStore().turboStatus;
        if (turbo === TURBOSTATUSMAP.MAX) return 2;
        if (turbo === TURBOSTATUSMAP.FAST) return 1;
        return 0;
    }

    /**
     * 同步設定畫面與音訊倍率。
     *
     * @param factor 播放倍率，1 為原速。
     */
    private applyPlaybackSpeed(factor: number): void {
        setDirectorSpeedFactor(factor);
        AppAudio.getInstance().setPlaybackRate(factor);
    }

    /** 同步重設畫面與音訊倍率 */
    private resetPlaybackSpeed(): void {
        resetDirectorSpeedFactor();
        AppAudio.getInstance().setPlaybackRate(1);
    }

    /** turbo 檔位改變時重新套用播放倍率；轉動中檔位已鎖定，不處理。 */
    private onTurboStatusChanged(): void {
        if (this.spinTurboIndex !== null) return;
        const sceneSpeed = SceneSpeedStore.get(GameConfigManager.GAMEID);
        if (sceneSpeed?.activationMode !== SceneSpeedActivationMode.GAME_WIDE) return;
        this.applyPlaybackSpeed(sceneSpeed.speedFactors[this.getTurboIndex()] ?? 1);
    }

    /**
     * DebugPanel 覆寫場景速度時套用新設定。
     *
     * @param sceneSpeed 覆寫值；沒有覆寫的欄位沿用 turbo 檔位的預設。
     */
    private onSceneSpeedChanged(sceneSpeed: SceneSpeedOverride): void {
        if (sceneSpeed.activationMode === SceneSpeedActivationMode.GAME_WIDE) {
            this.applyPlaybackSpeed(sceneSpeed.speedFactors[this.getTurboIndex()] ?? 1);
            return;
        }
        if (this.storeManager.getGameStore().spinStatus === GAMESTOREMAP.NEW_GAME) {
            this.resetPlaybackSpeed();
        }
    }

    /**
     * 消除落下演出的時長設定。只壓「過場／等待」，spine 演出本體不動；快轉／極速不再各自寫死一組節奏，
     * 改由「整體速度」倍率（見 applyPlaybackSpeed）等比縮放。public：供 Net/Task 系列呼叫。
     *
     * @returns 這一局用的時長；DebugPanel 有覆寫時以覆寫值為準。
     */
    public cascadeTiming(): CascadeTimingConfig {
        // 每次起轉／消除補格前才讀取：PM 透過 DebugPanel 調整的覆寫值 > reelConfig.json > ReelConfig.ts 的預設。
        // 預設只認 DEFAULT_REEL_CONFIG 一份，原本這裡另外寫死一組 fill／fillStagger，json 載不到時兩邊會對不上。
        // breath／fgDelay 不在 reelConfig.json 裡，固定寫在這裡。補牌前全盤抖完到開始落下原本有一段 gap
        // （2026-10-19 照參考影片量成 240ms），2026-10-20 拿掉，抖完立即掉落
        const reel = ReelTimingDebugStore.get(GameConfigManager.GAMEID) ?? DEFAULT_REEL_CONFIG;
        return {
            spinDuration: reel.spinDuration,
            startInterval: reel.startInterval,
            stopInterval: reel.stopInterval,
            breath: 500,
            winFx: reel.tier.winFx,
            fill: reel.tier.fill,
            fillStagger: reel.tier.fillStagger,
            fillEase: reel.tier.fillEase,
            fgDelay: 500,
            tenpai: reel.tenpaiDuration,
            miGoldSpineDelay: reel.miGoldSpineDelay,
            miGoldMiDelay: reel.miGoldMiDelay,
            miGoldFlyDelay: reel.miGoldFlyDelay,
            miGoldFlyDuration: reel.miGoldFlyDuration,
            miGoldStopDelay: reel.miGoldStopDelay,
            focusFadeOutSec: reel.focusFadeOutSec,
            fgEnterDelay: reel.fgEnterDelay
        };
    }

    /**
     * 按下 spin（主遊戲）或免費遊戲每局開頭：照基底的流程起轉機台，再讓轉輪當下就轉起來。
     *
     * 方法本體在共用的 SlotGameMain 基底；這裡只補轉輪起轉——不等伺服器回應，按下去就轉，結果
     * 回來後由 `runCascadeReels()` 逐欄停輪。基底只在機台閒置時才起轉，這裡跟著同一個條件。
     */
    public override onNormalSpin(): void {
        const wasIdle = this.slotMachineModel.state === SlotMachineState.IDLE;
        super.onNormalSpin();
        if (wasIdle) startReelSpin(this);
    }

    /** 收掉這一支自己建立的訂閱與快停點擊節點，並還原播放速度，其餘交給基底。 */
    public override onDestroy(): void {
        this.sceneSpeedUnsubscribe?.();
        this.sceneSpeedUnsubscribe = null;
        this.resetPlaybackSpeed();
        if (this.quickStopTouch?.isValid) this.quickStopTouch.destroy();
        this.quickStopTouch = null;
        super.onDestroy();
    }

    /**
     * 建立接快停點擊的全螢幕空白節點：放在遊戲畫面之上、操作列與彈窗之下，只在轉動中啟用。
     *
     * layer 要跟著父節點設：程式建出來的節點 layer 不會自動修正，Camera 遮罩會整個擋掉（坑 #3）。
     */
    private setupQuickStopTouch(): void {
        const parent = director.getScene()?.getComponentInChildren(GameRoot)?.gameNode;
        if (!parent?.isValid) {
            console.warn('[GameMain_1003] 找不到 GameRoot.gameNode，快停點擊節點沒建');
            return;
        }
        const node = new Node('QuickStopTouch');
        node.layer = parent.layer;
        node.addComponent(UITransform).setContentSize(10000, 10000);
        node.on(Node.EventType.TOUCH_START, () => this.requestQuickStop());
        node.active = false;
        parent.addChild(node);
        this.quickStopTouch = node;
    }

    // win bar 跑分（setWinBarNum/resetWinBar/clearWinBarScore/addWinBarScore/addWinBalance/
    // rollWinBalance）、shouldEnterFreeGame/updateFgUi
    // 方法本體都在共用的 SlotGameMain 基底
}
