import StoreManager from "../store/StoreManager";
import { GAMESTOREMAP } from "../store/StoreMap";
import AppAudio from "../audio/AppAudio";

/**
 * WinAnimationController（中獎連線演出全家族）
 *
 * 1001/1002 共用同一份邏輯，各遊戲透過 WinAnimationDeps 注入音效路徑。負責：
 * - playWinAnimations：篩出 line 類型中獎，播連線音效後停掉舊動畫，等一幀讓
 *   reel 完全停下，再對所有 view 播 playSymbolWins（viewH 的 Promise 當主要
 *   等待對象）。
 * - startWinCarousel：多筆中獎輪播——先單獨播完再全部一起播，循環直到
 *   stopAnimations() 或下一輪 spin 取消 token。
 * - runWinScore/stopWinScore：中獎分數與餘額同時逐幀跑分（tick-based tween），
 *   stopWinScore 可中途直接跳到最終值。
 * - stopAnimations：中止所有 view 的連線演出並凍結 reel spine timeScale。
 * - winPhaseAwait：讓中獎演繹任一 await 都能被 STOP 快捷鍵跳過。
 */

/**
 * WinAnimationController 只需要用到的中獎項目子集合。各遊戲自己的 AchieveItem
 * （`type`/`win`/`icon`/`amount` 等更多欄位）結構相容即可傳入——`slotMachineView`
 * 底下用方法簽章（非箭頭函式屬性）宣告，TypeScript 對介面方法採雙變數檢查，
 * 各遊戲實際的 `playSymbolWins(achieves: AchieveItem[], ...)` 因此能滿足這裡
 * 宣告的 `WinAchieveItem[]` 參數型別，不需要额外的泛型參數。
 */
export interface WinAchieveItem {
    type: string;
    line?: string;
    order?: number;
}

/** WinAnimationController 只需要用到的 View 子集合，各遊戲自己的 GameViewAdapter 結構相容即可傳入 */
export interface WinAnimationView {
    slotMachineView: {
        setSymbolSpinesTimeScale(scale: number): void;
        playSymbolWins(achieves: WinAchieveItem[], loop?: boolean): Promise<void>;
        stopAllSymbolWins(): void;
    } | null;
}

export interface WinAnimationDeps<TView extends WinAnimationView> {
    getViews: () => TView[];
    getViewH: () => TView;
    storeManager: StoreManager;
    /** 各遊戲自己 AudioConfig.EFFECTSMAP 裡對應的中獎連線音效路徑；空字串代表不播 */
    lineWinEffect: string;
    /** 傳入 GameMain 自己的 Component.scheduleOnce，保留原本的元件生命週期安全性 */
    scheduleOnce: (callback: () => void, delay?: number) => void;
}

export class WinAnimationController<TView extends WinAnimationView> {
    /** STOP 期間用：若不為 null 表示中獎演繹/跑分中，呼叫即跳過 */
    winPhaseSkipFn: (() => void) | null = null;

    private winAnimCancelToken: { cancelled: boolean } = { cancelled: false };
    private winScoreTargetWin: number = 0;
    private winScoreTargetBalance: number = 0;
    private winScoreResolve: (() => void) | null = null;
    private winScoreActive = false;
    private winScoreElapsed = 0;
    private winScoreDuration = 0;
    private winScoreStartWin = 0;
    private winScoreStartBalance = 0;
    private winScoreBalanceDiff = 0;

    /**
     * 排程借用 GameMain 自己的 `scheduleOnce`，計時跟著 GameMain 的生命週期，離開遊戲時一起停。
     *
     * @param deps 取得 View、store 與排程的依賴集合。
     */
    constructor(private deps: WinAnimationDeps<TView>) {}

    /**
     * 讓中獎演繹任一 await 都可被 STOP 跳過。
     *
     * @param promise 要等的演出；STOP 會讓回傳的 promise 提早 resolve，這支本身不會被中止。
     * @returns 演出結束或按下 STOP 時 resolve，以先到者為準。
     */
    winPhaseAwait(promise: Promise<void>): Promise<void> {
        return new Promise<void>((resolve) => {
            this.winPhaseSkipFn = resolve;
            // 若上一次 STOP 已將 spinStatus 設為 SPIN_END，重置為 TAKE_WIN，
            // 確保下次按 STOP 時 MobX 偵測到值變化而觸發 reaction
            const gameStore = this.deps.storeManager.getGameStore();
            if (gameStore.spinStatus === GAMESTOREMAP.SPIN_END) {
                gameStore.setSpinStatus(GAMESTOREMAP.TAKE_WIN);
            }
            promise.then(resolve);
        });
    }

    /**
     * 播這一局的中獎連線演出；沒有任何連線時直接返回。
     *
     * @param achieves 中獎項目，只取 type 為 'line' 的。
     * @returns 演出開始之後 resolve（輪播本身是持續進行的）。
     */
    async playWinAnimations(achieves: WinAchieveItem[]): Promise<void> {
        const lineAchieves = achieves.filter((a) => a.type === "line" && a.line);
        if (lineAchieves.length === 0) return;

        if (this.deps.lineWinEffect) AppAudio.getInstance().playEffect(this.deps.lineWinEffect);
        this.stopAnimations();

        // 等一個 frame 讓所有 view 的 reel 都完成 stop（避免 viewV 還在 step()）
        await new Promise<void>((r) => this.deps.scheduleOnce(r, 0.05));

        for (const v of this.deps.getViews()) {
            v.slotMachineView?.setSymbolSpinesTimeScale(1);
        }

        const viewH = this.deps.getViewH();
        let mainPromise: Promise<void> = Promise.resolve();
        for (const v of this.deps.getViews()) {
            const p = v.slotMachineView?.playSymbolWins(lineAchieves, false) ?? Promise.resolve();
            if (v === viewH) mainPromise = p;
        }
        return mainPromise;
    }

    /**
     * 依 order 依序輪播每一條中獎連線，播完一輪再從頭來。
     *
     * 用一個 cancel token 而不是 unschedule：輪播是靠遞迴排程串起來的，
     * stopAnimations() 只要把 token 標記成已取消，下一段就不會再排下去。
     *
     * @param lineAchieves 中獎的連線項目。
     */
    startWinCarousel(lineAchieves: WinAchieveItem[]): void {
        const token = { cancelled: false };
        this.winAnimCancelToken = token;

        const sorted = [...lineAchieves].sort((a, b) => (a.order ?? 0) - (b.order ?? 0));

        const wait = (sec: number) => new Promise<void>((r) => this.deps.scheduleOnce(r, sec));

        const viewH = this.deps.getViewH();
        const stopAll = () => {
            for (const v of this.deps.getViews()) v.slotMachineView?.stopAllSymbolWins();
        };
        const playAll = (achs: WinAchieveItem[]): Promise<void> => {
            let mainPromise: Promise<void> = Promise.resolve();
            for (const v of this.deps.getViews()) {
                const p = v.slotMachineView?.playSymbolWins(achs, false) ?? Promise.resolve();
                if (v === viewH) mainPromise = p;
            }
            return mainPromise;
        };
        const run = async () => {
            await wait(3);
            if (token.cancelled) return;

            while (!token.cancelled) {
                for (let i = 0; i < sorted.length; i++) {
                    if (token.cancelled) return;
                    stopAll();
                    await playAll([sorted[i]]);
                    if (token.cancelled) return;
                    await wait(1);
                    if (token.cancelled) return;
                }

                stopAll();
                await playAll(sorted);
                if (token.cancelled) return;
                await wait(1);
            }
        };
        run();
    }

    // 用 dt 累加 不用固定間隔 setTimeout 累加寫法能吃到 director hook 的加速縮放
    /**
     * 每幀推進中獎跑分（贏分與餘額同時跑）；沒有在跑分時直接返回。
     *
     * @param dt 距離上一幀的秒數。
     */
    update(dt: number): void {
        if (!this.winScoreActive) return;
        this.winScoreElapsed += dt;
        const ratio = this.winScoreDuration <= 0 ? 1 : Math.min(this.winScoreElapsed / this.winScoreDuration, 1);
        const userStore = this.deps.storeManager.getModel("UserStore");
        const templateStore = this.deps.storeManager.getModel("TemplateStore");
        const win = this.winScoreStartWin + (this.winScoreTargetWin - this.winScoreStartWin) * ratio;
        templateStore.setWinBalance(Number(win.toFixed(2)));
        userStore.setBalance(Number((this.winScoreStartBalance + this.winScoreBalanceDiff * ratio).toFixed(2)));
        if (ratio >= 1) {
            this.winScoreActive = false;
            const resolve = this.winScoreResolve;
            this.winScoreResolve = null;
            resolve?.();
        }
    }

    /**
     * 讓贏分與餘額同時跑分到目標值。重複呼叫會先結束上一次。
     *
     * @param totalWin 這一局的總贏分。
     * @param serverBalance 後端回傳的餘額（跑完直接對齊這個值，不自己累加）。
     * @param duration 跑分秒數。
     * @param startWin 贏分的起始值，預設 0。
     * @returns 跑完之後 resolve。
     */
    runWinScore(totalWin: number, serverBalance: number, duration: number, startWin: number = 0): Promise<void> {
        this.stopWinScore();
        this.winScoreTargetWin = totalWin;
        this.winScoreTargetBalance = serverBalance;
        const userStore = this.deps.storeManager.getModel("UserStore");
        const templateStore = this.deps.storeManager.getModel("TemplateStore");
        this.winScoreStartWin = startWin;
        this.winScoreStartBalance = userStore.balance;
        this.winScoreBalanceDiff = serverBalance - this.winScoreStartBalance;
        this.winScoreDuration = duration;
        this.winScoreElapsed = 0;
        templateStore.setWinBalance(Number(startWin.toFixed(2)));

        return new Promise<void>((resolve) => {
            if (duration <= 0) {
                templateStore.setWinBalance(Number(totalWin.toFixed(2)));
                userStore.setBalance(Number(serverBalance.toFixed(2)));
                resolve();
                return;
            }
            this.winScoreResolve = resolve;
            this.winScoreActive = true;
        });
    }

    /**
     * 立刻結束跑分並把贏分與餘額直接設成目標值。
     *
     * 一定要補寫最終值：中途停掉而不補的話畫面會停在半路的數字，
     * 跟後端實際餘額對不起來。
     */
    stopWinScore(): void {
        if (this.winScoreActive) {
            this.winScoreActive = false;
            const userStore = this.deps.storeManager.getModel("UserStore");
            const templateStore = this.deps.storeManager.getModel("TemplateStore");
            templateStore.setWinBalance(this.winScoreTargetWin);
            userStore.setBalance(this.winScoreTargetBalance);
            if (this.winScoreResolve) {
                this.winScoreResolve();
                this.winScoreResolve = null;
            }
        }
    }

    /**
     * 中止所有中獎演出：取消輪播、停掉符號動畫、結束跑分。
     */
    stopAnimations(): void {
        this.winAnimCancelToken.cancelled = true;
        for (const v of this.deps.getViews()) {
            // stopAllSymbolWins() 讓出中獎層之後，格子會自己把中獎用的顯示物件還回池裡、
            // 換回靜止外觀，沒有東西還在播——不必再額外凍結一次（同 GameMain_1003 的說明）。
            v.slotMachineView?.stopAllSymbolWins();
        }
    }
}
