import { _decorator, Layout, Node, ProgressBar } from 'cc';
import LoadingViewModel from './LoadingViewModel';
import { EventComponent } from '../../events/EventComponent';
import type { TypedEventBus } from '../../events/TypedEventBus';

const { ccclass, property } = _decorator;

/**
 * 進度條每秒最多前進多少（1 = 100%），所以從 0 跑到 100% 至少 1 秒。
 *
 * 重新選座後再進場，資源多半已經在快取裡，實際進度會瞬間跳到底；
 * 不限速的話 Loading 畫面一閃而過，看不出有在載入。
 */
const PROGRESS_MAX_SPEED = 1;

@ccclass('1003/LoadingView')
export class LoadingView extends EventComponent {
    /**
     * EventComponent.subscribeEvent 是 protected，這裡轉一層 public 供 LoadingViewModel 呼叫。
     * 訂閱掛在這個元件上，元件銷毀時一起解除。
     *
     * @param bus 要訂閱的事件匯流排。
     * @param type 事件種類。
     * @param handler 收到事件時呼叫。
     */
    public subscribeGameEvent<TEvents extends object, K extends keyof TEvents>(
        bus: TypedEventBus<TEvents>,
        type: K,
        handler: (payload: TEvents[K]) => void
    ): void {
        this.subscribeEvent(bus, type, handler);
    }

    @property(ProgressBar)
    progressBar: ProgressBar = null;

    @property(Node)
    tipH: Node = null;
    @property(Node)
    tipV: Node = null;

    viewModel: LoadingViewModel;

    isPortrait: boolean;
    verticalY = { logo: -630, progressBar: -585 };
    horizontalY = { logo: -320, progressBar: -265 };
    /** 畫面上顯示的進度，每幀往 targetProgress 追，速度上限 PROGRESS_MAX_SPEED */
    private displayProgress = 0;
    /** 實際載入回報的進度，只增不減 */
    private targetProgress = 0;
    /** fillToEnd() 等待中的回呼 */
    private fillWaiters: (() => void)[] = [];
    // fillToEnd 排的計時器
    private fillTimer: ReturnType<typeof setTimeout> | null = null;

    /** 進度條一律從 0 開始，不沿用 prefab 上存的值。 */
    protected override onLoad(): void {
        super.onLoad?.();
        this.progressBar.progress = 0;
    }
    /**
     * 建立這個畫面的 ViewModel。
     */
    protected override start(): void {
        this.viewModel = new LoadingViewModel(this);
    }
    /**
     * 更新目標進度，畫面上的進度條會平滑追上去。
     *
     * @param count 進度（0～1）；比目前小的值忽略，只增不減。
     */
    public updateProgress(count: number) {
        this.targetProgress = Math.min(1, Math.max(this.targetProgress, count));
    }

    /**
     * 把進度補滿，等畫面上的進度條真的跑到 100% 才 resolve。
     *
     * 元件被關掉時 update 不會跑，所以另外用 setTimeout 估算的時間兜底，不會永遠不 resolve。
     *
     * @returns 進度條跑滿之後 resolve。
     */
    public fillToEnd(): Promise<void> {
        this.targetProgress = 1;
        if (this.displayProgress >= 1) return Promise.resolve();
        return new Promise((resolve) => {
            this.fillWaiters.push(resolve);
            const remainingMs = ((1 - this.displayProgress) / PROGRESS_MAX_SPEED) * 1000;
            this.fillTimer = setTimeout(() => this.finishFill(), remainingMs + 500);
        });
    }

    /**
     * 每幀把顯示的進度往目標推進，跑滿時通知 fillToEnd() 的等待者。
     *
     * @param dt 這一幀的秒數。
     */
    protected override update(dt: number): void {
        if (this.displayProgress >= this.targetProgress) return;
        this.displayProgress = Math.min(this.targetProgress, this.displayProgress + PROGRESS_MAX_SPEED * dt);
        this.progressBar.progress = this.displayProgress;
        if (this.displayProgress >= 1) this.finishFill();
    }

    /** 進度條確定跑滿：補到 100% 並放行所有等待者，重複呼叫沒有副作用。 */
    private finishFill(): void {
        if (this.fillTimer !== null) clearTimeout(this.fillTimer);
        this.fillTimer = null;
        this.displayProgress = 1;
        if (this.progressBar?.isValid) this.progressBar.progress = 1;
        const waiters = this.fillWaiters;
        if (!waiters) return;
        this.fillWaiters = [];
        waiters.forEach((resolve) => resolve());
    }

    /** 畫面提早被銷毀也要放行等待者，GameRoot 才不會卡住。 */
    public override onDestroy(): void {
        this.finishFill();
        super.onDestroy();
    }
    /**
     * 依方向切換橫版／直版的提示文字。
     *
     * @param isPortrait 方向字串，'portrait' 代表直版。
     */
    checkPosition(isPortrait) {
        if (isPortrait !== 'portrait') {
            this.tipH.active = true;
            this.tipV.active = false;
            return;
        }
        this.tipH.active = false;
        this.tipV.active = true;
    }
}
