import { STEP_STATE, type SlotApiBoard, type SlotApiEvent, type SlotApiHistoryDetail, type SlotApiStep, type SlotApiSymbolChange } from './SlotApiTypes';
import type { SlotAward, SlotAwardPosition, SlotFreeEndReason, SlotFreeMultiplierStep, SlotFreeRetrigger, SlotFreeSpin, SlotJackpotResult, SlotResume, SlotRoundResult, SlotRoundStep, SlotRoundSteps } from '../models/SlotRound';
import type { SlotGridLayout } from '../models/SlotGrid';
import type { SlotBoardDamp } from './GridLayoutConfig';
import { SlotGridDecoder } from './SlotGridDecoder';
import { multiplyDecimal } from './SlotResponseAdapter';

/** 本款用到的事件代碼（渲染契約第 3 章、results-tycoonmahjong.md ⑥） */
const EVENT = {
    /** 播這張盤面的中獎 */
    WIN: 'WE',
    /** 原地改盤：`rsn` 是 `golden_flip` 時是金牌翻百搭 */
    SYMBOLS_CHANGED: 'SX',
    /** 觸發免費遊戲：`rd` 授的轉數 */
    FREE_ENTERED: 'FE',
    /** 湊滿 Scatter 但這一轉已經到上限，不進免費遊戲 */
    FREE_BLOCKED: 'FB',
    /** 免費遊戲再觸發：`awd` 加了幾轉、`tt` 加局後的總轉數 */
    RETRIGGER: 'RT',
    /** 單局上限截斷：`org` 截斷前、`cap` 截斷後的整局總額（底注倍數） */
    CAP: 'CA',
    /** 免費遊戲結束：`rsn` 是結束原因 */
    FREE_EXITED: 'FX',
} as const;

const NO_JACKPOT: SlotJackpotResult = { won: false, tier: '', payout: '0', currency: '' };

/**
 * 從步驟編號取局號：`{round_id}:{seq}:{index}` 第一個 `:` 前面那段（規格 §5.2）。
 *
 * @param stepId 步驟編號。
 * @returns 局號；沒有 `:` 時原樣回傳。
 */
export function roundIdOf(stepId: string): string {
    return stepId.split(':')[0];
}

/**
 * 玩家端 API 的盤面結果轉成前端模型 `SlotRoundResult`／`SlotFreeSpin`／`SlotRoundSteps` 的唯一轉換點。
 * Handler／Task／View 不得直接讀 SlotApiTypes。
 *
 * 一張盤面（`r.sg[]` 的一項）轉成一個 `SlotRoundStep`。bet 每一步只帶一張盤面（第一步是初盤 `B`，
 * 之後每次連消一張 `C`），所以盤面贏分直接用那一步的 `ctw`；history 的細單是一整轉、沒有逐步金額，
 * 改用盤面的 `bm`（底注倍數）乘底注換算。
 */
export class SlotRoundMapper {
    private readonly decoder: SlotGridDecoder;

    /**
     * @param layout 可見盤的形狀。
     * @param damp 每軸上下的 damp 格數。
     * @param amountScale 幣別小數位（entry 的 `cd`），換算出來的金額至少保留這麼多位。
     */
    constructor(
        layout: SlotGridLayout,
        damp: SlotBoardDamp,
        private readonly amountScale: number
    ) {
        this.decoder = new SlotGridDecoder(layout, damp);
    }

    /**
     * 主遊戲一轉（開局那步加上它的所有連消步）轉成 `SlotRoundResult`。
     *
     * 觸發免費遊戲時只帶授的轉數（`freeSpinsTotal`），免費遊戲每一轉在播放時才向後端要（{@link toSlotFreeSpin}）。
     *
     * @param steps 這一轉的步驟，依交付順序。
     * @param baseBet 底注金額（cs × ml × bb），把盤面上的底注倍數換成金額。
     * @returns 這一轉的結果；金額以後端給的 `tw`／`bl`／`tb` 為準。
     * @throws `steps` 是空陣列時丟出。
     */
    toSlotRoundResult(steps: readonly SlotApiStep[], baseBet: string): SlotRoundResult {
        const first = steps[0];
        const last = steps[steps.length - 1];
        if (!first || !last) throw new RangeError('SlotRoundMapper.toSlotRoundResult: no steps');

        const events = this.eventsOf(steps);
        const entered = findEvent(events, EVENT.FREE_ENTERED);
        const freeSpinTriggered = !!entered || last.nst === STEP_STATE.FREE_SPIN;
        return {
            operationId: roundIdOf(first.sid),
            betId: first.sid,
            totalWin: last.tw,
            rawEngineWin: last.tw,
            engineWin: last.tw,
            maxWin: this.toMaxWin(events, baseBet),
            balanceAfter: last.bl,
            outcome: Number(last.tw) > 0 ? 'won' : 'lost',
            freeRound: false,
            chargedWager: first.tb,
            jackpot: NO_JACKPOT,
            mainSteps: this.toSteps(steps, baseBet),
            freeRounds: [],
            freeSpinTriggered,
            freeMultipliers: [],
            freeRetriggers: [],
            // 1003 沒有整局倍率：階梯倍數在各 step 的 multiplier
            multiplier: 0,
            freeSpinsTotal: freeSpinTriggered ? toCount(entered?.d?.rd) || (last.fs?.ts ?? 0) : undefined,
            freeGameBlocked: !!findEvent(events, EVENT.FREE_BLOCKED),
        };
    }

    /**
     * 免費遊戲一轉（`st` 21 那步加上它的所有連消步）轉成 `SlotFreeSpin`。
     *
     * @param steps 這一轉的步驟，依交付順序。
     * @param baseBet 底注金額。
     * @returns 這一轉的結果；轉數以最後一步的 `fs` 為準（再觸發會讓總數增加）。
     * @throws `steps` 是空陣列時丟出。
     */
    toSlotFreeSpin(steps: readonly SlotApiStep[], baseBet: string): SlotFreeSpin {
        const last = steps[steps.length - 1];
        if (!last) throw new RangeError('SlotRoundMapper.toSlotFreeSpin: no steps');

        const events = this.eventsOf(steps);
        return {
            steps: this.toSteps(steps, baseBet),
            win: last.tw,
            awardedRounds: events.filter((e) => e.t === EVENT.RETRIGGER).reduce((sum, e) => sum + toCount(e.d?.awd), 0),
            remain: last.fs?.s ?? 0,
            total: last.fs?.ts ?? 0,
            finished: last.nst === STEP_STATE.BASE_SPIN,
            roundWin: last.aw,
            balance: last.bl,
            endReason: toEndReason(findEvent(events, EVENT.FREE_EXITED)?.d?.rsn),
        };
    }

    /**
     * 進場回應的最近一步 `ls` 轉成「進場要還原什麼」，entry 之後只呼叫一次（`HttpClientStore.applyEntry()`）。
     *
     * 輸出分兩塊，使用端各自取用：
     * - `grid`：進場盤面，取 `ls.r.sg` 最後一張（連消到一半斷線時，最後一張才是停下來的那一步）。沒玩過或上一局
     *   已結束時是後端的預設盤面；`ls.r` 為 null 或 `sg` 為空時是 null，使用端退回隨機盤面。
     * - `freeGame`：只有 `ls.nst` 是 `STEP_STATE.FREE_SPIN` 且有 `ls.fs` 時才有（免費遊戲打到一半，含剛觸發還沒打第一轉）。
     *   剩餘與總轉數取 `ls.fs`、贏分取 `ls.aw`。`result` 是收尾（`ExitFreeGameTask`）用的局資料，只有帳務欄位。
     *
     * 局打到一半（`isRoundInProgress(ls)`）但 `freeGame` 為 null，代表連消播到一半（`nst` 4／22）這種還沒支援續打的
     * 狀態，使用端只畫盤面並印警告。1003 沒有跨轉累積的倍數（`ls.gs.am` 恆為 `"0"`），所以不讀 `gs`。
     *
     * 結構照 1001／1002 的 `toResume()`（`docs/api-v8.1-遷移.md` §9.3「進場還原的結構」），差在解碼收 `board.rl`、
     * 沒有累積倍數與彩池。
     *
     * @param ls 進場回應的最近一步，永遠有值（沒玩過是後端合成的預設步驟）。
     * @returns 進場盤面與免費遊戲還原資料。
     * @throws 盤面每軸長度跟全窗格對不上時，由解碼器丟出；呼叫端要接住並退回隨機盤面。
     */
    toResume(ls: SlotApiStep): SlotResume {
        const boards = ls.r?.sg ?? [];
        const board = boards[boards.length - 1];
        const grid = board ? this.decoder.decode(board.rl) : null;
        const fs = ls.fs;
        if (ls.nst !== STEP_STATE.FREE_SPIN || !fs) return { grid, freeGame: null };

        const result: SlotRoundResult = {
            operationId: roundIdOf(ls.sid),
            betId: ls.sid,
            totalWin: ls.aw,
            rawEngineWin: ls.aw,
            engineWin: ls.aw,
            maxWin: { applied: false, multiplier: '', capAmount: '' },
            balanceAfter: ls.bl,
            outcome: Number(ls.aw) > 0 ? 'won' : 'lost',
            freeRound: false,
            chargedWager: ls.tb,
            jackpot: NO_JACKPOT,
            mainSteps: [],
            freeRounds: [],
            freeSpinTriggered: true,
            freeMultipliers: [],
            freeRetriggers: [],
            multiplier: 0,
            freeSpinsTotal: fs.ts,
            freeGameBlocked: false,
        };
        return { grid, freeGame: { total: fs.ts, remain: fs.s, totalWin: ls.aw, result } };
    }

    /**
     * 單局重播的細單轉成 `SlotRoundSteps`。每張細單是一整轉（`result.sg` 是這一轉各步的盤面依序接起來），
     * 第一張是主遊戲，其餘是免費遊戲各轉。
     *
     * @param details 細單，順序不拘（照 `seq` 排）。
     * @param baseBet 母單的 `base_bet_amount`。
     * @returns 主遊戲與各轉免費遊戲的盤面、免費遊戲逐轉的贏分與加局。
     */
    toRoundSteps(details: readonly SlotApiHistoryDetail[], baseBet: string): SlotRoundSteps {
        const sorted = [...details].sort((a, b) => a.seq - b.seq);
        const [main, ...free] = sorted;
        const mainBoards = main?.result?.sg ?? [];
        const freeBoards = free.map((detail) => detail.result?.sg ?? []);
        return {
            mainSteps: mainBoards.map((board) => this.toStep(board, this.boardWin(board, baseBet), baseBet)),
            freeRounds: freeBoards.map((boards) => boards.map((board) => this.toStep(board, this.boardWin(board, baseBet), baseBet))),
            freeSpinTriggered: free.length > 0 || mainBoards.some((board) => findEvent(board.e ?? [], EVENT.FREE_ENTERED)),
            freeMultipliers: free.map((detail, round) => this.toFreeMultiplier(detail, round)),
            freeRetriggers: freeBoards.map((boards, round) => toRetrigger(boards.flatMap((board) => board.e ?? []), round)),
            multiplier: 0,
        };
    }

    /**
     * 把幾個步驟的盤面依序攤平成 step。每步只有一張盤面時贏分用這一步的 `ctw`；
     * 一步有好幾張（目前不會發生）時改用各盤面的 `bm` 換算，避免同一筆 `ctw` 被算兩次。
     *
     * @param steps 步驟。
     * @param baseBet 底注金額。
     * @returns 依序的 step；`r` 是 null 的步驟沒有盤面可畫，略過（規格：不要自己產生盤面）。
     */
    private toSteps(steps: readonly SlotApiStep[], baseBet: string): SlotRoundStep[] {
        return steps.flatMap((step) => {
            const boards = step.r?.sg ?? [];
            if (boards.length === 1) return [this.toStep(boards[0], step.ctw, baseBet)];
            return boards.map((board) => this.toStep(board, this.boardWin(board, baseBet), baseBet));
        });
    }

    /**
     * 一張盤面轉成一個 step。
     *
     * @param board 盤面。
     * @param win 這張盤面的贏分金額。
     * @param baseBet 底注金額，把中獎的底注倍數換成金額。
     * @returns 對應的 step；中獎、翻牌的位置已換成可見盤座標。
     */
    private toStep(board: SlotApiBoard, win: string, baseBet: string): SlotRoundStep {
        const ladder = board.ov?.ld;
        const goldenFlips = (board.e ?? [])
            .filter((e) => e.t === EVENT.SYMBOLS_CHANGED && e.d?.rsn === 'golden_flip')
            .flatMap((e) => ((e.d?.ch as SlotApiSymbolChange[] | undefined) ?? []).map((change) => change.c));
        return {
            grid: this.decoder.decode(board.rl),
            awards: (board.wn ?? []).map(
                (win): SlotAward => ({
                    symbolId: win.sy,
                    count: win.l ?? 0,
                    positions: this.toCells(board, win.c),
                    pay: multiplyDecimal(win.w, baseBet, this.amountScale),
                })
            ),
            win,
            multiplier: ladder?.v,
            ladderIndex: ladder?.i,
            goldenFlips: goldenFlips.length > 0 ? this.toCells(board, goldenFlips) : undefined,
        };
    }

    /**
     * 一張盤面的贏分金額：`bm`（底注倍數）× 底注。沒有中獎的盤面不帶 `bm`，視為 0。
     *
     * @param board 盤面。
     * @param baseBet 底注金額。
     * @returns 贏分金額。
     */
    private boardWin(board: SlotApiBoard, baseBet: string): string {
        return multiplyDecimal(board.bm ?? '0', baseBet, this.amountScale);
    }

    /**
     * 格子位置換成可見盤座標，落在 damp 上的略過。
     *
     * @param board 位置所在的盤面。
     * @param positions 格子位置。
     * @returns 可見盤座標。
     */
    private toCells(board: SlotApiBoard, positions: readonly number[]): SlotAwardPosition[] {
        return positions.flatMap((position) => this.decoder.toCell(board.rl, position) ?? []);
    }

    /**
     * 單局上限截斷（`CA`）轉成前端的 maxWin。
     *
     * @param events 這一轉的事件。
     * @param baseBet 底注金額。
     * @returns 有 `CA` 時 applied 為 true，`multiplier` 是截斷後的底注倍數、`capAmount` 是換算的金額。
     */
    private toMaxWin(events: readonly SlotApiEvent[], baseBet: string): SlotRoundResult['maxWin'] {
        const cap = findEvent(events, EVENT.CAP)?.d?.cap;
        if (cap === undefined) return { applied: false, multiplier: '', capAmount: '' };
        return { applied: true, multiplier: String(cap), capAmount: multiplyDecimal(String(cap), baseBet, this.amountScale) };
    }

    /**
     * 免費遊戲一轉的贏分與這一轉走到的階梯值。
     *
     * @param detail 細單。
     * @param round 第幾轉（0 起算）。
     * @returns 贏分取細單的 `payout_amount`；倍數取最後一張盤面的階梯值。
     */
    private toFreeMultiplier(detail: SlotApiHistoryDetail, round: number): SlotFreeMultiplierStep {
        const boards = detail.result?.sg ?? [];
        const ladder = boards[boards.length - 1]?.ov?.ld?.v ?? 0;
        return { round, multiplier: ladder, accumulated: ladder, win: detail.payout_amount };
    }

    /**
     * 收集幾個步驟裡所有盤面的事件，依播放順序。
     *
     * @param steps 步驟。
     * @returns 事件。
     */
    private eventsOf(steps: readonly SlotApiStep[]): SlotApiEvent[] {
        return steps.flatMap((step) => (step.r?.sg ?? []).flatMap((board) => board.e ?? []));
    }
}

/**
 * 找第一個指定代碼的事件。
 *
 * @param events 事件。
 * @param type 事件代碼。
 * @returns 找到的事件；沒有時 undefined。
 */
function findEvent(events: readonly SlotApiEvent[], type: string): SlotApiEvent | undefined {
    return events.find((e) => e.t === type);
}

// 事件裡的結束原因 不認得的值當沒給
function toEndReason(value: unknown): SlotFreeEndReason | null {
    return value === 'spins_done' || value === 'cap_stop' ? value : null;
}

/**
 * 事件 `d` 裡的轉數欄位轉成整數。
 *
 * @param value 欄位值。
 * @returns 非負整數；不是數字時 0。
 */
function toCount(value: unknown): number {
    const count = Number(value);
    return Number.isFinite(count) && count > 0 ? Math.floor(count) : 0;
}

/**
 * 免費遊戲一轉的加局（`RT`）。
 *
 * @param events 這一轉的事件。
 * @param round 第幾轉（0 起算）。
 * @returns 加局結果；沒有 `RT` 時視為沒加局。
 */
function toRetrigger(events: readonly SlotApiEvent[], round: number): SlotFreeRetrigger {
    const retrigger = findEvent(events, EVENT.RETRIGGER);
    return {
        round,
        triggered: !!retrigger,
        awardedRounds: toCount(retrigger?.d?.awd),
        totalRoundsAfter: toCount(retrigger?.d?.tt),
    };
}
