import type { sp } from 'cc';
import type { GameViewAdapter } from './GameViewAdapter';
import { trySetAnimation } from '../utils/SpineSafe';

/**
 * 免費遊戲轉輪兩側的霓虹框（`GameViewH/FG/skeleton`，`spine/skeleton.json`）。
 *
 * | 時機 | 動畫 | 呼叫端 |
 * |---|---|---|
 * | 進 FG（含斷線重進 FG） | `fg_idle` 循環 | `GameMain_1003.applyGameModeUi()` |
 * | 連鎖每一段開始演出中獎符號 | `fg_win` 播一次，播完接回 `fg_idle` | `CascadeReelsTask.runCascadeReels()` |
 * | 加局，局數跳上去那一刻 | `fg_win_sc_plus` 播一次，播完接回 `fg_idle` | `PlayFreeRoundTask.playRetrigger()` |
 * | 這一局的報獎結束、下一局 spin 開始前 | 還停在那兩支的切回 `fg_idle`（保險） | `PlayFreeRoundTask.run()` |
 *
 * 節點在 `FG` 底下、跟著 `fgNode` 開關，主遊戲期間不顯示也不更新，所以不用另外停；每次進 FG 都從頭
 * 重播 `fg_idle`，不接在上次離開時的進度上。
 *
 * 美術動效清單 #45／#46 寫「中獎時／加局時，播放一次」（各 0.5 秒）。2026-10-29 前兩支都是循環，`fg_win`
 * 一直播到這一局的報獎結束、`fg_win_sc_plus` 一直播到下一局 spin 前。現在連鎖每一段中獎都從頭播一次；
 * 中獎開始的時間點跟 FG 人物的 win 同一刻（`CharacterPerformance`）。
 *
 * **只有橫版有**（直版沒有 FG 節點），單一個 view 沒接是正常的；每一個 view 都沒接才是漏接，
 * 那種情況印一次警告。
 */

/** 常駐動畫 */
const IDLE_ANIM = 'fg_idle';
/** 贏分，每段中獎播一次，播完接回 {@link IDLE_ANIM} */
const WIN_ANIM = 'fg_win';
/** 加局，局數跳上去時播一次，播完接回 {@link IDLE_ANIM} */
const RETRIGGER_ANIM = 'fg_win_sc_plus';

/** 漏接警告只印一次：每段中獎都會走到，每次印會把 console 洗掉 */
let warnedMissing = false;

/**
 * 收集所有 view 上有接的霓虹框，每一個 view 都沒接時警告一次。
 *
 * @param views 通常是 `game.allViews`。
 * @returns 有接且有效的 spine。
 */
function collectSkeletons(views: readonly GameViewAdapter[]): sp.Skeleton[] {
    const found = views.map((view) => view.fgReelFxSkel).filter((skeleton): skeleton is sp.Skeleton => !!skeleton?.isValid);
    if (found.length === 0 && !warnedMissing) {
        warnedMissing = true;
        console.warn('[FgReelFx] 沒有任何 view 接上霓虹框：Game.prefab 的 GameViewAdapter 上 fgReelFxSkel 是空的');
    }
    return found;
}

/**
 * 取這支 spine 第 0 軌正在播的動畫名稱。
 *
 * @param skeleton 要查的 spine。
 * @returns 動畫名稱；沒在播時回 null。
 */
function currentAnim(skeleton: sp.Skeleton): string | null {
    return skeleton.getCurrent(0)?.animation?.name ?? null;
}

/**
 * 進 FG：從頭循環播 {@link IDLE_ANIM}。
 *
 * @param views 通常是 `game.allViews`。
 */
export function playFgReelFxIdle(views: readonly GameViewAdapter[]): void {
    for (const skeleton of collectSkeletons(views)) trySetAnimation(skeleton, IDLE_ANIM, true, 'FgReelFx.idle');
}

/**
 * 從頭播一次指定動畫，播完接回 {@link IDLE_ANIM} 循環。
 *
 * @param skeleton 霓虹框 spine。
 * @param anim 要播一次的動畫。
 * @param tag 播放失敗時印在 warn 裡的來源標記。
 */
function playOnceThenIdle(skeleton: sp.Skeleton, anim: string, tag: string): void {
    if (trySetAnimation(skeleton, anim, false, tag)) skeleton.addAnimation(0, IDLE_ANIM, true, 0);
}

/**
 * 免費遊戲贏分：從頭播一次 {@link WIN_ANIM}，播完接回 idle。
 *
 * 連鎖每一段中獎都會呼叫，每一段都從頭播。
 *
 * @param views 通常是 `game.allViews`。
 */
export function playFgReelFxWin(views: readonly GameViewAdapter[]): void {
    for (const skeleton of collectSkeletons(views)) playOnceThenIdle(skeleton, WIN_ANIM, 'FgReelFx.win');
}

/**
 * 這一局的贏分階段結束：還停在 {@link WIN_ANIM} 的切回 {@link IDLE_ANIM}，其他的不動。
 *
 * `fg_win` 只播一次、播完自己接回 idle，正常流程走到這裡時早就播完了；這支只是保險，萬一還停在
 * `fg_win`（例如接 idle 失敗）才切回去。
 *
 * @param views 通常是 `game.allViews`。
 */
export function stopFgReelFxWin(views: readonly GameViewAdapter[]): void {
    for (const skeleton of collectSkeletons(views)) {
        if (currentAnim(skeleton) === WIN_ANIM) trySetAnimation(skeleton, IDLE_ANIM, true, 'FgReelFx.idle');
    }
}

/**
 * 加局：從頭播一次 {@link RETRIGGER_ANIM}，播完接回 idle。
 *
 * @param views 通常是 `game.allViews`。
 */
export function playFgReelFxRetrigger(views: readonly GameViewAdapter[]): void {
    for (const skeleton of collectSkeletons(views)) playOnceThenIdle(skeleton, RETRIGGER_ANIM, 'FgReelFx.retrigger');
}

/**
 * 加局階段結束（下一局 spin 開始前）：還停在 {@link RETRIGGER_ANIM} 的切回 {@link IDLE_ANIM}，其他的不動。
 *
 * 跟 {@link stopFgReelFxWin} 一樣只是保險，正常流程走到這裡時 `fg_win_sc_plus` 早就播完、接回 idle 了。
 *
 * @param views 通常是 `game.allViews`。
 */
export function stopFgReelFxRetrigger(views: readonly GameViewAdapter[]): void {
    for (const skeleton of collectSkeletons(views)) {
        if (currentAnim(skeleton) === RETRIGGER_ANIM) trySetAnimation(skeleton, IDLE_ANIM, true, 'FgReelFx.idle');
    }
}
