import type { SlotGrid } from './SlotGrid';

/** 中獎位置 已對齊 SlotGrid 的 canonical row（buffer 已移除，跟 grid.columns[].symbolIds 同一套座標） */
export interface SlotAwardPosition {
    readonly col: number;
    readonly row: number;
}

export interface SlotAward {
    readonly symbolId: number;
    readonly count: number;
    readonly positions: readonly SlotAwardPosition[];
    readonly pay: string;
}

export interface SlotRoundStep {
    readonly grid: SlotGrid;
    readonly awards: readonly SlotAward[];
    readonly win: string;
    /**
     * 這個 step 套用的階梯倍數（有這種玩法的遊戲才有值，例如 1003 的 1/2/3/5 與 2/4/6/10）。
     * `win` 已經乘過它，這裡只是給 UI 顯示數字用，不要再拿去乘一次。
     */
    readonly multiplier?: number;
    /** 階梯走到第幾格（0 起算），對應後端盤面標記 `ld.i` */
    readonly ladderIndex?: number;
    /**
     * 這張盤面中獎後翻成百搭的金牌（後端 `SX` 事件，`rsn` 是 `golden_flip`）。`grid` 還是翻牌前的樣子，
     * 翻成的百搭在下一個 step 的盤面才看得到。演出目前照盤面自己推，這裡給對照與之後改用。
     */
    readonly goldenFlips?: readonly SlotAwardPosition[];
}

/**
 * 免費遊戲某一局的再觸發加局結果（GDD 4.3：局中再湊滿 3 顆 Scatter 可以加局）。
 * 來源是那一轉終盤的 `RT` 事件，沒有 `RT` 視為沒有加局。
 */
export interface SlotFreeRetrigger {
    /** 第幾局（0 起算），對齊 freeRounds 的索引 */
    readonly round: number;
    readonly triggered: boolean;
    /** 這一局加到的局數；沒加局時為 0 */
    readonly awardedRounds: number;
    /** 這一局結束後的免費遊戲總局數 */
    readonly totalRoundsAfter: number;
}

export interface SlotFreeMultiplierStep {
    readonly round: number;
    readonly multiplier: number;
    readonly accumulated: number;
    readonly win: string;
}

/** 中性的 JP 等級名稱 */
export type SlotJackpotTier = 'mini' | 'minor' | 'major' | 'grand';

export interface SlotJackpotResult {
    readonly won: boolean;
    readonly tier: SlotJackpotTier | '';
    readonly payout: string;
    readonly currency: string;
}

/** Main／Free 局的 Grid／Awards 解碼結果，跟「這是哪次 spin」無關，History Detail 沒有 spin 信封欄位時也能重用 */
export interface SlotRoundSteps {
    readonly mainSteps: readonly SlotRoundStep[];
    readonly freeRounds: readonly (readonly SlotRoundStep[])[];
    readonly freeSpinTriggered: boolean;
    readonly freeMultipliers: readonly SlotFreeMultiplierStep[];
    /**
     * 免費遊戲逐局的加局結果，索引對齊 freeRounds。
     * `freeRounds` 本身已經包含加到的那幾局，所以進場時要顯示的「初始局數」是
     * `freeRounds.length` 減掉所有 `awardedRounds`，不是直接拿長度。
     */
    readonly freeRetriggers: readonly SlotFreeRetrigger[];
    /** 這一局的整體倍率 */
    readonly multiplier: number;
}

/** Spin 一局的正規化結果 後端格式無關 Handler／Task／Controller／Presentation 只認這個型別 */
export interface SlotRoundResult extends SlotRoundSteps {
    readonly operationId: string;
    readonly betId?: string;
    readonly totalWin: string;
    readonly rawEngineWin: string;
    readonly engineWin: string;
    readonly maxWin: {
        readonly applied: boolean;
        readonly multiplier: string;
        readonly capAmount: string;
    };
    readonly balanceAfter: string;
    readonly outcome: 'won' | 'lost';
    readonly freeRound: boolean;
    readonly chargedWager: string;
    readonly jackpot: SlotJackpotResult;
    /**
     * 觸發免費遊戲時授的轉數（`FE` 的 `rd`）。有值代表免費遊戲要一轉一轉向後端要（{@link SlotFreeSpin}），
     * 這時 `freeRounds` 是空的；沒觸發時 undefined。
     */
    readonly freeSpinsTotal?: number;
    /** 盤面湊滿 Scatter，但這一轉贏分已經達到單局上限，不進免費遊戲（後端 `FB` 事件） */
    readonly freeGameBlocked: boolean;
}

// 免費遊戲結束原因 spins_done 排程打完 cap_stop 達到上限
export type SlotFreeEndReason = 'spins_done' | 'cap_stop';

/** 免費遊戲的一轉（開頭那步加上它的所有連消步），播完這一轉才向後端要下一轉 */
export interface SlotFreeSpin {
    readonly steps: readonly SlotRoundStep[];
    /** 這一轉的贏分（最後一步的 `tw`） */
    readonly win: string;
    /** 這一轉再觸發加的轉數（`RT` 的 `awd`）；沒加局是 0 */
    readonly awardedRounds: number;
    /** 這一轉結束時的剩餘轉數（`fs.s`） */
    readonly remain: number;
    /** 這一轉結束時的總轉數（`fs.ts`） */
    readonly total: number;
    /** 局在這一轉結束（`nst` 是 1）；撞上限提早結束時 `remain` 可能大於 0 */
    readonly finished: boolean;
    /** 整局到這一轉為止的累計贏分（`aw`）；`finished` 時就是整局實際派彩 */
    readonly roundWin: string;
    /** 這一轉之後要顯示的餘額；局還沒結束時是開局扣款後的值 */
    readonly balance: string;
    /** 局在這一轉結束時的原因（`FX` 的 `rsn`）；沒結束或後端沒給時為 null */
    readonly endReason: SlotFreeEndReason | null;
}

/**
 * 免費遊戲打到一半時，進場要還原的資料（來源是 entry 的 `ls`）。
 *
 * 1003 沒有跨轉累積的倍數（`ls.gs.am` 恆為 `"0"`），所以不像 1001／1002 帶 `accumulated`。
 */
export interface SlotFreeResume {
    /** 總轉數（`ls.fs.ts`） */
    readonly total: number;
    /** 剩餘轉數（`ls.fs.s`） */
    readonly remain: number;
    /** 整局到停下那一步為止的累計贏分（`ls.aw`） */
    readonly totalWin: string;
    /** 收尾（`ExitFreeGameTask`）用的局資料：只有帳務欄位，沒有任何盤面步驟 */
    readonly result: SlotRoundResult;
}

/** 進場時要還原的畫面資料，`SlotRoundMapper.toResume()` 產生 */
export interface SlotResume {
    /** 進場盤面；後端沒給（`ls.r` 為 null 或沒有盤面）時為 null，使用端退回隨機盤面 */
    readonly grid: SlotGrid | null;
    /** 免費遊戲打到一半時才有 */
    readonly freeGame: SlotFreeResume | null;
}
