import { _decorator, Component, Label, Node } from 'cc';
import StoreManager from '../../store/StoreManager';
import { AlertView } from './AlertView';
const { ccclass, property } = _decorator;

@ccclass('1003/StoreAlertView')
export class StoreAlertView extends AlertView {

    @property(Node)
    cancelBtn: Node = null;
    @property(Node)
    btnLayout: Node = null
    /**
     * 後端沒給儲值網址時，把「前往儲值」那排按鈕換成單顆取消鈕。
     *
     * 沒有網址卻留著儲值鈕的話，玩家按下去只會開一個空白分頁。
     */
    protected override onLoad(): void {
        super.onLoad();
        if (!StoreManager.getInstance().getGameStore().cashierURL) {
            this.cancelBtn.active = true;
            this.btnLayout.active = false;
        }
    }
    /**
     * 在目前分頁開啟儲值頁。
     */
    showStore() {
        window.open(StoreManager.getInstance().getGameStore().cashierURL, '_self');
    }
}
