    spinSpeed: { min: 5, max: 60, step: 1 },
    spinDuration: { min: 0, max: 5, step: 0.05 },
    bounceDuration: { min: 0.02, max: 1, step: 0.01 },
    stopBounceHeight: { min: 0, max: 0.3, step: 0.01 },
    stopBounceUp: { min: 0, max: 0.5, step: 0.01 },
    stopBounceDown: { min: 0, max: 0.5, step: 0.01 },
    scatterSoundLead: { min: 0, max: 1, step: 0.01 },
    startInterval: { min: 0, max: 0.5, step: 0.01 },
    stopInterval: { min: 0, max: 0.5, step: 0.01 },
    tenpaiDuration: { min: 0, max: 5, step: 0.05 },
    miGoldSpineDelay: { min: 0, max: 5, step: 0.05 },
