    /**
     * 讀出「恢復預設」的目標與目前生效的值給 UI 顯示；不在這裡套到轉輪——套用時機交給 SlotGameMain
     * 在每次 spin 開始前處理。
     *
     * 預設值就是遊戲啟動時載入的 reelConfig.json（GameMain.gameInit() 呼叫 setLocalDefault() 設定），
     * 「恢復預設」才會永遠對齊目前的 reelConfig.json，不用手動同步兩份。面板可能比那份 json 早畫出來，
     * 還沒載入時先拿 ReelConfig.ts 的靜態常數頂著、不記成已載入，下次重畫再讀一次。
     */
    private ensureReelTimingLoaded(): void {
        if (this.reelTimingLoaded) return;
        const localDefault = ReelTimingDebugStore.getLocalDefault(REEL_TIMING_GAME_ID);
        this.reelTimingDefault = localDefault ?? DEFAULT_REEL_CONFIG;
        this.reelTiming = ReelTimingDebugStore.get(REEL_TIMING_GAME_ID) ?? this.reelTimingDefault;
        this.reelTimingLoaded = localDefault !== null;
    }

    /** 只存進 ReelTimingDebugStore，不直接套到場上轉輪——下次 spin 開始前由 SlotGameMain 讀取套用 */
    private saveReelTiming(): void {
        ReelTimingDebugStore.set(REEL_TIMING_GAME_ID, this.reelTiming);
        console.log(`[DebugPanel] 轉輪節奏已存進 ReelTimingDebugStore（key="${REEL_TIMING_GAME_ID}"）`, this.reelTiming);
    }

    // ─── 整體速度（PM 線上調整用）───

    /**
     * 讀出整體速度「恢復預設」的目標與目前生效的值給 UI 顯示。
     *
     * 基準值優先用遊戲啟動時已載入的 reelConfig.json 本地端預設值，確保「恢復預設」永遠對齊目前的 reelConfig.json。
     * 跟 {@link ensureReelTimingLoaded} 一樣，json 還沒載入時先拿 SceneSpeedConfig.ts 的常數頂著、不記成已載入，
     * 下次重畫再讀一次——不然面板會一直停在常數，拖滑桿或匯出時還會把常數當成目前的值寫出去。
     */
    private ensureSceneSpeedLoaded(): void {
        if (this.sceneSpeedLoaded) return;
        const localDefault = SceneSpeedStore.getLocalDefault(SCENE_SPEED_GAME_ID);
        const base = localDefault ?? DEFAULT_SCENE_SPEED_CONFIG;
        this.sceneSpeedDefault = { ...base, speedFactors: [...base.speedFactors] as [number, number, number] };
        this.sceneSpeed = SceneSpeedStore.get(SCENE_SPEED_GAME_ID) ?? this.sceneSpeedDefault;
        this.sceneSpeedLoaded = localDefault !== null;
    }

    /** 存進 SceneSpeedStore 並通知 GameMain 依生效模式處理 */
    private saveSceneSpeed(): void {
        SceneSpeedStore.set(SCENE_SPEED_GAME_ID, this.sceneSpeed);
        console.log(`[DebugPanel] 整體速度已存進 SceneSpeedStore（key="${SCENE_SPEED_GAME_ID}"）`, this.sceneSpeed);
    }

    /**
     * 「轉輪節奏」區塊的恢復預設：轉輪節奏與整體速度一起回到 reelConfig.json，最後重畫一次面板。
     *
     * 兩邊都是清掉本次調整，而不是把預設值再 set 一次：store 裡沒有覆寫值，之後讀到的就一直是
     * reelConfig.json 本身，不會留下一份當下的副本。
     */
    private resetReelConfig(): void {
        if (this.reelTimingDefault) {
            ReelTimingDebugStore.clear(REEL_TIMING_GAME_ID);
            this.reelTiming = { ...this.reelTimingDefault, tier: { ...this.reelTimingDefault.tier } };
        }
        if (this.sceneSpeedDefault) {
            SceneSpeedStore.clear(SCENE_SPEED_GAME_ID);
            this.sceneSpeed = { ...this.sceneSpeedDefault, speedFactors: [...this.sceneSpeedDefault.speedFactors] as [number, number, number] };
        }
        console.log(`[DebugPanel] 轉輪節奏與整體速度已恢復為 reelConfig.json`, { reelTiming: this.reelTiming, sceneSpeed: this.sceneSpeed });
        this.render();
    }

    /**
     * 「轉輪節奏」區塊的匯出：把目前的轉輪節奏與整體速度存成一份 JSON 下載，PM 調好之後整份貼回
     * reelConfig.json——面板的調整只留在記憶體，不匯出貼回去，重新載入就沒了。
     */
    private exportReelConfig(): void {
        // 跟整體速度共用同一份 reelConfig.json，匯出時一併帶上 speedFactors
        const payload = { ...this.reelTiming, speedFactors: this.sceneSpeed.speedFactors, speedActivationMode: this.sceneSpeed.activationMode, exportedAt: new Date().toISOString() };
        const blob = new Blob([JSON.stringify(payload, null, 2)], { type: 'application/json' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `reel-timing-1003-${Date.now()}.json`;
        document.body.appendChild(a);
        a.click();
        a.remove();
        URL.revokeObjectURL(url);
    }

