    /**
     * 治具：在目前方向的盤面播一次免費遊戲第三軸的金牌轉換，不用進免費遊戲。
     *
     * 照正式流程（`CascadeReelsTask.runMiGoldConversion()`）的時間點，用同一支 `startMiGoldConversion()`：第三軸起轉後，
     * spine（沒接就跳過）→ 瞇牌特效 → 金牌飛入依轉輪節奏的時間點依序接續 → 金牌排好後第三軸停輪，準備停輪時收掉瞇牌特效。
     * 差別是只轉第三軸、不壓黑、只演目前方向那一台（見 {@link runMiGoldIntroPreview}）。
     *
     * 第三軸停回起轉前那一盤，盤面不會被治具改掉；金牌逐列避開那一盤，跟正式流程避開結果一樣。
     *
     * @param holdSec 金牌排好之後停幾秒才往下滑；不給時用正式流程的停頓。
     */
    private testMiGoldIntro(holdSec?: number): void {
        if (this.goldIntroPreviewRunning) {
            console.warn('[DebugPanel] 金牌轉換演示還在播，播完再按');
            return;
        }
        const adapter = this.resolveActiveAdapter();
        const machine = adapter?.slotMachineView;
        const reel = machine?.reelViews[MI_REEL_INDEX];
        if (!adapter || !machine || !reel) {
            console.warn('[DebugPanel] 找不到目前顯示中的第三軸');
            return;
        }
        if (reel.isReelSpinning() || !reel.startSpin(0)) {
            console.warn('[DebugPanel] 第三軸轉動中，停下來再演示');
            return;
        }

        // 只有第三軸在轉，正式流程的「第一軸準備停輪」在這裡就是第三軸自己；淡出秒數跟正式流程同一個值
        const fadeSec = (ReelTimingDebugStore.get(REEL_TIMING_GAME_ID) ?? DEFAULT_REEL_CONFIG).focusFadeOutSec;
        const disposeMiHide = reel.model.events.on('stateChanged', ({ state }) => {
            if (state === ReelState.STOPPING) hideMiEffect([adapter], fadeSec);
        });

        this.goldIntroPreviewRunning = true;
        this.runMiGoldIntroPreview(adapter, reel, holdSec)
            .catch((error) => console.warn('[DebugPanel] 金牌轉換演示失敗', error))
            .finally(() => {
                disposeMiHide();
                hideMiEffect([adapter], fadeSec);
                this.goldIntroPreviewRunning = false;
            });
    }

    /**
     * {@link testMiGoldIntro} 的演出本體，第三軸已經起轉。時間點照正式流程，讀轉輪節奏的 miGold* 五個值
     * （覆寫值 > `reelConfig.json` > 預設值）：spine → 瞇牌特效 → 金牌飛入依序接續，金牌排好後 `miGoldStopDelay` 秒停輪，
     * 停輪不看輪轉時長。spine 還沒播完時等它播完才結束。
     *
     * 「飛入後停 2 秒」是對位置用的，等金牌滑完才停輪：照正常的停輪延遲，第三軸會停在還沒滑走的金牌底下。
     *
     * @param adapter 目前方向的 view。
     * @param reel 第三軸。
     * @param holdSec 金牌排好之後停幾秒才往下滑；不給時用正式流程的停頓。
     * @returns 第三軸停回原盤、金牌滑完、spine 播完之後 resolve。
     */
    private async runMiGoldIntroPreview(adapter: GameViewAdapter, reel: ReelView_1003, holdSec?: number): Promise<void> {
        const timing = ReelTimingDebugStore.get(REEL_TIMING_GAME_ID) ?? DEFAULT_REEL_CONFIG;
        const rows = Array.from({ length: reel.getDataRowCount() }, (_, row) => row);
        const originalFrames = reel.visibleDataFrames();

        const gold = startMiGoldConversion({
            views: [adapter],
            host: this,
            elapsed: reel.getSpinElapsed(),
            timing: { spineDelay: timing.miGoldSpineDelay, miDelay: timing.miGoldMiDelay, flyDelay: timing.miGoldFlyDelay, flyDuration: timing.miGoldFlyDuration },
            reels: [{ machine: adapter.slotMachineView, reel }],
            symbolIds: randomGoldenSymbolIds(rows.length, rows.map((row) => reel.symbolIdAtRow(row))),
            showMi: () => showMiEffect([adapter], MI_REEL_INDEX),
            canShowMi: () => reel.model.state === ReelState.BEGIN || reel.model.state === ReelState.LOOP,
            holdSec,
            // 跟正式流程一樣把第三軸換成金牌輪帶（下一次起轉時還原）
            goldenStrip: true,
        });
        if (holdSec === undefined) {
            await gold.arranged;
            await waitSeconds(this, timing.miGoldStopDelay);
        } else {
            await gold.finished;
        }
        // 停輪延遲要在起轉之後才算得出來：停著時 getTimeUntilStoppable() 一律是 0
        await Promise.all([reel.stopSpin(originalFrames, undefined, reel.getTimeUntilStoppable(0)), gold.finished, gold.spineDone]);
    }

