import { _decorator, Component, UIOpacity, Vec3 } from 'cc';
import { SymbolImageManager } from './SymbolImageManager';
import { ISymbolCellHost, ReelFlag, SymbolState, SymbolStateLevel } from './SymbolState';
import { SymbolView } from './SymbolView';

const { ccclass } = _decorator;

/**
 * 一個常駐的邏輯格子：知道自己現在該顯示哪個符號的哪個狀態，並向 {@link SymbolImageManager}
 * 租借對應的顯示物件掛到自己底下。
 *
 * 設計依據：entry repo `docs/SlotSymbolSystem_設計參考.md` §4。
 *
 * **常駐、不銷毀**——轉動時搬的是位置與資料，不是節點。這一點跟 1003 原本 `ReelView.initSymbols()`
 * 建固定節點集合的做法一致，差別只在「節點自己掛滿所有美術」改成「向池子租當下需要的那一份」。
 *
 * **所有想改變這一格外觀的系統，都只能透過 {@link setState}。** 轉動邏輯、聽牌、中獎演出各自在
 * 自己的層級喊一個狀態，這裡每幀取最高層的生效值，誰也不必知道誰。盤點文件
 * （`.docs/1003-symbol-system-gap-analysis.md`）記錄的六條直達顯示層路徑，就是這個類別要收掉的東西。
 *
 * **顯示物件不一定掛在格子底下。** 狀態來自中獎層或聽牌層時，輪軸會把物件放進機台的覆蓋層
 * （`Layer_Win`，見 {@link ISymbolCellHost.attachOverlayView}），讓它不受盤面遮罩
 * 裁切、畫在壓黑之上。那時物件跟格子已經不是父子關係，所以位置、縮放與透明度由這裡每幀從格子
 * 抄過去——轉動、補牌落下、消除時把格子透明度歸零這些套在格子上的動作，對物件照樣生效。
 *
 * 前提是狀態節點不靠父節點決定尺寸或位置：搬進覆蓋層之後父節點是整層，撐滿父節點的 Widget 會把物件撐成
 * 整層大小、還在換父節點那一幀把它拉到層的中心（踩坑 #59）。Symbol prefab 的狀態節點因此不掛 Widget；
 * 以後美術在狀態節點裡放了要靠父節點尺寸的東西（尺寸模式 CUSTOM 的 Sprite、撐滿的子節點），就得改成在
 * 覆蓋層裡替每格建一個格子大小的替身節點、把物件掛在替身底下。
 */
@ccclass('1003/SymbolCell')
export class SymbolCell extends Component {
    /** 目前顯示的符號 id */
    private symbolId: number = -1;

    /** 每個優先權層級各存一個強制狀態，`None` 代表這一層沒有意見 */
    private readonly forceStates: SymbolState[] = new Array(SymbolStateLevel.Count).fill(SymbolState.None);

    /** 這一幀實際生效的狀態 */
    private currentState: SymbolState = SymbolState.None;

    /** 目前生效的是哪一層，用來判斷「狀態沒變但來源層變了」也要重算 */
    private currentLevel: number = -1;

    /** 目前租到的顯示物件 */
    private view: SymbolView | null = null;

    /** {@link view} 目前是不是放在覆蓋層、要每幀跟著格子同步 */
    private viewInOverlay: boolean = false;

    /**
     * {@link keepCurrentViewFor} 留在覆蓋層裡、還沒歸還的物件。
     *
     * 它們已經不歸這一格管，但留在原地播完的前提是「跟著格子走」：掛在格子底下時這件事是自動的，
     * 放在覆蓋層就得跟 {@link view} 一樣每幀同步。
     */
    private readonly lingeringOverlayViews: SymbolView[] = [];

    private stateDirty: boolean = true;
    private imageDirty: boolean = false;

    /** DebugPanel 調整的整體縮放倍率，每次換顯示物件都要重新套用 */
    private scaleMultiplier: number = 1;

    /** 格子自己的透明度元件，由 `ReelView` 建格子時加上；物件在覆蓋層時要抄它的值 */
    private cellOpacity: UIOpacity | null = null;

    private manager: SymbolImageManager = null!;
    private host: ISymbolCellHost = null!;

    /**
     * 綁定池子與所屬輪軸。由 `ReelView` 在建立格子時呼叫。
     *
     * @param manager 顯示物件的池。
     * @param host 所屬輪軸，提供預設狀態的依據與覆蓋層。
     */
    public setup(manager: SymbolImageManager, host: ISymbolCellHost): void {
        this.manager = manager;
        this.host = host;
    }

    /**
     * 換成另一個符號。狀態不會被清掉——轉動中換符號時不該讓 `Blur` 掉回 `Normal`。
     *
     * @param symbolId 新的符號 id。
     */
    public setSymbolId(symbolId: number): void {
        if (this.symbolId === symbolId) return;
        this.symbolId = symbolId;
        this.imageDirty = true;
    }

    /**
     * 取這一格目前的符號 id。疊放順位與「目前畫面上是哪張牌」都靠它。
     *
     * @returns 目前顯示的符號 id；還沒設定過時為 -1。
     */
    public getSymbolId(): number {
        return this.symbolId;
    }

    /**
     * 在指定層級設定強制狀態。
     *
     * @param state 要設定的狀態。
     * @param level 優先權層級，預設最高層。
     */
    public setState(state: SymbolState, level: SymbolStateLevel = SymbolStateLevel.High): void {
        if (this.forceStates[level] === state) return;
        this.forceStates[level] = state;
        this.stateDirty = true;
    }

    /**
     * 清除指定層級的強制狀態，讓下一層（或預設推算）接手。
     *
     * @param level 優先權層級，預設最高層。
     */
    public clearState(level: SymbolStateLevel = SymbolStateLevel.High): void {
        this.setState(SymbolState.None, level);
    }

    /**
     * 標記下一幀要重算狀態。
     *
     * 輪軸旗標變動時由 `ReelView.setReelFlag()` 呼叫——旗標不是這一格自己的資料，格子無從
     * 察覺它變了，必須由外面通知。
     */
    public markStateDirty(): void {
        this.stateDirty = true;
    }

    /** 清掉所有層級的強制狀態，回到完全由輪軸旗標推算的預設狀態 */
    public clearAllStates(): void {
        for (let i = 0; i < this.forceStates.length; i++) this.forceStates[i] = SymbolState.None;
        this.stateDirty = true;
    }

    /**
     * 取這一幀生效的狀態：各層強制狀態取最高的那層，都沒有時是輪軸旗標推算的預設。
     *
     * @returns 這一幀生效的狀態。
     */
    public getState(): SymbolState {
        return this.currentState;
    }

    /** 要求目前的顯示物件從頭重播動畫 */
    public resetAni(): void {
        this.view?.resetAni();
    }

    /**
     * 立刻把待處理的狀態／換圖跑完，不等下一幀的 `update()`。
     *
     * 演出流程是「設狀態 → 馬上 await 它播完」，中間沒有機會讓 `update()` 插進來；不先 flush 的話
     * 等到的會是**上一個**狀態的動畫。
     */
    public flush(): void {
        if (this.stateDirty) this.updateState();
        if (this.imageDirty) this.updateImage();
    }

    /**
     * 套用目前狀態並等它播完一次。
     *
     * 一定要有保底計時器：complete 事件在動畫名不存在、資產換到一半、或節點中途被關掉時都可能
     * 不來，少了它這個 Promise 永遠不 settle，`await` 它的整條演出流程會無聲吊死
     * （entry docs/agent-pitfalls.md 坑 #35）。
     *
     * @param fallbackSec 保底秒數；動畫沒有在這段時間內回報結束就強制 resolve。
     * @returns 播完（或保底時間到）後 resolve。
     */
    public playCurrentStateOnce(fallbackSec: number): Promise<void> {
        this.flush();
        const view = this.view;
        if (!view) return Promise.resolve();

        return new Promise<void>((resolve) => {
            let done = false;
            const finish = (): void => {
                if (done) return;
                done = true;
                this.unschedule(finish);
                resolve();
            };
            view.playOnce(finish);
            this.scheduleOnce(finish, Math.max(fallbackSec, 0.05) + 0.2);
        });
    }

    /**
     * 調整目前顯示物件的動畫播放速度。
     *
     * @param scale 倍率，1 為原速、0 為凍結。
     */
    public setTimeScale(scale: number): void {
        this.view?.setTimeScale(scale);
    }

    /**
     * 目前顯示物件的動畫在原速下要播多久。
     *
     * 讀的是「當下」那顆顯示物件，切完狀態要先 {@link flush}，否則拿到的是上一個狀態的長度。
     *
     * @returns 秒數；沒有顯示物件或是靜態圖時回 0。
     */
    public getAnimDuration(): number {
        return this.view?.getAnimDuration() ?? 0;
    }

    /**
     * 目前顯示物件的主軌在原速下第幾秒結束。跟 {@link getAnimDuration} 一樣，切完狀態要先 {@link flush}。
     *
     * @returns 秒數；沒有顯示物件或是靜態圖時回 0。
     */
    public getMainEndTime(): number {
        return this.view?.getMainEndTime() ?? 0;
    }

    /**
     * 目前顯示物件的主軌先播一次開場動畫，播完接回原本的動畫。跟 {@link getAnimDuration} 一樣，切完狀態要先 {@link flush}。
     *
     * @param anim 開場動畫名稱。
     * @returns 開場動畫在原速下的秒數；沒有顯示物件、是靜態圖或沒有這支動畫時回 0。
     */
    public playIntro(anim: string): number {
        return this.view?.playIntro(anim) ?? 0;
    }

    /**
     * 讓目前這顆顯示物件留在原地繼續播 `seconds` 秒，時間到才歸還物件池。
     *
     * 它從這一刻起不再歸這一格管：之後換符號或換狀態會另外租一顆新的，放在這一格的最底層，
     * 所以留下來的這顆畫在新那顆上面；在覆蓋層裡則是請輪軸把它排到該層所有符號之上，效果相同。
     * 用在金牌翻 Wild：蓋牌的那顆身上還有爆破沒播完，換成 Wild 時照一般流程會被立刻歸還、爆破跟著中斷。
     *
     * 留下來的那顆會繼續跟著格子走：在格子底下時它就是子節點，格子被搬動（補牌掉落、搬進特殊符號層）
     * 時會一起走；在覆蓋層時由 {@link lateUpdate} 同步。計時排在這一格上，跟動畫用同一個 dt；格子是
     * 常駐節點，不會在期間被關掉（坑 #52）。
     *
     * @param seconds 還要留多久（秒）；0 或負數時立刻歸還。
     */
    public keepCurrentViewFor(seconds: number): void {
        const view = this.view;
        if (!view) return;
        const inOverlay = this.viewInOverlay;
        this.view = null;
        this.viewInOverlay = false;
        this.imageDirty = true;

        if (seconds <= 0) {
            this.releaseView(view);
            return;
        }
        if (inOverlay) {
            this.host?.attachOverlayView(this.currentLevel, this.node, view.node, true);
            this.lingeringOverlayViews.push(view);
        }
        this.scheduleOnce(() => {
            const i = this.lingeringOverlayViews.indexOf(view);
            if (i >= 0) this.lingeringOverlayViews.splice(i, 1);
            this.releaseView(view);
        }, seconds);
    }

    /**
     * DebugPanel「Symbol 縮放」用的整體縮放。
     *
     * 套在租到的顯示物件上而不是格子節點上——格子節點的 scale 會被轉動時的
     * `setScale(1,1,1)` 重置與消除縮放反覆改寫，套在那裡會被蓋掉。
     *
     * @param scale 縮放倍率，1 為原始大小。
     */
    public setScaleMultiplier(scale: number): void {
        this.scaleMultiplier = scale;
        this.applyViewScale();
    }

    /**
     * 整格重置：歸還顯示物件、清掉所有狀態。
     *
     * 換盤、進新的一局時呼叫，確保上一局的殘留不會跟著留到下一局。
     */
    public resetCell(): void {
        this.releaseView(this.view);
        this.view = null;
        this.viewInOverlay = false;
        this.symbolId = -1;
        this.clearAllStates();
        this.imageDirty = true;
    }

    /** 每幀推進：先算狀態，狀態決定要租哪一顆，所以換顯示物件排在後面 */
    protected override update(): void {
        if (this.stateDirty) this.updateState();
        if (this.imageDirty) this.updateImage();
    }

    /**
     * 放在覆蓋層的物件跟著格子同步。
     *
     * 放在 lateUpdate：tween 在 update 與 lateUpdate 之間推進，這裡讀到的是格子這一幀最後的位置與透明度。
     */
    protected override lateUpdate(): void {
        if (this.view && this.viewInOverlay) this.syncOverlayView(this.view);
        for (const view of this.lingeringOverlayViews) this.syncOverlayView(view);
    }

    /**
     * 從最高層往下找第一個非 `None` 的強制狀態；都沒有才用輪軸旗標推算預設值。
     *
     * 狀態或來源層任一個變了就要標記換圖：同樣是 `Normal`，但從「中獎層喊的」變成「預設推算的」
     * 代表中獎演出結束了，該重播一次動畫。
     */
    private updateState(): void {
        this.stateDirty = false;

        let target = SymbolState.None;
        let level = -1;
        for (let i = SymbolStateLevel.Count - 1; i >= 0; i--) {
            if (this.forceStates[i] !== SymbolState.None) {
                target = this.forceStates[i];
                level = i;
                break;
            }
        }
        if (target === SymbolState.None) target = this.getTargetState();

        if (target === this.currentState && level === this.currentLevel) return;
        this.currentState = target;
        this.currentLevel = level;
        this.imageDirty = true;
    }

    /**
     * 沒有任何層級指定狀態時，依輪軸狀態推算預設狀態：轉動中且開了模糊旗標是 `Blur`，其餘都是 `Normal`。
     *
     * 壓黑不在這裡：2026-10-20 起由機台的 `Layer_Black/Black` 整片蓋上去，格子不必知道有沒有在壓黑。
     *
     * @returns 預設狀態。
     */
    private getTargetState(): SymbolState {
        if (!this.host?.isReelSpinning()) return SymbolState.Normal;
        if (this.host.hasReelFlag(ReelFlag.Blur)) return SymbolState.Blur;
        return SymbolState.Normal;
    }

    /**
     * 依目前的符號與狀態換顯示物件；已經是對的那一顆就只重新安置並重播動畫，不做多餘的租還。
     *
     * 同一顆也要重新安置：狀態沒換、來源層換了的時候（例如 Wild 從中獎層的 `Normal` 退回預設的
     * `Normal`），物件要從覆蓋層搬回格子底下。
     */
    private updateImage(): void {
        this.imageDirty = false;
        if (!this.manager || this.symbolId < 0) return;

        if (this.manager.isSame(this.view, this.symbolId, this.currentState)) {
            this.view!.symbolId = this.symbolId;
            this.view!.state = this.currentState;
            this.placeView(this.view!);
            this.view!.resetAni();
            return;
        }

        this.releaseView(this.view);
        this.view = this.manager.rent(this.symbolId, this.currentState, this.node);
        if (this.view) this.placeView(this.view);
    }

    /**
     * 決定顯示物件掛在哪裡：輪軸替目前的來源層準備了覆蓋層就交給它，否則掛在格子的最底層。
     *
     * @param view 要安置的物件，必須是 {@link view}。
     */
    private placeView(view: SymbolView): void {
        this.host?.detachOverlayView(view.node);
        this.viewInOverlay = this.currentLevel >= 0 && (this.host?.attachOverlayView(this.currentLevel, this.node, view.node, false) ?? false);
        if (this.viewInOverlay) {
            this.syncOverlayView(view);
            return;
        }

        if (view.node.parent !== this.node) view.node.setParent(this.node);
        view.node.setPosition(Vec3.ZERO);
        view.node.setSiblingIndex(0);
        SymbolCell.setViewOpacity(view, 255);
        this.applyViewScale();
    }

    /**
     * 把格子這一幀的世界座標、縮放與透明度抄到覆蓋層裡的物件上。
     *
     * 縮放要乘上 DebugPanel 的倍率；格子自己的透明度元件在 {@link setup} 時可能還沒加上，所以用到才找。
     * 旋轉不抄：格子與機台都不會旋轉。
     *
     * @param view 放在覆蓋層的物件。
     */
    private syncOverlayView(view: SymbolView): void {
        const node = view.node;
        node.setWorldPosition(this.node.worldPosition);
        const s = this.node.worldScale;
        node.setWorldScale(s.x * this.scaleMultiplier, s.y * this.scaleMultiplier, s.z);

        this.cellOpacity ??= this.getComponent(UIOpacity);
        SymbolCell.setViewOpacity(view, this.cellOpacity?.opacity ?? 255);
    }

    /** 把 DebugPanel 的縮放倍率套到目前的顯示物件上 */
    private applyViewScale(): void {
        const view = this.view;
        if (!view) return;
        if (this.viewInOverlay) this.syncOverlayView(view);
        else view.node.setScale(this.scaleMultiplier, this.scaleMultiplier, 1);
    }

    /**
     * 歸還一顆顯示物件：先讓覆蓋層放手、把透明度還原，再交回物件池。
     *
     * 透明度一定要還原——在覆蓋層時它抄的是格子的值，消除後格子是 0，不還原的話下一格租到它會整顆看不見。
     *
     * @param view 要歸還的物件；傳 null 是安全的。
     */
    private releaseView(view: SymbolView | null): void {
        if (!view?.isValid) return;
        this.host?.detachOverlayView(view.node);
        SymbolCell.setViewOpacity(view, 255);
        this.manager?.returnView(view);
    }

    /**
     * 設定顯示物件的透明度。物件身上沒有 `UIOpacity` 時，只在要調低的時候才加，不替每顆物件都掛一個。
     *
     * @param view 目標物件。
     * @param opacity 0–255。
     */
    private static setViewOpacity(view: SymbolView, opacity: number): void {
        const comp = view.node.getComponent(UIOpacity);
        if (comp) comp.opacity = opacity;
        else if (opacity < 255) view.node.addComponent(UIOpacity).opacity = opacity;
    }
}
