import { instantiate, NodePool, Node } from "cc";
import AppAssetBundle from "../utils/AppAssetBundle";

/**
 * AppViewPool
 * 原生替代 KYCocosSDK/Module/KYViewPool.ts，方法簽名 1:1 對應，
 * 供逐步替換 import 路徑使用，KYCocosSDK 內檔案本身不受影響。
 * 內部依賴已改用原生的 AppAssetBundle。
 */
export default class AppViewPool {
    poolMap: Map<string, NodePool>;
    _bundleName: string;
    private static instance: AppViewPool;
    /**
     * 私有建構子，一律走 getInstance() 取得實例。
     */
    private constructor() {
        this.poolMap = new Map<string, NodePool>();
    }
    /**
     * 取得節點池單例，第一次呼叫時才建立。
     *
     * @returns 單例。
     */
    public static getInstance(): AppViewPool {
        if (!AppViewPool.instance) {
            AppViewPool.instance = new AppViewPool();
        }
        return AppViewPool.instance;
    }

    /**
     * 從池裡取一個 view 節點；池是空的就載入 prefab 現做一個。
     *
     * @param viewName 相對於 bundle 的 prefab 路徑，同時作為池的鍵。
     * @param bundleName 要從哪個 bundle 載。
     * @returns 已啟用的節點。
     */
    async getView(viewName: string, bundleName): Promise<Node> {
        const pool = this.getPool(viewName);
        if (pool.size() > 0) {
            const node = pool.get();
            node.active = true;
            return node;
        }
        return instantiate(await AppAssetBundle.getInstance(bundleName).loadPrefab(viewName));
    }

    /**
     * 取得（必要時建立）某個 view 的節點池。
     *
     * @param viewName 池的鍵。
     * @returns 對應的節點池。
     */
    private getPool(viewName: string): NodePool {
        if (!this.poolMap.has(viewName)) {
            this.poolMap.set(viewName, new NodePool());
        }
        return this.poolMap.get(viewName);
    }

    /**
     * 把節點關掉並放回池裡重複使用。
     *
     * @param viewName 池的鍵。
     * @param node 要回收的節點。
     */
    put(viewName: string, node: Node) {
        node.active = false;
        this.getPool(viewName).put(node);
    }

    /**
     * 清空所有節點池。
     */
    clear() {
        this.poolMap.forEach(pool => pool.clear());
        this.poolMap.clear();
    }
}
