import { _decorator, Component, Mask, Node, Size, sp, tween, type Tween, UIOpacity, UITransform, Vec2, Vec3 } from 'cc';
import { SlotMachineModel } from '../model/SlotMachineModel';
import { ReelView_1003 } from './ReelView_1003';
import { SymbolOverlayLayer } from './SymbolOverlayLayer';
import type { AchieveItem } from '../../types/SpinTypes';
import type { ReelSpinTiming } from '../../config/ReelTimingDebugStore';

const { ccclass, property } = _decorator;

/** 壓黑淡入、淡出各花多久（秒），沿用改版前逐格壓暗的 `DIM_DURATION`；補間吃整體速度倍率，急速時等比變快 */
const BLACK_FADE_SEC = 0.25;

/**
 * 機台根節點底下各層的名稱，由下往上。{@link SlotMachineView.onLoad} 拿它比對 prefab 的實際順序，
 * 每一層的用途見 {@link SlotMachineView} 的層級表。
 */
const MACHINE_LAYER_ORDER = ['Layer_Reels', 'Layer_Black', 'Layer_Mi', 'Layer_Frame', 'Layer_Dragon', 'Layer_Win', 'Layer_Custom'] as const;

/** 一個要播中獎動畫的格子：盤面座標加上要播的 spine 動畫名稱 */
interface WinTarget {
    col: number;
    row: number;
    animName: string;
}

/**
 * 機台：五欄轉輪，加上中獎、聽牌、瞇牌演出用的各層。
 *
 * **層級**：機台根節點的子節點，由下往上。順序以 prefab 為準，{@link onLoad} 會跟 {@link MACHINE_LAYER_ORDER}
 * 比對，不一樣就印 warn。其他檔案提到層的前後關係時一律指回這張表，不要各自再寫一份。
 *
 * | 層 | 裝什麼 | 為什麼排在這裡 |
 * | --- | --- | --- |
 * | `Layer_Reels` | 五欄轉輪，與它們的 Wild／Scatter 特殊符號層（{@link buildSpecialSymbolLayer}） | 矩形遮罩裁成盤面 |
 * | `Layer_Black` | 壓黑（{@link blackOverlay}） | 蓋住轉輪，把沒中獎、沒聚焦的格子壓暗 |
 * | `Layer_Mi` | 聽牌框（{@link miSkel}，prefab 上的 `slowmotion`），上面是聚焦中的那一軸（聽牌、FG 第三軸瞇牌），裝在執行時建的裁切節點 `FocusClip` 裡（{@link liftFocusedReel}） | 壓黑之上才是亮的；外框之下，第一、第五軸角落的裝飾格與聽牌框的外圈才不會蓋到外框。`FocusClip` 建在這一層最後面，聚焦的那一軸畫在聽牌框之上 |
 * | `Layer_Frame` | 外框 | 蓋住轉輪、聽牌框與聚焦那一軸的邊緣 |
 * | `Layer_Dragon` | FG 金牌轉換的龍（{@link miGoldSkel}） | 外框之上，龍頭可以伸出盤面 |
 * | `Layer_Win` | 中獎中、聽牌中的符號（{@link winLayer}） | 不受盤面遮罩裁切，畫在壓黑、聚焦的那一軸與外框之上；疊放順序由 `SymbolOverlayLayer` 照盤面重建 |
 * | `Layer_Custom` | FG 金牌飛入（{@link customLayer}） | 最上層；有盤面大小的遮罩，飛出盤面就看不到 |
 *
 * 2026-11-05 整理成這個順序：之前聚焦的那一軸與聽牌 Scatter 都在 `Layer_Mi`（排在 `Layer_Spine` 之上），
 * 聚焦軸靠執行時插順序才能壓在外框之下，聽牌 Scatter 又會被同一層後加的聚焦軸蓋到。同一天稍晚聽牌框從
 * `Layer_Spine` 搬進 `Layer_Mi`、`Layer_Spine` 改名 `Layer_Dragon`：聽牌框留在外框之上時會蓋在聚焦的那一軸上面。
 */
@ccclass('1003/SlotMachineView')
export class SlotMachineView extends Component {
    @property([ReelView_1003])
    reelViews: ReelView_1003[] = [];

    /**
     * 符號尺寸（一格的寬×高），盤面上**唯一要手動調整的尺寸**。
     *
     * 各欄在 onLoad 時往上找到機台讀這個值，格子大小、列距（＝高＋列間距）、欄寬（＝寬）、
     * 欄高（＝可視列數×高＋列間距）全部由它與 {@link symbolSpacing} 推出來；其他 .ts 需要符號尺寸
     * 也一律讀這裡，不要另外寫死數字。
     *
     * 符號 prefab（`Symbols/Symbol_*.prefab`）上的尺寸不受它控制，改這個值不會改到狀態節點的尺寸：
     * 狀態節點底下全是 spine，畫在哪裡只看節點原點，不看尺寸，所以沒有影響。狀態節點原本掛著撐滿父節點的
     * Widget，2026-10-20 拿掉了——中獎物件改放 `Layer_Win` 之後，它會把物件撐成整層大小、還在換父節點
     * 那一幀把物件拉到 `Layer_Win` 中心（踩坑 #59）。
     */
    @property({ type: Size, tooltip: '符號尺寸（一格的寬×高）。格子大小、列距、欄寬、欄高都由它與符號間距決定' })
    public symbolSize: Size = new Size(198, 222);

    /**
     * 符號之間的間距：x 是欄與欄之間、y 是列與列之間，只加在格子之間，盤面最外圈不加。
     *
     * 格子本身的大小仍然是 {@link symbolSize}，間距是格子外面的空隙。轉動、補牌落下、中獎框、飛行
     * 特效都讀各欄 `posList` 的座標，所以只在產生座標的地方（`ReelView_1003.onLoad` 與
     * {@link layoutReelColumns}）加進去就會一路帶下去。
     *
     * 加大間距會讓整個盤面變大，但 `Layer_Reels` 上的 Mask 不會跟著變，外側的欄與上下的列可能被裁掉。
     */
    @property({ type: Vec2, tooltip: '符號間距：x 是欄與欄之間、y 是列與列之間。盤面會跟著變大，Mask 不會自動跟著變' })
    public symbolSpacing: Vec2 = new Vec2(0, 0);

    /**
     * 第一軸與最後一軸（第五軸）往下移的距離，正數往下、負數往上。
     *
     * 葫蘆型盤面兩側欄比中間欄少一列，美術要它們整欄再低一點。移的是欄節點本身，格子、緩衝格、
     * Wild／Scatter 特殊層（每幀對齊 Container 的世界座標）、中獎框與飛行特效都跟著走。
     * 往下移之後下緣角落那格緩衝格可能被 `Layer_Reels` 上的 Mask 裁掉一部分。
     */
    @property({ tooltip: '第一軸與第五軸往下移的距離（正數往下、負數往上）' })
    public edgeReelOffsetY: number = 0;

    /**
     * 壓黑遮罩（`Layer_Black/Black`）：中獎演出時整片蓋在盤面上，把沒中獎的格子壓暗，見 {@link setBlack}。
     *
     * prefab 上是開著的，方便在 Editor 裡看效果，{@link onLoad} 會先關掉。
     */
    @property({ type: Node, tooltip: '壓黑遮罩（Layer_Black/Black），中獎演出時打開' })
    public blackOverlay: Node | null = null;

    /**
     * 中獎層（`Layer_Win`）：狀態來自中獎層與聽牌層的符號顯示物件都放這裡（中獎中的符號、聽牌中已落定的
     * Scatter），不受 `Layer_Reels` 的 Mask 裁切。層級見類別說明。
     */
    @property({ type: Node, tooltip: '中獎層（Layer_Win）：中獎中與聽牌中的符號' })
    public winLayer: Node | null = null;

    /**
     * 瞇牌層（`Layer_Mi`）：聽牌框（{@link miSkel}）在 prefab 上就放這裡；聚焦中的那一軸（聽牌或 FG 第三軸瞇牌）
     * 搬進這一層的裁切節點（{@link ensureFocusClip}），排在聽牌框之上。整層畫在壓黑之上、外框之下。層級見類別說明。
     */
    @property({ type: Node, tooltip: '瞇牌層（Layer_Mi）：聽牌框與聚焦中的那一軸（聽牌、FG 第三軸瞇牌）' })
    public miLayer: Node | null = null;

    /**
     * 自訂演出層（`Layer_Custom`）：FG 金牌飛入這類從盤面外進來的演出，排在最上面。{@link onLoad} 會加上跟盤面
     * 一樣大的矩形遮罩，演出物件出了盤面就看不到——所以聽牌、瞇牌那些不能被裁切的東西不放這裡。
     */
    @property({ type: Node, tooltip: '自訂演出層（Layer_Custom）：金牌飛入等特殊演出，執行時加上盤面大小的遮罩' })
    public customLayer: Node | null = null;

    /**
     * 瞇牌／聽牌框的 spine（`Layer_Mi/slowmotion`），由 `ui/MiEffect.ts` 開關與左右移動。
     *
     * 放在 `Layer_Mi`，排在聚焦的那一軸（`FocusClip`）之下，整層又在外框之下，層級見類別說明。
     * 2026-11-03 前是掛在 `Game.prefab` 的 `GameViewH/MiNode`、執行時搬進 `Layer_Mi` 最上面；11-03～11-05 在
     * `Layer_Spine`（11-05 下午那段排在聚焦的那一軸與外框之上）。橫直兩台都有。
     */
    @property({ type: sp.Skeleton, tooltip: '瞇牌／聽牌框的 spine（Layer_Mi/slowmotion）；留空則沒有框' })
    public miSkel: sp.Skeleton | null = null;

    /**
     * FG 第三軸金牌轉換前播的 spine（`Layer_Dragon/dragon`，`spine/dragon.json`），由 `MiGoldIntro.playMiGoldSpine()` 播。
     *
     * 節點平常關著，播的時候才開、播完關掉——prefab 上要保持關著，它的 setup pose 有圖，開著的話進遊戲就會停著一隻龍。
     * 父節點必須一直開著：父節點關著時第一次的動畫會被引擎丟掉，之後的也停在 0 秒（坑 #70），所以不能放進會開關的容器裡。
     */
    @property({ type: sp.Skeleton, tooltip: 'FG 第三軸金牌轉換前播的 spine（Layer_Dragon/dragon，平常關著）；留空則跳過，直接進瞇牌' })
    public miGoldSkel: sp.Skeleton | null = null;

    /** 特殊符號層，見 {@link buildSpecialSymbolLayer} */
    private specialLayer: Node | null = null;

    /** 特殊符號層裡每一欄的 Wild／Scatter 容器；聚焦時要跟著那一欄一起搬，見 {@link liftFocusedReel} */
    private specialContainersByCol: { wild: Node; scatter: Node }[] = [];

    /** 聚焦用的裁切節點（矩形遮罩），第一次聚焦時建在 {@link miLayer} 裡 */
    private focusClip: Node | null = null;

    /** 壓黑目前的目標：true 是淡入中或已經全開，false 是淡出中或已經關掉，見 {@link setBlack} */
    private blackOn = false;

    /** 壓黑的淡入淡出補間；換方向時停掉，從當下的透明度接著補 */
    private blackTween: Tween<UIOpacity> | null = null;

    /** 聚焦中被搬進 {@link focusClip} 的那一軸，以及搬回時要還原的父節點、順序與區域座標 */
    private lifted: { col: number; restore: { node: Node; parent: Node; index: number; position: Vec3 }[] } | null = null;

    /** 結束聚焦時，等壓黑淡完才搬回那一軸的排程是否還在等，見 {@link liftFocusedReel} */
    private restorePending = false;

    public model: SlotMachineModel = null!;

    /**
     * 進場整理各層：比對層級順序、檢查各層有沒有接；{@link customLayer} 加上盤面大小的矩形遮罩；
     * 壓黑遮罩在 prefab 上是開著的，先關掉、透明度歸零，第一次淡入才從 0 開始。
     */
    protected override onLoad(): void {
        this.checkLayerOrder();
        this.warnUnwiredLayers();
        // Layer_Custom 跟 Layer_Reels 一樣用 Widget 撐滿盤面，遮罩照自己的大小裁，出了盤面的演出物件就看不到
        if (this.customLayer && !this.customLayer.getComponent(Mask)) this.customLayer.addComponent(Mask);

        const black = this.blackOverlay;
        if (!black) return;
        black.active = false;
        (black.getComponent(UIOpacity) ?? black.addComponent(UIOpacity)).opacity = 0;
    }

    /**
     * 比對機台根節點底下各層的順序跟 {@link MACHINE_LAYER_ORDER} 一不一致，少了哪一層或順序不同就印 warn。
     *
     * 層的前後關係決定誰蓋誰，在 Editor 裡拖錯一層不會有任何錯誤，只會在某個演出時才看到東西被蓋住。
     * 只檢查、不修正：照著 prefab 跑，修 prefab 才是正解。
     */
    private checkLayerOrder(): void {
        const actual = this.node.children.map((c) => c.name).filter((name) => (MACHINE_LAYER_ORDER as readonly string[]).includes(name));
        const missing = MACHINE_LAYER_ORDER.filter((name) => !actual.includes(name));
        if (missing.length > 0) {
            console.warn(`[SlotMachineView] ${this.node.parent?.name}/${this.node.name} 少了 ${missing.join('、')}，演出時會有東西被蓋住或沒地方放`);
            return;
        }
        if (actual.join() !== MACHINE_LAYER_ORDER.join()) {
            console.warn(`[SlotMachineView] ${this.node.parent?.name}/${this.node.name} 的層級順序是 ${actual.join(' < ')}，應該是 ${MACHINE_LAYER_ORDER.join(' < ')}`);
        }
    }

    /**
     * 綁定模型、把各欄依寬度排開，並逐一初始化轉輪。
     *
     * 各欄的停輪助跑格數統一成最長那一欄的格數（兩側欄比中間欄多一格），
     * 否則格數少的欄會提早停，各欄停輪的間隔就不等於下指令的間隔。
     *
     * @param model 這台機台的模型，每一欄對應一個 reelModel。
     */
    init(model: SlotMachineModel): void {
        this.model = model;
        this.layoutReelColumns();
        this.buildSpecialSymbolLayer();
        this.attachOverlayLayer();

        const stopRunUpSteps = Math.max(0, ...this.reelViews.map((reel) => reel.posList.length));
        for (let i = 0; i < this.reelViews.length; i++) {
            this.reelViews[i].stopRunUpSteps = stopRunUpSteps;
            this.reelViews[i].init(model.reelModels[i]);
            this.reelViews[i].node.setSiblingIndex(i);
        }
    }

    /**
     * 在所有欄之後建一層「特殊符號層」，讓 Scatter／Wild 能蓋到左右欄的一般符號上。
     *
     * 各欄是依序整欄疊上去的，只靠欄內排序做不到跨欄：右欄的一般符號永遠蓋在左欄的 Scatter 上。
     * 這一層排在所有欄之後，底下每欄各一個 Wild 容器與 Scatter 容器，順序是全部 Wild 在前、
     * 全部 Scatter 在後，所以 Scatter > Wild > 一般符號，跨欄也成立。
     *
     * 這一層建在各欄的父節點（`Layer_Reels`）底下，會被同一個 Mask 裁切、被 `Layer_Black` 的壓黑蓋到，
     * 不需要自己的遮罩。2026-10-20 前各欄直接掛在機台根節點上，這一層也建在根節點；prefab 分層之後
     * 還建在根節點的話，會排到 `Layer_Custom` 之後——不被裁切、蓋在外框上，也不會被壓黑。
     *
     * 容器只負責分層，格子什麼時候搬進來由各欄自己決定（見 `ReelView_1003.placeCell`）。
     * 重複呼叫時沿用既有的那一層。
     */
    private buildSpecialSymbolLayer(): void {
        if (this.specialLayer?.isValid) return;

        const layer = this.makeLayerNode('SpecialSymbolLayer', this.reelViews[0]?.node.parent ?? this.node);
        const wilds = this.reelViews.map((_, i) => this.makeLayerNode(`Wild_${i}`, layer));
        const scatters = this.reelViews.map((_, i) => this.makeLayerNode(`Scatter_${i}`, layer));
        this.reelViews.forEach((reel, i) => reel.attachSpecialContainers(wilds[i], scatters[i]));
        this.specialContainersByCol = wilds.map((wild, i) => ({ wild, scatter: scatters[i] }));
        this.specialLayer = layer;
    }

    /**
     * 聚焦某一軸（聽牌、FG 第三軸瞇牌）：把那一軸搬進 `Layer_Mi` 的裁切節點（{@link ensureFocusClip}），
     * 畫在壓黑之上、外框之下；其他軸留在 `Layer_Reels`，被呼叫端打開的壓黑（{@link setBlack}）蓋住。聽牌中已落定的
     * Scatter 另外切到聽牌狀態、放 `Layer_Win`，畫在聚焦的那一軸之上（見 {@link showLandedScattersTenpai}）。
     * 層級見類別說明。傳另一軸時先把上一軸搬回去。
     *
     * 搬的是欄節點本身，連同它在特殊符號層的 Wild／Scatter 容器——Wild、Scatter 的格子平常住在那兩個容器裡，
     * 不一起搬就會留在壓黑底下。三者照「一般牌 < Wild < Scatter」的順序放進同一個裁切節點，搬動時保留世界
     * 座標，轉動與格子位置都不受影響。
     *
     * 裁切節點是必要的：沒有遮罩的話轉動中的緩衝格會露出盤面外。它的寬度是那一軸的寬度、高度與中心跟
     * `Layer_Reels` 的遮罩一樣，所以這一軸被裁到的範圍跟在 `Layer_Reels` 裡相同。
     *
     * 結束聚焦（`col` 是 null）時可以等壓黑淡完才搬回：淡出途中就搬回的話，那一軸會回到還沒淡完的壓黑底下，
     * 先被蓋暗一下再亮回來，跟 {@link endScattersTenpai} 放回 Scatter 是同一個道理。等待期間又聚焦別軸（或同一軸）
     * 時取消等待：別軸照常先搬回再搬新的，同一軸就留在原處。計時掛在機台自己身上，它一直開著（坑 #52）。
     *
     * @param col 要搬的軸（0 起算）；null 是全部搬回 `Layer_Reels`。
     * @param restoreDelaySec 結束聚焦時等幾秒才搬回，通常是壓黑淡出的秒數；0 是當下就搬。
     */
    public liftFocusedReel(col: number | null, restoreDelaySec: number = 0): void {
        if (col !== null) this.cancelDelayedRestore();
        if (this.lifted?.col === col || (col === null && !this.lifted)) return;
        if (col === null) {
            if (restoreDelaySec > 0) {
                if (this.restorePending) return;
                this.restorePending = true;
                this.scheduleOnce(this.restoreLiftedReelLater, restoreDelaySec);
            } else {
                this.cancelDelayedRestore();
                this.restoreLiftedReel();
            }
            return;
        }
        this.restoreLiftedReel();

        const reel = this.reelViews[col];
        const clip = reel ? this.ensureFocusClip(reel) : null;
        if (!reel || !clip) return;
        this.alignFocusClip(clip, reel);

        const special = this.specialContainersByCol[col];
        const nodes = [reel.node, special?.wild, special?.scatter].filter((n): n is Node => !!n?.isValid && !!n.parent);
        const restore = nodes.map((node) => ({ node, parent: node.parent!, index: node.getSiblingIndex(), position: node.position.clone() }));
        for (const node of nodes) node.setParent(clip, true);
        this.lifted = { col, restore };
    }

    /**
     * 聽牌：第 1 軸到 `upToCol` 軸已落定的 Scatter 切到聽牌狀態，放進 `Layer_Win`、畫在壓黑之上
     * （見 `ReelView_1003.setLandedScattersTenpai()`）。重複呼叫是安全的，已經切過的那幾顆不會重來。
     *
     * @param upToCol 已落定的最後一軸（0 起算）。
     */
    public showLandedScattersTenpai(upToCol: number): void {
        this.unschedule(this.clearScattersTenpai);
        for (let col = 0; col <= upToCol && col < this.reelViews.length; col++) {
            this.reelViews[col]?.setLandedScattersTenpai(true);
        }
    }

    /**
     * 結束聽牌時放回已落定的 Scatter：等壓黑淡出完才放回。淡出途中就放回的話，
     * Scatter 會回到還沒淡完的壓黑底下，先被蓋暗一下再亮回來。
     *
     * 計時掛在機台自己身上：直橫兩台都一直開著（隱藏的那台只是移到畫面外），計時不會被暫停（坑 #52）。
     *
     * @param delaySec 等幾秒才放回，跟壓黑淡出的秒數一致；預設 {@link BLACK_FADE_SEC}。
     */
    public endScattersTenpai(delaySec: number = BLACK_FADE_SEC): void {
        this.unschedule(this.clearScattersTenpai);
        this.scheduleOnce(this.clearScattersTenpai, delaySec);
    }

    /** {@link liftFocusedReel} 延後搬回那一軸的排程；寫成箭頭函式欄位，排程與取消時拿到的是同一個參照 */
    private readonly restoreLiftedReelLater = (): void => {
        this.restorePending = false;
        this.restoreLiftedReel();
    };

    /** 取消還在等的延後搬回；沒在等時什麼都不做 */
    private cancelDelayedRestore(): void {
        if (!this.restorePending) return;
        this.restorePending = false;
        this.unschedule(this.restoreLiftedReelLater);
    }

    /** 每一軸都清掉聽牌層；寫成箭頭函式欄位，排程與取消時拿到的是同一個參照 */
    private readonly clearScattersTenpai = (): void => {
        for (const reel of this.reelViews) reel?.setLandedScattersTenpai(false);
    };

    /**
     * 把聽牌中的那一軸搬回原本的父節點，順序與區域座標都照搬走前記下的值還原（不靠世界座標換算，免得
     * 來回搬幾次累積誤差）。
     *
     * 依原本的順序由小到大放回：同一個父節點底下排前面的先就位，後面的索引才對得上。
     */
    private restoreLiftedReel(): void {
        const lifted = this.lifted;
        if (!lifted) return;
        this.lifted = null;

        const ordered = [...lifted.restore].sort((a, b) => a.index - b.index);
        for (const { node, parent, index, position } of ordered) {
            if (!node.isValid || !parent.isValid) continue;
            node.setParent(parent);
            node.setSiblingIndex(index);
            node.setPosition(position);
        }
    }

    /**
     * 取聚焦用的裁切節點，第一次用到時建在 {@link miLayer} 裡。
     *
     * 裁切節點是必要的：`Layer_Mi` 撐滿盤面但沒有遮罩，整軸直接放進去的話轉動中的緩衝格會露出盤面外。
     * 尺寸在掛遮罩之前就設好：寬度是一軸的寬，高度是 `Layer_Reels` 的高。遮罩是預設的矩形，依節點尺寸裁切。
     *
     * 加在這一層的最後面：prefab 上的聽牌框（{@link miSkel}）排在它前面，聚焦的那一軸才會畫在聽牌框之上。
     * 以後往 `Layer_Mi` 加要蓋在聚焦軸上的東西，要排在它後面。
     *
     * @param reel 任一軸，用來量軸寬與 `Layer_Reels` 的高度。
     * @returns 裁切節點；{@link miLayer} 沒接時為 null（聚焦的那一軸就留在壓黑底下）。
     */
    private ensureFocusClip(reel: ReelView_1003): Node | null {
        if (this.focusClip?.isValid) return this.focusClip;
        const layer = this.miLayer;
        if (!layer?.isValid) return null;

        const clip = this.makeLayerNode('FocusClip', layer);
        const width = reel.node.getComponent(UITransform)?.width ?? this.symbolSize.width;
        const height = reel.node.parent?.getComponent(UITransform)?.height ?? 0;
        clip.getComponent(UITransform)!.setContentSize(width, height);
        clip.addComponent(Mask);
        this.focusClip = clip;
        return clip;
    }

    /**
     * 把裁切節點對到這一軸：x 對齊這一軸的中心，y 對齊 `Layer_Reels` 遮罩的中心。
     *
     * 必須在這一軸還掛在 `Layer_Reels` 時呼叫——讀的是它當下的父節點位置。
     *
     * @param clip 裁切節點。
     * @param reel 要聚焦的那一軸。
     */
    private alignFocusClip(clip: Node, reel: ReelView_1003): void {
        const space = clip.parent?.getComponent(UITransform);
        const reels = reel.node.parent;
        if (!space || !reels) return;
        const world = new Vec3(reel.node.worldPosition.x, reels.worldPosition.y, 0);
        clip.setPosition(space.convertToNodeSpaceAR(world, new Vec3()));
    }

    /**
     * 把 {@link winLayer} 包成覆蓋層配發給各欄，中獎與聽牌的符號都放這一層（見 `ReelView_1003.attachOverlayView`）。
     * 沒接時傳 null，那些物件就留在格子底下。
     */
    private attachOverlayLayer(): void {
        const overlay = this.winLayer ? new SymbolOverlayLayer(this.winLayer) : null;
        this.reelViews.forEach((reel, i) => reel.attachOverlayLayer(overlay, i));
    }

    /**
     * 各層一律由 Inspector 接，不靠節點名稱找；少接的印 warn。
     *
     * 少接的症狀都是「某個演出看起來不對」而且不報錯，跟其他十幾種原因長得一樣，所以進場就講清楚。
     */
    private warnUnwiredLayers(): void {
        const where = `${this.node.parent?.name}/${this.node.name}`;
        if (!this.blackOverlay) console.warn(`[SlotMachineView] ${where} 的 blackOverlay（Layer_Black/Black）沒接，中獎與聚焦時不會壓黑`);
        if (!this.miLayer) console.warn(`[SlotMachineView] ${where} 的 miLayer（Layer_Mi）沒接，聚焦的那一軸會留在壓黑底下`);
        if (!this.winLayer) console.warn(`[SlotMachineView] ${where} 的 winLayer（Layer_Win）沒接，中獎與聽牌中的符號會留在盤面裡，被遮罩裁切、被壓黑蓋住`);
        if (!this.customLayer) console.warn(`[SlotMachineView] ${where} 的 customLayer（Layer_Custom）沒接，FG 金牌飛入不會播`);
    }

    /**
     * 建一個空的 UI 節點並掛到指定父節點的最後面。
     *
     * @param name 節點名稱。
     * @param parent 父節點。
     * @returns 新節點。layer 跟機台一致——程式建出來的節點 layer 不會自動修正，Camera 遮罩會整個
     *          擋掉（踩坑 #3）。
     */
    private makeLayerNode(name: string, parent: Node): Node {
        const node = new Node(name);
        node.layer = this.node.layer;
        node.addComponent(UITransform);
        parent.addChild(node);
        return node;
    }

    /**
     * 把各欄依自己的寬度由左到右排開，欄與欄之間隔 {@link symbolSpacing} 的 x，整組水平置中，不用手動擺位置。
     *
     * 欄距取各欄 UITransform 的寬度（各欄在 onLoad 時已依 {@link symbolSize} 設好），不是「根節點寬 ÷ 欄數」：根節點維持跟盤面遮罩圖
     * （Reel_mask，含外框）同尺寸，用它平分會把外側兩欄推到框上。
     * y 保留各欄在 prefab 上的值——遮罩的框內區在圖裡偏上，靠各欄的 y 對齊；頭尾兩欄再往下移
     * {@link edgeReelOffsetY}。移動是加在 prefab 的值上，所以只能在 {@link init} 跑這一次，重跑會累加。
     */
    private layoutReelColumns(): void {
        const widths = this.reelViews.map((reel) => reel.getComponent(UITransform)?.contentSize.width ?? 0);
        const gap = this.symbolSpacing.x;
        const total = widths.reduce((sum, w) => sum + w, 0) + gap * Math.max(0, widths.length - 1);
        if (total <= 0) return;
        const last = this.reelViews.length - 1;
        let left = -total / 2;
        for (let i = 0; i < this.reelViews.length; i++) {
            const reelNode = this.reelViews[i].node;
            const y = reelNode.position.y - (i === 0 || i === last ? this.edgeReelOffsetY : 0);
            reelNode.setPosition(left + widths[i] / 2, y, reelNode.position.z);
            left += widths[i] + gap;
        }
    }

    /**
     * 整台套用同一組轉輪節奏。
     *
     * @param timing 起轉曲線／起轉時長／輪轉速度／落定曲線／落定時長／回彈高度／上彈時長／落回時長。
     */
    applyTiming(timing: ReelSpinTiming): void {
        for (const reel of this.reelViews) {
            reel.applyTiming(timing);
        }
    }

    private static readonly SPINE_ANIM_MAP: Record<string, string> = {
        fu: 'idle',
        caishen: 'animation',
        jin_chan: 'h2',
        wealth_tree: 'h3',
        golden_carp: 'h4',
        golden_ruyi: 'h5',
        a: 'n1',
        k: 'n2',
        q: 'n3',
        j: 'n4',
        ten: 'n5',
    };

    /**
     * 播中獎符號的動畫，同時把沒中獎的格子壓暗。
     *
     * @param achieves 中獎資料，含每組的座標。
     * @param loop 動畫是否循環，預設 true。
     * @returns 全部開始播放後 resolve；loop 為 false 時等播完。
     */
    playSymbolWins(achieves: AchieveItem[], loop: boolean = true): Promise<void> {
        this.setSymbolSpinesTimeScale(1);

        const toPlay = SlotMachineView.collectWinTargets(achieves);
        if (toPlay.length === 0) return Promise.resolve();

        // 壓黑非中獎圖示
        this.dimNonWinning(toPlay);

        return new Promise<void>((resolve) => {
            if (loop) this.playWinsLooping(toPlay, resolve);
            else this.playWinsOnce(toPlay, resolve);
        });
    }

    /**
     * 把中獎資料攤平成「哪一格要播哪支動畫」的清單。
     *
     * @param achieves 中獎資料。
     * @returns 每一格的欄、列與動畫名稱；不是連線、沒有對應動畫的項目會被濾掉。
     */
    private static collectWinTargets(achieves: AchieveItem[]): WinTarget[] {
        const toPlay: WinTarget[] = [];

        for (const achieve of achieves) {
            if (achieve.type !== 'line' || !achieve.line || !achieve.icon) continue;

            const animName = SlotMachineView.SPINE_ANIM_MAP[achieve.icon];
            if (!animName) continue;

            // line 可能帶逗號分隔（例如 "1,2,3"），去掉後一個字元就是一列
            const rows = String(achieve.line).replace(/,/g, '').split('').map(Number);
            const len = achieve.length ?? rows.length;
            const isLeft = achieve.left === 1;

            for (let i = 0; i < len; i++) {
                toPlay.push({ col: isLeft ? i : 4 - i, row: rows[i], animName });
            }
        }

        return toPlay;
    }

    /**
     * 輪播模式：全部循環播放，等第一支真的播出來的 spine 跑完一輪就 resolve。
     *
     * 只掛第一支的完成回呼，是因為所有 spine 同時起跑、長度一致，
     * 等一支等於等全部；掛多支只會讓 resolve 被呼叫好幾次。
     *
     * @param toPlay 要播的格子清單。
     * @param resolve 播完一輪後呼叫。一支都沒播成功時立刻呼叫，避免流程卡住。
     */
    private playWinsLooping(toPlay: WinTarget[], resolve: () => void): void {
        let resolved = false;
        const onFirst = (): void => {
            if (resolved) return;
            resolved = true;
            resolve();
        };

        let hasBound = false;
        for (const { col, row, animName } of toPlay) {
            const played = this.reelViews[col]?.playWinAnim(row, animName, true, hasBound ? undefined : onFirst);
            if (!hasBound && played) hasBound = true;
        }

        if (!hasBound) resolve();
    }

    /**
     * 單次模式：全部一起播一遍。
     *
     * Cocos Creator 的 `setCompleteListener` 對 loop=false 的 spine 不會觸發，
     * 所以這裡不等回呼，改用固定 1 秒的 timeout 收尾（動畫 0.8 秒 + buffer）。
     *
     * @param toPlay 要播的格子清單。
     * @param resolve 時間到之後呼叫。一支都沒播成功時立刻呼叫。
     */
    private playWinsOnce(toPlay: WinTarget[], resolve: () => void): void {
        let hasAny = false;
        for (const { col, row, animName } of toPlay) {
            if (this.reelViews[col]?.playWinAnim(row, animName, false)) hasAny = true;
        }

        if (!hasAny) {
            resolve();
            return;
        }
        this.scheduleOnce(resolve, 1);
    }

    /** 停掉所有中獎動畫並關掉壓黑。 */
    stopAllSymbolWins(): void {
        for (const reel of this.reelViews) {
            reel.stopAllWinAnims();
        }
        this.setBlack(false);
    }

    /**
     * 整台調整符號動畫的播放速度。
     *
     * @param scale 倍率，1 為原速、0 為凍結。
     */
    setSymbolSpinesTimeScale(scale: number): void {
        for (const reel of this.reelViews) {
            reel.setSymbolSpinesTimeScale(scale);
        }
    }

    /**
     * 開關整台的壓黑：{@link blackOverlay} 淡入蓋在盤面上、淡出後關掉，預設各 {@link BLACK_FADE_SEC} 秒。
     *
     * 淡入淡出用節點上的 `UIOpacity`（0–255），最暗就是 Sprite 本身的顏色（alpha 128）。已經朝同一個方向走
     * 就什麼都不做——聽牌換下一軸時會重複呼叫開，不該每次重來；方向相反時停掉前一段，從當下的透明度接著補，
     * 時長照剩下的距離縮短，畫面不會跳一下。
     *
     * 中獎中的物件在它上面的 `Layer_Win`，不受影響；沒中獎的格子（含特殊符號層的 Wild／Scatter）都在
     * `Layer_Reels` 裡，被它蓋住。中獎與壓黑仍然是兩個互不知道對方的系統（規格書 §11.7），只是合成方式
     * 從「狀態機的優先權」換成了「節點的上下層」，不碰任何符號。
     *
     * 2026-10-20 前這裡是打開輪軸旗標，讓沒有強制狀態的格子推算成 `Black` 狀態、逐格乘顏色；更早是逐格
     * `tween(sprite).to(..., { color })`，跟金牌 tint 搶同一個 `Sprite.color`，誰後到誰贏（見
     * `.docs/1003-symbol-system-gap-analysis.md` 第二節第 6 條）。
     *
     * 除了本類別的 {@link playSymbolWins}，1003 自己的連鎖流程（`CascadeReelsTask` 的中獎階段）
     * 也直接呼叫這裡，所以是 public。
     *
     * @param on true = 壓黑，false = 還原。
     * @param fadeSec 從全亮到全黑（或反過來）要幾秒；聽牌與 FG 瞇牌結束時用轉輪節奏的 `focusFadeOutSec`，
     *                其他地方用預設的 {@link BLACK_FADE_SEC}。
     */
    public setBlack(on: boolean, fadeSec: number = BLACK_FADE_SEC): void {
        const node = this.blackOverlay;
        if (!node?.isValid || on === this.blackOn) return;
        this.blackOn = on;

        const opacity = node.getComponent(UIOpacity) ?? node.addComponent(UIOpacity);
        this.blackTween?.stop();
        if (on) node.active = true;

        const target = on ? 255 : 0;
        const duration = (fadeSec * Math.abs(target - opacity.opacity)) / 255;
        this.blackTween = tween(opacity)
            .to(duration, { opacity: target })
            .call(() => {
                this.blackTween = null;
                if (!on) node.active = false;
            })
            .start();
    }

    /**
     * 把不在中獎位置的符號壓暗，凸顯中獎組合。
     *
     * 中獎位置本身不需要在這裡處理——它們會被 `playSymbolWins` 在中獎層設成 `WinAnimation`，物件放在
     * 壓黑之上的 `Layer_Win`，自動不受壓黑影響。
     *
     * @param _winPositions 中獎格子的座標，保留參數維持呼叫端相容。
     */
    private dimNonWinning(_winPositions: { col: number; row: number }[]): void {
        this.setBlack(true);
    }

    /**
     * 依名稱矩陣重建各欄的輪帶內容。
     *
     * @param iconMatrix 外層是欄、內層是該欄的符號名稱。
     */
    updateStrips(iconMatrix: string[][]): void {
        for (let i = 0; i < this.reelViews.length; i++) {
            if (iconMatrix[i]) {
                this.reelViews[i].updateStrip(iconMatrix[i]);
            }
        }
    }
}
