import type { SlotGridLayout } from '../models/SlotGrid';

export interface SlotLayoutSource {
    readonly cols: number;
    /** 每欄可視列數一致時給單一數字；不規則輪帶（如葫蘆型盤面）給各欄列數的陣列。 */
    readonly rows: number | readonly number[];
}

/** 盤面上下各露出幾格不計分的 damp */
export interface SlotBoardDamp {
    readonly top: number;
    readonly bottom: number;
}

export const TEMPORARY_SLOT_LAYOUT_SOURCE: SlotLayoutSource = { cols: 6, rows: 5 };

/**
 * 各遊戲的本地盤面形狀，以可見格為準。只有「不規則輪帶」的遊戲需要登記——沒登記的一律沿用
 * TEMPORARY_SLOT_LAYOUT_SOURCE。
 *
 * 玩家端 API 不在回應裡給盤面大小（v7.0 起放在前端打包的遊戲固定資料檔），所以照
 * 後端串接包 `games/<game_id>.json` 的 `board` 登記在這裡：`rows_per_column` 扣掉上下 damp 就是可見格。
 */
const SLOT_LAYOUT_BY_GAME: Readonly<Record<string, SlotLayoutSource>> = {
    // 巨亨麻將：4-5-5-5-4 葫蘆型（後端全窗格 6-7-7-7-6，上下各 1 格 damp）
    '1003': { cols: 5, rows: [4, 5, 5, 5, 4] },
};

/** 各遊戲盤面上下的 damp 格數，照 `games/<game_id>.json` 的 `board.damp_top`／`damp_bottom` */
const BOARD_DAMP_BY_GAME: Readonly<Record<string, SlotBoardDamp>> = {
    '1003': { top: 1, bottom: 1 },
};

/**
 * 取得該遊戲的本地登記形狀。
 *
 * @param gameId 遊戲代號。
 * @returns 登記的形狀；未登記回傳共用預設值。
 */
export function getSlotLayoutSource(gameId: string): SlotLayoutSource {
    return SLOT_LAYOUT_BY_GAME[gameId] ?? TEMPORARY_SLOT_LAYOUT_SOURCE;
}

/**
 * 取得該遊戲盤面上下的 damp 格數。後端 `rl` 每軸是「上 damp＋可見格＋下 damp」，解碼時要先扣掉。
 *
 * @param gameId 遊戲代號。
 * @returns 上下的 damp 格數；未登記的遊戲兩邊都是 0。
 */
export function getBoardDamp(gameId: string): SlotBoardDamp {
    return BOARD_DAMP_BY_GAME[gameId] ?? { top: 0, bottom: 0 };
}

/**
 * 把登記的形狀轉成解碼用的盤面設定。
 *
 * @param source 盤面形狀。
 * @returns 盤面設定；不規則輪帶的 `visibleRows` 是各欄最大值，逐欄列數放在 `visibleRowsPerColumn`。
 */
export function createSlotGridLayout(source: SlotLayoutSource): SlotGridLayout {
    const rows = source.rows;
    const isPerColumn = typeof rows !== 'number';
    return {
        columns: source.cols,
        visibleRows: isPerColumn ? Math.max(...rows) : rows,
        visibleRowsPerColumn: isPerColumn ? rows : undefined,
        bufferRows: 0,
        bufferPlacement: 'start',
        sourceRowOrder: 'top-down',
        presentationRowOrder: 'top-down',
    };
}
