import type { ReelTimingOverride, ReelTimingTier } from '../config/ReelTimingDebugStore';

// reelConfig.json 的路徑（bundle 相對路徑，不含副檔名）
export const REEL_CONFIG_PATH = 'resources/jsons/reelConfig';

// 對應 cc.TweenEasing 的合法字串清單，這裡刻意不 import cc 保持這份檔案跟引擎解耦
const VALID_EASE_NAMES = new Set([
    'linear', 'smooth', 'fade', 'constant',
    'quadIn', 'quadOut', 'quadInOut', 'quadOutIn',
    'cubicIn', 'cubicOut', 'cubicInOut', 'cubicOutIn',
    'quartIn', 'quartOut', 'quartInOut', 'quartOutIn',
    'quintIn', 'quintOut', 'quintInOut', 'quintOutIn',
    'sineIn', 'sineOut', 'sineInOut', 'sineOutIn',
    'expoIn', 'expoOut', 'expoInOut', 'expoOutIn',
    'circIn', 'circOut', 'circInOut', 'circOutIn',
    'elasticIn', 'elasticOut', 'elasticInOut', 'elasticOutIn',
    'backIn', 'backOut', 'backInOut', 'backOutIn',
    'bounceIn', 'bounceOut', 'bounceInOut', 'bounceOutIn',
]);

// 以下兩組預設值跟 resources/jsons/reelConfig.json 保持一致：json 讀不到、或 DebugPanel 比 json 早畫出來時
// 用的就是這裡，兩邊不一樣會讓面板跟實際生效的值對不起來。改 json 時這裡要一起改

// 消除補格的一般節奏預設值（快轉/急速轉改由「整體速度」倍率處理，不再各自寫死一組節奏）。
// fillStagger 0：同一欄的牌一起落下（2026-10-19 照參考影片，原本 0.06）；落地回彈是往上彈，
// 錯開起跑的話上面那顆會在下面那顆還彈在半空時落定，兩張牌疊在一起
const DEFAULT_TIER: ReelTimingTier = { winFx: 2, fill: 0.3, fillStagger: 0, fillEase: 'quadIn' };

// 2026-10-22 照原版參考影片（等速每秒 25.2 格、起轉與停輪各軸間隔約 0.10／0.11 秒、第一軸 1.76 秒落定、
// 落定後往上彈約 6% 格距再落回）。
// 起轉 backIn 先微微上提再加速：backIn 收尾速度是「一格 ÷ 時長」的 4.7 倍，0.19 秒剛好接上每秒 25 格；
// 落定 quadOut 初速是「一格 ÷ 時長」的 2 倍，0.08 秒同樣接上等速、不衝過定位。改 spinSpeed 時這兩個時長
// 要跟著換算，不然進出等速段會頓一下。回彈是落定之後另外播的一段（stopBounce*），落定曲線再選
// backOut／elasticOut 會先衝過頭再接回彈，等於彈兩次。
// 2026-10-28 停輪間隔改成 0.30 秒（不再照參考影片的 0.11）、聽牌時間改成 3 秒
export const DEFAULT_REEL_CONFIG: ReelTimingOverride = {
    beginEase: 'backIn',
    beginDuration: 0.19,
    spinSpeed: 25,
    spinDuration: 1.49,
    bounceEase: 'quadOut',
    bounceDuration: 0.08,
    stopBounceHeight: 0.06,
    stopBounceUp: 0.08,
    stopBounceDown: 0.08,
    // Scatter 落地音效：2026-11-02 使用者要求比原本（回彈結束後，約落定後 0.16 秒）提早 0.5 秒左右，
    // 換算成碰到定位之前 0.34 秒
    scatterSoundLead: 0.34,
    startInterval: 0.1,
    stopInterval: 0.3,
    tenpaiDuration: 3,
    // FG 金牌轉換（2026-10-23 在 DebugPanel 調好的值）：spine 起轉後 1 秒 → 瞇牌再 1 秒 → 金牌再 0.5 秒，
    // 依序接續（換算成從起轉算是 1／2／2.5 秒）；飛入時長 1.2 秒是第一張出發到最後一張排好（參考影片原本是
    // 0.48 秒）；停輪從排好起算
    miGoldSpineDelay: 1,
    miGoldMiDelay: 1,
    miGoldFlyDelay: 0.5,
    miGoldFlyDuration: 1.2,
    miGoldStopDelay: 1.3,
    // 瞇牌／聽牌框與壓黑一起淡出的秒數；0.25 是壓黑原本的淡出時間（SlotMachineView 的 BLACK_FADE_SEC）
    focusFadeOutSec: 0.25,
    // 進 FG 轉場結束後、升級倍數動畫前的停頓（2026-10-29 定 0.5 秒）；0 是轉場一結束就接著播
    fgEnterDelay: 0.5,
    tier: DEFAULT_TIER,
};

/**
 * 讀一個數值欄位：是數字而且不小於下限才採用，否則沿用預設。
 *
 * @param value 設定檔裡的原始值。
 * @param fallback 不合格時要用的值。
 * @param min 下限；含等於。
 * @param exclusiveMin true 時下限本身也不合格（用在會被拿去當除數的欄位）。
 * @returns 採用的數值。
 */
function readNumber(value: unknown, fallback: number, min: number, exclusiveMin = false): number {
    if (typeof value !== 'number' || !Number.isFinite(value)) return fallback;
    return value > min || (!exclusiveMin && value === min) ? value : fallback;
}

/**
 * 讀一個緩動名稱欄位：是合法的 cc.TweenEasing 名稱才採用，否則沿用預設。
 *
 * @param value 設定檔裡的原始值。
 * @param fallback 不合格時要用的值。
 * @returns 採用的緩動名稱。
 */
function readEase(value: unknown, fallback: string): string {
    return typeof value === 'string' && VALID_EASE_NAMES.has(value) ? value : fallback;
}

/**
 * 把設定檔裡的消除補格節奏解析成 ReelTimingTier。
 *
 * @param raw 原始設定，格式不對時整段忽略。
 * @param fallback 解析不出來時要用的預設值。
 * @returns 解析後的節奏設定。
 */
function parseTier(raw: unknown, fallback: ReelTimingTier): ReelTimingTier {
    const obj = raw as Partial<Record<keyof ReelTimingTier, unknown>> | null;
    if (!obj) return { ...fallback };

    return {
        winFx: readNumber(obj.winFx, fallback.winFx, 0, true),
        fill: readNumber(obj.fill, fallback.fill, 0, true),
        fillStagger: readNumber(obj.fillStagger, fallback.fillStagger, 0),
        fillEase: readEase(obj.fillEase, fallback.fillEase),
    };
}

/**
 * 解析 reelConfig.json，格式不對的欄位（或整段 tier）保留預設值，不整份丟棄。
 *
 * 起轉／落定時長與速度會被拿去當除數，所以必須大於 0；輪轉時長與兩個間隔可以是 0（結果一到就停／
 * 整台同時起轉／停輪）。回彈的高度與兩段時長也可以是 0，代表不彈。
 *
 * @param raw json 內容。
 * @returns 解析後的轉輪節奏。
 */
export function parseReelConfig(raw: unknown): ReelTimingOverride {
    const d = DEFAULT_REEL_CONFIG;
    const obj = raw as Partial<Record<keyof ReelTimingOverride, unknown>> | null;
    if (!obj) return { ...d, tier: { ...d.tier } };

    return {
        beginEase: readEase(obj.beginEase, d.beginEase),
        beginDuration: readNumber(obj.beginDuration, d.beginDuration, 0, true),
        spinSpeed: readNumber(obj.spinSpeed, d.spinSpeed, 0, true),
        spinDuration: readNumber(obj.spinDuration, d.spinDuration, 0),
        bounceEase: readEase(obj.bounceEase, d.bounceEase),
        bounceDuration: readNumber(obj.bounceDuration, d.bounceDuration, 0, true),
        stopBounceHeight: readNumber(obj.stopBounceHeight, d.stopBounceHeight, 0),
        stopBounceUp: readNumber(obj.stopBounceUp, d.stopBounceUp, 0),
        stopBounceDown: readNumber(obj.stopBounceDown, d.stopBounceDown, 0),
        scatterSoundLead: readNumber(obj.scatterSoundLead, d.scatterSoundLead, 0),
        startInterval: readNumber(obj.startInterval, d.startInterval, 0),
        stopInterval: readNumber(obj.stopInterval, d.stopInterval, 0),
        tenpaiDuration: readNumber(obj.tenpaiDuration, d.tenpaiDuration, 0),
        miGoldSpineDelay: readNumber(obj.miGoldSpineDelay, d.miGoldSpineDelay, 0),
        miGoldMiDelay: readNumber(obj.miGoldMiDelay, d.miGoldMiDelay, 0),
        miGoldFlyDelay: readNumber(obj.miGoldFlyDelay, d.miGoldFlyDelay, 0),
        miGoldFlyDuration: readNumber(obj.miGoldFlyDuration, d.miGoldFlyDuration, 0, true),
        miGoldStopDelay: readNumber(obj.miGoldStopDelay, d.miGoldStopDelay, 0),
        focusFadeOutSec: readNumber(obj.focusFadeOutSec, d.focusFadeOutSec, 0),
        fgEnterDelay: readNumber(obj.fgEnterDelay, d.fgEnterDelay, 0),
        tier: parseTier(obj.tier, d.tier),
    };
}
