import { _decorator, Node } from 'cc';
import { BaseUIComponent } from './BaseUIComponent';
import { BaseToggleGroup } from './BaseToggleGroup';
const { ccclass, property } = _decorator;

/**
 * 單顆開關：點擊切換 ON／OFF 兩個子節點的顯示。
 *
 * 父節點掛了 BaseToggleGroup 時會自動註冊成群組的一員，改由群組決定誰亮；
 * 沒有群組時就是獨立的一顆開關。
 *
 * 原本從 1001 複製（2026-09-22）。2026-09-23 起這份不再與 1001 一致：`On`／`Off` 的解析
 * 改成惰性的 {@link ensureNodes}，讓群組可以在自己的 `onLoad`（早於子節點的 `onLoad`）就
 * 安全地呼叫 `setToggle()`，詳見 BaseToggleGroup 的檔頭。
 *
 * 跟 entry 的 GameToggle 仍是同一套點擊設計：群組內再點一次已經亮的那顆會變成「全部不選」、
 * 群組回呼收到 index = -1（agent-pitfalls.md 坑 #8），不允許無選取的用途要在回呼裡擋掉
 * index < 0。
 */
@ccclass('1003/BaseToggle')
export class BaseToggle extends BaseUIComponent {
    @property({ type: Node, displayName: 'ON節點' }) public On: Node = null!;
    @property({ type: Node, displayName: 'OFF節點' }) public Off: Node = null!;

    /**
     * 設定狀態改變時的回呼。
     *
     * @param v 回呼，參數是切換後的 ON 狀態。
     */
    public set onToggleOn(v: (isOn: boolean) => void) {
        this._onToggleOn = v;
    }
    private _onToggleOn: ((isOn: boolean) => void) | null = null;

    /**
     * 是否為點亮狀態。
     *
     * @returns true = 目前是 ON。
     */
    public get IsON(): boolean {
        this.ensureNodes();
        return this._isON;
    }
    private _isON: boolean = false;

    /** ensureNodes() 跑過了沒；必須冪等，第二次呼叫不能再從已被改過的 active 推導 _isON */
    private _nodesResolved = false;

    private _group: BaseToggleGroup | null = null;

    /**
     * 解析 ON／OFF 節點並同步初始狀態，只有第一次呼叫會真的執行。
     *
     * 抽出來而不是留在 `onLoad()`，是因為父節點的 `BaseToggleGroup` 會在它自己的 `onLoad`
     * 就收集並 `register()` 這顆 Toggle，而父節點的 `onLoad` 早於子節點——那時這裡若還沒
     * 解析過節點，`setToggle()` 就會對著 null 空轉。
     *
     * 冪等是必要的：初始狀態是從 `On.active` 推導的，跑第二次會讀到已經被 `setToggle()`
     * 改過的值，`_isON` 就對不上 prefab 的原始狀態了。
     *
     * Inspector 沒指定 ON／OFF 節點時，退回用子節點名稱 `ON`／`OFF` 去找。
     */
    private ensureNodes(): void {
        if (this._nodesResolved) return;
        this._nodesResolved = true;

        if (!this.On) this.On = this.node.getChildByName('ON')!;
        if (!this.Off) this.Off = this.node.getChildByName('OFF')!;

        // 同步初始狀態：以 On 節點 active 為準；兩邊都 active 時優先保留 Off（預設關閉）
        if (this.On && this.Off && this.On.active && this.Off.active) {
            this.On.active = false;
        }
        this._isON = this.On ? this.On.active : false;
    }

    /**
     * 解析節點、向父節點的群組註冊，並開始監聽點擊。
     *
     * 群組通常已經在自己的 `onLoad` 收過這顆了，這裡的 `register()` 是給「執行期才被搬到
     * 群組底下」的 Toggle 用的補登記；`register()` 本身會去重，重複呼叫無害。
     */
    protected override onLoad(): void {
        this.ensureNodes();

        this._group = this.node.parent?.getComponent(BaseToggleGroup) ?? null;
        this._group?.register(this);
        this.node.on(Node.EventType.TOUCH_END, this.onTouchEnd, this);
    }

    /**
     * 解除點擊監聽。
     */
    protected override onDestroy(): void {
        this.node.off(Node.EventType.TOUCH_END, this.onTouchEnd, this);
    }

    /**
     * 點擊處理：有群組時交給群組選取，沒有群組時自己切換。
     */
    private onTouchEnd(): void {
        if (this._group) {
            // 群組使用：再點一次已選取的項目 = 取消選取（回到都不選）
            if (this._isON) {
                this._group.selectIndex(-1);
            } else {
                this._group.selectToggle(this);
            }
        } else {
            // 單顆使用
            this.setToggle(!this._isON);
        }
    }

    /**
     * 設定開關狀態並通知回呼。
     *
     * @param isON true = 點亮。
     */
    public setToggle(isON: boolean): void {
        this.ensureNodes();

        if (this.On) this.On.active = isON;
        if (this.Off) this.Off.active = !isON;

        this._onToggleOn?.(isON);

        this._isON = isON;
    }
}
