import { easing, tween, UITransform, Vec3, type Node } from 'cc';
import { goldenSymbolIdOf, SYMBOL_IDS } from '../config/SlotGameDefinition';
import type { ReelView_1003 } from '../reel/view/ReelView_1003';
import type { SlotMachineView } from '../reel/view/SlotMachineView';
import type { SymbolView } from '../reel/symbol/SymbolView';
import { SymbolState } from '../reel/symbol/SymbolState';
import { trySetAnimation } from '../utils/SpineSafe';
import { waitSeconds, type TimerHost } from '../utils/Wait';
import type { GameViewAdapter } from './GameViewAdapter';

/**
 * 免費遊戲第三軸的金牌轉換演出，由 {@link startMiGoldConversion} 依序接續排好三段，每一段都從上一段起播算：
 *
 * - {@link playMiGoldSpine}：五軸起轉後播金牌轉換前的 spine（機台的 `Layer_Dragon/dragon`，1.6 秒；沒接的 view 跳過），
 *   播完自己關掉，不擋後面兩段。
 * - 瞇牌：spine 起播後蓋上，第三軸聚焦、蓋上瞇牌特效、其他軸壓黑（由呼叫端決定怎麼蓋），一直蓋到第一軸準備停輪。
 * - {@link playMiGoldIntro}：瞇牌起播後，隨機金牌從盤面外不同位置飛到**轉動中**的第三軸各列排好，再照第三軸的轉速
 *   往下滑出盤面。
 *
 * 停輪由呼叫端在金牌排好後再等一段時間才下（`CascadeReelsTask.runCascadeReels()` 的 `miGoldStopDelay`）。
 *
 * 金牌只是特效，跟結果無關：停輪後第三軸照常停在後端的結果，金牌逐列避開那一列的結果（{@link randomGoldenSymbolIds}）。
 *
 * 飛入節奏的預設照原版參考影片（2026-10-22 的錄影）量出來：0.05 秒錯開出發、單張飛 0.28 秒，0.47 秒左右五顆排好，
 * 0.52 秒開始往下。飛入時長可以調，錯開與單張飛行時間照比例縮放。
 *
 * 金牌從格子用的物件池租（`SymbolImageManager`），從出發、排好到滑出盤面全程放在 `Layer_Custom`：機台最上層，
 * 蓋在機台其他各層之上（層級見 `SlotMachineView` 的類別說明）；這一層有盤面大小的遮罩（`SlotMachineView.onLoad()`），
 * 出發點在盤面外時看不到，進了盤面才出現，往下滑出盤面時在下緣被切掉。不換父節點，所以沒有交棒的那一幀（坑 #53）。
 */

/** 金牌每顆錯開幾秒出發（預設飛入時長下） */
const LAUNCH_STAGGER_SEC = 0.05;

/** 每顆從盤面外飛到格位花幾秒（預設飛入時長下） */
const FLIGHT_SEC = 0.28;

/** 全部落位之後停多久才開始往下滑 */
const SETTLE_HOLD_SEC = 0.05;

/** 出發點離盤面邊緣多遠，以格子寬／高為單位 */
const SPAWN_MARGIN_CELLS = 0.8;

/** 弧線往外拱多少：控制點離直線中點的距離，佔飛行距離的比例 */
const ARC_RATIO = 0.25;

/** {@link playMiGoldIntro} 的兩個時間點 */
export interface MiGoldIntroRun {
    /** 金牌全部飛到定位（排好）時 resolve；FG 的停輪從這一刻起算 */
    readonly arranged: Promise<void>;
    /** 金牌全部滑出盤面、還回物件池之後 resolve */
    readonly finished: Promise<void>;
}

/** {@link playMiGoldIntro} 的選項 */
export interface MiGoldIntroOptions {
    /** 飛入時長（秒）：第一張出發到最後一張排好；不給時照參考影片的節奏 */
    readonly durationSec?: number;
    /** 全部排好之後停幾秒才往下滑；DebugPanel 的治具會拉長它來對位置 */
    readonly holdSec?: number;
    /**
     * 全部排好的那一刻，把第三軸換成只轉得出金牌（`ReelView_1003.convertToGolden()`）；換的時候正好被金牌蓋住。
     * 只有 mock 要開：mock 引擎在 FG 第三軸只出金牌，正式後端由結果決定，不轉
     */
    readonly goldenStrip?: boolean;
}

/** {@link startMiGoldConversion} 的時間點（秒），依序接續，見 `ReelTimingOverride` 的 miGold* 欄位 */
export interface MiGoldTiming {
    /** spine 起播：五軸起轉後幾秒 */
    readonly spineDelay: number;
    /** 瞇牌起播：spine 起播後幾秒 */
    readonly miDelay: number;
    /** 金牌飛入起播：瞇牌起播後幾秒 */
    readonly flyDelay: number;
    /** 金牌飛入時長 */
    readonly flyDuration: number;
}

/** {@link startMiGoldConversion} 的參數 */
export interface MiGoldConversionOptions {
    /** 要播 spine 的 view */
    readonly views: readonly GameViewAdapter[];
    /** 排計時的元件，必須一直開著（坑 #52） */
    readonly host: TimerHost;
    /** 五軸起轉後已經過了幾秒；spine 的起播點已經過了就立即開始，後面兩段照樣接續 */
    readonly elapsed: number;
    /** 各段的時間點 */
    readonly timing: MiGoldTiming;
    /** 要飛入的機台與第三軸（橫直兩台各一組，共用同一組金牌） */
    readonly reels: readonly { readonly machine: SlotMachineView; readonly reel: ReelView_1003 }[];
    /** 由上而下每列的金牌符號 id */
    readonly symbolIds: readonly number[];
    /** 蓋上瞇牌；正式流程連同第三軸聚焦、其他軸壓黑，治具只蓋特效 */
    readonly showMi: () => void;
    /** 到了瞇牌的時間點還能不能蓋：第一軸已經在停輪時不蓋，不然沒人收（例如等待期間 spin 失敗、原地停輪） */
    readonly canShowMi: () => boolean;
    /** 金牌排好之後停幾秒才往下滑，見 {@link MiGoldIntroOptions.holdSec} */
    readonly holdSec?: number;
    /** 金牌排好後第三軸只轉得出金牌，見 {@link MiGoldIntroOptions.goldenStrip} */
    readonly goldenStrip?: boolean;
}

/** {@link startMiGoldConversion} 的三個時間點 */
export interface MiGoldConversionRun {
    /** spine 播完並關掉節點（沒接時是到了起播點）後 resolve */
    readonly spineDone: Promise<void>;
    /** 金牌全部排好後 resolve，橫直兩台都到才算 */
    readonly arranged: Promise<void>;
    /** 金牌全部滑出盤面後 resolve，橫直兩台都到才算 */
    readonly finished: Promise<void>;
}

/**
 * 依序接續排好金牌轉換的三段：五軸起轉後 `spineDelay` 秒播 spine → spine 起播後 `miDelay` 秒蓋瞇牌 →
 * 瞇牌起播後 `flyDelay` 秒金牌飛入。每一段從上一段**實際**起播的那一刻算：結果比 spine 的起播點晚回來時，
 * spine 在結果一到就播，後面兩段跟著順延。spine 播多久不影響後面兩段。
 *
 * 正式流程（`CascadeReelsTask.runCascadeReels()`）與 DebugPanel 的治具共用這一支，差別只在怎麼蓋瞇牌。
 * 計時掛在 `host` 上，整體速度倍率會套上，跟轉輪同一個鐘。
 *
 * @param options 參數，見 {@link MiGoldConversionOptions}。
 * @returns 三個時間點；停輪由呼叫端在 `arranged` 之後自己排。
 */
export function startMiGoldConversion(options: MiGoldConversionOptions): MiGoldConversionRun {
    const { host, timing } = options;

    const spineStarted = waitSeconds(host, timing.spineDelay - options.elapsed);
    const spineDone = spineStarted.then(() => playMiGoldSpine(options.views, host));
    const miStarted = spineStarted
        .then(() => waitSeconds(host, timing.miDelay))
        .then(() => {
            if (options.canShowMi()) options.showMi();
        });
    const runs = miStarted
        .then(() => waitSeconds(host, timing.flyDelay))
        .then(() => options.reels.map(({ machine, reel }) => playMiGoldIntro(machine, reel, options.symbolIds, { durationSec: timing.flyDuration, holdSec: options.holdSec, goldenStrip: options.goldenStrip })));

    return {
        spineDone,
        arranged: runs.then((list) => Promise.all(list.map((run) => run.arranged))).then(() => undefined),
        finished: runs.then((list) => Promise.all(list.map((run) => run.finished))).then(() => undefined),
    };
}

/** 世界座標下的矩形 */
interface WorldRect {
    readonly xMin: number;
    readonly xMax: number;
    readonly yMin: number;
    readonly yMax: number;
}

/**
 * 隨機挑一組金牌：每列從一般符號裡隨機挑一張，換成它的金牌版。
 *
 * 金牌只是特效，不能被看成結果：給了 `avoid` 時，每一列都避開那一列的符號，停輪後同一列不會剛好是同一張。
 * 橫直兩台要看到同一組牌，所以只挑一次、兩台共用。
 *
 * @param count 要幾張（第三軸的資料列數）。
 * @param avoid 每一列要避開的符號 id（通常是這一局第三軸的結果）；沒給或那一列沒有值時不限制。
 * @returns 由上而下每列的金牌符號 id。
 */
export function randomGoldenSymbolIds(count: number, avoid: readonly number[] = []): number[] {
    const golden = Array.from({ length: SYMBOL_IDS.normalMax - SYMBOL_IDS.normalMin + 1 }, (_, i) => goldenSymbolIdOf(SYMBOL_IDS.normalMin + i));
    return Array.from({ length: count }, (_, row) => {
        const candidates = golden.filter((id) => id !== avoid[row]);
        return candidates[Math.floor(Math.random() * candidates.length)];
    });
}

/**
 * 播金牌轉換前的 spine（`SlotMachineView.miGoldSkel`：機台的 `Layer_Dragon/dragon`，橫直兩台都有）。
 *
 * 播的是 Editor 裡設的預設動畫，沒設就取骨架的第一支。寫法照轉場 spine（`TransitionEffect.playTransitionSpine()`）：
 * 動畫長度從骨架資料查，用時長收尾而不是等 completeListener——隱藏中的那個 view 不會 update，等不到。
 * 計時掛在 `host` 上，不掛在 view 上：關著的 view 排的計時會被暫停（坑 #52）。
 *
 * 開了節點還沒真正啟用（某一層父節點關著）就警告並略過：那樣的 spine 第一次 `setAnimation()` 會被引擎靜靜丟掉，
 * 之後設得進去也停在 0 秒，只剩「圖不會動」（坑 #70）。龍原本掛在瞇牌容器 `MiNode` 底下就是這樣。
 *
 * @param views 要播的 view，正式流程是 `game.allViews`。
 * @param host 用來排計時的元件，必須是一直開著的那一個。
 * @returns 播完並關掉節點後 resolve；沒有任何 view 接上時立即 resolve，流程直接進瞇牌。
 */
export function playMiGoldSpine(views: readonly GameViewAdapter[], host: TimerHost): Promise<void> {
    const nodes: Node[] = [];
    let duration = 0;

    for (const v of views) {
        const sk = v.slotMachineView?.miGoldSkel;
        if (!sk?.isValid) continue;
        const data = sk.skeletonData?.getRuntimeData(true);
        const anim = sk.animation || data?.animations[0]?.name;
        if (!anim) {
            console.warn(`[MiGoldIntro] ${v.node.name} 的 miGoldSkel 沒有任何動畫，略過`);
            continue;
        }
        sk.node.active = true;
        if (!sk.node.activeInHierarchy) {
            sk.node.active = false;
            console.warn(`[MiGoldIntro] ${v.node.name} 的 miGoldSkel 有父節點關著，spine 播不出來，略過`);
            continue;
        }
        trySetAnimation(sk, anim, false, 'MiGoldIntro.playMiGoldSpine');
        duration = Math.max(duration, data?.findAnimation(anim)?.duration ?? 0);
        nodes.push(sk.node);
    }

    if (nodes.length === 0) return Promise.resolve();
    return new Promise<void>((resolve) => {
        host.scheduleOnce(() => {
            for (const n of nodes) {
                if (n.isValid) n.active = false;
            }
            resolve();
        }, duration);
    });
}

/**
 * 在一台機台上播第三軸的金牌飛入：飛到各列格位排好，停一下，再照第三軸的轉速往下滑出盤面。
 *
 * 第三軸在底下照轉，金牌對準的是格位本身（`ReelView_1003.rowSlotWorldPosition()`），不是某一顆格子。
 * 給了飛入時長時，錯開出發與單張飛行時間照參考影片的比例一起縮放。機台沒有 `Layer_Custom` 時不演，流程照樣往下走。
 *
 * @param machine 機台。
 * @param reel 第三軸。
 * @param symbolIds 由上而下每個資料列的金牌符號 id。
 * @param options 飛入時長與排好後的停頓，見 {@link MiGoldIntroOptions}。
 * @returns 「排好」與「滑出完畢」兩個時間點；不演時兩個都已經 resolve。
 */
export function playMiGoldIntro(machine: SlotMachineView, reel: ReelView_1003, symbolIds: readonly number[], options: MiGoldIntroOptions = {}): MiGoldIntroRun {
    const layer = machine.customLayer;
    if (!layer?.isValid) return { arranged: Promise.resolve(), finished: Promise.resolve() };

    // 出發點繞著 Layer_Custom 的框算：它跟 Layer_Reels 一樣撐滿盤面，而且不會被搬動。不能用第三軸的父節點——
    // 瞇牌比金牌早開始時，第三軸已經被搬進只有一軸寬的聚焦裁切節點，算出來的「盤面外」會落在隔壁軸上
    const rect = boardWorldRect(layer);
    const cellW = (reel.node.getComponent(UITransform)?.width ?? 0) * Math.abs(reel.node.worldScale.x);
    const cellH = rowSpacing(reel);
    const rows = symbolIds.length;
    const baseSec = Math.max(0, rows - 1) * LAUNCH_STAGGER_SEC + FLIGHT_SEC;
    const scale = options.durationSec !== undefined && baseSec > 0 ? options.durationSec / baseSec : 1;
    const landed: SymbolView[] = [];

    // 最後一張落位那一幀，金牌正好蓋滿這一軸：在這一幀換成金牌輪帶，看不到換的瞬間；滑走之後露出來的、
    // 之後轉進來的都是金牌。要在落位的回呼裡同步換，等 Promise 的話那一幀已經畫完，縫隙會露出一幀白牌（坑 #53）
    let pending = rows;
    const onLand = (): void => {
        pending--;
        if (pending === 0 && options.goldenStrip && reel.node.isValid) reel.convertToGolden();
    };
    const flights = shuffledRows(rows).map((row, i) =>
        flyOne(reel, layer, row, symbolIds[row], spawnPoint(rect, cellW, cellH), i * LAUNCH_STAGGER_SEC * scale, FLIGHT_SEC * scale, onLand).then((view) => {
            if (view) landed.push(view);
        })
    );

    const arranged = Promise.all(flights).then(() => undefined);
    const finished = arranged
        .then(() => wait(layer, options.holdSec ?? SETTLE_HOLD_SEC))
        .then(() => slideOut(reel, landed, cellH, rows));
    return { arranged, finished };
}

/**
 * 一顆金牌從出發點沿弧線飛到某一列的格位上，全程留在 `Layer_Custom`。
 *
 * 弧線是二次貝茲曲線：控制點放在直線中點往上拱的一側，看起來是拋進去而不是直線滑進去；
 * 時間軸套 `quadOut`，快到格位時減速、對準落位。縮放一開始就照那一軸設好，飛行途中不變。
 *
 * @param reel 那一軸，借它的物件池租顯示物件。
 * @param layer 金牌掛的覆蓋層（`Layer_Custom`）。
 * @param row 要落到哪一列（資料列，0 起算）。
 * @param symbolId 金牌符號 id。
 * @param from 出發點的世界座標。
 * @param delay 出發前等幾秒。
 * @param flightSec 飛行花幾秒。
 * @param onLand 落位（或確定不飛）的當下同步呼叫；要在最後一張落位那一幀做的事放這裡，
 *               寫在回傳的 Promise 後面會晚一幀（坑 #53）。
 * @returns 落位之後 resolve 那顆金牌；租不到顯示物件、或飛行途中離開遊戲時為 null。
 */
function flyOne(reel: ReelView_1003, layer: Node, row: number, symbolId: number, from: Vec3, delay: number, flightSec: number, onLand: () => void): Promise<SymbolView | null> {
    const view = reel.symbolManager?.rent(symbolId, SymbolState.Normal, layer);
    if (!view) {
        onLand();
        return Promise.resolve(null);
    }

    const node = view.node;
    const s = reel.node.worldScale;
    node.setWorldScale(s.x, s.y, s.z);
    node.active = false;

    const to = reel.rowSlotWorldPosition(row, new Vec3());
    const control = arcControlPoint(from, to);
    const p = new Vec3();
    const state = { t: 0 };

    return new Promise<SymbolView | null>((resolve) => {
        tween(state)
            .delay(delay)
            .call(() => {
                node.active = true;
                node.setWorldPosition(from);
            })
            .to(flightSec, { t: 1 }, {
                onUpdate: () => {
                    // 第三軸在飛行途中會被搬進聚焦用的裁切節點，每幀重新讀格位的世界座標
                    reel.rowSlotWorldPosition(row, to);
                    quadBezier(from, control, to, easing.quadOut(state.t), p);
                    if (node.isValid) node.setWorldPosition(p);
                },
            })
            .call(() => {
                // 飛行途中離開遊戲時節點已經銷毀
                if (!node.isValid) {
                    onLand();
                    resolve(null);
                    return;
                }
                // 留在 Layer_Custom（最上層、有盤面遮罩），對準格位停住
                node.setWorldPosition(reel.rowSlotWorldPosition(row, to));
                onLand();
                resolve(view);
            })
            .start();
    });
}

/**
 * 排好的金牌照那一軸目前的轉速一起往下滑，滑出盤面後還回物件池。
 *
 * 滑的距離是「列數 + 1」格：最上面那顆也整顆離開最下面那一列，在盤面邊緣被遮罩切掉。
 * 時間用同一個速度換算，看起來就是跟著轉輪往下帶走。
 *
 * @param reel 那一軸，提供轉速與物件池。
 * @param views 排好的金牌。
 * @param cellH 格高（世界座標）。
 * @param rows 列數。
 * @returns 全部還回物件池之後 resolve。
 */
function slideOut(reel: ReelView_1003, views: readonly SymbolView[], cellH: number, rows: number): Promise<void> {
    if (views.length === 0) return Promise.resolve();

    const cells = rows + 1;
    const cellsPerSec = reel.getCellsPerSecond();
    const starts = views.map((v) => v.node.worldPosition.clone());
    const state = { d: 0 };

    return new Promise<void>((resolve) => {
        tween(state)
            .to(cellsPerSec > 0 ? cells / cellsPerSec : 0, { d: cells * cellH }, {
                onUpdate: () => {
                    views.forEach((v, i) => {
                        if (v.node.isValid) v.node.setWorldPosition(starts[i].x, starts[i].y - state.d, starts[i].z);
                    });
                },
            })
            .call(() => {
                for (const v of views) {
                    if (v.node.isValid) reel.symbolManager?.returnView(v);
                }
                resolve();
            })
            .start();
    });
}

/**
 * 盤面的世界矩形，取節點自己的 UITransform（呼叫端傳 `Layer_Custom`，大小跟 `Layer_Reels` 一樣撐滿盤面）。
 *
 * 不用 `getBoundingBoxToWorld()`：它會把子節點（飛行中的金牌、聚焦的那一軸連同上下緩衝格）一起算進去，
 * 比看得到的盤面大（坑 #6）。
 *
 * @param board 跟盤面一樣大的節點。
 * @returns 世界座標下的矩形；沒有 UITransform 時退化成節點所在的一個點。
 */
function boardWorldRect(board: Node): WorldRect {
    const ui = board.getComponent(UITransform);
    const pos = board.worldPosition;
    if (!ui) return { xMin: pos.x, xMax: pos.x, yMin: pos.y, yMax: pos.y };
    const w = ui.width * Math.abs(board.worldScale.x);
    const h = ui.height * Math.abs(board.worldScale.y);
    const xMin = pos.x - ui.anchorX * w;
    const yMin = pos.y - ui.anchorY * h;
    return { xMin, xMax: xMin + w, yMin, yMax: yMin + h };
}

/**
 * 相鄰兩個資料列格位的世界距離，當作格子高度用。
 *
 * @param reel 那一軸。
 * @returns 格高；不到兩列時為 0。
 */
function rowSpacing(reel: ReelView_1003): number {
    if (reel.getDataRowCount() < 2) return 0;
    const a = reel.rowSlotWorldPosition(0, new Vec3());
    const b = reel.rowSlotWorldPosition(1, new Vec3());
    return Math.abs(a.y - b.y);
}

/**
 * 隨機挑一個盤面外的出發點：左、右兩側的上半段，或盤面正上方。
 *
 * 參考影片的金牌都是從上方與左右上角進來的，所以兩側只取盤面上半段，不從下方進來。
 *
 * @param rect 盤面的世界矩形。
 * @param cellW 格寬。
 * @param cellH 格高。
 * @returns 出發點的世界座標。
 */
function spawnPoint(rect: WorldRect, cellW: number, cellH: number): Vec3 {
    const marginX = cellW * SPAWN_MARGIN_CELLS;
    const marginY = cellH * SPAWN_MARGIN_CELLS;
    const midY = (rect.yMin + rect.yMax) / 2;
    const side = Math.floor(Math.random() * 3);
    if (side === 0) return new Vec3(rect.xMin - marginX, lerp(midY, rect.yMax + marginY, Math.random()), 0);
    if (side === 1) return new Vec3(rect.xMax + marginX, lerp(midY, rect.yMax + marginY, Math.random()), 0);
    return new Vec3(lerp(rect.xMin, rect.xMax, Math.random()), rect.yMax + marginY, 0);
}

/**
 * 弧線的控制點：直線中點往垂直方向推 {@link ARC_RATIO} 倍的距離，推向上方的那一側。
 *
 * @param from 起點。
 * @param to 終點。
 * @returns 控制點。
 */
function arcControlPoint(from: Vec3, to: Vec3): Vec3 {
    const dx = to.x - from.x;
    const dy = to.y - from.y;
    const len = Math.hypot(dx, dy) || 1;
    // 兩個垂直方向挑 y 比較大的那一個，弧線才是往上拱
    let nx = -dy / len;
    let ny = dx / len;
    if (ny < 0) {
        nx = -nx;
        ny = -ny;
    }
    const k = len * ARC_RATIO;
    return new Vec3((from.x + to.x) / 2 + nx * k, (from.y + to.y) / 2 + ny * k, 0);
}

/**
 * 二次貝茲曲線上的一點。
 *
 * @param p0 起點。
 * @param p1 控制點。
 * @param p2 終點。
 * @param t 進度 0～1。
 * @param out 寫入結果的向量。
 * @returns 同一個 `out`。
 */
function quadBezier(p0: Vec3, p1: Vec3, p2: Vec3, t: number, out: Vec3): Vec3 {
    const u = 1 - t;
    return out.set(u * u * p0.x + 2 * u * t * p1.x + t * t * p2.x, u * u * p0.y + 2 * u * t * p1.y + t * t * p2.y, 0);
}

/**
 * 0～n-1 的隨機排列：金牌落位的先後順序，不是固定由上而下。
 *
 * @param n 列數。
 * @returns 打亂的列索引。
 */
function shuffledRows(n: number): number[] {
    const rows = Array.from({ length: n }, (_, i) => i);
    for (let i = n - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [rows[i], rows[j]] = [rows[j], rows[i]];
    }
    return rows;
}

/**
 * 線性內插。
 *
 * @param a 起點。
 * @param b 終點。
 * @param t 進度 0～1。
 * @returns 內插值。
 */
function lerp(a: number, b: number, t: number): number {
    return a + (b - a) * t;
}

/**
 * 等幾秒。用 tween 計時而不是元件的 `scheduleOnce`：tween 跟著導演的整體速度倍率走，
 * 急速模式會一起變快；也不會因為掛在關著的元件上被暫停（坑 #52）。
 *
 * @param target tween 的目標節點，只拿來綁生命週期。
 * @param sec 秒數。
 * @returns 時間到之後 resolve。
 */
function wait(target: Node, sec: number): Promise<void> {
    return new Promise<void>((resolve) => tween(target).delay(sec).call(() => resolve()).start());
}
