import { _decorator, Component } from 'cc';
import { SymbolView } from './SymbolView';
import { SymbolState } from './SymbolState';

const { ccclass, property } = _decorator;

/**
 * 一個符號的「狀態模板集」，掛在 `resources/prefabs/Symbols/Symbol_<name>.prefab` 的根節點上。
 *
 * 設計依據：entry repo `docs/SlotSymbolSystem_設計參考.md` §5.2。規格書裡這組模板是內嵌在場景
 * 節點樹（§12.1）；1003 改成一個符號一支 prefab，理由見 §12.3 的取捨表——圖示數量會持續增加、
 * 多人協作時場景檔衝突風險太高。**存法不同，角色完全一樣**：manager 啟動時把每支 prefab
 * instantiate 一次當模板庫，之後池子都是從這裡面的子節點複製出去的。
 *
 * **欄位留空是正常的，不是漏接。** 缺項會由 {@link SymbolImageManager} 依 fallback 規則頂替，
 * 美術不必為每個符號做滿全部狀態——規格書 §12.2 的實測是 16 個符號裡只有 5 個做了瞇牌、
 * 2 個做了壓黑，其餘全靠 fallback。
 */
@ccclass('1003/SymbolImageSet')
export class SymbolImageSet extends Component {
    @property({ tooltip: '後端的符號 id，要跟 SlotGameDefinition.ts 裡宣告的一致' })
    public symbolId: number = 0;

    @property({ type: SymbolView, tooltip: '靜態圖。這一個一定要填，其餘缺項都靠它或它的衍生頂替' })
    public normal: SymbolView = null!;

    @property({ type: SymbolView, tooltip: '轉動模糊。留空時 fallback 到 normal' })
    public blur: SymbolView = null!;

    @property({
        type: SymbolView,
        tooltip: '聽牌強調。留空時 fallback 到 winAnimation（不是 normal，見類別註解）'
    })
    public tenpai: SymbolView = null!;

    @property({ type: SymbolView, tooltip: '中獎演出（含消除的壓扁與爆破）。留空時 fallback 到 normal' })
    public winAnimation: SymbolView = null!;

    /**
     * 取得某個狀態對應的模板（未套用 fallback 的原始值）。
     *
     * fallback 邏輯刻意不放這裡而是放在 {@link SymbolImageManager}，因為建池時需要分辨
     * 「這一格本來就有」與「這一格是頂替來的」——兩者會影響池要不要共用。
     *
     * @param state 要查的狀態。
     * @returns 該狀態在這支 prefab 上宣告的模板；沒宣告時為 null。
     */
    public getTemplate(state: SymbolState): SymbolView | null {
        switch (state) {
            case SymbolState.Normal:
                return this.normal;
            case SymbolState.Blur:
                return this.blur;
            case SymbolState.Tenpai:
                return this.tenpai;
            case SymbolState.WinAnimation:
                return this.winAnimation;
            default:
                return null;
        }
    }
}
