import { _decorator, Component, director, Label, Node, sp, Vec3 } from 'cc';
import { GAME_EVENT_TYPE, gameRuntimeEventBus } from '../events/GameRuntimeEventBus';
import StoreManager from '../store/StoreManager';
import { GameViewAdapter } from './GameViewAdapter';
import AppAudio from '../audio/AppAudio';
import { EFFECTSMAP } from '../audio/AudioConfig';
import { trySetAnimation } from '../utils/SpineSafe';

const { ccclass, property } = _decorator;

/** 對話框彈出（0.67 秒彈到定位，之後是閃光，整段 3 秒） */
const ENTER_ANIM = 'begin';
/** 彈出之後的常駐動畫 */
const LOOP_ANIM = 'loop';
/** 關閉時收起（0.33 秒縮到 0） */
const EXIT_ANIM = 'end';
/** 讀不到 {@link EXIT_ANIM} 長度時的保底秒數 */
const EXIT_FALLBACK_SEC = 0.34;
/** 玩家沒點的話，彈出幾秒後自己關 */
const AUTO_DISMISS_SEC = 10;
/** 對話框本體的骨骼，局數 Label 跟著它縮放；spine 的 `number` 骨骼就掛在它底下 */
const DIALOG_BONE = 'buy_dialog';

/** spine 骨骼的最小切面：世界矩陣的兩個分量與世界座標（spine 座標，跟節點本地座標同單位） */
type SpineBone = { a: number; c: number; worldX: number; worldY: number };

/**
 * 恭喜獲得免費遊戲的彈窗，進 FG 轉場前顯示。點畫面任何地方或等 10 秒關閉，
 * 關完呼叫 `GameStore.completeWinFreeGame()` 讓流程繼續。
 *
 * 2026-10-19 起對話框整個是一支 spine（`buy_dialog`）：標題、文字、局數框都在 spine 裡，進場 `begin` 接
 * `loop`、關閉 `end`。只有局數是另外的 Label，它不在 spine 節點底下，所以每幀依對話框骨骼的縮放把
 * Label 的位置（相對對話框中心）與大小一起換算（{@link syncRoundLabel}），彈出與收起時才會跟著對話框走。
 * 不用 spine 的骨骼掛點（socket）：它要求 Label 是 spine 節點的直接子節點，而且會用骨骼位置蓋掉 prefab 上
 * 擺好的位置，字級也會跟著 spine 節點的縮放一起變。
 */
@ccclass('1003/WinFreeGamePopupView')
export class WinFreeGamePopupView extends Component {
    @property({ type: sp.Skeleton, tooltip: '對話框本體的 spine（buy_dialog）：進場 begin 接 loop，關閉時 end' })
    backgroundSpine: sp.Skeleton = null!;

    @property({ type: Label, tooltip: '局數，會跟著對話框的彈出與收起一起縮放' })
    roundLabel: Label = null!;

    /** 點擊任何地方 */
    @property(Node)
    clickCatcher: Node = null!;

    /** 解除事件訂閱的函式，{@link onDestroy} 時一次呼叫 */
    private disposers: Array<() => void> = [];
    /** 自動關閉的計時；玩家先點了就取消 */
    private dismissTimer: (() => void) | null = null;

    /** 收起計時：用動畫長度計時、不掛播完事件，事件可能不來（坑 #35）；收起期間不是 null，重複點擊不會再關一次 */
    private exitTimer: (() => void) | null = null;

    /** prefab 上 spine 節點的位置與縮放（套直橫版覆寫之前），換算 Label 的相對位置用 */
    private readonly spinePrefabPos = new Vec3();
    private readonly spinePrefabScale = new Vec3(1, 1, 1);
    /** prefab 上 Label 的位置與縮放：對話框完全展開、沒有直橫版覆寫時，Label 就在這裡 */
    private readonly labelPrefabPos = new Vec3();
    private readonly labelPrefabScale = new Vec3(1, 1, 1);

    /** 對話框骨骼；每次進場重新取，取不到時 Label 停在 prefab 上的位置 */
    private dialogBone: SpineBone | null = null;

    /** 記下 prefab 上的擺放、套直橫版覆寫、綁關閉事件，並訂閱彈窗資料。 */
    protected override onLoad(): void {
        this.spinePrefabPos.set(this.backgroundSpine.node.position);
        this.spinePrefabScale.set(this.backgroundSpine.node.scale);
        this.labelPrefabPos.set(this.roundLabel.node.position);
        this.labelPrefabScale.set(this.roundLabel.node.scale);
        this.applyAdapterOverride();

        this.clickCatcher?.on(Node.EventType.TOUCH_END, this.onDismiss, this);

        this.disposers.push(
            gameRuntimeEventBus.on(GAME_EVENT_TYPE.WIN_FREE_GAME_DATA_CHANGED, (event) => {
                if (event.data) this.show(event.data);
            })
        );

        const data = StoreManager.getInstance().getGameStore().winFreeGameData;
        if (data) this.show(data);
    }

    /** 每幀讓局數 Label 跟上對話框骨骼（見 {@link syncRoundLabel}）。 */
    protected override lateUpdate(): void {
        this.syncRoundLabel();
    }

    /** 解除訂閱與計時。 */
    protected override onDestroy(): void {
        this.disposers.forEach((d) => d());
        this.disposers = [];
        if (this.dismissTimer) this.unschedule(this.dismissTimer);
        this.cancelExit();
    }

    /**
     * 直版跟橫版的位置／縮放覆寫，只套在對話框 spine 上；Label 由 {@link syncRoundLabel} 跟著 spine 換算。
     *
     * 2026-10-19 以前還有一組給文字容器 `popup` 的覆寫（直版上移 30、縮 0.7），新版文字都在 spine 裡，那組已經拿掉。
     */
    private applyAdapterOverride(): void {
        const isPortrait = StoreManager.getInstance().getDeviceStore().isPortrait;
        const adapterName = isPortrait ? 'GameViewV' : 'GameViewH';
        const scene = director.getScene();
        if (!scene) return;
        const adapter = scene.getComponentsInChildren(GameViewAdapter).find((a) => a.node.name === adapterName);
        if (!adapter) return;

        const spineNode = this.backgroundSpine.node;
        const lp = adapter.winFreeGamePopupBgSpineLpos;
        if (lp && (lp.x !== 0 || lp.y !== 0 || lp.z !== 0)) spineNode.setPosition(lp);
        const sc = adapter.winFreeGamePopupBgSpineScale;
        if (sc && (sc.x !== 0 || sc.y !== 0 || sc.z !== 0)) {
            spineNode.setScale(this.spinePrefabScale.x * sc.x, this.spinePrefabScale.y * sc.y, this.spinePrefabScale.z * sc.z);
        }
    }

    /**
     * 顯示「獲得免費遊戲」的內容。
     *
     * 照音效規格表（gotofree）：彈窗出現時播放，同時停止所有背景音樂；免費遊戲的背景音樂由
     * `FGState_1003` 進場時再開。2026-10-22 前是 fg_popup 加上一秒後循環的 transition_loop，規格表沒有這兩支。
     *
     * @param data 取得的免費局數。
     */
    private show(data: { freeRoundCount: number }): void {
        this.roundLabel.string = data.freeRoundCount + '';
        this.node.active = true;
        this.playEnter();
        const audio = AppAudio.getInstance();
        audio.stopMusic();
        audio.playEffect(EFFECTSMAP.GOTOFREE);
        this.scheduleAutoDismiss();
    }

    /** 重新開始自動關閉的倒數：{@link AUTO_DISMISS_SEC} 秒內沒點就自己關。 */
    private scheduleAutoDismiss(): void {
        if (this.dismissTimer) this.unschedule(this.dismissTimer);
        const cb = () => this.onDismiss();
        this.dismissTimer = cb;
        this.scheduleOnce(cb, AUTO_DISMISS_SEC);
    }

    /** 玩家關閉：播收起，播完才關窗並讓外部等待的流程繼續。收起期間再點不會重複關。 */
    private onDismiss(): void {
        if (this.exitTimer) return;
        if (this.dismissTimer) {
            this.unschedule(this.dismissTimer);
            this.dismissTimer = null;
        }
        this.playExit(() => {
            this.node.active = false;
            StoreManager.getInstance().getGameStore().completeWinFreeGame();
        });
    }

    /** 播進場：{@link ENTER_ANIM} 播完接 {@link LOOP_ANIM} 循環，Label 從對話框的初始大小（0）開始跟。 */
    private playEnter(): void {
        this.cancelExit();
        const spine = this.backgroundSpine;
        if (trySetAnimation(spine, ENTER_ANIM, false, 'WinFreeGamePopupView.enter')) {
            spine.addAnimation(0, LOOP_ANIM, true, 0);
        }
        this.dialogBone = spine.findBone(DIALOG_BONE) as SpineBone | null;
        if (!this.dialogBone) console.warn(`[WinFreeGamePopupView] spine 沒有骨骼 "${DIALOG_BONE}"，局數 Label 不會跟著對話框縮放`);
        this.syncRoundLabel();
    }

    /**
     * 播收起：{@link EXIT_ANIM} 播完才回呼。
     *
     * 用動畫長度計時，不掛播完事件——事件在動畫名不對、節點中途被關掉時可能永遠不來，關窗流程就卡死（坑 #35）。
     *
     * @param onComplete 播完後的回呼。
     */
    private playExit(onComplete: () => void): void {
        const spine = this.backgroundSpine;
        const duration = trySetAnimation(spine, EXIT_ANIM, false, 'WinFreeGamePopupView.exit') ? spine.findAnimation(EXIT_ANIM)?.duration ?? EXIT_FALLBACK_SEC : 0;
        const done = (): void => {
            this.exitTimer = null;
            if (this.node?.isValid) onComplete();
        };
        this.exitTimer = done;
        this.scheduleOnce(done, duration);
    }

    /** 取消還沒跑完的收起計時（收起途中又被要求顯示時）。 */
    private cancelExit(): void {
        if (!this.exitTimer) return;
        this.unschedule(this.exitTimer);
        this.exitTimer = null;
    }

    /**
     * 讓局數 Label 跟著對話框骨骼縮放：位置相對對話框中心等比縮放、大小乘上同一個倍率。
     *
     * 對話框骨骼的世界縮放 s 在 `begin` 由 0 彈到 1.2 再回到 1、`end` 縮回 0；s = 1 而且沒有直橫版覆寫時，
     * Label 剛好回到 prefab 上擺的位置與大小。直版覆寫改的是 spine 節點本身，這裡依它目前的位置與縮放換算，
     * Label 會一起移動、縮放。
     */
    private syncRoundLabel(): void {
        const bone = this.dialogBone;
        const label = this.roundLabel?.node;
        if (!bone || !label) return;

        const spineNode = this.backgroundSpine.node;
        const s = Math.hypot(bone.a, bone.c);
        // Label 在 spine 座標裡相對對話框中心的位移（prefab 擺放、對話框完全展開時）
        const offsetX = (this.labelPrefabPos.x - this.spinePrefabPos.x) / this.spinePrefabScale.x - bone.worldX;
        const offsetY = (this.labelPrefabPos.y - this.spinePrefabPos.y) / this.spinePrefabScale.y - bone.worldY;
        label.setPosition(
            spineNode.position.x + spineNode.scale.x * (bone.worldX + s * offsetX),
            spineNode.position.y + spineNode.scale.y * (bone.worldY + s * offsetY),
            this.labelPrefabPos.z
        );
        label.setScale(
            this.labelPrefabScale.x * (spineNode.scale.x / this.spinePrefabScale.x) * s,
            this.labelPrefabScale.y * (spineNode.scale.y / this.spinePrefabScale.y) * s,
            this.labelPrefabScale.z
        );
    }
}
