import { director, Director, Node, UIOpacity, Vec3, type sp } from 'cc';

/**
 * 讓一個節點跟著 spine 的某根 bone 移動、縮放，必要時透明度也跟著某個 slot 的 alpha。
 *
 * 美術動效清單裡「數字請前端綁 bone 點：num」這一類用的：spine 裡留一根空的 bone（常常還配一個沒有圖的
 * slot），動畫只在它身上做縮放、位移、淡出，前端把數字 Label 掛上去跟著動。
 *
 * **對齊方式**：建立時記下目標節點在 prefab 上的擺位，並從骨架資料算出那根 bone 在初始姿勢的世界位置與
 * 縮放。之後每一幀照 bone 相對初始姿勢的變化去推目標節點：bone 停在初始姿勢時，節點就待在 prefab 擺的
 * 位置、原本的大小；bone 放大一倍，節點以 bone 為中心跟著放大一倍。所以 prefab 上不必把 Label 精準擺在
 * bone 上，維持現在的擺位就好。目標節點必須跟 spine 節點同一個父節點。
 *
 * **同步時機**：spine 在 `SkeletonSystem.postUpdate` 更新骨架，順序在 `Director.EVENT_AFTER_UPDATE` 之後、
 * `EVENT_BEFORE_DRAW` 之前，所以掛在 `EVENT_BEFORE_DRAW`：讀到的是這一幀的 bone，又趕得上這一幀的繪製。
 * 掛在元件的 update／lateUpdate 會晚一幀。
 *
 * 只處理位移與等比縮放，不處理旋轉與錯切——數字不會被轉，算了反而讓文字歪掉。
 *
 * **縮放只跟這根 bone 自己那一段**（世界縮放 ÷ 父 bone 世界縮放），不含父鏈的縮放；位置照樣跟世界座標。
 * 當初的例子是倍率飛行的落地特效 `win_bar.json`（2026-11-05 移除）：整段動畫（含第 0 格與最後一格）都把 `root`
 * 放大 1.3 倍，那是整個特效的尺寸；數字的大小已經在 prefab 上調好，連父鏈一起跟的話，數字第一次落地後就停在
 * 1.3 倍（動畫播完停在最後一格）。
 */

/** 骨架座標裡 bone 的位置與等比縮放 */
interface BoneTransform {
    x: number;
    y: number;
    scale: number;
}

/** spine runtime 的 bone 物件，只用到世界變換這幾個欄位 */
type RuntimeBone = { a: number; c: number; worldX: number; worldY: number };

/** spine runtime 的 slot 物件，只用到顏色 */
type RuntimeSlot = { color: { a: number } };

/** 骨架 json 裡一根 bone 的初始姿勢欄位（沒寫的欄位是預設值） */
interface BoneJson {
    name: string;
    parent?: string;
    x?: number;
    y?: number;
    rotation?: number;
    scaleX?: number;
    scaleY?: number;
}

/**
 * 取骨架 json 裡的 bone 清單。
 *
 * 讀的是 `sp.SkeletonData._skeletonJson`（`.json` 匯入的骨架才有，`.skel` 二進位的是 null）。
 *
 * @param skeleton 要查的 spine。
 * @returns bone 清單；不是 json 骨架時是 null。
 */
function bonesJsonOf(skeleton: sp.Skeleton): BoneJson[] | null {
    const bones = (skeleton.skeletonData?._skeletonJson as { bones?: BoneJson[] } | null)?.bones;
    return Array.isArray(bones) ? bones : null;
}

/**
 * 從骨架 json 算出某根 bone 在初始姿勢的世界位置與等比縮放（骨架座標）。
 *
 * 沿父鏈把每一根的平移、旋轉、縮放乘上去；錯切與繼承模式不算，這裡用到的 bone 都沒有。
 * 2026-10-29 拿官方 spine runtime 比對過 `win`／`win_bar` 的 `num` 與 `mg_man` 的 `root`，結果一致。
 *
 * @param skeleton 要查的 spine。
 * @param boneName bone 名稱。
 * @returns 初始姿勢的世界變換；不是 json 骨架或找不到這根 bone 時是 null。
 */
export function setupBoneTransform(skeleton: sp.Skeleton, boneName: string): BoneTransform | null {
    const bones = bonesJsonOf(skeleton);
    if (!bones) return null;

    const byName = new Map(bones.map((bone) => [bone.name, bone]));
    const chain: BoneJson[] = [];
    for (let bone = byName.get(boneName); bone; bone = bone.parent ? byName.get(bone.parent) : undefined) {
        chain.unshift(bone);
    }
    if (chain.length === 0) return null;

    // 世界矩陣 [a b; c d] 加平移 (x, y)，從 root 往下乘
    let a = 1, b = 0, c = 0, d = 1, x = 0, y = 0;
    for (const bone of chain) {
        const rad = ((bone.rotation ?? 0) * Math.PI) / 180;
        const sx = bone.scaleX ?? 1;
        const sy = bone.scaleY ?? 1;
        const la = Math.cos(rad) * sx, lb = -Math.sin(rad) * sy, lc = Math.sin(rad) * sx, ld = Math.cos(rad) * sy;
        const lx = bone.x ?? 0, ly = bone.y ?? 0;
        x += a * lx + b * ly;
        y += c * lx + d * ly;
        [a, b, c, d] = [a * la + b * lc, a * lb + b * ld, c * la + d * lc, c * lb + d * ld];
    }
    return { x, y, scale: Math.hypot(a, c) };
}

/**
 * 讀某根 bone 這一幀的世界位置與等比縮放（骨架座標）。
 *
 * @param skeleton 要查的 spine。
 * @param boneName bone 名稱。
 * @returns 這一幀的世界變換；spine 還沒初始化或找不到這根 bone 時是 null。
 */
export function currentBoneTransform(skeleton: sp.Skeleton, boneName: string): BoneTransform | null {
    const bone = skeleton.findBone(boneName) as RuntimeBone | null;
    if (!bone) return null;
    return { x: bone.worldX, y: bone.worldY, scale: Math.hypot(bone.a, bone.c) };
}

/**
 * 取節點的 UIOpacity，沒有就補一個。
 *
 * @param node 目標節點。
 * @returns 那顆 UIOpacity。
 */
function opacityOf(node: Node): UIOpacity {
    return node.getComponent(UIOpacity) ?? node.addComponent(UIOpacity);
}

/**
 * 一個「節點跟著 bone」的綁定。用 {@link SpineBoneFollower.create} 建立，{@link start} 開始每幀同步，
 * {@link stop} 停止並把節點還原成建立時的擺位。
 */
export class SpineBoneFollower {
    private following = false;

    /** 目標節點建立時（prefab 擺位）的位置、縮放、不透明度 */
    private readonly basePos: Vec3;
    private readonly baseScale: Vec3;
    private readonly baseOpacity: number;

    /** spine 節點建立時的縮放；之後 spine 節點被縮放（例如直橫版覆寫）時，目標跟著等比換算 */
    private readonly spineBaseScale: Vec3;

    /** 目標節點在骨架座標裡、相對 bone 初始姿勢位置的位移 */
    private readonly offsetX: number;
    private readonly offsetY: number;

    /** 父 bone 名稱與它初始姿勢的世界縮放；這根就是 root 時是 null，見檔頭「縮放只跟這根 bone 自己那一段」 */
    private readonly parentName: string | null;
    private readonly setupLocalScale: number;

    /**
     * 只記下參數與擺位，請用 {@link SpineBoneFollower.create}。
     *
     * @param skeleton 動畫所在的 spine。
     * @param boneName 要跟的 bone。
     * @param target 要跟著動的節點，必須跟 spine 節點同一個父節點。
     * @param setup bone 的初始姿勢世界變換。
     * @param slotName 要跟透明度的 slot；不給就不動透明度。
     */
    private constructor(
        private readonly skeleton: sp.Skeleton,
        private readonly boneName: string,
        private readonly target: Node,
        setup: BoneTransform,
        private readonly slotName?: string
    ) {
        const spineNode = skeleton.node;
        this.basePos = target.position.clone();
        this.baseScale = target.scale.clone();
        this.baseOpacity = target.getComponent(UIOpacity)?.opacity ?? 255;
        this.spineBaseScale = spineNode.scale.clone();
        this.offsetX = (this.basePos.x - spineNode.position.x) / spineNode.scale.x - setup.x;
        this.offsetY = (this.basePos.y - spineNode.position.y) / spineNode.scale.y - setup.y;

        this.parentName = bonesJsonOf(skeleton)?.find((bone) => bone.name === boneName)?.parent ?? null;
        const parentSetup = this.parentName ? setupBoneTransform(skeleton, this.parentName) : null;
        this.setupLocalScale = parentSetup?.scale ? setup.scale / parentSetup.scale : setup.scale;
    }

    /**
     * 建立綁定。建立的當下就是記錄 prefab 擺位的時刻，所以要在節點還沒被任何演出動過時建立。
     *
     * @param skeleton 動畫所在的 spine。
     * @param boneName 要跟的 bone。
     * @param target 要跟著動的節點，必須跟 spine 節點同一個父節點。
     * @param slotName 要跟透明度的 slot；不給就不動透明度。
     * @returns 綁定；spine 沒資料、找不到這根 bone 或兩個節點不同層時印一行 warn 並回 null。
     */
    public static create(skeleton: sp.Skeleton | null, boneName: string, target: Node | null, slotName?: string): SpineBoneFollower | null {
        if (!skeleton?.isValid || !target?.isValid) return null;
        if (target.parent !== skeleton.node.parent) {
            console.warn(`[SpineBoneFollow] ${target.name} 跟 ${skeleton.node.name} 不在同一個父節點底下，無法跟隨 bone "${boneName}"`);
            return null;
        }
        const setup = setupBoneTransform(skeleton, boneName);
        if (!setup || setup.scale === 0) {
            console.warn(`[SpineBoneFollow] ${skeleton.node.name} 的骨架找不到 bone "${boneName}"（或不是 json 骨架），${target.name} 不會跟著動`);
            return null;
        }
        return new SpineBoneFollower(skeleton, boneName, target, setup, slotName);
    }

    /** 開始每幀同步；已經在同步時不重複掛。 */
    public start(): void {
        if (this.following) return;
        this.following = true;
        director.on(Director.EVENT_BEFORE_DRAW, this.sync, this);
        this.sync();
    }

    /** 停止同步，把節點還原成建立時的位置、縮放與不透明度。 */
    public stop(): void {
        if (!this.following) return;
        this.following = false;
        director.off(Director.EVENT_BEFORE_DRAW, this.sync, this);
        if (!this.target.isValid) return;
        this.target.setPosition(this.basePos);
        this.target.setScale(this.baseScale);
        if (this.slotName) opacityOf(this.target).opacity = this.baseOpacity;
    }

    /**
     * 把目標節點對到 bone 這一幀的位置與縮放；節點或 spine 已經失效就自己停掉。
     */
    private sync(): void {
        if (!this.target.isValid || !this.skeleton.isValid) {
            this.stop();
            return;
        }
        const bone = currentBoneTransform(this.skeleton, this.boneName);
        if (!bone) return;
        const parent = this.parentName ? currentBoneTransform(this.skeleton, this.parentName) : null;
        const localScale = parent?.scale ? bone.scale / parent.scale : bone.scale;

        const spineNode = this.skeleton.node;
        const ratio = localScale / this.setupLocalScale;
        this.target.setPosition(
            spineNode.position.x + spineNode.scale.x * (bone.x + ratio * this.offsetX),
            spineNode.position.y + spineNode.scale.y * (bone.y + ratio * this.offsetY),
            this.basePos.z
        );
        this.target.setScale(
            this.baseScale.x * (spineNode.scale.x / this.spineBaseScale.x) * ratio,
            this.baseScale.y * (spineNode.scale.y / this.spineBaseScale.y) * ratio,
            this.baseScale.z
        );

        if (this.slotName) {
            const slot = this.skeleton.findSlot(this.slotName) as RuntimeSlot | null;
            if (slot) opacityOf(this.target).opacity = this.baseOpacity * slot.color.a;
        }
    }
}
