/**
 * 簡單的 fetch／XHR 攔截器，在 Cocos Creator 環境裡假造 API 回應。
 * 不用 MSW 是因為它依賴的 path-to-regexp 在 SystemJS 環境下不相容。
 *
 * 開啟方式（二選一）：
 * 1. 網址加上 ?mock=true
 *    例：http://localhost:7456/?mock=true
 *
 * 2. 網址加上 ?scenario=xxx
 *    例：http://localhost:7456/?scenario=lobby/normal
 */

interface MockRoute {
    method: string;
    pattern: RegExp;
    handler: (request: Request, match: RegExpMatchArray) => Promise<Response> | Response;
}

const routes: MockRoute[] = [];

// 換掉之前的原生 fetch，對不到路由的請求與外部需要真請求時用
export const originalFetch = globalThis.fetch.bind(globalThis);

// 掛到 window 上方便在 Console 直接打真請求
if (typeof window !== "undefined") {
    (window as any).__originalFetch = originalFetch;
}

/**
 * 登記一條假路由。fetch 與 XHR 共用同一張路由表，先登記的先比對。
 *
 * @param method HTTP 方法，大小寫不拘。
 * @param pattern 比對「路徑＋查詢字串」的正規式，不含網域。
 * @param handler 對到時產生回應；拿到簡化過的 Request（只有 `url`、`method`、`json()`）與比對結果。
 */
export function addMockRoute(
    method: string,
    pattern: RegExp,
    handler: (request: Request, match: RegExpMatchArray) => Promise<Response> | Response
): void {
    routes.push({ method: method.toUpperCase(), pattern, handler });
}

/**
 * 清掉所有假路由。替身本身不會拆掉，之後的請求一律轉給真的 fetch／XHR。
 */
export function clearMockRoutes(): void {
    routes.length = 0;
}

/**
 * 取代全域 fetch 的替身：對得到假路由就交給 handler，對不到就轉給原生 fetch。
 *
 * handler 丟例外時回 500 加錯誤訊息，不讓例外往上丟，呼叫端看到的跟真後端出錯時一樣。
 *
 * @param input 請求網址或 Request。
 * @param init 請求選項；`body` 只支援字串（JSON）。
 * @returns 假回應或真回應。
 */
async function mockFetch(input: RequestInfo | URL, init?: RequestInit): Promise<Response> {
    let pathname: string;
    let method: string = init?.method?.toUpperCase() || "GET";

    if (typeof input === "string") {
        pathname = input;
    } else if (input instanceof URL) {
        pathname = input.pathname + input.search;
    } else if (input instanceof Request) {
        pathname = input.url;
        method = input.method?.toUpperCase() || method;
    } else {
        pathname = String(input);
    }

    // 完整網址只留路徑＋查詢字串，路由的正規式不含網域
    try {
        const url = new URL(pathname, "http://localhost");
        pathname = url.pathname + url.search;
    } catch {
        // 連當成相對路徑都解析不了的網址，就拿原字串去比對路由；對不到時照樣轉給原生 fetch
    }

    // 組一個簡化的 Request 給 handler 用
    const bodyStr = init?.body as string | undefined;
    const mockRequest = {
        url: "http://localhost" + pathname,
        method: method,
        json: async () => {
            if (bodyStr) {
                try {
                    return JSON.parse(bodyStr);
                } catch {
                    return {};
                }
            }
            return {};
        },
    } as Request;

    for (const route of routes) {
        if (route.method !== method) continue;

        const match = pathname.match(route.pattern);
        if (match) {
            console.log(`[SimpleMock] Intercepted: ${method} ${pathname}`);
            try {
                return await route.handler(mockRequest, match);
            } catch (error) {
                console.error(`[SimpleMock] Handler error:`, error);
                return new Response(JSON.stringify({ error: "Mock handler error" }), {
                    status: 500,
                    headers: { "Content-Type": "application/json" },
                });
            }
        }
    }

    // 對不到路由的請求交給原生 fetch
    return originalFetch(input, init);
}

let isStarted = false;
const OriginalXHR = globalThis.XMLHttpRequest;

/** 取代全域 XMLHttpRequest 的替身：對得到假路由就自己產生回應，對不到就整個轉給真正的 XHR。 */
class MockXHR {
    public readyState: number = 0;
    public status: number = 0;
    public statusText: string = "";
    public response: any = null;
    public responseText: string = "";
    public responseType: XMLHttpRequestResponseType = "";
    public responseURL: string = "";
    public timeout: number = 0;
    public withCredentials: boolean = false;

    public onreadystatechange: ((this: XMLHttpRequest, ev: Event) => any) | null = null;
    public onload: ((this: XMLHttpRequest, ev: ProgressEvent) => any) | null = null;
    public onerror: ((this: XMLHttpRequest, ev: ProgressEvent) => any) | null = null;
    public ontimeout: ((this: XMLHttpRequest, ev: ProgressEvent) => any) | null = null;
    public onloadend: ((this: XMLHttpRequest, ev: ProgressEvent) => any) | null = null;
    public onloadstart: ((this: XMLHttpRequest, ev: ProgressEvent) => any) | null = null;
    public onprogress: ((this: XMLHttpRequest, ev: ProgressEvent) => any) | null = null;
    public onabort: ((this: XMLHttpRequest, ev: ProgressEvent) => any) | null = null;

    private _method: string = "GET";
    private _url: string = "";
    private _headers: Record<string, string> = {};
    private _fallback: XMLHttpRequest | null = null;

    /**
     * XHR 介面：記下方法與網址，真正的分派在 send()。
     *
     * @param method HTTP 方法。
     * @param url 目標網址。
     */
    open(method: string, url: string): void {
        this._method = method.toUpperCase();
        this._url = url;
        this.readyState = 1;
        this.responseURL = url;
    }

    /**
     * XHR 介面：記下 header，走 fallback 時會原樣轉給真正的 XHR。
     *
     * @param key header 名稱。
     * @param value header 值。
     */
    setRequestHeader(key: string, value: string): void {
        this._headers[key] = value;
    }

    /**
     * XHR 介面：中止請求。mock 回應是同步產生的，只有 fallback 那條路需要真的中止。
     */
    abort(): void {
        if (this._fallback) this._fallback.abort();
    }

    /**
     * XHR 介面：mock 回應一律是 JSON。
     *
     * @returns 只有 content-type 一行的 header 字串。
     */
    getAllResponseHeaders(): string {
        return "content-type: application/json\r\n";
    }

    /**
     * XHR 介面：只認得 content-type。
     *
     * @param name header 名稱。
     * @returns content-type 的值，其餘一律 null。
     */
    getResponseHeader(name: string): string | null {
        return typeof name === "string" && name.toLowerCase() === "content-type" ? "application/json" : null;
    }

    /**
     * XHR 介面：mock 固定回 JSON，不接受覆寫。
     *
     * @param _mime 忽略。
     */
    overrideMimeType(_mime: string): void {}
    /**
     * XHR 介面：mock 只透過 onreadystatechange／onload 回呼，不走事件機制。
     */
    addEventListener(): void {}
    /**
     * XHR 介面：配合 addEventListener() 的空實作。
     */
    removeEventListener(): void {}
    /**
     * XHR 介面：沒有事件機制可派送。
     *
     * @returns 固定 true。
     */
    dispatchEvent(): boolean { return true; }

    /**
     * 依網址比對 mock 路由表：對得到就同步組出回應，對不到就轉給真正的 XHR。
     *
     * @param body 請求內容。
     */
    send(body?: any): void {
        const pathSearch = (() => {
            try {
                const u = new URL(this._url, "http://localhost");
                return u.pathname + u.search;
            } catch {
                return this._url;
            }
        })();

        const match = matchRoute(this._method, pathSearch);
        if (!match) {
            this._sendFallback(body);
            return;
        }

        const mockRequest = {
            url: this._url,
            method: this._method,
            json: async () => {
                if (typeof body === "string") {
                    try { return JSON.parse(body); } catch { return {}; }
                }
                if (body && typeof body === "object") return body;
                return {};
            },
        } as unknown as Request;

        console.log(`[SimpleMock-XHR] Intercepted: ${this._method} ${pathSearch}`);

        Promise.resolve(match.route.handler(mockRequest, match.match)).then(async (resp) => {
            const text = await resp.text();
            this.status = resp.status;
            this.statusText = resp.status === 200 ? "OK" : "Error";
            this.responseText = text;
            if (this.responseType === "json" || this.responseType === "") {
                try { this.response = JSON.parse(text); } catch { this.response = text; }
            } else if (this.responseType === "text") {
                this.response = text;
            } else {
                this.response = text;
            }
            this._fireComplete();
        }).catch((err) => {
            console.error("[SimpleMock-XHR] Handler error:", err);
            this.status = 500;
            this.statusText = "Mock Error";
            this.responseText = JSON.stringify({ error: String(err) });
            this.response = this.responseType === "json" ? { error: String(err) } : this.responseText;
            this._fireComplete();
        });
    }

    /**
     * 依序把 readyState 推到 2→3→4 並逐段觸發回呼，模擬真正 XHR 的狀態變化。
     *
     * 有些呼叫端是靠 readyState 的中間值判斷進度的，一次跳到 4 會漏掉它們。
     */
    private _fireComplete(): void {
        this.readyState = 2;
        this.onreadystatechange?.call(this as unknown as XMLHttpRequest, new Event("readystatechange"));
        this.readyState = 3;
        this.onreadystatechange?.call(this as unknown as XMLHttpRequest, new Event("readystatechange"));
        this.readyState = 4;
        this.onreadystatechange?.call(this as unknown as XMLHttpRequest, new Event("readystatechange"));
        this.onload?.call(this as unknown as XMLHttpRequest, new ProgressEvent("load"));
        this.onloadend?.call(this as unknown as XMLHttpRequest, new ProgressEvent("loadend"));
    }

    /**
     * 把這次請求原樣交給真正的 XMLHttpRequest，並把回應接回自己身上。
     *
     * @param body 請求內容。
     */
    private _sendFallback(body?: any): void {
        const xhr = new OriginalXHR();
        this._fallback = xhr;
        xhr.open(this._method, this._url);
        for (const k of Object.keys(this._headers)) xhr.setRequestHeader(k, this._headers[k]);
        if (this.responseType) xhr.responseType = this.responseType;
        if (this.timeout) xhr.timeout = this.timeout;
        xhr.onreadystatechange = () => {
            this.readyState = xhr.readyState;
            this.status = xhr.status;
            this.statusText = xhr.statusText;
            this.responseURL = xhr.responseURL;
            try { this.responseText = xhr.responseText; } catch { /* responseType 不允許讀 responseText */ }
            this.response = xhr.response;
            this.onreadystatechange?.call(this as unknown as XMLHttpRequest, new Event("readystatechange"));
        };
        xhr.onload = (e: ProgressEvent) => this.onload?.call(this as unknown as XMLHttpRequest, e);
        xhr.onerror = (e: ProgressEvent) => this.onerror?.call(this as unknown as XMLHttpRequest, e);
        xhr.ontimeout = (e: ProgressEvent) => this.ontimeout?.call(this as unknown as XMLHttpRequest, e);
        xhr.onloadend = (e: ProgressEvent) => this.onloadend?.call(this as unknown as XMLHttpRequest, e);
        xhr.send(body);
    }
}

/**
 * 照登記順序找第一條方法相同、正規式對得到的路由。
 *
 * @param method 大寫的 HTTP 方法。
 * @param pathSearch 路徑＋查詢字串。
 * @returns 路由與比對結果；都對不到時為 null。
 */
function matchRoute(method: string, pathSearch: string): { route: MockRoute; match: RegExpMatchArray } | null {
    for (const route of routes) {
        if (route.method !== method) continue;
        const m = pathSearch.match(route.pattern);
        if (m) return { route, match: m };
    }
    return null;
}

/**
 * 把全域的 fetch／XHR 換成本 bundle 的替身，重複呼叫是安全的。
 *
 * 要不要裝看的是「全域現在是不是本 bundle 的替身」，不能只看模組旗標：離開遊戲後 bundle 的模組不會卸載，
 * 荷魯斯、金虎爺、門神也各帶一份 simple-mock，可能已經把自己的替身蓋在上面，只看旗標的話回到這款遊戲時
 * 會跳過安裝，本 bundle 註冊的假後端路由就攔不到（坑 #67 同一類）。
 */
export function startSimpleMock(): void {
    if (isStarted && globalThis.fetch === mockFetch) return;
    console.log("[SimpleMock] Starting mock server...");
    globalThis.fetch = mockFetch;
    (globalThis as any).XMLHttpRequest = MockXHR;
    isStarted = true;
    console.log("[SimpleMock] Mock server started (fetch + XHR)");
    console.log("[SimpleMock] 用 window.__originalFetch() 可以繞過 mock 送真請求");
}

/**
 * 把全域的 fetch／XHR 換回原生的。路由表不清，下次 {@link startSimpleMock} 照樣生效。
 */
export function stopSimpleMock(): void {
    if (!isStarted) return;
    globalThis.fetch = originalFetch;
    (globalThis as any).XMLHttpRequest = OriginalXHR;
    isStarted = false;
    console.log("[SimpleMock] Mock server stopped");
}

/**
 * 組一個 JSON 回應，給路由的 handler 用。
 *
 * @param data 回應內容，會被 JSON.stringify。
 * @param status HTTP 狀態碼，預設 200。
 * @returns `Content-Type: application/json` 的回應。
 */
export function jsonResponse<T>(data: T, status = 200): Response {
    return new Response(JSON.stringify(data), {
        status,
        headers: { "Content-Type": "application/json" },
    });
}
