import { director } from 'cc';
import GameConfigManager from './GameConfigManager';

// director 是跨 Bundle 共用的全域單例 但這支腳本會隨各遊戲私有 Bundle 每次載入重新產生模組副本
// 如果 installed／currentFactor 只存在模組作用域 每次重進同一款遊戲都會在 director.tick 外面
// 再包一層 舊的包裝閉包（連同它 bind 住的舊 director.tick）永遠不會被釋放 疊到後面就會讓每一幀
// 都對著早已不存在的場景重新嘗試銷毀 演出 s[a]._destroyImmediate is not a function 的崩潰
// 比照 AppAudio／RootStore 的做法 狀態改放 globalThis 讓跨模組副本共用同一份
// key 用 GameConfigManager.GAMEID 動態組出來 這支檔案在每款遊戲都原封不動直接複製 不用改任何字
type SpeedHookGlobalScope = typeof globalThis & Record<string, boolean | number | undefined>;

/**
 * 存放攔截狀態的全域物件，跨模組副本共用同一份（原因見檔頭）。
 *
 * @returns globalThis。
 */
function scope(): SpeedHookGlobalScope {
    return globalThis as SpeedHookGlobalScope;
}

/**
 * 「這款遊戲已經攔截過 director.tick」旗標的 key。每次呼叫才組字串：GAMEID 要等進場後才有值（坑 #30）。
 *
 * @returns 帶 gameId 的 key。
 */
function installedKey(): string {
    return `__slotDirectorSpeedHookInstalled_${GameConfigManager.GAMEID}__`;
}

/**
 * 目前速度倍數的 key，組法同 {@link installedKey}。
 *
 * @returns 帶 gameId 的 key。
 */
function factorKey(): string {
    return `__slotDirectorSpeedFactor_${GameConfigManager.GAMEID}__`;
}

/**
 * 攔截 director.tick(dt) 乘倍數往下傳
 * 含 Component update、Tween、scheduleOnce、Spine 動畫、shader 時間 uniform
 */
export function installDirectorSpeedHook(): void {
    const g = scope();
    if (g[installedKey()]) return;
    g[installedKey()] = true;
    if (g[factorKey()] === undefined) g[factorKey()] = 1;

    const originalTick = director.tick.bind(director);

    director.tick = (dt: number) => originalTick(dt * ((scope()[factorKey()] as number) ?? 1));
}

/**
 * 目前的速度倍數。快停跳過時暫時疊加倍率，結束後要還原成這個值。
 *
 * @returns 倍數；沒設過時是 1。
 */
export function getDirectorSpeedFactor(): number {
    return (scope()[factorKey()] as number) ?? 1;
}

/**
 * 設定目前速度倍數，下一幀起生效。
 *
 * @param factor 倍數；1 是原速。
 */
export function setDirectorSpeedFactor(factor: number): void {
    scope()[factorKey()] = factor;
}

/** 重置加速 NEW_GAME／onDestroy 都要 */
export function resetDirectorSpeedFactor(): void {
    scope()[factorKey()] = 1;
}
