import { _decorator, sp } from 'cc';
import { SymbolView } from './SymbolView';
import { trySetAnimation, tryClearAnimation } from '../../utils/SpineSafe';

const { ccclass, property } = _decorator;

/**
 * 跟主軌同時播放的一支額外 Skeleton，以及它自己的播放設定。
 *
 * 純資料類別（不是 Component），序列化進 prefab 時 `__type__` 是 `@ccclass` 名稱，
 * 不是壓縮過的腳本 uuid（entry docs/agent-pitfalls.md 坑 #40）。
 */
@ccclass('1003/SymbolSpineTrack')
export class SymbolSpineTrack {
    @property({ type: sp.Skeleton, tooltip: '要一起播的 Skeleton；留空的這一筆會被略過' })
    public skeleton: sp.Skeleton | null = null;

    @property({ tooltip: '租借時要播的動畫名稱' })
    public animName: string = 'animation';

    @property({ tooltip: '是否循環播放。只影響租借時的播放，playOnce 一律只播一次' })
    public loop: boolean = false;

    @property({ tooltip: '開始秒數：這個狀態開始播後幾秒這一軌才開始播（不跟著主軌的延遲），等待時停在這支動畫的第一格。0 是立刻開始' })
    public startTime: number = 0;

    @property({ tooltip: '結束秒數：這個狀態開始播後幾秒把這一軌收掉（清掉動畫並隱藏這支 Skeleton），要大於開始秒數。0 是不設，播到自然結束或一直循環' })
    public endTime: number = 0;
}

/** 一次播放實際要用的設定：哪支 skeleton、播哪個動畫、是否循環、在主軌時間軸上的起訖 */
interface ResolvedTrack {
    skeleton: sp.Skeleton;
    anim: string;
    loop: boolean;
    /** 這個狀態開始播後幾秒才開始播；主軌是 {@link SymbolViewSpine.startTime}，停在第一格時為 0 */
    startTime: number;
    /** 這個狀態開始播後幾秒收掉；0 代表不收（主軌一律 0） */
    endTime: number;
    /** 停在第一格當靜態圖（只有主軌會是 true，見 {@link SymbolViewSpine.holdFirstFrame}） */
    held: boolean;
}

/** 時間軸上排定的一個時刻：某一軌在 {@link SymbolViewSpine} 的播放時鐘走到 `at` 秒時要做的事 */
interface TrackCue {
    skeleton: sp.Skeleton;
    at: number;
}

/**
 * Spine 版的顯示層：租出去時播動畫，回收時清掉軌道。
 *
 * 設計依據：entry repo `docs/SlotSymbolSystem_設計參考.md` §6（顯示技術轉接器）。
 * 邏輯層完全感覺不到自己租到的是 Sprite 版還是這一版。
 *
 * 一個狀態可以同時播好幾支 Skeleton：{@link skeleton} 是主軌，{@link extraTracks} 是跟它一起播的
 * 其他軌，租借、回收、調速、播一次都對全部一起作用。主軌沿用單一欄位而不是併進陣列，是為了讓
 * 既有 prefab 上存的 `skeleton`／`animName`／`loop` 不必搬遷。
 *
 * 額外軌可以設開始／結束秒數、主軌可以設開始秒數，全部從這個狀態開始播那一刻起算（額外軌不跟著
 * 主軌的延遲）。時間由這顆元件自己的 update 記（{@link clock}），乘上 {@link setTimeScale} 的倍率，
 * 所以整段被壓成指定秒數時起訖點也等比縮放。
 * 等待開始的軌速度設 0、停在第一格；到了結束秒數就清掉動畫並把那支 Skeleton 關掉。
 *
 * 用在每個符號的 Normal（主軌停在第一格當靜態圖）與 WinAnimation。2026-10-14 起 Erase 併進
 * WinAnimation：一般牌的 WinAnimation 由主軌 `normal`／`golden` 演牌面壓扁、額外軌 `symbol_win` 火焰框
 * 與 `symbol_frame` 爆破。Wild 原本另外接 `scaleTarget` 由程式壓扁，2026-10-19 拿掉。
 */
@ccclass('1003/SymbolViewSpine')
export class SymbolViewSpine extends SymbolView {
    @property({ type: sp.Skeleton, tooltip: '主軌：實際播動畫的 Skeleton；主軌與額外軌都留空時這顆物件等同靜態圖' })
    public skeleton: sp.Skeleton = null!;

    @property({ tooltip: '主軌租借時要播的動畫名稱' })
    public animName: string = 'animation';

    @property({ tooltip: '主軌是否循環播放。中獎中的常駐演出勾起來，一次性爆破不要勾' })
    public loop: boolean = false;

    /**
     * 主軌停在動畫第一格當靜態圖：照樣切到要播的動畫（含 {@link setAnimOverride}），但速度固定 0。
     *
     * 跟靜態圖一樣不算演出時間：{@link playOnce} 不等它、{@link getAnimDuration} 算 0，
     * {@link setTimeScale} 也不會把它帶動。額外軌照常播放。
     */
    @property({ tooltip: '主軌停在第一格當靜態圖：只顯示動畫的第一格、不播放，播一次時也不等它；額外軌照常' })
    public holdFirstFrame: boolean = false;

    /**
     * 主軌延遲幾秒才開始播，等待時停在動畫第一格。跟額外軌的 {@link SymbolSpineTrack.startTime} 同一套
     * 時鐘：從這個狀態開始播那一刻起算，乘上 {@link setTimeScale} 的倍率。
     *
     * 用途是對齊不同骨架的節奏：l 系列的 `symbol` 動畫只有 0.5 秒、0.2 秒就開始壓扁，h 系列的
     * `symbol_p` 是 1.5 秒、1.2 秒才壓扁，WinAnimation 的爆破卻都從第 1 秒開始。l 系列主軌延 1 秒，
     * 壓扁就落在 1.2～1.4 秒，跟 h 系列一致。勾了 {@link holdFirstFrame} 時這個值沒有作用。
     */
    @property({ tooltip: '主軌開始秒數：延遲幾秒才開始播，等待時停在第一格。0 是立刻開始；勾了停在第一格時無效' })
    public startTime: number = 0;

    @property({ type: [SymbolSpineTrack], tooltip: '跟主軌同時播放的其他 Skeleton，各自設定動畫名與是否循環' })
    public extraTracks: SymbolSpineTrack[] = [];

    /**
     * 每個符號的動畫名稱可能不同（例如 `symbol_h` 這份骨架裡 h1 叫 `God`、h2 叫 `h2`），
     * 所以租借時允許外部指定主軌的動畫；沒指定就用 {@link animName}。
     */
    private overrideAnim: string | null = null;

    /** 這一輪播放從開始播那一刻起經過的秒數（已乘上 {@link playbackScale}），開始／結束秒數都跟它比 */
    private clock: number = 0;

    /** {@link setTimeScale} 設的倍率。還在等開始秒數的軌速度固定 0，輪到它時才恢復成這個值 */
    private playbackScale: number = 1;

    /** 還在等開始秒數的軌 */
    private waiting: TrackCue[] = [];

    /** 排了結束秒數、還沒收掉的軌 */
    private ending: TrackCue[] = [];

    /** 被結束秒數收掉而關掉的 Skeleton，下一輪播放或回收時要打開 */
    private readonly hidden = new Set<sp.Skeleton>();

    /** {@link playOnce} 還在等的軌被結束秒數提早收掉時，要算成播完 */
    private onTrackEnded: ((skeleton: sp.Skeleton) => void) | null = null;

    /**
     * 指定這次租借主軌要播的動畫，必須在 {@link onRent} 之前呼叫。額外軌不受影響。
     *
     * @param anim 動畫名稱；傳 null 表示改用 prefab 上設定的 {@link animName}。
     */
    public setAnimOverride(anim: string | null): void {
        this.overrideAnim = anim;
    }

    /** 建立當下先把每一軌都清乾淨，避免 prefab 存檔時殘留的預設動畫在節點一開就播出來。 */
    protected override onInit(): void {
        for (const { skeleton } of this.resolveTracks()) tryClearAnimation(skeleton, 'SymbolViewSpine.onInit');
    }

    /**
     * 歸還：每一軌都停掉動畫、解除監聽並清空軌道，否則下次租出去會先閃一格上一次的最後畫面。
     */
    public override onReturn(): void {
        this.resetTimeline();
        for (const { skeleton } of this.resolveTracks()) {
            skeleton.setCompleteListener(null!);
            tryClearAnimation(skeleton, 'SymbolViewSpine.onReturn');
        }
        this.overrideAnim = null;
        this.playbackScale = 1;
        super.onReturn();
    }

    /** 每一軌都從頭重播，速度回到原速。動畫名不存在時 {@link trySetAnimation} 會吞掉例外並警告一次，不會中斷整條流程 */
    public override resetAni(): void {
        this.playbackScale = 1;
        this.startTimeline(false, 'SymbolViewSpine.resetAni');
    }

    /**
     * 每一軌各播一次，等最晚結束的那一軌結束才回呼。
     *
     * 只等切換成功的軌：動畫名不存在的那一軌不會有結束事件，把它算進去會讓這次播放只能靠
     * `SymbolCell` 的保底計時器收尾。所以監聽是在切完動畫、知道哪幾軌真的在播之後才掛；一軌都沒
     * 播起來（含完全沒接 skeleton）時立刻回呼，行為與基底一致。
     *
     * 被結束秒數提早收掉的軌也算播完：它的 complete 事件不會再來，不算進去的話 `await` 這次播放的
     * 消除流程只能等保底計時器（坑 #35）。停在第一格的主軌（{@link holdFirstFrame}）跟靜態圖一樣
     * 不等，也是同一個理由——它永遠不會播完。
     *
     * 只在 `trackIndex === 0` 時計數，避免其他軌道的結束事件誤觸。
     *
     * @param onComplete 全部播完時呼叫。
     */
    public override playOnce(onComplete: () => void): void {
        for (const { skeleton } of this.resolveTracks()) skeleton.setCompleteListener(null!);
        const playing = this.startTimeline(true, 'SymbolViewSpine.playOnce');
        if (playing.length === 0) {
            onComplete();
            return;
        }

        const pending = new Set(playing);
        const settle = (skeleton: sp.Skeleton): void => {
            if (!pending.delete(skeleton)) return;
            skeleton.setCompleteListener(null!);
            if (pending.size > 0) return;
            this.onTrackEnded = null;
            onComplete();
        };
        this.onTrackEnded = settle;
        for (const skeleton of playing) {
            skeleton.setCompleteListener((entry) => {
                if (entry.trackIndex === 0) settle(skeleton);
            });
        }
    }

    /**
     * 每一軌一起調整播放速度，供三段速（一般／快速／turbo）與消除壓時長用。還在等開始秒數的軌
     * 維持 0，輪到它時才套這個倍率；停在第一格的主軌一直是 0。計算起訖的時鐘也乘上同一個倍率。
     *
     * @param scale 倍率，1 為原速、0 為凍結。
     */
    public override setTimeScale(scale: number): void {
        this.playbackScale = scale;
        for (const { skeleton, held } of this.resolveTracks()) skeleton.timeScale = held || this.isWaiting(skeleton) ? 0 : scale;
    }

    /**
     * 整段演出在原速下的總長：每一軌從開始播那一刻算到它結束的秒數，取最大值。
     *
     * 一軌的結束是「開始秒數 ＋ 動畫長度」，設了結束秒數而且更早時取結束秒數。查不到動畫的軌
     * （動畫名不存在、資料還沒載好）長度算 0，不會讓結果變成 NaN。停在第一格的主軌不播，算 0。
     *
     * @returns 秒數；一軌都沒有可播的動畫時回 0。
     */
    public override getAnimDuration(): number {
        let longest = 0;
        for (const { skeleton, anim, startTime, endTime, held } of this.resolveTracks()) {
            if (held) continue;
            const naturalEnd = startTime + (skeleton.findAnimation(anim)?.duration ?? 0);
            longest = Math.max(longest, endTime > 0 ? Math.min(endTime, naturalEnd) : naturalEnd);
        }
        return longest;
    }

    /**
     * 主軌在原速下第幾秒結束：主軌開始秒數 ＋ 主軌動畫長度。
     *
     * 金牌翻 Wild 靠它決定時間點——`golden` 動畫在主軌裡把牌蓋掉，主軌一結束格子就空了，
     * 要在這一刻接上 Wild，不能等整段（含額外軌的爆破）播完。
     *
     * @returns 秒數；沒接主軌、停在第一格，或查不到動畫時回 0。
     */
    public override getMainEndTime(): number {
        const main = this.resolveTracks()[0];
        if (!main || main.skeleton !== this.skeleton || main.held) return 0;
        return main.startTime + (main.skeleton.findAnimation(main.anim)?.duration ?? 0);
    }

    /**
     * 主軌先播一次開場動畫，播完自動接回原本設定的動畫（含它的循環設定）。額外軌照舊。
     *
     * 用在金牌翻成 Wild：Wild 的 Normal 主軌是 `idle` 循環，換上去的當下先播 `begin`。
     * 沒接主軌、主軌停在第一格當靜態圖（{@link holdFirstFrame}），或開場動畫不存在時不播，
     * 畫面維持原本的動畫。
     *
     * 開場動畫播到一半時這顆物件被重播（{@link resetAni}）或歸還，會被直接蓋掉——呼叫端要等它播完，
     * 才能去動這一格的狀態。
     *
     * @param anim 開場動畫名稱。
     * @returns 開場動畫在原速下的秒數；沒有播時回 0。
     */
    public override playIntro(anim: string): number {
        const main = this.resolveTracks()[0];
        if (!main || main.skeleton !== this.skeleton || main.held) return 0;
        if (!trySetAnimation(main.skeleton, anim, false, 'SymbolViewSpine.playIntro')) return 0;
        main.skeleton.addAnimation(0, main.anim, main.loop, 0);
        return main.skeleton.findAnimation(anim)?.duration ?? 0;
    }

    /**
     * 推進這一輪播放的時鐘：到了開始秒數的軌恢復速度，到了結束秒數的軌收掉。
     *
     * @param dt 距離上一幀的秒數。
     */
    protected override update(dt: number): void {
        if (this.waiting.length === 0 && this.ending.length === 0) return;
        this.clock += dt * this.playbackScale;

        if (this.waiting.length > 0) {
            this.waiting = this.waiting.filter(({ skeleton, at }) => {
                if (this.clock < at) return true;
                if (skeleton.isValid) skeleton.timeScale = this.playbackScale;
                return false;
            });
        }

        if (this.ending.length > 0) {
            const due = this.ending.filter(({ at }) => this.clock >= at);
            if (due.length === 0) return;
            this.ending = this.ending.filter(({ at }) => this.clock < at);
            for (const { skeleton } of due) this.endTrack(skeleton);
        }
    }

    /**
     * 開始新的一輪播放：每一軌都切好動畫，設了開始秒數的先停在第一格，排好開始與結束的時刻。
     *
     * 等待中的軌也是當下就切動畫，而不是時間到才切：動畫名有錯可以立刻知道，等待時也停在那支
     * 動畫的第一格，而不是上一輪留下的畫面。
     *
     * 停在第一格的主軌（{@link holdFirstFrame}）一樣切好動畫、速度設 0，但不算在回傳的播放清單裡。
     *
     * @param once true 時每一軌都只播一次（{@link playOnce}），false 時照各軌自己的循環設定。
     * @param tag 警告訊息用的呼叫端識別字。
     * @returns 真的切換成功、這一輪有在播的 Skeleton（不含停在第一格的主軌）。
     */
    private startTimeline(once: boolean, tag: string): sp.Skeleton[] {
        this.resetTimeline();
        const playing: sp.Skeleton[] = [];
        for (const { skeleton, anim, loop, startTime, endTime, held } of this.resolveTracks()) {
            if (!trySetAnimation(skeleton, anim, once ? false : loop, tag)) continue;
            if (held) {
                skeleton.timeScale = 0;
                continue;
            }
            playing.push(skeleton);
            skeleton.timeScale = startTime > 0 ? 0 : this.playbackScale;
            if (startTime > 0) this.waiting.push({ skeleton, at: startTime });
            if (endTime > 0) this.ending.push({ skeleton, at: endTime });
        }
        return playing;
    }

    /**
     * 結束秒數到了：清掉這一軌的動畫並關掉 Skeleton，讓它從畫面上消失。
     *
     * 只清動畫的話 Skeleton 會留在設定姿勢上，特效類的骨架通常還看得到東西，所以一併關掉；
     * 下一輪播放或回收時由 {@link resetTimeline} 打開。
     *
     * @param skeleton 要收掉的軌。
     */
    private endTrack(skeleton: sp.Skeleton): void {
        this.waiting = this.waiting.filter((cue) => cue.skeleton !== skeleton);
        if (!skeleton.isValid) return;
        skeleton.setCompleteListener(null!);
        tryClearAnimation(skeleton, 'SymbolViewSpine.endTrack');
        skeleton.enabled = false;
        this.hidden.add(skeleton);
        this.onTrackEnded?.(skeleton);
    }

    /** 清掉上一輪排定的開始／結束時刻，把被收掉的 Skeleton 打開，時鐘歸零。 */
    private resetTimeline(): void {
        this.clock = 0;
        this.waiting = [];
        this.ending = [];
        this.onTrackEnded = null;
        for (const skeleton of this.hidden) {
            if (skeleton.isValid) skeleton.enabled = true;
        }
        this.hidden.clear();
    }

    /**
     * 這一軌是不是還在等開始秒數。
     *
     * @param skeleton 要查的軌。
     * @returns 還在等時為 true。
     */
    private isWaiting(skeleton: sp.Skeleton): boolean {
        return this.waiting.some((cue) => cue.skeleton === skeleton);
    }

    /**
     * 列出要一起播的所有軌：主軌在前，額外軌依序在後。
     *
     * 沒接 skeleton 的、已銷毀的、以及重複出現的 skeleton 都會被略過——同一支掛兩次的話，
     * {@link playOnce} 會為一個只會來一次的結束事件等兩次。主軌的動畫名吃 {@link setAnimOverride}、
     * 是否停在第一格吃 {@link holdFirstFrame}，額外軌一律用自己的設定。
     *
     * @returns 去重後的播放清單；一軌都沒接時為空陣列。
     */
    private resolveTracks(): ResolvedTrack[] {
        const out: ResolvedTrack[] = [];
        const seen = new Set<sp.Skeleton>();
        const add = (skeleton: sp.Skeleton | null, anim: string, loop: boolean, startTime: number, endTime: number, held: boolean): void => {
            if (!skeleton?.isValid || seen.has(skeleton)) return;
            seen.add(skeleton);
            out.push({ skeleton, anim, loop, startTime: Math.max(0, startTime), endTime: Math.max(0, endTime), held });
        };

        add(this.skeleton, this.overrideAnim ?? this.animName, this.loop, this.holdFirstFrame ? 0 : this.startTime ?? 0, 0, this.holdFirstFrame);
        for (const track of this.extraTracks) {
            if (track) add(track.skeleton, track.animName, track.loop, track.startTime ?? 0, track.endTime ?? 0, false);
        }
        return out;
    }
}
