import {
    _decorator,
    director,
    Node,
    Layout,
    Button,
    Label,
    Vec3,
    tween,
    Tween,
    sp,
    UIOpacity
} from 'cc';
import TemplateViewModel from './TemplateViewModel';
import { EventComponent } from '../../events/EventComponent';
import type { TypedEventBus } from '../../events/TypedEventBus';
import StoreManager from '../../store/StoreManager';
import { GameStateKey } from '../../states/GameStateKey';
import AppAnimation from '../AppAnimation';
import { BaseButton } from '../BaseButton/BaseButton';
import { trySetAnimation } from '../../utils/SpineSafe';
const { ccclass, property } = _decorator;

/**
 * spin 箭頭轉一圈的秒數，跟 AppAnimation.playSpinArrow 的預設值相同。橫版轉的是 `Spin/spin_arrorw` 那張箭頭，
 * 直版沒有 spin_icon，整顆 spin 鈕轉。
 */
const SPIN_TURN_SECONDS = 1;

/** spin 鈕上 spin_icon 的按下動畫，播一次 */
const SPIN_ICON_CLICK = 'click';

/** spin 鈕上 spin_icon 平常的循環動畫 */
const SPIN_ICON_IDLE = 'idle';

/**
 * TemplateView（巨亨麻將的下方操作列 View）
 *
 * 原本是 TemplateViewBase（共用基底）＋ TemplateView（1003 覆寫）兩層。獨立成 bundle 之後
 * 沒有跨遊戲共用的必要，依 1001 定稿基線合併成這一支，8 個覆寫直接就地取代基底的版本。
 *
 * ccclass 末尾加 gameId（`TemplateView_1003`）是這個專案的既定隔離做法，比照
 * `1001/TemplateView_1001`、`1002/TemplateView_1002`——entry 仍存在同名的 TemplateView 類別。
 */
@ccclass('1003/TemplateView_1003')
export class TemplateView extends EventComponent {
    /**
     * 訂閱事件匯流排，元件銷毀時自動解除。
     *
     * `EventComponent.subscribeEvent` 是 protected，這裡轉一層 public 供 TemplateViewModel 呼叫。
     *
     * @param bus 目標事件匯流排。
     * @param type 事件類型。
     * @param handler 收到事件時呼叫。
     */
    public subscribeGameEvent<TEvents extends object, K extends keyof TEvents>(
        bus: TypedEventBus<TEvents>,
        type: K,
        handler: (payload: TEvents[K]) => void
    ): void {
        this.subscribeEvent(bus, type, handler);
    }

    @property(Node)
    betFrame: Node = null;
    @property(Node)
    winFrame: Node = null;
    @property(Node)
    userFrame: Node = null;
    @property(Layout)
    lockView: Layout = null;

    // 接 BaseButton 而不是 cc.Button：禁用／懸浮換圖與 turbo 檔位都由它負責。
    // cc.Button 仍在同一個節點上，bindButtons() 綁的 Button.EventType.CLICK 不受影響。
    @property(BaseButton)
    spinBtn: BaseButton = null;
    @property(BaseButton)
    turboBtn: BaseButton = null;
    @property(BaseButton)
    autoBtn: BaseButton = null;
    @property(BaseButton)
    minusBtn: BaseButton = null;
    @property(BaseButton)
    plusBtn: BaseButton = null;
    @property(BaseButton)
    selectBetBtn: BaseButton = null;

    // Auto 的位置在自動旋轉中換成 Pause；Spin 的位置疊了 Spin／AutoSpin／FGCounter 三顆，
    // 誰顯示一律由 applySpinArea() 決定。
    @property(BaseButton)
    pauseBtn: BaseButton = null;
    @property(BaseButton)
    autoSpinBtn: BaseButton = null;
    @property(Label)
    autoSpinTimesLabel: Label = null;
    @property(Node)
    autoSpinInfinite: Node = null;
    @property(BaseButton)
    fgCounterBtn: BaseButton = null;
    @property(Label)
    fgTimesLabel: Label = null;

    @property(Node)
    menuBtn: Node = null;

    @property(sp.Skeleton)
    spinBtnSpine: sp.Skeleton = null;
    @property(sp.Skeleton)
    autoSpinBtnSpine: sp.Skeleton = null;

    /**
     * spin 鈕上的圖示 spine（`Spin/spin_icon`）：平常循環播 `idle`，按下 spin 播一次 `click` 再接回 `idle`，
     * 取代原本整顆按鈕轉一圈。沒拖時用名字找 spin 鈕底下的 `spin_icon`；直版還沒有這個節點，照舊轉按鈕。
     */
    @property({ type: sp.Skeleton, tooltip: 'spin 鈕上的圖示 spine（Spin/spin_icon）：idle 循環、按下播 click；留空則找 spin 鈕底下名為 spin_icon 的節點' })
    spinIconSpine: sp.Skeleton | null = null;

    /**
     * spin 鈕上的箭頭圖（`Spin/spin_arrorw`）：按下 spin 時跟 spin_icon 的 `click` 一起轉一圈，轉法比照 1001 的
     * `BTN_spin_arrow`。2026-10-30 前箭頭畫在 spin_icon 的 `arrorw` 插槽裡、由 `click` 動畫轉，美術把它拆成獨立的圖。
     * 沒拖時用名字找 spin 鈕底下的 `spin_arrorw`。
     */
    @property({ type: Node, tooltip: 'spin 鈕上的箭頭（Spin/spin_arrorw）：按下 spin 轉一圈；留空則找 spin 鈕底下名為 spin_arrorw 的節點' })
    spinArrowNode: Node | null = null;

    @property(Label)
    versionLabel: Label = null;

    /**
     * 場景裡同時存在橫/直版兩個 TemplateView 實例 SpinStartStatus 靠這個判斷負責扣 AutoSpin 局數
     * 在建立橫版那個實例時設為 true 直版維持預設 false 不要用節點
     */
    public isPrimary: boolean = false;

    viewModel: TemplateViewModel;
    protected spinTween: any;

    /** FGCounter 的原始縮放，按下縮放每次都從這裡開始；第一次播時才記下 */
    private fgCounterBaseScale: Vec3 | null = null;

    /** 找不到 spin 箭頭的 warn 只印一次（見 resolveSpinArrow） */
    private spinArrowWarned = false;

    /**
     * 找目前顯示中的那一份操作列。
     *
     * 橫直版各有一份，同時存在但只有一份 active，所以取 `activeInHierarchy` 的那個；
     * 都不是 active 時退回第一份。
     *
     * @returns 顯示中的操作列；場景還沒好或場景裡沒有時是 null。
     */
    public static findActive(): TemplateView | null {
        const views = director.getScene()?.getComponentsInChildren(TemplateView) ?? [];
        return views.find((v) => v.node?.activeInHierarchy) ?? views[0] ?? null;
    }

    /**
     * 基底宣告了 start()，這裡刻意留空——所有初始化都在 onLoad() 完成。
     */
    protected override start(): void {}

    /** 建立 ViewModel、綁定按鈕，spin 鈕回到待機動畫。 */
    protected override onLoad(): void {
        this.viewModel = new TemplateViewModel(this);
        this.viewModel.initial();
        this.bindButtons();
        // 兩顆按鈕的 spine 都設了 defaultAnimation，不清掉進場就會自己播一次
        this.spinBtnSpine?.clearTracks();
        this.autoSpinBtnSpine?.clearTracks();
        this.playSpinIconIdle();
        // FG_ROUND_CHANGED 才會發
        this.updateFgRound?.(0, 0);
    }

    /**
     * 把操作列按鈕的點擊綁到對應的 handler 上。FGCounter 不綁：免費遊戲是固定表演，不能停。
     *
     * 原本這些綁定存在 prefab 的 `cc.Button.clickEvents` 裡（序列化成 `cc.ClickEvent`，
     * 以壓縮 CID 指向目標元件）。改成在程式裡綁定，複製 prefab 時就不會再把
     * `_componentId` 一起帶到別款遊戲去（見 docs/agent-pitfalls.md 坑 #16），
     * 綁定關係也變成在程式碼裡搜得到。
     *
     * 用 `Button.EventType.CLICK` 而不是 `Node.EventType.TOUCH_END`：
     * minusBtn／plusBtn／selectBetBtn 在轉動期間會被 `interactable = false` 鎖住
     * （SpinStartStatus／NewGameStatus），而節點層級的 TOUCH_END 不看 `interactable`，
     * 換過去玩家就能在轉動中改注金。CLICK 由 cc.Button 自己發出，閘門保留。
     *
     * 解綁交給基底的 `trackDisposer()`，隨 onDestroy 一併釋放，但**要先檢查 `node.isValid`**：
     * Cocos 拆解節點樹是先銷毀子節點、再銷毀自己的元件，所以這支的 onDestroy 跑到時按鈕
     * 節點早就死了，而 `Node.off()` 內部會走已經被清成 null 的 `_eventProcessor`，直接丟
     * TypeError。那個例外會中止 `SubscriptionBag.dispose()` 的迴圈，讓後面所有還沒跑的
     * 解除函式永遠不執行——包括 TemplateViewModel 掛的事件總線訂閱。寫法比照
     * `PopupBase.bindClick()`。
     */
    private bindButtons(): void {
        const bindings: Array<[string, Node | null | undefined, () => void]> = [
            ["spinBtn", this.spinBtn?.node, this.spinClick],
            ["turboBtn", this.turboBtn?.node, this.turboClick],
            ["autoBtn", this.autoBtn?.node, this.autoClick],
            // Pause 只在自動旋轉中顯示，按下走 autoClick 的「停止後續局數」分支
            ["pauseBtn", this.pauseBtn?.node, this.autoClick],
            ["autoSpinBtn", this.autoSpinBtn?.node, this.autoSpinClick],
            ["minusBtn", this.minusBtn?.node, this.minusClick],
            ["plusBtn", this.plusBtn?.node, this.plusClick],
            ["selectBetBtn", this.selectBetBtn?.node, this.selectBetClick],
            ["menuBtn", this.menuBtn, this.menuClick]
        ];

        for (const [name, node, handler] of bindings) {
            if (!node) {
                console.warn(`[TemplateView] ${name} 沒接，略過點擊綁定`);
                continue;
            }
            node.on(Button.EventType.CLICK, handler, this);
            this.trackDisposer(() => {
                if (node.isValid) node.off(Button.EventType.CLICK, handler, this);
            });
        }
    }

    // ******************** Button Click  ************************
    /**
     * spin 鈕。播按鈕 spine 之後把實際邏輯交給 ViewModel。
     */
    spinClick() {
        this.playSpinBtnSpine();
        this.viewModel.spinClick();
    }

    /**
     * 播 spin 鈕上的按壓 spine；沒掛 spine 就什麼都不做。
     */
    private playSpinBtnSpine(): void {
        if (!this.spinBtnSpine) return;
        this.spinBtnSpine.setAnimation(0, 'animation', false);
    }

    /**
     * AutoSpin 鈕（自動旋轉中取代 spin 鈕的那一顆）。播自己的按壓 spine，邏輯跟 spin 鈕相同：
     * 自動旋轉中按下就是停止後續局數。
     */
    autoSpinClick() {
        this.autoSpinBtnSpine?.setAnimation(0, 'animation', false);
        this.viewModel.spinClick();
    }
    /**
     * 選單鈕，轉給 ViewModel。
     */
    menuClick() {
        this.viewModel.menuClick();
    }
    /**
     * 自動轉鈕，轉給 ViewModel。
     */
    autoClick() {
        this.viewModel.autoClick();
    }
    /**
     * 加速鈕，轉給 ViewModel。
     */
    turboClick() {
        this.viewModel.turboClick();
    }
    /**
     * 減注鈕，轉給 ViewModel。
     */
    minusClick() {
        this.viewModel.minusClick();
    }
    /**
     * 加注鈕，轉給 ViewModel。
     */
    plusClick() {
        this.viewModel.plusClick();
    }

    /**
     * 選注鈕，轉給 ViewModel。
     */
    selectBetClick() {
        this.viewModel.selectBetClick();
    }

    // ******************** 更新 UI  ************************
    /**
     * 更新自動轉剩餘次數的數字，補零成兩位數。
     *
     * @param times 剩餘次數。
     */
    updateAutoSpinTimes(times) {
        if (!this.autoSpinTimesLabel) return;
        this.autoSpinTimesLabel.string = `${String(times).padStart(2, '0')}`;
    }

    // FG 局數倒數 覆寫
    /**
     * 更新免費局的局數顯示；是再觸發加局造成的變動時，順便讓 FGCounter 播按鈕按下的縮放。
     *
     * 加局特效每一發飛到 FGCounter 時各呼叫一次（見 `PlayFreeRoundTask.playRetrigger()`），
     * 所以數字是分幾次加上去的，每次都播一次。
     *
     * 免費遊戲最後一局剩 0 局時顯示 `00`，不留空白。回主遊戲時靠 {@link isFgMode} 收起來：
     * `freeSpinsTotal` 離開 FG 後不會歸零，只看局數分不出還在不在 FG，而直版的數字掛在 Spin 鈕底下，
     * 不收會一直蓋在 Spin 鈕上。`ExitFreeGameTask` 是先切狀態（`setGameMode` 同步跑完）才呼叫這裡。
     *
     * @param remaining 剩餘局數。
     * @param total 總局數。
     * @param awarded 這次加上來的局數（GDD 4.3）；大於 0 才播，一般倒數不播。
     */
    updateFgRound(remaining: number, total: number, awarded: number = 0): void {
        const label = this.fgTimesLabel;
        if (!label) return;
        const visible = this.isFgMode && total > 0;
        label.node.active = visible;
        if (!visible) return;
        label.string = `${String(remaining).padStart(2, '0')}`;
        if (awarded > 0) this.playFgCounterPress();
    }

    /**
     * 加局時 FGCounter 按下縮放的長度（放大加縮回）。
     *
     * `PlayFreeRoundTask` 用它等最後一次縮放播完才接下一局。從 FGCounter 自己的 cc.Button 設定算，不寫死。
     *
     * @returns 秒數；這一份操作列沒有 FGCounter 按鈕時是 0。
     */
    get fgCounterPressDuration(): number {
        const button = this.fgCounterBtn?.getComponent(Button);
        return button ? button.duration * 2 : 0;
    }

    /**
     * 照 FGCounter 自己 cc.Button 的縮放設定（`zoomScale`／`duration`）放大再縮回，跟玩家按下 Spin 鈕的效果一樣。
     * 取代原本數字放大彈回的演出。
     *
     * 每次都從記下的原始縮放開始：連續觸發時上一段可能還沒縮回，從當下的縮放算會越疊越大。
     */
    private playFgCounterPress(): void {
        const node = this.fgCounterBtn?.node;
        const button = node?.getComponent(Button);
        if (!node?.isValid || !button) return;

        this.fgCounterBaseScale ??= node.scale.clone();
        const base = this.fgCounterBaseScale;
        const pressed = base.clone().multiplyScalar(button.zoomScale);
        Tween.stopAllByTarget(node);
        node.setScale(base);
        tween(node).to(button.duration, { scale: pressed }).to(button.duration, { scale: base }).start();
    }

    // spin 那一區的顯示狀態，applySpinArea() 依這四個值決定每顆按鈕開關
    private isFgMode = false;
    private autoSpinShown = false;
    private autoPlaying = false;
    private spinAreaVisible = true;

    // 進出 FG 模式 覆寫
    /**
     * 依主遊戲／免費遊戲切換底部列的樣式。
     *
     * @param gameMode 目前的遊戲狀態。
     */
    setGameMode(gameMode: GameStateKey): void {
        this.isFgMode = gameMode === GameStateKey.FG;
        this.applySpinArea();
    }

    /**
     * 更新玩家餘額顯示，格式依目前幣別決定。
     *
     * @param balance 餘額。
     */
    updateUserBalance(balance) {
        let userBalance = this.userFrame.getChildByName('Value').getComponent(Label);
        userBalance.string = StoreManager.getInstance().getGameStore().formatAmount(balance);
    }

    /**
     * 更新本局贏分顯示，格式依目前幣別決定。
     *
     * @param balance 贏分。
     */
    updateWinBalance(balance) {
        let winBalance = this.winFrame.getChildByName('Value').getComponent(Label);
        winBalance.string = StoreManager.getInstance().getGameStore().formatAmount(balance);
    }

    /**
     * 更新下注額顯示，格式依目前幣別決定。
     *
     * @param balance 下注額。
     */
    updateBetBalance(balance) {
        let betBalance = this.betFrame.getChildByName('Value').getComponent(Label);
        betBalance.string = StoreManager.getInstance().getGameStore().formatAmount(balance);
    }

    // ******************** 更新 UI  ************************
    /**
     * 切換加速鈕的檔位。
     *
     * 三個檔位各自的一般／懸浮／禁用圖都掛在 BaseButton 的型態列表上，型態名稱直接用
     * TURBOSTATUSMAP 的值（NORMAL／FAST／MAX），所以這裡不需要任何對映表。橫版與直版
     * 各接各的美術，由 prefab 決定。
     *
     * @param gear TURBOSTATUSMAP 的其中一個值；節點已銷毀或型態不存在時不做事。
     */
    setTurboGear(gear: string): void {
        if (!this.turboBtn?.node?.isValid) return;
        this.turboBtn.setVariant(gear);
    }
    /**
     * 一次設定三顆注額按鈕能不能按，不能按的狀態由 BaseButton 負責顯示。
     *
     * @param minus 減注額按鈕。
     * @param plus 加注額按鈕。
     * @param select 選注額按鈕。
     */
    setBetButtons(minus: boolean, plus: boolean, select: boolean) {
        this.minusBtn.setInteractable(minus);
        this.plusBtn.setInteractable(plus);
        this.selectBetBtn.setInteractable(select);
    }
    /**
     * 依目前注額重新整理三顆注額按鈕。
     *
     * @param locked 是否鎖住，轉動中為 true。
     */
    refreshBetButtons(locked: boolean) {
        this.viewModel.refreshBetButtons(locked);
    }
    // ******************** 設定狀態  ************************
    /**
     * 顯示或隱藏 spin 那一區（Spin／AutoSpin／FGCounter、Auto／Pause、Turbo）。
     *
     * @param status 要不要顯示。
     */
    setSpinFrameVisible(status: boolean) {
        this.spinAreaVisible = status;
        this.applySpinArea();
    }
    /**
     * 顯示或隱藏下注那一區。
     *
     * @param status 要不要顯示。
     */
    setBetFrameVisible(status: boolean) {
        this.betFrame.active = status;
    }
    /**
     * 切換自動轉的「無限」標記與剩餘次數數字，兩者互斥。
     *
     * @param status true 顯示無限標記，false 顯示次數。
     */
    setInfiniteVisible(status: boolean) {
        if (this.autoSpinInfinite) this.autoSpinInfinite.active = status;
        if (this.autoSpinTimesLabel) this.autoSpinTimesLabel.node.active = !status;
    }
    /**
     * 寫入畫面角落的版本字串。
     *
     * @param version 版本字串。
     */
    setVersionLabel(version: string) {
        this.versionLabel.string = version;
    }
    /**
     * 切換 spin 的位置要顯示 AutoSpin（剩餘次數）還是 Spin。
     *
     * @param status true 顯示 AutoSpin；免費遊戲中一律顯示 FGCounter，不受這個值影響。
     */
    setAutoSpinVisible(status: boolean) {
        this.autoSpinShown = status;
        // 自動模式下箭頭淡出後才換成 AutoSpin，換回 Spin 時把它還原，不然中途停止自動那一局的 Spin 鈕沒有箭頭
        if (!status) this.resetSpinArrow();
        this.applySpinArea();
    }

    /**
     * 自動旋轉開關變動時切換 Auto／Pause：自動中顯示 Pause，按下停止後續局數。
     *
     * @param on 自動旋轉是否開啟。
     */
    setAutoPlaying(on: boolean) {
        this.autoPlaying = on;
        this.applySpinArea();
    }

    /**
     * 依目前狀態開關 spin 那一區的每顆按鈕，這一區的顯示只由這裡寫。
     *
     * Spin 的位置疊了三顆：免費遊戲顯示 FGCounter（剩餘局數，不能按停），自動旋轉中顯示
     * AutoSpin（剩餘次數或無限標記，按下停止），其餘顯示 Spin。Auto 的位置在自動旋轉中換成 Pause。
     * 每顆都做 null 防護：直版 prefab 還沒換成新結構時只是少顯示，不會丟例外。
     */
    private applySpinArea(): void {
        const show = this.spinAreaVisible;
        const setActive = (btn: BaseButton | null, active: boolean) => {
            if (btn?.node?.isValid) btn.node.active = active;
        };
        setActive(this.fgCounterBtn, show && this.isFgMode);
        setActive(this.autoSpinBtn, show && !this.isFgMode && this.autoSpinShown);
        setActive(this.spinBtn, show && !this.isFgMode && !this.autoSpinShown);
        setActive(this.autoBtn, show && !this.autoPlaying);
        setActive(this.pauseBtn, show && this.autoPlaying);
        setActive(this.turboBtn, show);
    }

    /**
     * 回到一般可操作的樣式：兩區都顯示、spin 鈕轉回原位、改回顯示 Spin 與剩餘次數。
     */
    setDefaultMode() {
        this.resumeSpinAction();
        this.autoSpinShown = false;
        this.spinAreaVisible = true;
        this.setBetFrameVisible(true);
        this.setInfiniteVisible(false);
        this.applySpinArea();
    }

    /** 切回一般 spin 狀態：spin 鈕轉一圈後確定顯示 Spin、收起 AutoSpin。 */
    setSpinMode() {
        this.spinAreaVisible = true;
        this.setBetFrameVisible(true);
        this.applySpinArea();
        this._playSpinAction(() => {
            this.setInfiniteVisible(false);
            this.setAutoSpinVisible(false);
        });
    }

    /**
     * 切到自動 spin 狀態：spin 鈕轉一圈後換成 AutoSpin。
     */
    setAutoSpinMode() {
        this._playSpinAction(() => {
            this.spinAreaVisible = true;
            this.setBetFrameVisible(true);
            this.setAutoSpinVisible(true);
        }, true, true);
    }

    //spin 動畫
    /**
     * 中止 spin 鈕的動效：spin_icon 還沒回到 `idle` 就切回去、箭頭停下並還原；沒有 spin_icon 的直版把轉圈停掉、
     * 角度復位。
     */
    resumeSpinAction() {
        if (this.spinTween) {
            this.spinTween.stop();
            this.spinTween = null;
        }
        const icon = this.resolveSpinIcon();
        if (icon) {
            if (icon.getCurrent(0)?.animation?.name !== SPIN_ICON_IDLE) this.playSpinIconIdle();
            this.resetSpinArrow();
            return;
        }
        const node = this.spinBtn?.node;
        if (node?.isValid) node.eulerAngles = new Vec3(0, 0, 0);
    }

    /**
     * 取 spin 鈕上的圖示 spine：沒拖 {@link spinIconSpine} 時用名字找 spin 鈕底下的 `spin_icon`，找到就記下來。
     *
     * @returns spin_icon 的 spine；這一份操作列沒有時（直版）為 null。
     */
    private resolveSpinIcon(): sp.Skeleton | null {
        this.spinIconSpine ??= this.spinBtn?.node.getChildByName('spin_icon')?.getComponent(sp.Skeleton) ?? null;
        return this.spinIconSpine?.isValid ? this.spinIconSpine : null;
    }

    /**
     * 取 spin 鈕上的箭頭：沒拖 {@link spinArrowNode} 時用名字找 spin 鈕底下的 `spin_arrorw`，找到就記下來。
     *
     * 有 spin_icon 卻找不到箭頭時印一次 warn：spin_icon 已經不畫箭頭，漏接的話按 spin 時箭頭完全不動，
     * 看起來跟其他十幾種原因一樣（坑 #45 連帶）。
     *
     * @returns 箭頭節點；這一份操作列沒有時（直版）為 null。
     */
    private resolveSpinArrow(): Node | null {
        this.spinArrowNode ??= this.spinBtn?.node.getChildByName('spin_arrorw') ?? null;
        if (this.spinArrowNode?.isValid) return this.spinArrowNode;
        if (!this.spinArrowWarned && this.resolveSpinIcon()) {
            this.spinArrowWarned = true;
            console.warn('[TemplateView] spin 鈕底下找不到 spin_arrorw，按 spin 時箭頭不會轉');
        }
        return null;
    }

    /** 箭頭停下、轉回原位、不透明度回到 255；沒有箭頭（直版）時什麼都不做。 */
    private resetSpinArrow(): void {
        const arrow = this.resolveSpinArrow();
        if (!arrow) return;
        Tween.stopAllByTarget(arrow);
        arrow.eulerAngles = Vec3.ZERO;
        const opacity = arrow.getComponent(UIOpacity);
        if (opacity) {
            Tween.stopAllByTarget(opacity);
            opacity.opacity = 255;
        }
    }

    /** spin_icon 從頭循環播 `idle`；沒有 spin_icon 時什麼都不做。 */
    private playSpinIconIdle(): void {
        const icon = this.resolveSpinIcon();
        if (icon) trySetAnimation(icon, SPIN_ICON_IDLE, true, 'TemplateView.spinIcon');
    }

    /**
     * 切換操作鎖遮罩。
     *
     * @param islock true 時蓋上遮罩擋住所有按鈕。
     */
    setLockStatus(islock) {
        this.lockView.node.active = islock;
    }

    /**
     * 按下 spin 的共用動效；已經有動效在跑時直接呼叫回呼、不疊第二份。
     *
     * 有 spin_icon 時播一次 `click`，播完接回循環的 `idle`，按鈕本身不動；回呼等 `click` 播完才呼叫——自動模式
     * 會在回呼裡把 spin 鈕換成 AutoSpin，提早關掉的話 spine 停在 click 中間，中途停止自動時切回來是半張動畫。
     * 計時掛在 spin 鈕節點的 tween 上，節點關掉時跟著暫停，跟 spine 停下來的進度一致。
     * 同時讓箭頭（{@link spinArrowNode}）照 1001 的轉法轉一圈：1 秒、`backIn`、轉到 -360°；自動模式也照 1001 在
     * 第 0.8 秒起淡出 0.2 秒，跟 `click` 同時結束、接著換成 AutoSpin。開轉前先還原（{@link resetSpinArrow}），
     * 轉完把角度歸零，不然下一次是從 -360° 轉到 -360°，等於沒轉。淡出的透明度留在箭頭上，換回 Spin 時
     * （{@link setAutoSpinVisible}、{@link resumeSpinAction}）才還原。
     *
     * 沒有 spin_icon 的那一份（目前是直版）照舊整顆按鈕轉一圈：箭頭畫在 spin 鈕的圖上。不做淡出：自動模式會在
     * 回呼裡把 spin 鈕換成 AutoSpin，淡出的透明度留在 spin 鈕上的話，中途停止自動時切回來的 spin 鈕會是透明的。
     *
     * @param callBack 動效告一段落後呼叫；沒有 spin 鈕時直接呼叫。
     * @param waitFullTurn 轉圈時回呼要不要等轉滿一圈（spin_icon 一律等 `click` 播完）。回呼會把 spin 鈕關掉時
     *        要給 true：節點關掉後 tween 跟著暫停，提早關會讓 spin 鈕停在半圈，中途停止自動時切回來就是歪的。
     * @param fadeArrow 箭頭轉圈時要不要淡出（自動模式）；只影響有 spin_icon 的那一份。
     */
    private _playSpinAction(callBack?: () => void, waitFullTurn: boolean = false, fadeArrow: boolean = false) {
        const node = this.spinBtn?.node;
        if (this.spinTween || !node?.isValid) {
            callBack?.();
            return;
        }

        const icon = this.resolveSpinIcon();
        if (icon) {
            trySetAnimation(icon, SPIN_ICON_CLICK, false, 'TemplateView.spinIcon');
            icon.addAnimation(0, SPIN_ICON_IDLE, true, 0);
            const arrow = this.resolveSpinArrow();
            if (arrow) {
                this.resetSpinArrow();
                AppAnimation.playSpinArrow(arrow, { rotationDuration: SPIN_TURN_SECONDS, callbackDelay: SPIN_TURN_SECONDS, fadeOpacity: fadeArrow }, () => {
                    if (arrow.isValid) arrow.eulerAngles = Vec3.ZERO;
                });
            }
            const duration = icon.skeletonData?.getRuntimeData(true)?.findAnimation(SPIN_ICON_CLICK)?.duration ?? 0;
            this.spinTween = tween(node)
                .delay(duration)
                .call(() => callBack?.())
                .start();
            return;
        }

        const options = waitFullTurn ? { rotationDuration: SPIN_TURN_SECONDS, callbackDelay: SPIN_TURN_SECONDS } : {};
        this.spinTween = AppAnimation.playSpinArrow(node, options, callBack);
    }
}
