import type { Node } from 'cc';

/** 覆蓋層裡的一顆物件與它的疊放鍵 */
interface OverlayEntry {
    readonly node: Node;
    readonly key: number;
}

/**
 * 機台覆蓋層（`Layer_Win`）裡符號顯示物件的疊放順序；中獎中與聽牌中的符號都在這一層。
 *
 * 物件放進覆蓋層之後就不再是格子的子節點，盤面上靠「格子在哪個容器、排第幾個」做出來的疊放順序
 * （Scatter > Wild > 一般牌、右欄蓋左欄、下排蓋上排，見 `ReelView_1003.placeCell()`／`updateDrawOrder()`）
 * 要在這裡重建：每顆物件帶一個疊放鍵，越大畫越上面，鍵由輪軸決定（`ReelView_1003.overlayDrawKey()`）。
 *
 * 只管自己收進來的物件，而且一律排在這一層的最底下——同一層裡其他程式加進來的東西都會在符號上面，
 * 所以會蓋到符號的節點不要放進這一層（2026-11-05 前聚焦的那一軸就是這樣蓋到聽牌 Scatter）。位置、縮放、透明度不歸這裡管，由 `SymbolCell` 每幀同步。
 */
export class SymbolOverlayLayer {
    /** 目前管著的物件，依疊放鍵由小到大（＝由下到上） */
    private readonly entries: OverlayEntry[] = [];

    /**
     * 包住一個覆蓋層節點，之後收進來的物件都排在這一層。
     *
     * @param root 覆蓋層節點。
     */
    constructor(public readonly root: Node) {}

    /**
     * 收進一顆物件並重排順序；已經收過的會照新的鍵重排。
     *
     * 鍵相同時新收的排在下面：同一格換上的新物件要畫在 `SymbolCell.keepCurrentViewFor()` 留下來的那顆底下。
     *
     * @param node 物件節點。
     * @param key 疊放鍵，越大畫越上面。
     */
    public add(node: Node, key: number): void {
        this.remove(node);
        let i = 0;
        while (i < this.entries.length && this.entries[i].key < key) i++;
        this.entries.splice(i, 0, { node, key });
        if (node.parent !== this.root) node.setParent(this.root);
        this.applyOrder();
    }

    /**
     * 不再管這顆物件。節點本身不動，搬去哪裡由呼叫端決定；沒收過的物件傳進來也安全。
     *
     * @param node 物件節點。
     */
    public remove(node: Node): void {
        const i = this.entries.findIndex((e) => e.node === node);
        if (i >= 0) this.entries.splice(i, 1);
    }

    /** 依 {@link entries} 的順序把物件排到這一層最底下那幾格；已經被搬走或銷毀的順手清掉 */
    private applyOrder(): void {
        for (let i = this.entries.length - 1; i >= 0; i--) {
            const node = this.entries[i].node;
            if (!node.isValid || node.parent !== this.root) this.entries.splice(i, 1);
        }
        this.entries.forEach((e, i) => e.node.setSiblingIndex(i));
    }
}
