import { _decorator, Component, instantiate, Layout, Prefab } from 'cc';

import HistoryModel from '../../History/HistoryModel';
import { ORIENTATION } from '../../../store/StoreMap';
const { ccclass, property } = _decorator;

@ccclass('1003/HistoryView')
export class HistoryView extends Component {
    @property(Prefab)
    historyItemPrefab: Prefab = null;

    @property(Prefab)
    historyItemHPrefab: Prefab = null;

    _spinnerView = null;
    viewModel: HistoryModel;
    scrollViewContent: Layout;
    /**
     * 建立這個畫面的 ViewModel。
     */
    protected override onLoad() {
        this.viewModel = new HistoryModel(this);
    }

    /**
     * 每次開啟時清掉舊清單再重建，避免上一次的項目殘留。
     */
    protected override onEnable(): void {
        this.node.removeAllChildren();
        this.viewModel.addHistoryItem();
    }
    /**
     * 依方向實體化對應版本的清單項目並掛進畫面。
     *
     * @param orientation 目前方向。
     * @returns 新建的項目節點。
     */
    addHistoryItem(orientation) {
        let item = orientation === ORIENTATION.LANDSCAPE ? instantiate(this.historyItemPrefab) : instantiate(this.historyItemHPrefab);
        this.node.addChild(item);
        return item;
    }
}
