import { GameTask } from './GameTask';
import { WinAnimationView } from '../ui/WinAnimationView';
import type { ISlotGameMain } from '../types/ISlotGameMain';
import type { GameViewAdapter } from '../ui/GameViewAdapter';
import { NO_WIN_VOICES, SMALL_WIN_VOICE_CHANCE, SMALL_WIN_VOICES } from '../audio/AudioConfig';
import { playRandomVoice } from '../audio/VoiceLine';
import { WinTier } from '../config/GameConst';

/**
 * 依這局總贏分報獎：BIG 以上開報獎彈窗；小獎（WIN）不開彈窗，改在同一個時機收尾。
 *
 * 兩種都先收起盤面上贏分條的數字：大獎由彈窗的跑分數字取代，小獎改由操作列的 Win 顯示。
 * 數字在下一局開始時打開回來（`resetWinBar()`）。
 *
 * @param game 遊戲主體。
 * @param totalWin 這一局的總贏分；0 以下不報。
 * @returns 報獎彈窗關掉之後 resolve；小獎與不報獎時立即 resolve。
 */
export async function playWinAnimationIfNeeded(game: ISlotGameMain<GameViewAdapter>, totalWin: number): Promise<void> {
    const bet = game.storeManager.getModel('TemplateStore').betBalance;
    const key = totalWin > 0 ? WinAnimationView.getWinKey(totalWin, bet) : null;
    if (!key) return;
    game.hideWinBarNum();
    if (key === WinTier.WIN) {
        settleSmallWin(game, totalWin);
        return;
    }
    await game.popups.showWinAnimation(totalWin, bet);
}

/**
 * 小獎收尾：原本開小獎彈窗（`win_s`）的時機。操作列的 Win 顯示這局總贏分，小獎語音照原本的機率播。
 *
 * @param game 遊戲主體。
 * @param totalWin 這一局的總贏分。
 */
function settleSmallWin(game: ISlotGameMain<GameViewAdapter>, totalWin: number): void {
    game.storeManager.getModel('TemplateStore').setWinBalance(Number(totalWin.toFixed(2)));
    playRandomVoice(SMALL_WIN_VOICES, SMALL_WIN_VOICE_CHANCE);
}

export class WinAnimationTask extends GameTask {
    /**
     * 只記下參數，演出要等任務佇列輪到這一筆才開始。
     *
     * @param game 遊戲主體。
     * @param totalWin 這一局的總贏分。
     */
    constructor(
        private readonly game: ISlotGameMain<GameViewAdapter>,
        private readonly totalWin: number
    ) {
        super();
    }

    /**
     * Task 進入點：播報獎演出；這一局沒中獎就改播一句沒中獎語音。
     *
     * 沒中獎語音放在這裡而不是 `playWinAnimationIfNeeded()`：那支 FG 結算也會呼叫，FG 總贏分為 0
     * 不該說「可惜，只差一點」。沒中獎時這個 Task 只出現在 MG 不進 FG 的那條流程上（見 `planSpinFlow()`）：進 FG 時有贏分才會排。
     */
    protected onStart(): void {
        if (this.totalWin <= 0) playRandomVoice(NO_WIN_VOICES);
        playWinAnimationIfNeeded(this.game, this.totalWin)
            .catch((error) => console.warn('[WinAnimationTask] failed', error))
            .finally(() => this.finish());
    }
}
