import { WinTier } from './GameConst';

// presentation.json 的路徑
export const PRESENTATION_CONFIG_PATH = 'resources/config/presentation';

export interface PresentationConfig {
    /** 免費遊戲逐局報獎總開關：false = 原本的流程（出來才報），true = 每局報獎 */
    featureRoundWinPresentationEnabled: boolean;
    /** 上面開關開啟時，單局贏分要達到這個等級以上才報 */
    featureRoundWinPresentationMinTier: WinTier;
    /**
     * FG 結算面板（報獎彈窗的 TOTAL WIN）出現後停留幾秒才自動關閉；玩家可以提早點掉。
     * 2026-10-29 從 2 秒拉長到 4 秒，DebugPanel「免費遊戲」區塊可調。
     */
    totalWinDwellSec: number;
}

export const DEFAULT_PRESENTATION_CONFIG: PresentationConfig = {
    featureRoundWinPresentationEnabled: false,
    featureRoundWinPresentationMinTier: WinTier.BIG,
    totalWinDwellSec: 4,
};

/**
 * 把 presentation.json 解析成演出設定；格式不對的欄位各自沿用 {@link DEFAULT_PRESENTATION_CONFIG}，不整份丟棄。
 *
 * @param raw json 內容；讀不到時是 null。
 * @returns 解析後的演出設定。
 */
export function parsePresentationConfig(raw: unknown): PresentationConfig {
    const cfg: PresentationConfig = { ...DEFAULT_PRESENTATION_CONFIG };
    const obj = raw as Partial<Record<keyof PresentationConfig, unknown>> | null;
    if (!obj) return cfg;

    if (typeof obj.featureRoundWinPresentationEnabled === 'boolean') {
        cfg.featureRoundWinPresentationEnabled = obj.featureRoundWinPresentationEnabled;
    }

    const tier = obj.featureRoundWinPresentationMinTier;
    if (typeof tier === 'string' && (Object.values(WinTier) as string[]).includes(tier)) {
        cfg.featureRoundWinPresentationMinTier = tier as WinTier;
    }

    const dwell = obj.totalWinDwellSec;
    if (typeof dwell === 'number' && Number.isFinite(dwell) && dwell > 0) {
        cfg.totalWinDwellSec = dwell;
    }

    return cfg;
}
