import { _decorator, easing, Node, Tween, tween, type TweenEasing, UIOpacity, Vec3 } from 'cc';
import type { ReelSpinTiming } from '../../config/ReelTimingDebugStore';
import { EventComponent } from '../../events/EventComponent';
import { ReelModel, ReelState } from '../model/ReelModel';
import { SymbolCell } from '../symbol/SymbolCell';
import { ReelFlag } from '../symbol/SymbolState';

const { ccclass, property } = _decorator;

/**
 * 依字串名稱到 cc.easing 命名空間查緩動函式。設定檔與 Inspector 存的都是名稱，轉動時才換成函式。
 *
 * 找不到就退回 linear，等同沒套用任何緩動。
 *
 * @param name 緩動名稱，對應 cc.TweenEasing（例如 `backIn`）。
 * @returns 緩動函式：輸入 0～1 的進度，回傳位移比例。
 */
function resolveEasing(name: string): (k: number) => number {
    const fn = (easing as unknown as Record<string, ((k: number) => number) | undefined>)[name];
    return fn ?? easing.linear;
}

/**
 * 補牌的落地回彈：落到定位後往上彈、再落回定位，不壓扁。照參考影片（2026-10-19 的錄影）逐格量出來：
 * 兩次落下、各欄的回彈高度都在格距的 12～15%，上彈約 0.085 秒、落回約 0.08 秒。
 */
const LANDING_BOUNCE = {
    /** 往上彈的高度，佔格距的比例 */
    heightRatio: 0.135,
    /** 上彈時長（秒），quadOut 減速到頂 */
    upTime: 0.085,
    /** 落回時長（秒），quadIn 加速落回 */
    downTime: 0.08,
};

@ccclass('1003/ReelView')
export class ReelView extends EventComponent {
    @property(Node)
    protected container: Node = null!;

    @property({ type: [Node], tooltip: '停輪格位標記點，由上到下排列：前 2 個是補牌進場緩衝、中間是可視列、最後 2 個是消除掉落緩衝。1003 由 ReelView_1003 在 onLoad 依可視列數自動產生，這裡手填無效' })
    public posList: Node[] = [];

    /**
     * frameIdx → 圖名（也就是符號定義裡的 `frame`，例如 `H1`、`H1_g`）。輪帶、盤面、補牌都用 frameIdx
     * 溝通，這張表是 frameIdx 與符號名稱之間唯一的對照。
     *
     * 原本是 Inspector 上的 `spriteFrames`，用每張圖的檔名當名稱。2026-10-14 一般牌改成 spine、靜態圖
     * 刪掉之後，圖一不見名稱就全變成空字串，每一格都對不到符號，盤面整個是空的，而且不報錯。所以改由
     * 子類在 onLoad 依符號定義填好，不再依賴圖檔；{@link init} 收到後端輪帶時就會用到，不能晚於它。
     */
    protected frameNames: string[] = [];

    // 下面五個是 reelConfig.json 載入失敗時的退路：正常情況每次 spin 前都會被 applyTiming() 蓋掉。
    // 欄位名稱維持舊的（endEase 就是「落定曲線」、loopTime 是輪轉速度的倒數），prefab 序列化的值才接得上

    @property({ tooltip: '起轉曲線，對應 cc.TweenEasing（例如 backIn）' })
    protected beginEase: string = 'linear';

    @property({ tooltip: '落定曲線：停輪最後一格怎麼減速落到定位，對應 cc.TweenEasing（quadOut 不衝過頭；backOut 會先衝過頭再接回彈）' })
    protected endEase: string = 'linear';

    @property({ tooltip: '起轉時長（秒）' })
    protected beginDuration: number = 0.5;

    @property({ tooltip: '落定時長（秒）：停輪最後一格花的時間' })
    protected endDuration: number = 0.1;

    // 停輪的落地回彈：落到定位後整欄往上彈、再落回定位，彈法跟 LANDING_BOUNCE 一樣，幅度小得多。
    // 預設值照原版參考影片（2026-10-22 的錄影，格距 166 px）逐格量出來：往上彈約 10 px，上彈約 0.08 秒、
    // 落回約 0.07～0.13 秒，從頭到尾沒有往下衝過定位。跟上面五個一樣每次 spin 前由 applyTiming() 蓋掉；
    // 不掛 @property，prefab 不必多存三個值

    /** 回彈高度，佔格距的比例；0 是不彈 */
    protected stopBounceHeight: number = 0.06;

    /** 上彈時長（秒），quadOut 減速到頂 */
    protected stopBounceUp: number = 0.08;

    /** 落回時長（秒），quadIn 加速落回 */
    protected stopBounceDown: number = 0.08;

    @property({ tooltip: '等速轉動時，每移動一格所需時間（秒），即輪轉速度的倒數' })
    protected loopTime: number = 0.05;

    public model: ReelModel = null!;
    public symbolNodes: Node[] = [];
    protected symbolOpacities: UIOpacity[] = [];
    protected posIndexes: number[] = [];

    public strip: number[] = [];

    protected ratio: number = 0;
    protected time: number = 0;
    protected isSpinning: boolean = false;

    /** 這次起轉前先原地等幾秒（起轉間隔 × 欄序），由子類起轉時設定 */
    protected startDelay: number = 0;

    /** 這一欄從起轉開始累計的秒數，用來量停輪指令實際生效比預定晚了多久 */
    private spinClock: number = 0;

    /** 進入等速段的時刻（{@link spinClock}），算輪轉時長轉滿了沒，見 {@link getTimeUntilStoppable} */
    private loopStartedAt: number = 0;

    /** 距離下停輪指令還有幾秒；負數代表沒有排程中的停輪，見 {@link scheduleStop} */
    private stopCountdown: number = -1;

    /** 排程中的停輪要停在哪個輪帶位置 */
    private pendingStopRng: number = 0;

    /** 停輪指令「應該」生效的時刻（{@link spinClock}）；負數代表還沒下 */
    private stopIdealAt: number = -1;

    /** 停輪段每跳一格的秒數，見 {@link enterStopping}；0 代表沒算過，退回 {@link loopTime} */
    private stoppingStepTime: number = 0;

    /** 這一次停輪是否已經碰到定位，{@link onStopReached} 只通知一次 */
    private stopReached: boolean = false;

    /**
     * 落定前幾秒通知 {@link onLandingSoon}（套用 reelConfig 的 `scatterSoundLead`）；0 是落定當下。
     * 初始值跟 `DEFAULT_REEL_CONFIG` 一樣，是 reelConfig.json 載入失敗時的退路
     */
    private landingLead: number = 0.34;

    /** 這一次停輪預計碰到定位的時刻（{@link spinClock}）；負數代表還沒進停輪段，算不出來 */
    private landingAt: number = -1;

    /** 這一次停輪是否已經通知過 {@link onLandingSoon} */
    private landingSoonNotified: boolean = false;

    /** 是否正在停輪後的落地回彈，見 {@link updateStopBounce} */
    private stopBouncing: boolean = false;

    /** 落地回彈從 {@link time} 的哪一刻開始 */
    private stopBounceFrom: number = 0;

    /**
     * 收到停輪指令後要再跑幾格才停，0 代表用這一欄自己的 posList 長度。
     *
     * 至少要跑滿 posList 長度，整欄每一格才會換成輪帶上的終盤。各欄格數不同時（1003 兩側欄
     * 比中間欄多一格），由機台統一設成最長那欄，各欄停輪的間隔才會等於下指令的間隔。
     */
    public stopRunUpSteps: number = 0;

    /**
     * 這一欄每個格位上的邏輯格，與 {@link symbolNodes} 同索引。
     *
     * `symbolNodes[i]` 是節點本身（轉動時被搬位置的那顆），`symbolCells[i]` 是掛在它上面、
     * 決定該顯示哪個符號的哪個狀態的元件。由子類在建立格子時填入；基底自己不使用。
     */
    public symbolCells: (SymbolCell | null)[] = [];

    /** 輪軸層級的旗標，影響這一欄所有格子推算出來的預設狀態 */
    private reelFlags: number = ReelFlag.None;

    /**
     * 開關一個輪軸旗標。旗標影響的是沒有被指定強制狀態的格子推算出來的預設狀態
     * （見 `SymbolCell.getTargetState()`），所以變動時要通知這一欄的每一格重算。
     *
     * **目前沒有呼叫端。** 2026-10-20 拿掉壓黑旗標之後只剩 `ReelFlag.Blur`，而 1003 還沒有模糊圖（`Blur` 狀態
     * 缺項會退回 `Normal`）。這是規格書 §3.3 的輪軸旗標機制，跟 `Blur` 一樣先留著，有模糊圖時在起轉／停輪
     * 處開關即可，不是漏接。
     *
     * @param flag 要操作的旗標。
     * @param enable true 開啟、false 關閉。
     */
    public setReelFlag(flag: ReelFlag, enable: boolean): void {
        const next = enable ? this.reelFlags | flag : this.reelFlags & ~flag;
        if (next === this.reelFlags) return;
        this.reelFlags = next;
        for (const cell of this.symbolCells) cell?.markStateDirty();
    }

    /**
     * 查詢輪軸旗標，`ISymbolCellHost` 的實作。
     *
     * @param flag 要查的旗標。
     * @returns 該旗標是否開啟。
     */
    public hasReelFlag(flag: ReelFlag): boolean {
        return (this.reelFlags & flag) !== 0;
    }

    /**
     * 這一欄是否在轉動，`ISymbolCellHost` 的實作。
     *
     * 方法名不叫 `isSpinning` 是因為那是本類別既有的 protected 欄位，同名會衝突。
     *
     * @returns 轉動中為 true。
     */
    public isReelSpinning(): boolean {
        return this.isSpinning;
    }

    /**
     * 這一欄這次起轉之後過了幾秒（含起轉前原地等的起轉間隔），跟轉動用的是同一個 dt。
     *
     * @returns 秒數；沒在轉時為 0。
     */
    public getSpinElapsed(): number {
        return this.isSpinning ? this.spinClock : 0;
    }

    /**
     * 套用轉輪節奏（reelConfig.json 或 DebugPanel 的覆寫值）。每次 spin 開始前由 SlotGameMain 呼叫，
     * 不在轉動中途套，免得改到正在播的那一段。
     *
     * @param timing 起轉曲線／起轉時長／輪轉速度／落定曲線／落定時長／回彈高度／上彈時長／落回時長。
     *               速度與起轉、落定時長必須大於 0，回彈三項可以是 0（不彈），由 `parseReelConfig()`
     *               與 DebugPanel 的拉桿範圍把關。
     */
    applyTiming(timing: ReelSpinTiming): void {
        this.beginEase = timing.beginEase;
        this.beginDuration = timing.beginDuration;
        this.loopTime = 1 / timing.spinSpeed;
        this.endEase = timing.bounceEase;
        this.endDuration = timing.bounceDuration;
        this.stopBounceHeight = timing.stopBounceHeight;
        this.stopBounceUp = timing.stopBounceUp;
        this.stopBounceDown = timing.stopBounceDown;
        this.landingLead = Math.max(0, timing.scatterSoundLead ?? 0);
    }

    /**
     * 停輪要跑幾格：至少 posList 長度，整欄每一格才會換成輪帶上的終盤；機台另外統一成最長那欄
     * （見 {@link stopRunUpSteps}）。
     *
     * @returns 格數。
     */
    protected get stopRunUp(): number {
        return Math.max(this.posList.length, this.stopRunUpSteps);
    }

    /**
     * 還要多久才可以對這一欄下停輪指令：起轉段要跑完（停輪指令只在等速段的格線上生效，坑 #50），
     * 而且整段等速要轉滿輪轉時長。
     *
     * 輪轉時長算的是畫面上看到的等速段，從進入等速到開始回彈。下指令之後還會等速跑
     * `stopRunUp - 1` 格才回彈（9 格、25 格/秒時約 0.36 秒），所以指令可以提早這麼多下；
     * 輪轉時長比這段還短時就等於 0，等速段最短就是這幾格。
     *
     * @param spinDuration 輪轉時長（秒）。
     * @returns 秒數；已經可以停、或已經在停輪中時為 0。
     */
    public getTimeUntilStoppable(spinDuration: number): number {
        const loopBeforeStop = Math.max(0, spinDuration - (this.stopRunUp - 1) * this.loopTime);
        const state = this.model?.state;
        if (state === ReelState.BEGIN) return Math.max(0, this.startDelay + this.beginDuration - this.time) + loopBeforeStop;
        if (state === ReelState.LOOP) return Math.max(0, loopBeforeStop - (this.spinClock - this.loopStartedAt));
        return 0;
    }

    /**
     * 排程停輪：倒數 `delay` 秒後才對 model 下停輪指令。
     *
     * 倒數放在這一欄自己的 update 裡算，跟轉動用的是同一個 dt，不會跟 scheduleOnce 各走各的鐘。
     * 指令要等到下一條格線才生效，晚掉的那一點由 {@link enterStopping} 補回來，所以落地時刻只看
     * 「預定的下指令時刻」，各欄的停輪間隔才會準。
     *
     * @param rng 要停在的輪帶位置。
     * @param delay 倒數秒數；0 或負數立即下指令。
     */
    protected scheduleStop(rng: number, delay: number): void {
        if (delay > 0) {
            this.stopCountdown = delay;
            this.pendingStopRng = rng;
            return;
        }
        this.stopCountdown = -1;
        this.requestStop(rng, 0);
    }

    /**
     * 快停：還在倒數的停輪改成「能停就停」，剩下的輪轉時長、停輪間隔與聽牌延長都不等了。
     *
     * 起轉段還沒跑完的要等它跑完：停輪指令只在等速段的格線上生效，提早下會讓前幾欄擠在同一條格線上
     * 一起停（坑 #50）。已經下過指令、或沒有排程中的停輪時不動。
     */
    public hurryStop(): void {
        if (this.stopCountdown < 0) return;
        this.stopCountdown = this.getTimeUntilStoppable(0);
    }

    /**
     * 對 model 下停輪指令，並記下它「應該」生效的時刻。
     *
     * @param rng 要停在的輪帶位置。
     * @param lateBy 這一刻已經比預定晚了幾秒（倒數在一幀之內歸零時的零頭）。
     */
    private requestStop(rng: number, lateBy: number): void {
        this.stopIdealAt = this.spinClock - lateBy;
        this.model.stop(rng);
    }

    /**
     * 停輪第一次碰到定位時呼叫一次，由子類覆寫（停輪音之類的時機）。
     *
     * 這一刻早於停輪結束：之後還有落地回彈（{@link updateStopBounce}），落定曲線衝過頭時還要先拉回定位。
     */
    protected onStopReached(): void {}

    /**
     * 停輪預計碰到定位之前 `scatterSoundLead` 秒呼叫一次，由子類覆寫（Scatter 落地音效的時機）。
     *
     * 停輪指令生效（進停輪段）之後，落定時刻就固定了：停輪段每格的時間乘上剩下的格數，再加上落定時長
     * （見 {@link enterStopping}）。所以能在碰到定位之前準時通知，而且跟轉輪用同一個時鐘，急速模式一起變快。
     * 提早量比停輪段加落定段還長時，進停輪段當下就通知；快停、直接拉到定位這類沒有走停輪段的情況，
     * 在碰到定位時補通知（{@link notifyStopReached}），不會漏。
     */
    protected onLandingSoon(): void {}

    /** 通知 {@link onLandingSoon}，同一次停輪只通知一次。 */
    private notifyLandingSoon(): void {
        if (this.landingSoonNotified) return;
        this.landingSoonNotified = true;
        this.onLandingSoon();
    }

    /** 通知 {@link onStopReached}，同一次停輪只通知一次；還沒通知過落定前的話先補。 */
    private notifyStopReached(): void {
        if (this.stopReached) return;
        this.notifyLandingSoon();
        this.stopReached = true;
        this.onStopReached();
    }

    /**
     * 綁定這一欄的 model、建立符號節點，並訂閱 model 的狀態變化。
     *
     * 進 STOPPING 時會先把 currentRng 校正到「終點再往前 posList 長度（或 {@link stopRunUpSteps}）」的位置，
     * 讓接下來的減速剛好停在 finalRng 上，不必另外做補間。
     *
     * mobx 移除之後 model 的狀態改用自己的 TypedEventBus 通知。
     *
     * @param model 這一欄的轉輪 model。
     * @param iconColumn 這一欄的符號名稱序列；不給就沿用現有的。
     */
    init(model: ReelModel, iconColumn?: string[]): void {
        if (iconColumn) {
            this.strip = this.buildStrip(iconColumn);
        }

        this.model = model;
        this.initSymbols();

        // mobx 移除計劃：ReelModel.state 已改由自己的 TypedEventBus 通知，不再用 mobx reaction
        this.subscribeEvent(this.model.events, 'stateChanged', ({ state }) => {
            if (state === ReelState.IDLE) {
                this.isSpinning = false;
                this.stopCountdown = -1;
            } else if (state === ReelState.STOPPING) {
                const newRng = (this.model.finalRng + this.stopRunUp + this.strip.length) % this.strip.length;
                this.model.setCurrentRng(newRng);
            } else {
                this.time = 0;
                this.isSpinning = true;
                if (state === ReelState.BEGIN) {
                    this.spinClock = 0;
                    this.stopIdealAt = -1;
                    this.stoppingStepTime = 0;
                    this.stopBouncing = false;
                    this.landingAt = -1;
                    this.landingSoonNotified = false;
                } else if (state === ReelState.LOOP) {
                    this.loopStartedAt = this.spinClock;
                } else if (state === ReelState.END) {
                    this.stopReached = false;
                    this.stopBouncing = false;
                }
            }
        });

        this.subscribeEvent(this.model.events, 'forceSnap', (rng) => this.snapToFinal(rng));
    }

    /**
     * 收到強制快照通知時，把 reel 立即帶到準備停止的位置（設進 END 狀態），依目前狀態分三種處理：
     * - STOPPING：rapid-step 直接跑到 oneStepBefore，再手動同步 posIndexes 對應的畫面位置
     * - END：把 time 校正到 70% 進度，讓收尾動畫接著播完；已經在落地回彈的話直接收尾
     * - BEGIN/LOOP：直接設定 currentRng，同步 posIndexes/symbol 顯示到 oneStepBefore
     *
     * @param rng 要停在的輪帶位置。
     */
    public snapToFinal(rng: number): void {
        if (this.stopBouncing) {
            // 已經碰到定位、正在落地回彈：把回彈撥到最後，下一幀就收尾（不在這裡同步通知 model 已停止）
            this.stopBounceFrom = this.time - (this.stopBounceUp + this.stopBounceDown);
            return;
        }
        this.time = 0;
        this.isSpinning = true;
        const oneStepBefore = (((rng + 1) % this.strip.length) + this.strip.length) % this.strip.length;

        if (this.model.state === ReelState.STOPPING) {
            // rapid-step 直接跑迴圈到 oneStepBefore，safety 是防止意外跑成無窮迴圈的安全上限
            let safety = this.strip.length;
            while (this.model.currentRng !== oneStepBefore && safety-- > 0) {
                this.step();
            }
            // step() 不會動到 symbol 實際位置，這裡才手動 snap 到 posList[posIndexes[i]]
            for (let i = 0; i < this.symbolNodes.length; i++) {
                const curIdx = this.posIndexes[i];
                this.symbolNodes[i].setPosition(0, this.posList[curIdx].position.y, 0);
                const op = this.symbolOpacities[i];
                if (op) op.opacity = curIdx === this.posList.length - 1 ? 0 : 255;
            }
            this.updateDrawOrder();
            this.model.setState(ReelState.END);
            return;
        }

        if (this.model.state === ReelState.END) {
            // 已經在 END 狀態，把 time 設到 70% 進度，讓收尾動畫接著播完
            this.time = this.endDuration * 0.7;
            return;
        }

        // BEGIN/LOOP：目前 posIndexes 對應的 position，跟 symbols 實際該顯示的畫面不同步，
        // 所以要用 currentRng 反推每個 symbol 該對應哪個 posIdx 的 strip frame，
        // 讓 updateEnd 之後的 position 插值直接對齊 posList[curIdx]，跳過中間的落差
        this.model.setCurrentRng(oneStepBefore);
        for (let i = 0; i < this.symbolNodes.length; i++) {
            const stripIdx = (oneStepBefore + this.posIndexes[i]) % this.strip.length;
            this.setSymbolDisplay(i, this.strip[stripIdx]);
        }
        this.model.setState(ReelState.END);
    }

    /**
     * 建立這一欄的格子。由子類實作。
     *
     * 基底原本的版本是 `instantiate(symbolPrefab)`——每一格複製一份掛滿全部美術的 NgSymbol。
     * 改成物件池之後格子是沒有美術的空殼、要顯示什麼向池子租，那份 prefab 與對應的
     * `symbolPrefab` 欄位已隨 NgSymbol 一起移除，所以這裡只留一個掛勾。
     *
     * 實作要負責把 {@link symbolNodes}／{@link symbolCells}／{@link symbolOpacities}／
     * {@link posIndexes} 四個平行陣列填滿（長度都等於 `posList.length`），最後呼叫
     * {@link updateDrawOrder}；基底其餘的轉動邏輯都靠這幾個陣列運作。
     */
    protected initSymbols(): void {
        console.warn(`[ReelView] ${this.node.name} 沒有覆寫 initSymbols()，這一欄不會有任何格子`);
    }

    /** 依 posIdx 排序調整每個 symbol 的顯示層級（sibling index），
     *  container 底下固定就是這幾個 pos，只是重新排序疊放順序，
     *  確保 posIdx 越大（越下面）的 symbol 疊在越上層，畫面前後關係才正確 */
    protected updateDrawOrder(): void {
        const order = this.symbolNodes.map((_, i) => i).sort((a, b) => this.posIndexes[a] - this.posIndexes[b]);
        const last = this.container.children.length - 1;
        for (const i of order) {
            this.symbolNodes[i].setSiblingIndex(last);
        }
    }

    /**
     * 符號轉進頂部、換上新 frame 時呼叫，給子類覆寫（例如判斷是不是 coin 顯示）。
     *
     * @param _symbolIdx 這一欄裡的格子索引。
     * @param _stripIdx 新 frame 在輪帶上的位置。
     * @param _frameIdx 換上的 frameIdx。
     */
    protected onSymbolStepIntoTop(_symbolIdx: number, _stripIdx: number, _frameIdx: number): void {}

    /**
     * 符號下落／消除 settle 完成後呼叫，給子類覆寫做收尾。
     *
     * @param _symbolIdx 落定的格子索引。
     */
    protected onSymbolSettled(_symbolIdx: number): void {}

    /**
     * 後端符號名稱 → 圖名（{@link frameNames}）的對照表，給子類覆寫；兩邊名稱一樣時不用覆寫。
     *
     * @returns 對照表；查不到的名稱原樣當圖名用。
     */
    protected getSymbolNameMap(): Record<string, string> {
        return {};
    }

    /**
     * 這一欄實際可視列數（posList 扣掉頭部 2 列進場 buffer 與尾部 2 列掉落 buffer），不規則輪帶每欄可能不同。
     *
     * @returns 列數。
     */
    get visibleRowCount(): number {
        return Math.max(0, this.posList.length - 4);
    }

    /**
     * 可視列 row 對應到 posList 的索引偏移。
     *
     * 預設 2，也就是頭部那兩格進場 buffer——可視列 0 就是 posList 的第 3 格。
     * 子類別如果在可視區裡安插了不吃後端資料的裝飾格（1003 兩側欄在 2026-10-14 前有過，已拿掉），
     * 要覆寫這個值把那些格子讓開，否則後端的列會整欄錯位。
     *
     * @returns 可視列 0 在 posList 的索引。
     */
    protected get rowToPosOffset(): number {
        return 2;
    }

    /**
     * 這一欄真正吃後端資料的列數。
     *
     * 預設等於可視列數。子類別若在可視區裡安插裝飾格，要覆寫成扣掉那些格子之後的數字。
     *
     * @returns 列數。
     */
    protected get dataRowCount(): number {
        return this.visibleRowCount;
    }

    /**
     * 取得可視區某一列目前顯示的符號節點。
     *
     * @param row 可視列索引（0 起算，會自動跳過頭部 2 格 buffer）。
     * @returns 該列的節點；沒有節點停在那個位置時是 null。
     */
    getVisibleSymbol(row: number): Node | null {
        const posIdx = row + this.rowToPosOffset;
        for (let i = 0; i < this.symbolNodes.length; i++) {
            if (this.posIndexes[i] === posIdx) {
                return this.symbolNodes[i];
            }
        }
        return null;
    }

    /**
     * 找出目前停在指定格位的是哪一個符號節點。
     *
     * @param posIdx posList 的索引。
     * @returns symbolNodes 的索引；沒有節點在那裡時回 -1。
     */
    findSymbolNodeAtPosIndex(posIdx: number): number {
        for (let i = 0; i < this.symbolNodes.length; i++) {
            if (this.posIndexes[i] === posIdx) return i;
        }
        return -1;
    }

    /**
     * 依圖名找 frameIdx（原本 tumbleFill/setInitialSymbol/CascadeReelsTask 各自重寫一份一模一樣的
     * 線性搜尋，收斂成這一份共用）。
     *
     * @param name 圖名，見 {@link frameNames}。
     * @returns frameIdx；找不到時回 -1。
     */
    frameIdxByName(name: string): number {
        return this.frameNames.indexOf(name);
    }

    /**
     * 換掉整條輪帶並立刻重繪畫面。
     *
     * @param iconColumn 新的符號名稱序列。
     */
    updateStrip(iconColumn: string[]): void {
        this.strip = this.buildStrip(iconColumn);
        this.refreshDisplay();
    }

    /**
     * 直接指定可視區某一列要顯示哪個符號（不經過輪帶，用於還原盤面）。
     *
     * @param row 可視列索引（0 起算）。
     * @param symbolName 後端的符號名稱，會先過一次名稱對照表。
     */
    setInitialSymbol(row: number, symbolName: string): void {
        const posIdx = row + this.rowToPosOffset;
        const map = this.getSymbolNameMap();
        const imgName = map[symbolName] ?? symbolName;
        const frameIdx = Math.max(0, this.frameIdxByName(imgName));
        for (let i = 0; i < this.symbolNodes.length; i++) {
            if (this.posIndexes[i] === posIdx) {
                this.setSymbolDisplay(i, frameIdx);
                break;
            }
        }
    }

    /**
     * 依目前的 currentRng 把每個符號節點的圖重繪一次。
     */
    refreshDisplay(): void {
        for (let i = 0; i < this.symbolNodes.length; i++) {
            const stripIdx = (this.model.currentRng + i) % this.strip.length;
            this.setSymbolDisplay(i, this.strip[stripIdx]);
        }
    }

    /**
     * 把後端的符號名稱序列轉成 frameIdx 序列。
     *
     * 對不到名稱的一律退回索引 0，而不是留 undefined——undefined 一路傳下去不會報錯，只會什麼都
     * 不顯示，比顯示錯圖還難查（見 agent-pitfalls.md 坑 #23）。
     *
     * @param iconColumn 後端的符號名稱序列。
     * @returns 對應的 frameIdx 序列。
     */
    buildStrip(iconColumn: string[]): number[] {
        const map = this.getSymbolNameMap();
        return iconColumn.map((apiName) => {
            const idx = this.frameIdxByName(map[apiName] ?? apiName);
            return idx >= 0 ? idx : 0;
        });
    }

    /**
     * 讓某一格顯示指定的 frameIdx。基底沒有任何顯示方式，由子類實作。
     *
     * 原本基底是直接換 Sprite 的圖（`spriteFrames[frameIdx]`），1003 一直是子類覆寫成向物件池租符號，
     * 那段從沒被用到，隨 `spriteFrames` 一起移除。
     *
     * @param _symbolIdx 這一欄裡的格子索引。
     * @param _frameIdx 要顯示的 frameIdx。
     */
    setSymbolDisplay(_symbolIdx: number, _frameIdx: number): void {
        // 子類覆寫
    }

    /**
     * 把這一輪的盤面結果寫回輪帶的可視段，讓之後的轉動接得上畫面上的符號。
     *
     * 起點用 {@link rowToPosOffset} 而不是寫死的 2：可視區裡有裝飾格時偏移會變大，
     * 寫錯位置會讓下一輪轉動時整欄的符號對不上。
     *
     * @param frameIdxes 這一輪各可視列的 frameIdx，順序由上而下。
     */
    patchVisibleStrip(frameIdxes: number[]): void {
        for (let i = 0; i < frameIdxes.length; i++) {
            this.strip[this.rowToPosOffset + i] = frameIdxes[i];
        }
    }

    /**
     * 每幀依 model 的狀態推進對應的轉動階段；沒在轉時直接返回。
     *
     * @param dt 距離上一幀的秒數。
     */
    protected override update(dt: number): void {
        if (!this.isSpinning) return;

        this.time += dt;
        this.spinClock += dt;

        if (this.stopCountdown >= 0) {
            this.stopCountdown -= dt;
            if (this.stopCountdown <= 0) {
                const lateBy = -this.stopCountdown;
                this.stopCountdown = -1;
                this.requestStop(this.pendingStopRng, lateBy);
            }
        }

        switch (this.model.state) {
            case ReelState.BEGIN:
                this.updateBegin();
                break;
            case ReelState.LOOP:
                this.updateLoop();
                break;
            case ReelState.STOPPING:
                this.updateStopping();
                break;
            case ReelState.END:
                this.updateEnd();
                break;
        }

        // 停輪段之後的時間是固定的，落定前 landingLead 秒到了就通知（見 onLandingSoon）
        if (this.landingAt >= 0 && !this.landingSoonNotified && this.spinClock >= this.landingAt - this.landingLead) {
            this.notifyLandingSoon();
        }
    }

    /**
     * 起轉加速階段：先原地等完 {@link startDelay}（起轉間隔），再依 beginEase 換算位移比例，
     * 跑滿一段就跳一格並轉入等速。
     */
    protected updateBegin(): void {
        const elapsed = this.time - this.startDelay;
        if (elapsed < 0) return;

        const progress = Math.min(elapsed / this.beginDuration, 1);
        this.ratio = resolveEasing(this.beginEase)(progress);

        if (progress >= 1) {
            this.step();
            this.time = 0;
            this.model.setState(ReelState.LOOP);
            return;
        }

        this.moveSymbols();
    }

    /**
     * 等速轉動階段：這一幀跑過幾條格線就跳幾格，餘數留給下一格，避免累積誤差。
     *
     * 一幀可能跨不只一格：每秒 25 格配上急速 3 倍是每秒 75 格，裝置掉到 37.5 fps 以下時一幀就超過兩格。
     * 只跳一格的話多出來的整格會被餘數運算吃掉，轉輪變慢、落定時間也跟著往後拖。
     *
     * 收到停輪指令（`ReelModel.stop()`）後，在指令預定時刻之後的第一條格線轉進 STOPPING；在格線上
     * 切換，減速段的起點才會剛好對齊一格。格線比預定時刻早的那一條不算：這一幀裡格線可能落在倒數
     * 歸零之前，在那裡切換會讓這一欄比預定早停。轉進 STOPPING 之後，這一幀剩下的時間直接交給停輪段。
     */
    protected updateLoop(): void {
        while (this.time >= this.loopTime) {
            this.time -= this.loopTime;
            this.step();

            const gridAt = this.spinClock - this.time;
            if (this.model.requestStop && this.model.finalRng >= 0 && gridAt >= this.stopIdealAt - 1e-6) {
                this.enterStopping(gridAt);
                this.updateStopping();
                return;
            }
        }
        this.ratio = this.time / this.loopTime;
        this.moveSymbols();
    }

    /**
     * 轉進停輪段，並把「等格線」晚掉的時間攤進停輪段的每一格。
     *
     * 停輪指令只能在格線上生效，最多晚一格。各欄起轉時刻不同（起轉間隔）時格線彼此錯開，不補的話
     * 落地間隔會忽長忽短，最多差一格。停輪段固定跑 `stopRunUp - 1` 格，每格縮短 `晚掉的時間 ÷ 格數`，
     * 進回彈段的時刻就剛好是「預定時刻 + (stopRunUp - 1) 格」。以 9 格來說速度最多快約 14%，
     * 而且只在停輪前那一小段。
     *
     * 指令比這一欄進入等速還早（起轉階段就下了）時，晚掉的時間可能超過一格，只補一格。沒經過
     * {@link scheduleStop}、直接對 model 下的指令沒有預定時刻，不補。
     *
     * @param gridAt 這條格線落在 {@link spinClock} 的哪一刻。
     */
    private enterStopping(gridAt: number): void {
        const steps = Math.max(1, this.stopRunUp - 1);
        const late = this.stopIdealAt < 0 ? 0 : Math.min(Math.max(gridAt - this.stopIdealAt, 0), this.loopTime);
        this.stoppingStepTime = this.loopTime - late / steps;
        // 停輪段跑 steps 格、再花落定時長碰到定位：從這條格線起算，碰到定位的時刻就固定了
        this.landingAt = gridAt + steps * this.stoppingStepTime + this.endDuration;
        this.model.setState(ReelState.STOPPING);
    }

    /**
     * 準備停輪階段：等速（略快，見 {@link enterStopping}），每跳一格就檢查是否已經到達停輪位置。
     *
     * 跟 {@link updateLoop} 一樣，一幀跨幾格就跳幾格，但逐格檢查，不會跳過停輪位置。
     */
    protected updateStopping(): void {
        const stepTime = this.stoppingStepTime > 0 ? this.stoppingStepTime : this.loopTime;
        const oneStepBefore = (((this.model.finalRng + 1) % this.strip.length) + this.strip.length) % this.strip.length;

        while (this.time >= stepTime) {
            this.time -= stepTime;
            this.step();

            if (this.model.currentRng === oneStepBefore) {
                this.model.setState(ReelState.END);
                return;
            }
        }
        this.ratio = this.time / stepTime;
        this.moveSymbols();
    }

    /**
     * 停輪階段：最後一格依落定曲線（endEase）走完，跑完後跳最後一格、對齊到精確位置，接著播落地回彈
     * （{@link updateStopBounce}），彈完才通知 model 已停止。
     *
     * 比例超過 1 代表衝過定位（backOut、elasticOut 這類曲線），moveSymbols() 會照比例外插，
     * 之後曲線把它拉回 1。第一次碰到 1 的那一刻通知 {@link onStopReached}——停輪音、Scatter 落地
     * 都在這一刻，不等回彈。
     */
    protected updateEnd(): void {
        if (this.stopBouncing) {
            this.updateStopBounce();
            return;
        }

        const progress = Math.min(this.time / this.endDuration, 1);
        if (progress >= 1) {
            this.step();
            this.snapToFinalPosition();
            this.notifyStopReached();
            this.stopBouncing = true;
            this.stopBounceFrom = this.time;
            this.updateStopBounce();
            return;
        }

        this.ratio = resolveEasing(this.endEase)(progress);
        if (this.ratio >= 1) this.notifyStopReached();
        this.moveSymbols();
    }

    /**
     * 停輪後的落地回彈：整欄往上彈 {@link stopBounceHeight} 的高度再落回定位，彈完對齊並通知 model 已停止。
     * 高度或兩段時長合計是 0 時不彈，碰到定位就直接收尾。
     *
     * 搬的是每顆符號節點，不是欄容器：Wild／Scatter 的節點住在特殊符號層的容器裡（座標與欄容器一致），
     * 只搬欄容器的話它們不會跟著彈；中獎層上的物件由 SymbolCell 每幀照節點同步，也會跟著彈。
     * 往上彈時下緣露出的是下方緩衝格，它本來就是顯示著的，不會露出空白。
     */
    private updateStopBounce(): void {
        const heightRatio = this.stopBounceHeight;
        const upTime = this.stopBounceUp;
        const downTime = this.stopBounceDown;
        const elapsed = this.time - this.stopBounceFrom;
        if (heightRatio <= 0 || elapsed >= upTime + downTime) {
            this.stopBouncing = false;
            this.snapToFinalPosition();
            this.model.onStopped();
            return;
        }

        const lift = elapsed < upTime ? easing.quadOut(elapsed / upTime) : 1 - easing.quadIn((elapsed - upTime) / downTime);
        const offset = this.cellHeightAbs() * heightRatio * lift;
        for (let i = 0; i < this.symbolNodes.length; i++) {
            const y = this.posList[this.posIndexes[i]].position.y;
            this.symbolNodes[i].setPosition(0, y + offset, 0);
        }
    }

    /**
     * 把所有符號節點直接對齊到各自 posIndex 的座標，消掉插值留下的零頭。
     */
    protected snapToFinalPosition(): void {
        for (let i = 0; i < this.symbolNodes.length; i++) {
            const curIdx = this.posIndexes[i];
            const y = this.posList[curIdx].position.y;
            this.symbolNodes[i].setPosition(0, y, 0);
        }
    }

    /**
     * 把每個符號往前推一格，並同步倒推 model 的 currentRng。
     *
     * 只改邏輯上的格位索引，**不動節點實際座標**——座標由 moveSymbols() 每幀插值，
     * 或由 snapToFinalPosition() 一次對齊。
     */
    protected step(): void {
        for (let i = 0; i < this.symbolNodes.length; i++) {
            this.posIndexes[i] = (this.posIndexes[i] + 1) % this.posList.length;
        }

        const newRng = (this.model.currentRng - 1 + this.strip.length) % this.strip.length;
        this.model.setCurrentRng(newRng);

        for (let i = 0; i < this.symbolNodes.length; i++) {
            if (this.posIndexes[i] === 0) {
                const stripIdx = this.model.currentRng;
                const frameIdx = this.strip[stripIdx];
                this.setSymbolDisplay(i, frameIdx);
                this.onSymbolStepIntoTop(i, stripIdx, frameIdx);
            }
        }

        this.updateDrawOrder();
    }

    /**
     * 依目前的位移比例，把每個符號在「目前格位」與「下一格位」之間插值移動，
     * 並處理進出可視區時的淡入淡出。
     */
    protected moveSymbols(): void {
        for (let i = 0; i < this.symbolNodes.length; i++) {
            const curIdx = this.posIndexes[i];
            const nextIdx = (curIdx + 1) % this.posList.length;

            const opacity = this.symbolOpacities[i];

            if (curIdx === this.posList.length - 1) {
                opacity.opacity = 0;
            } else {
                opacity.opacity = 255;
            }

            const curY = this.posList[curIdx].position.y;
            const nextY = this.posList[nextIdx].position.y;

            const newY = curY + (nextY - curY) * this.ratio;
            this.symbolNodes[i].setPosition(0, newY, 0);
        }
    }

    // ========== 物理式掉落輔助方法 ==========

    /**
     * 依「參考距離／參考時間」推出重力常數，再算出任意距離的掉落時間（等加速度掉落）。
     *
     * g = 2 * refDistance / refDuration^2；t = sqrt(2 * distance / g)
     * 沿用既有已調校好的 reference（例：cellHeight/fillTime），讓不同掉落距離有物理上合理的比例，
     * 同時維持 normal/fast/turbo 各速度檔既有的調校手感。
     *
     * @param distance 這次要掉落的距離。
     * @param referenceDistance 參考距離（通常是一格高）。
     * @param referenceDuration 掉落參考距離所花的時間（秒）。
     * @returns 掉落時間（秒）；任一參數不是正數時回 referenceDuration。
     */
    protected physicsFallDuration(distance: number, referenceDistance: number, referenceDuration: number): number {
        const dist = Math.abs(distance);
        const refDist = Math.abs(referenceDistance);
        if (refDist <= 0 || referenceDuration <= 0 || dist <= 0) return referenceDuration;
        const gravity = (2 * refDist) / (referenceDuration * referenceDuration);
        if (gravity <= 0) return referenceDuration;
        return Math.sqrt((2 * dist) / gravity);
    }

    /**
     * 單一 cell 的高度（絕對值），做為物理掉落的參考距離。
     *
     * @returns 高度；posList 不到兩格時為 0。
     */
    protected cellHeightAbs(): number {
        if (this.posList.length < 2) return 0;
        return Math.abs(this.posList[0].position.y - this.posList[1].position.y);
    }

    /**
     * 在既有 tween 鏈後面接上「落地回彈」：到達定位後往上彈 {@link LANDING_BOUNCE} 的高度，再落回定位。
     *
     * 2026-10-19 照參考影片改：原本是往下衝過 5% 格高再拉回（0.055 + 0.07 秒），方向相反、幅度也小。
     * 回彈是往上，會頂進上面那格的位置——同一欄的補牌要一起落下（fillStagger 0），上面那顆才不會
     * 在下面那顆還彈在半空時就落定，兩張牌疊在一起。（原本後面還接果凍壓扁，2026-10-12 移除。）
     *
     * @param t 要接上去的 tween 鏈。
     * @param targetY 落定位置的 y。
     * @param cellHeight 格距，回彈高度依它換算。
     * @returns 接好回彈的同一條 tween 鏈。
     */
    protected appendLandingBounce(t: Tween<Node>, targetY: number, cellHeight: number): Tween<Node> {
        const height = Math.abs(cellHeight) * LANDING_BOUNCE.heightRatio;
        return t
            .to(LANDING_BOUNCE.upTime, { position: new Vec3(0, targetY + height, 0) }, { easing: 'quadOut' })
            .to(LANDING_BOUNCE.downTime, { position: new Vec3(0, targetY, 0) }, { easing: 'quadIn' });
    }

    // ========== 連鎖補牌 ==========

    /**
     * cascadeFill 共用的單顆掉落：掉到 targetY（彈跳開始前觸發 onLanded）→ 落地彈跳 → 落定。
     *
     * @param node 要掉落的符號節點。
     * @param targetY 落定位置的 y。
     * @param delay 起跑前的延遲（秒）。
     * @param duration 掉落段耗時（秒）。
     * @param cellHeight 一格高度，用來決定彈跳幅度。
     * @param symIdx 符號節點索引，落定時交給 onSymbolSettled。
     * @param fillEase 掉落段的 easing。
     * @param onLanded 到達 targetY 時呼叫。
     * @returns 彈跳演完、落定後 resolve。
     */
    private playCascadeDrop(node: Node, targetY: number, delay: number, duration: number, cellHeight: number, symIdx: number, fillEase: TweenEasing, onLanded?: () => void): Promise<void> {
        return new Promise<void>((resolve) => {
            Tween.stopAllByTarget(node);
            let t = tween(node)
                .delay(delay)
                .to(duration, { position: new Vec3(0, targetY, 0) }, { easing: fillEase })
                .call(() => onLanded?.());
            t = this.appendLandingBounce(t, targetY, cellHeight);
            t.call(() => {
                this.onSymbolSettled(symIdx);
                resolve();
            }).start();
        });
    }

    /**
     * 消除後補牌：被消掉的格子由上方的符號遞補，buffer 用完時直接生新符號補進來。
     *
     * 由下往上逐格處理，所以第一個排進去的掉落就是這一欄最下面那顆會移動的符號，
     * 停輪音只綁在它身上，不取最先落定的那顆（整欄被消掉時新生的最上面那顆可能先到）。
     *
     * @param toMapCol 補完後資料列的符號 frame 索引，由上到下。
     * @param elimRows 這次被消除的資料列（0-based）。
     * @param fillTime 掉落一格高度的參考耗時（秒），實際耗時依落下距離以重力反推。
     * @param dropRowDelay 相鄰兩顆起跑的間隔（秒）。
     * @param onBottomLanded 最下面那顆到達 targetY 時呼叫（停輪音），不等落地彈跳。
     * @param fillEase 掉落段的 easing。
     * @returns 全部掉落演完後 resolve；找不到符號節點時提早 return。
     */
    async cascadeFill(
        toMapCol: number[],
        elimRows: number[], // 這次被消除的 row（0-based，可見範圍）
        fillTime: number,
        dropRowDelay: number,
        onBottomLanded?: () => void,
        fillEase: TweenEasing = 'quadIn'
    ): Promise<void> {
        const len = this.posList.length;
        const keepRow = this.rowToPosOffset;
        // 最後一列資料格的 posIdx。用資料列數算而不是 len - 3：可視區裡若有裝飾格
        // （不吃後端資料、只跟著演出），len 會比資料列數多，照舊式算法會把裝飾格當成
        // 資料列去抓 toMapCol[該列]，取到 undefined 又不會報錯，那一格會變成空白。
        const visibleBottom = keepRow + this.dataRowCount - 1;
        const empty = new Set<number>(elimRows.map((r) => r + keepRow));
        const isEmpty = (p: number) => empty.has(p);
        const promises: Promise<void>[] = [];
        let dropCount = 0;
        const cellHeight = this.cellHeightAbs();

        for (let toPos = len - 1; toPos > 0; toPos--) {
            if (!isEmpty(toPos)) continue;

            let solidPos = toPos - 1;
            while (solidPos >= 0 && isEmpty(solidPos)) solidPos--;
            if (solidPos < 0) {
                // 上面已經沒東西可以掉了（buffer 用完），toPos 又在可見範圍內，做 ghost revive：直接生一個新的補進來
                if (toPos < keepRow || toPos > visibleBottom) continue;
                const ghostIdx = this.findSymbolNodeAtPosIndex(toPos);
                if (ghostIdx < 0) continue;
                const ghostTargetY = this.posList[toPos].position.y;
                // 從落點往上「消除格數」那麼高的地方起跑：最上面那一段（含 buffer）每顆都正好掉這麼多格，
                // 新生的牌就接在 buffer 上面排成一整條、一起滑下來。原本一律從 posList[0] 起跑，跟 buffer
                // 最上面那顆同一點出發，只靠 dropRowDelay 錯開——延遲是 0 時會整段疊成一張，到格位才分開
                const ghostStartY = ghostTargetY + elimRows.length * (this.posList[0].position.y - this.posList[1].position.y);
                const viewRow = toPos - keepRow;
                this.symbolOpacities[ghostIdx].opacity = 255;
                this.symbolNodes[ghostIdx].setScale(1, 1, 1);
                this.symbolNodes[ghostIdx].setPosition(0, ghostStartY, 0);
                this.setSymbolDisplay(ghostIdx, toMapCol[viewRow]);
                empty.delete(toPos);

                const ghostNode = this.symbolNodes[ghostIdx];
                const ghostDelay = dropCount * dropRowDelay;
                const ghostOnLanded = dropCount === 0 ? onBottomLanded : undefined;
                dropCount++;
                const ghostDist = ghostStartY - ghostTargetY;
                const ghostDuration = this.physicsFallDuration(ghostDist, cellHeight, fillTime);
                promises.push(this.playCascadeDrop(ghostNode, ghostTargetY, ghostDelay, ghostDuration, cellHeight, ghostIdx, fillEase, ghostOnLanded));
                continue;
            }

            const emptySymIdx = this.findSymbolNodeAtPosIndex(toPos);
            const solidSymIdx = this.findSymbolNodeAtPosIndex(solidPos);

            if (emptySymIdx < 0 || solidSymIdx < 0) {
                console.error(`[cascadeFill] symbol not found: toPos =${toPos} solidPos =${solidPos}`);
                return;
            }

            this.posIndexes[emptySymIdx] = solidPos;
            this.symbolNodes[emptySymIdx].setPosition(0, this.posList[solidPos].position.y, 0);

            this.posIndexes[solidSymIdx] = toPos;
            this.symbolOpacities[solidSymIdx].opacity = 255;
            this.symbolNodes[solidSymIdx].setScale(1, 1, 1);
            this.symbolNodes[solidSymIdx].setPosition(0, this.posList[solidPos].position.y, 0);

            if (toPos >= keepRow && toPos <= visibleBottom) {
                const viewRow = toPos - keepRow;
                this.setSymbolDisplay(solidSymIdx, toMapCol[viewRow]);
            } else {
                const newRng = this.model.currentRng - elimRows.length;
                const stripIdx = (((newRng + toPos) % this.strip.length) + this.strip.length) % this.strip.length;
                this.setSymbolDisplay(solidSymIdx, this.strip[stripIdx]);
            }
            empty.delete(toPos);
            empty.add(solidPos);

            const node = this.symbolNodes[solidSymIdx];
            const targetY = this.posList[toPos].position.y;
            const delay = dropCount * dropRowDelay;
            const onLanded = dropCount === 0 ? onBottomLanded : undefined;
            dropCount++;
            const dist = this.posList[solidPos].position.y - targetY;
            const duration = this.physicsFallDuration(dist, cellHeight, fillTime);
            promises.push(this.playCascadeDrop(node, targetY, delay, duration, cellHeight, solidSymIdx, fillEase, onLanded));
        }
        this.updateDrawOrder();
        await Promise.all(promises);
        this.model.setCurrentRng(this.model.currentRng - elimRows.length);
    }
}
