import type { IGameMain } from '../states/GameState';
import type { SlotMachineModel } from '../reel/model/SlotMachineModel';
import type StoreManager from '../store/StoreManager';
import type { SlotGameDefinition } from '../models/SlotGameTypes';
import type { SpinSkipController } from '../controllers/SpinSkipController';

/**
 * popups 的最小結構介面。對應 1001/1002 各自 `View/PopupManager.ts` 內
 * 實際被 Net/Task 系列呼叫到的方法（其餘彈窗方法屬於各遊戲內部使用，不收進來）。
 */
export interface ISlotPopupHost {
    showWinAnimation(totalWin: number, bet: number, mode?: string): Promise<void>;
    showJackpotOnAll(jpType: string, amount: number): Promise<void>;
}

/**
 * 一局轉輪與消除的節奏，`cascadeTiming()` 的回傳形狀。整台一組；快轉／急速轉不另外寫一組，由整體速度倍率
 * 等比縮放。**單位不一致**：`breath` 與 `fgDelay` 是毫秒，其餘時長都是秒。
 */
export interface CascadeTimingConfig {
    /** 輪轉時長（秒）：每一欄的等速段（進入等速到開始回彈）至少這麼長 */
    spinDuration: number;
    /** 起轉間隔（秒）：由左到右，每一欄比左邊那欄晚多久起轉 */
    startInterval: number;
    /** 停輪間隔（秒）：由左到右，每一欄比左邊那欄晚多久落地 */
    stopInterval: number;
    /** 每一步消除開始前的停頓（**毫秒**）：停輪或上一步補牌結束後，等這麼久才播這一步的中獎演出 */
    breath: number;
    /** 中獎消除演出的速度基準（秒）——timeScale ＝ 1.6 ÷ 這個值，見 ReelView_1003.playWinFx() */
    winFx: number;
    /** 補牌掉落耗時（秒） */
    fill: number;
    /** 補牌掉落每往上一顆多延遲多久起跑（秒）；0 是整欄同時落下 */
    fillStagger: number;
    /** 補格掉落 tween 的 easing 名稱（cc.TweenEasing），故意用 string 而非該型別，
     *  避免這份跨遊戲共用介面依賴 'cc' */
    fillEase: string;
    /** 免費遊戲兩局之間的停頓（**毫秒**），見 `SpinFlowPlanner` 的 `fgDelay` 步驟 */
    fgDelay: number;
    /** 聽牌時間（秒），見 `ReelTimingOverride.tenpaiDuration` */
    tenpai: number;
    /** FG 五軸起轉後幾秒播 spine（秒），見 `ReelTimingOverride.miGoldSpineDelay` */
    miGoldSpineDelay: number;
    /** FG spine 起播後幾秒蓋瞇牌（秒），見 `ReelTimingOverride.miGoldMiDelay` */
    miGoldMiDelay: number;
    /** FG 瞇牌起播後幾秒開始金牌飛入（秒），見 `ReelTimingOverride.miGoldFlyDelay` */
    miGoldFlyDelay: number;
    /** FG 金牌飛入時長（秒），見 `ReelTimingOverride.miGoldFlyDuration` */
    miGoldFlyDuration: number;
    /** FG 金牌飛到定位後幾秒停輪（秒），見 `ReelTimingOverride.miGoldStopDelay` */
    miGoldStopDelay: number;
    /** 瞇牌／聽牌框與壓黑一起淡出的秒數，見 `ReelTimingOverride.focusFadeOutSec` */
    focusFadeOutSec: number;
    /** 進 FG 轉場結束後、升級倍數動畫前的停頓（秒），見 `ReelTimingOverride.fgEnterDelay` */
    fgEnterDelay: number;
}

/** cc.Component.scheduleOnce 最小切面 */
export interface IGameScheduler {
    scheduleOnce(callback: Function, delay?: number): void;
    unschedule(callback: Function): void;
}

/** 快停：轉動中再點一下，還沒停的軸立刻停；範圍是 `toWinPopup` 時轉輪停好後還能點，跳過報獎前的等待（消除照常速播） */
export interface IQuickStop {
    /** 轉輪落定階段開始時登記快停處理，階段結束傳 null；登記當下已有待處理的快停會立刻觸發 */
    setQuickStopHandler(handler: (() => void) | null): void;
    /** 一轉開始 */
    openSpinWindow(): void;
    /** 一轉結束 */
    closeSpinWindow(): void;
    /** 跳過到贏獎彈窗 */
    readonly spinSkip: SpinSkipController;
}

/** 轉輪／多視圖存取 */
export interface IReelPresentation<TView> {
    readonly definition: SlotGameDefinition;
    readonly viewH: TView;
    readonly viewV: TView;
    readonly allViews: TView[];
    forEachView(fn: (v: TView) => void): void;
    readonly slotMachineModel: SlotMachineModel;
    readonly charMulLeadMs: number;
    cascadeTiming(): CascadeTimingConfig;
}

/** win bar 演出 */
export interface IWinMeterPresentation {
    winBarValue: number;
    winBarProxy: { v: number };
    setWinBarNum(val: number): void;
    addWinBarScore(delta: number): void;
    /** 盤面贏分條歸零，原本那一筆移進操作列 Win；Win 捲完時 resolve */
    clearWinBarScore(): Promise<void>;
    /** 把一筆贏分疊到操作列 Win 的累計上 */
    addWinBalance(delta: number): Promise<void>;
    resetWinBar(): void;
    hideWinBarNum(): void;
    showWinBarNum(): void;
    rollWinBalance(to: number, duration: number): Promise<void>;
}

/** 免費遊戲狀態流程 */
/** 轉場方向 進入或離開 */
export type TransitionDirection = 'enter' | 'exit';

export interface IFreeSpinPresentation {
    freeSpinsRemaining: number;
    freeSpinsTotal: number;
    fgTotalWin: number;
    updateFgUi(awardedRounds?: number): void;
    applyGameModeUi(fg: boolean): void;
    playTransition(direction: TransitionDirection): Promise<void>;
    shouldEnterFreeGame(freeSpinTriggered: boolean, currentCols: number[][]): boolean;
    showFreeBoard(): Promise<void>;
    onNormalSpin(): void;
}

/**
 * ISlotGameMain（最小掛鉤介面，SGEngine 階段二）
 *
 * 背景：比對舊專案（Cocos_2022）`SlotCustom`/`ISlotCustomSpin`/`ISlotCustomErase`
 * 後發現，entry 目前的 `GameTaskHandler` 子類別（如 `SpinResultHandler`）與各具名
 * `GameTask`（`CascadeReelsTask`/`CollectWinTask`/... 等）都直接把建構子參數型別
 * 寫死成具體的 `GameMain_1001`/`GameMain_1002`，而不是透過一層通用介面存取
 * `GameMain` 的能力——這是舊專案用 `ISlotCustomSpin`/`ISlotCustomErase` 解決的
 * 問題，entry 目前還沒有對應物。
 *
 * 這個介面收錄的是「比對 GameMain_1001 與 GameMain_1002 兩份實作後，簽章完全
 * 一致」的最小共同表面積，供未來 Net/Task 系列改成依賴此介面（而非具體類別）
 * 時使用。範圍原則：
 *   - 只收錄兩邊都有、簽章一致的成員。`cascadeTiming()` 原本只有 1001 有，
 *     2026-08-03 已補上 1002 的實作使兩邊同步（1001/1002 是同一款遊戲換皮，
 *     不是兩款獨立遊戲，兩邊本該有一致的能力），故收進來。
 *   - 注意：拿 1001/1002 互相比對只能驗證「兩份換皮實作彼此一致」，並不能真正
 *     驗證這個介面是否適用於「機制不同的其他遊戲」（例如 8001 百家樂）——那需要
 *     等真的有第二款機制不同的遊戲接上這套引擎才能驗證（見 worklist-EN.md 第三階段）。
 *   - `popups` 底下的具體類別（`PopupManager`）兩邊也是各自獨立實作（尚未共用），
 *     故此處只描述 Net/Task 系列實際用到的最小結構（見 `ISlotPopupHost`），非完整類別介面。
 *     1003 原本還有 `buyFeature`（購買免費遊戲），2026-10-19 隨功能移除。
 *
 * 2026-08-24 拆成獨立 port 純型別重組 成員簽章未變 現有 Task 建構子不用改
 *
 * TView 對應各遊戲自己的 `GameViewAdapter` 具體型別（1001/1002 各自一份，未共用）。
 */
export interface ISlotGameMain<TView> extends IGameMain, IGameScheduler, IQuickStop, IReelPresentation<TView>, IWinMeterPresentation, IFreeSpinPresentation {
    readonly storeManager: StoreManager;
    readonly popups: ISlotPopupHost;
}
