import { Logger } from '../utils/Logger';
import StoreManager from "../store/StoreManager";
import TrackerStore from "../store/TrackerStore";
import { TemplateView } from "../ui/TemplateView/TemplateView";
import { GAME_EVENT_TYPE, gameRuntimeEventBus } from "../events/GameRuntimeEventBus";
import type { SlotRoundResult } from "../models/SlotRound";

/**
 * 遊戲內埋點（單例）：把累計下注、累計贏分與遊玩時間寫進 TrackerStore，並把事件轉給外層網頁的
 * `trackEvent`。
 *
 * 原作者 Matthew（2026-03-09，原名 GameTracker）。
 */
export default class EagleTracker {
    static instance;
    storeManager: StoreManager
    store: TrackerStore
    context: TemplateView
    interval: number = 1000 * 60;

    /**
     * 取得埋點單例，第一次呼叫時才建立。
     *
     * @returns 單例。
     */
    static getInstance() {

        if (!EagleTracker.instance) {
            EagleTracker.instance = new EagleTracker();
        }

        return EagleTracker.instance;
    }


    /**
     * 綁定 View、取得 store、訂閱 spin 事件，並啟動遊玩時間的定時累加。
     *
     * @param context 用來掛事件訂閱的 View（元件銷毀時訂閱會自動解除）。
     */
    initGameTracker(context: TemplateView) {
        this.context = context;
        this.storeManager = StoreManager.getInstance();
        this.registerStore();
        this.registerReactions();
        this.trackerPlayTimes();
    }
    /**
     * 取得 StoreManager 與埋點用的 TrackerStore。
     */
    registerStore() {
        this.storeManager = StoreManager.getInstance();
        this.store = StoreManager.getInstance().getTrackerStore();
    }

    /**
     * 訂閱 spin 資料變化並立刻補跑一次目前的值。
     *
     * mobx 移除之後改走 gameRuntimeEventBus；補跑那一次等效原本的 `fireImmediately: true`。
     */
    registerReactions() {
        // mobx 移除計劃：SlotGameStore.spinData 已改由 gameRuntimeEventBus 通知，不再用 mobx reaction
        this.context.subscribeGameEvent(gameRuntimeEventBus, GAME_EVENT_TYPE.GAME_SPIN_DATA_CHANGED,
            (e) => this.trackSpinData(e.spinData));
        this.trackSpinData(this.storeManager.getGameStore().spinData); // 等效原本的 fireImmediately: true
    }

    /**
     * 從一次 spin 的結果累計贏分。
     *
     * @param spinData 主遊戲那一轉的結果；falsy 時直接略過。
     */
    trackSpinData(spinData: SlotRoundResult | null) {
        if (!spinData) return;
        this.trackerTotalWin(Number(spinData.totalWin) || 0);
    }

    /**
     * 把一次贏分累加進累計贏分。
     *
     * @param win 這次的贏分。
     */
    trackerTotalWin(win: number) {
        let totalWin = this.store.totalWin + win;
        this.store.setTotalWin(totalWin);
    }

    /**
     * 把一次下注累加進累計下注。
     *
     * @param bet 這次的下注額。
     */
    trackerTotalBet(bet: number) {
        let totalBet = this.store.totalBet + bet;
        this.store.setTotalBet(totalBet);
    }

    /**
     * 每隔固定時間把遊玩時間計數加一。
     *
     * 計時器刻意不保留參考、也不清除——埋點要涵蓋整個遊戲存續期間，
     * 遊戲結束時整個 runtime 也跟著收掉。
     */
    trackerPlayTimes() {
        setInterval(() => {
            this.store.setPlayTimes(this.store.playTimes + 1);
        }, this.interval);
    }

    /**
     * 送出一則埋點事件給外層網頁的 `trackEvent`。
     *
     * 宿主沒有提供 `trackEvent` 時只印 log 不做事——獨立測試與原生環境都不該因為
     * 少一個埋點函式就出錯。
     *
     * @param eventName 事件名稱。
     * @param params 附帶參數。
     */
    static trackerEvent(eventName: string, params?: Record<string, any>) {
        console.log("[EagleTracker] trackEvent: " + eventName, Logger.fmt(params));
        const trackEvent = (window as typeof window & { trackEvent?: (name: string, data?: Record<string, any>) => void }).trackEvent;
        trackEvent?.(eventName, params);
    }
}
