import { _decorator, Component, Label, Node } from 'cc';
import StoreManager from '../../store/StoreManager';
import { EFFECTSMAP } from '../../audio/SOUNDMAP';
import AppAudio from '../../audio/AppAudio';
import { GAMESTOREMAP, AUTOSPINSTATUSMAP } from '../../store/StoreMap';
const { ccclass, property } = _decorator;

@ccclass('1003/AlertView')
export class AlertView extends Component {
    @property(Label)
    contentLabel: Label = null

    alertInfo: any
    /**
     * 播進場音效並把 ViewStore 裡的內容填進文字。
     *
     * 標題是接在內容後面以 `- (標題)` 的形式顯示，不是獨立一行——
     * 這個彈窗的版面只有一個文字框。
     */
    protected override onLoad(): void {
        AppAudio.getInstance().playEffect(EFFECTSMAP.INTRO_POPUP);
        this.alertInfo = this.getAlertInfo();
        if (this.alertInfo) {
            let message = '';
            if (this.alertInfo.tittle) message = '- (' + this.alertInfo.tittle + ')';
            this.contentLabel.string = this.alertInfo.message + message;
        }
    }
    /**
     * 播彈窗關閉音效。
     */
    protected override onDestroy() {
        AppAudio.getInstance().playEffect(EFFECTSMAP.INTRO_CLOSE);
    }
    /**
     * 從 ViewStore 取出這次要顯示的彈窗內容。
     *
     * @returns 標題、內容與回呼。
     */
    getAlertInfo() {
        const viewStore = StoreManager.getInstance().getViewStore();
        return viewStore.alertInfo;
    }

    /**
     * 關閉彈窗。如果錯誤發生在一局進行中，直接重整頁面。
     *
     * 重整是因為局中出錯時前端狀態機已經對不上後端了，
     * 繼續玩下去會一路錯到底，重整走一次完整的續玩流程最乾淨。
     */
    onExitClick() {

        if (StoreManager.getInstance().getGameStore().spinStatus !== GAMESTOREMAP.NEW_GAME) {
            window.location.reload();
            // StoreManager.getInstance().getGameStore().setSpinStatus(GAMESTOREMAP.NEW_GAME);
            // StoreManager.getInstance().getGameStore().setAutoSpinStatus(AUTOSPINSTATUSMAP.OFF);

        }
        this.node.destroy();
    }
}
