import { GameTask } from './GameTask';
import type { ISlotGameMain } from '../types/ISlotGameMain';
import type { GameViewAdapter } from '../ui/GameViewAdapter';
import AppAudio from '../audio/AppAudio';
import { EFFECTSMAP } from '../audio/AudioConfig';
import { skipWait } from '../controllers/SkipWait';

/**
 * 對應 SGTask_Scatter（觸發免費遊戲時的 scatter 中獎演出，原 GameMain_1003.playScatterWin）。
 *
 * 照音效規格表（fg_trigger）播放時中斷背景音樂。這一步只在主遊戲觸發免費遊戲時才會走到
 * （見 `SpinFlowPlanner.planSpinFlow()`），免費遊戲的背景音樂由 `FGState_1003` 進場時再開。
 *
 * @param game 遊戲主體。
 * @param cols 停輪當下的盤面，用來找出要播中獎演出的 Scatter。
 * @returns 演出時間到了、或快停要求跳過之後 resolve。
 */
export async function playScatterWin(game: ISlotGameMain<GameViewAdapter>, cols: number[][]): Promise<void> {
    const audio = AppAudio.getInstance();
    audio.stopMusic();
    audio.playEffect(EFFECTSMAP.FG_TRIGGER);
    const scatterCells = findScatterCells(game, cols);
    game.forEachView((v) => {
        const reels = v.slotMachineView?.reelViews;
        for (const { col, row } of scatterCells) reels?.[col]?.playScatterWin(row);
    });
    // 快停要求跳過時不等（slotgame docs/快停.md）
    await skipWait(game, 1.2);
}

/**
 * 找出盤面上所有 Scatter 的位置。
 *
 * @param game 遊戲主體，用來判斷符號種類。
 * @param cols 盤面，外層是欄。
 * @returns 依欄、再依列排序的位置。
 */
function findScatterCells(game: ISlotGameMain<GameViewAdapter>, cols: number[][]): { col: number; row: number }[] {
    const cells: { col: number; row: number }[] = [];
    for (let col = 0; col < cols.length; col++) {
        for (let row = 0; row < cols[col].length; row++) {
            if (game.definition.symbols.resolve(cols[col][row]).kind === 'scatter') cells.push({ col, row });
        }
    }
    return cells;
}

export class ScatterWinTask extends GameTask {
    /**
     * 只記下參數，演出要等任務佇列輪到這一筆才開始。
     *
     * @param game 遊戲主體。
     * @param cols 停輪當下的盤面，用來找出要播中獎演出的 Scatter。
     */
    constructor(
        private readonly game: ISlotGameMain<GameViewAdapter>,
        private readonly cols: number[][]
    ) {
        super();
    }

    /** Task 進入點：播 scatter 中獎演出。 */
    protected onStart(): void {
        playScatterWin(this.game, this.cols)
            .catch((error) => console.warn('[ScatterWinTask] failed', error))
            .finally(() => this.finish());
    }
}
