// ============================================================
// net/mocks/index.ts
// 依當下的 GAMEID 選用對應的玩法引擎。
//
// 不快取、不寫成 module-level const：GAMEID 是進遊戲場景才寫入 globalThis 的，
// 提早求值會一律拿到預設值（見 docs/agent-pitfalls.md #30）。
// ============================================================

import GameConfigManager from '../../config/GameConfigManager';
import { mahjongWaysEngine } from './mahjong-ways';
import type { MockRoundEngine } from './types';

const ENGINE_BY_GAME: Readonly<Record<string, MockRoundEngine>> = {
    '1003': mahjongWaysEngine,
};

/**
 * 取得這個 bundle 的玩法引擎。
 *
 * 這份 bundle 只收錄巨亨麻將自己的引擎——荷魯斯／金虎爺的 cascade-multiplier 留在它們各自的
 * bundle 裡，不跨遊戲相依。
 *
 * @returns 對應 GAMEID 的引擎；查不到就回本 bundle 唯一那顆。
 */
export function resolveMockEngine(): MockRoundEngine {
    return ENGINE_BY_GAME[GameConfigManager.GAMEID] ?? mahjongWaysEngine;
}

export type { MockRoundEngine } from './types';
