import { TURBOSTATUSMAP, AUTOSPINSTATUSMAP, GAMESTOREMAP } from './StoreMap';
import { getLocalizedString } from '../i18n/LanguageData';
import AppUtility from '../utils/AppUtility';
import AppStore from './AppStore';
import type UserStore from './UserStore';
import type TemplateStore from '../ui/TemplateView/TemplateModel';
import type ViewStore from './ViewStore';
import type { SlotApiEntry } from '../net/SlotApiTypes';
import type { BetHistoryPage } from '../models/BetHistory';
import type { SlotGridLayout } from '../models/SlotGrid';
import type { SlotRoundResult } from '../models/SlotRound';
import { createSlotGridLayout, getSlotLayoutSource } from '../net/GridLayoutConfig';
import GameConfigManager from '../config/GameConfigManager';
import { GAME_EVENT_ID, GAME_EVENT_TYPE, gameRuntimeEventBus } from '../events/GameRuntimeEventBus';
import { GameStateKey } from '../states/GameStateKey';

/**
 * 一局遊戲的執行期狀態：流程階段、玩家設定（加速／自動轉）、後端回傳的原始資料，
 * 以及各種表演（報獎、Jackpot、轉場）的開關與等待訊號。
 *
 * 【欄位慣例】每筆狀態都是「私有 `_x` ＋ getter ＋ `setX()`」三件組。會影響畫面的
 * setter 在寫完欄位後發一則 `gameRuntimeEventBus` 事件，View 訂閱事件更新自己——
 * 這是 mobx 移除之後的替代做法，所以**繞過 setter 直接改 `_x` 畫面不會動**。
 * 純資料、沒人需要即時反應的欄位（roundId、historyData…）刻意不發事件。
 *
 * 【表演的等待訊號】`playXxx()` 設好資料並回一個 promise，對應的 View 播完後呼叫
 * `completeXxx()` 才讓它 resolve。這類 promise 只有 resolve 沒有 reject，所以
 * View 沒開出來就會永遠卡住，見 agent-pitfalls.md 坑 #35。
 */
export default class GameStore {
    /** registry 用的 model 識別字串，對應原本 mobx-keystone @model('store/GameStore') */
    public readonly $modelType = 'store/GameStore';

    private _roundId: string | null = null;
    /**
     * 目前這一局的 roundId；還沒開局時是 null。
     *
     * @returns 後端給的局號。
     */
    get roundId(): string | null {
        return this._roundId;
    }
    /**
     * 記下這一局的局號。不發事件，只有送 API 時會讀。
     *
     * @param roundId 後端給的局號，清空時傳 null。
     */
    setRoundId(roundId: string | null): void {
        this._roundId = roundId;
    }

    private _gameInitData: Object | null = null;
    /**
     * 開局回傳的原始資料；還沒連上後端時是 null。
     *
     * @returns 未經解析的 init 回應。
     */
    get gameInitData(): Object | null {
        return this._gameInitData;
    }

    private _spinStatus: string = GAMESTOREMAP.NEW_GAME;
    /**
     * Spin 流程目前走到哪一段，值域見 GAMESTOREMAP。
     *
     * @returns 流程狀態字串。
     */
    get spinStatus(): string {
        return this._spinStatus;
    }

    private _turboStatus: string = TURBOSTATUSMAP.NORMAL;
    /**
     * 目前的加速檔位，值域見 TURBOSTATUSMAP。
     *
     * @returns 檔位字串。
     */
    get turboStatus(): string {
        return this._turboStatus;
    }
    /**
     * 切換加速檔位，並發 TURBO_STATUS_CHANGED 通知 TemplateView 換按鈕圖。
     *
     * @param turboStatus TURBOSTATUSMAP 的其中一個值。
     */
    setTurboStatus(turboStatus: string): void {
        this._turboStatus = turboStatus;
        gameRuntimeEventBus.emit(GAME_EVENT_TYPE.TURBO_STATUS_CHANGED, {
            eventId: GAME_EVENT_ID.TURBO_STATUS_CHANGED,
            turboStatus,
        });
    }

    private _autoSpinStatus: string = AUTOSPINSTATUSMAP.OFF;
    /**
     * 自動轉是開還是關，值域見 AUTOSPINSTATUSMAP。
     *
     * @returns 自動轉狀態字串。
     */
    get autoSpinStatus(): string {
        return this._autoSpinStatus;
    }
    /**
     * 切換自動轉開關，並發 AUTO_SPIN_STATUS_CHANGED。
     *
     * @param autoSpinStatus AUTOSPINSTATUSMAP 的其中一個值。
     */
    setAutoSpinStatus(autoSpinStatus: string): void {
        this._autoSpinStatus = autoSpinStatus;
        gameRuntimeEventBus.emit(GAME_EVENT_TYPE.AUTO_SPIN_STATUS_CHANGED, {
            eventId: GAME_EVENT_ID.AUTO_SPIN_STATUS_CHANGED,
            autoSpinStatus,
        });
    }

    private _gameMode: GameStateKey = GameStateKey.NG;
    /**
     * 目前在主遊戲還是免費遊戲。
     *
     * @returns NG 或 FG。
     */
    get gameMode(): GameStateKey {
        return this._gameMode;
    }
    /**
     * 切換主遊戲／免費遊戲，並發 GAME_MODE_CHANGED 讓背景與 UI 一起換。
     *
     * @param gameMode 要切過去的模式。
     */
    setGameMode(gameMode: GameStateKey): void {
        this._gameMode = gameMode;
        gameRuntimeEventBus.emit(GAME_EVENT_TYPE.GAME_MODE_CHANGED, {
            eventId: GAME_EVENT_ID.GAME_MODE_CHANGED,
            gameMode,
        });
    }

    private _spinData: SlotRoundResult | null = null;
    /**
     * 最近一次 spin（主遊戲那一轉）轉好的結果；還沒轉過時是 null。
     *
     * @returns 這一轉的結果。
     */
    get spinData(): SlotRoundResult | null {
        return this._spinData;
    }

    /** 最近一次的進場回應 */
    private _entryData: SlotApiEntry | null = null;
    /**
     * 最近一次 `POST /player/entry` 的回應；還沒進場時是 null。
     *
     * @returns 進場回應。
     */
    get entryData(): SlotApiEntry | null {
        return this._entryData;
    }

    /**
     * 這款遊戲的盤面形狀（可見格）。
     *
     * **每次讀取才求值**，不在欄位初始器決定：GAMEID 是進遊戲場景時才寫進 globalThis 的，
     * 建立這個 store 的時機可能更早（見 agent-pitfalls.md 坑 #30）。順帶也避免
     * 在同一個 session 切換子遊戲後拿到上一款的形狀。
     *
     * @returns 盤面形狀。
     */
    get slotLayout(): SlotGridLayout {
        return createSlotGridLayout(getSlotLayoutSource(GameConfigManager.GAMEID));
    }

    /** 初始盤面（init 時從 last_result 解出，或 HK 的 lastResult） */
    private _lastResult: Object | null = null;
    /**
     * 進場時要還原的上一局盤面；沒有續玩資料時是 null。
     *
     * @returns 上一局的盤面資料。
     */
    get lastResult(): Object | null {
        return this._lastResult;
    }
    /**
     * 記下要還原的盤面。不發事件，由進場流程主動讀。
     *
     * @param lastResult 盤面資料，清掉時傳 null。
     */
    setLastResult(lastResult: Object | null): void {
        this._lastResult = lastResult;
    }

    /** restore phase=2 時設 true，讓 GameContext 進 free-spin 等待模式 */
    private _freeSpinPending: boolean = false;
    /**
     * 是否處於「斷線前還有免費遊戲沒跑完」的待續狀態。
     *
     * @returns true 代表 GameContext 要直接進免費遊戲等待模式。
     */
    get freeSpinPending(): boolean {
        return this._freeSpinPending;
    }
    /**
     * 標記免費遊戲待續。restore phase=2 時設為 true。
     *
     * @param freeSpinPending 是否待續。
     */
    setFreeSpinPending(freeSpinPending: boolean): void {
        this._freeSpinPending = freeSpinPending;
    }

    private _configData: Object | null = null;
    /**
     * 後端下發的遊戲設定檔；還沒載入時是 null。
     *
     * @returns 設定檔原始資料。
     */
    get configData(): Object | null {
        return this._configData;
    }

    private _initExtra: Object | null = null;
    /**
     * 開局回應裡的 extra 區塊；沒有時是 null。
     *
     * @returns extra 原始資料。
     */
    get initExtra(): Object | null {
        return this._initExtra;
    }

    private _autoSpinTimes: any = 0;
    /**
     * 自動轉剩餘局數；'MAX' 代表無限。
     *
     * @returns 剩餘局數，或字串 'MAX'。
     */
    get autoSpinTimes(): any {
        return this._autoSpinTimes;
    }
    /**
     * 更新自動轉剩餘局數，並發 AUTO_SPIN_TIMES_CHANGED 讓面板換數字。
     *
     * @param autoSpinTimes 剩餘局數，無限傳 'MAX'。
     */
    setAutoSpinTimes(autoSpinTimes: any): void {
        this._autoSpinTimes = autoSpinTimes;
        gameRuntimeEventBus.emit(GAME_EVENT_TYPE.AUTO_SPIN_TIMES_CHANGED, {
            eventId: GAME_EVENT_ID.AUTO_SPIN_TIMES_CHANGED,
            autoSpinTimes,
        });
    }

    private _historyData: BetHistoryPage | null = null;
    /**
     * 投注紀錄的當前分頁；還沒查詢時是 null。
     *
     * @returns 紀錄分頁。
     */
    get historyData(): BetHistoryPage | null {
        return this._historyData;
    }
    /**
     * 存下查到的投注紀錄分頁。不發事件，由 HistoryView 自己拉。
     *
     * @param historyData 紀錄分頁，清空時傳 null。
     */
    setHistoryData(historyData: BetHistoryPage | null): void {
        this._historyData = historyData;
    }

    private _historyDetailData: Object | null = null;
    /**
     * 投注紀錄單筆明細；還沒展開時是 null。
     *
     * @returns 明細原始資料。
     */
    get historyDetailData(): Object | null {
        return this._historyDetailData;
    }
    /**
     * 存下單筆明細。不發事件，由 HistoryItem 自己拉。
     *
     * @param historyDetailData 明細資料，清空時傳 null。
     */
    setHistoryDetailData(historyDetailData: Object | null): void {
        this._historyDetailData = historyDetailData;
    }

    private _serviceURL: string | null = null;
    /**
     * 客服網址；後端沒給時是 null。
     *
     * @returns 客服頁面網址。
     */
    get serviceURL(): string | null {
        return this._serviceURL;
    }
    /**
     * 記下客服網址。
     *
     * @param serviceURL 客服頁面網址。
     */
    setServiceURL(serviceURL: string | null): void {
        this._serviceURL = serviceURL;
    }

    private _cashierURL: string | null = null;
    /**
     * 儲值頁網址；後端沒給時是 null。
     *
     * @returns 儲值頁網址。
     */
    get cashierURL(): string | null {
        return this._cashierURL;
    }
    /**
     * 記下儲值頁網址，並發 CASHIER_URL_CHANGED 讓儲值提示彈窗決定要不要顯示按鈕。
     *
     * @param cashierURL 儲值頁網址。
     */
    setCashierURL(cashierURL: string | null): void {
        this._cashierURL = cashierURL;
        gameRuntimeEventBus.emit(GAME_EVENT_TYPE.CASHIER_URL_CHANGED, {
            eventId: GAME_EVENT_ID.CASHIER_URL_CHANGED,
            cashierURL,
        });
    }

    private _lobbyURL: string | null = null;
    /**
     * 返回大廳的網址；獨立測試時是 null。
     *
     * @returns 大廳網址。
     */
    get lobbyURL(): string | null {
        return this._lobbyURL;
    }
    /**
     * 記下大廳網址。
     *
     * @param lobbyURL 大廳網址。
     */
    setLobbyURL(lobbyURL: string | null): void {
        this._lobbyURL = lobbyURL;
    }

    private _isLock: boolean = false;
    /**
     * 畫面是否被鎖住（表演中不讓玩家操作）。
     *
     * @returns true 代表操作鎖定中。
     */
    get isLock(): boolean {
        return this._isLock;
    }
    /**
     * 切換操作鎖，並發 IS_LOCK_CHANGED 讓按鈕一起變灰。
     *
     * @param isLock 是否鎖定。
     */
    setIsLock(isLock: boolean): void {
        this._isLock = isLock;
        gameRuntimeEventBus.emit(GAME_EVENT_TYPE.IS_LOCK_CHANGED, {
            eventId: GAME_EVENT_ID.IS_LOCK_CHANGED,
            isLock,
        });
    }

    private _winAnimationData: { totalWin: number; bet: number } | null = null;
    /**
     * 正在播的報獎資料；沒有在報獎時是 null。
     *
     * @returns 報獎的贏分與下注額。
     */
    get winAnimationData(): { totalWin: number; bet: number } | null {
        return this._winAnimationData;
    }
    /**
     * 設定報獎資料並發 WIN_ANIMATION_DATA_CHANGED；傳 null 等於收掉報獎。
     *
     * @param winAnimationData 贏分與下注額，收掉時傳 null。
     */
    setWinAnimationData(winAnimationData: { totalWin: number; bet: number } | null): void {
        this._winAnimationData = winAnimationData;
        gameRuntimeEventBus.emit(GAME_EVENT_TYPE.WIN_ANIMATION_DATA_CHANGED, {
            eventId: GAME_EVENT_ID.WIN_ANIMATION_DATA_CHANGED,
            data: winAnimationData,
        });
    }

    private _bonusResultData: { totalWin: number } | null = null;
    /**
     * 正在播的 Bonus 結算資料；沒有時是 null。
     *
     * @returns Bonus 總贏分。
     */
    get bonusResultData(): { totalWin: number } | null {
        return this._bonusResultData;
    }
    /**
     * 設定 Bonus 結算資料並發 BONUS_RESULT_DATA_CHANGED；傳 null 等於收掉。
     *
     * @param bonusResultData Bonus 總贏分，收掉時傳 null。
     */
    setBonusResultData(bonusResultData: { totalWin: number } | null): void {
        this._bonusResultData = bonusResultData;
        gameRuntimeEventBus.emit(GAME_EVENT_TYPE.BONUS_RESULT_DATA_CHANGED, {
            eventId: GAME_EVENT_ID.BONUS_RESULT_DATA_CHANGED,
            data: bonusResultData,
        });
    }

    private _jackpotData: { jpType: string; amount: number } | null = null;
    /**
     * 正在播的 Jackpot 中獎資料；沒有時是 null。
     *
     * @returns Jackpot 種類與金額。
     */
    get jackpotData(): { jpType: string; amount: number } | null {
        return this._jackpotData;
    }
    /**
     * 設定 Jackpot 中獎資料並發 JACKPOT_DATA_CHANGED；傳 null 等於收掉。
     *
     * @param jackpotData Jackpot 種類與金額，收掉時傳 null。
     */
    setJackpotData(jackpotData: { jpType: string; amount: number } | null): void {
        this._jackpotData = jackpotData;
        gameRuntimeEventBus.emit(GAME_EVENT_TYPE.JACKPOT_DATA_CHANGED, {
            eventId: GAME_EVENT_ID.JACKPOT_DATA_CHANGED,
            data: jackpotData,
        });
    }

    private _hsTransitionData: { basePrefix: string } | null = null;
    /**
     * 正在播的轉場資料；沒有時是 null。
     *
     * @returns 轉場素材的前綴。
     */
    get hsTransitionData(): { basePrefix: string } | null {
        return this._hsTransitionData;
    }
    /**
     * 設定轉場資料並發 HS_TRANSITION_DATA_CHANGED；傳 null 等於收掉。
     *
     * @param hsTransitionData 轉場素材前綴，收掉時傳 null。
     */
    setHsTransitionData(hsTransitionData: { basePrefix: string } | null): void {
        this._hsTransitionData = hsTransitionData;
        gameRuntimeEventBus.emit(GAME_EVENT_TYPE.HS_TRANSITION_DATA_CHANGED, {
            eventId: GAME_EVENT_ID.HS_TRANSITION_DATA_CHANGED,
            data: hsTransitionData,
        });
    }

    private _winFreeGameData: { freeRoundCount: number } | null = null;
    /**
     * 正在播的「獲得免費遊戲」彈窗資料；沒有時是 null。
     *
     * @returns 這次拿到的免費局數。
     */
    get winFreeGameData(): { freeRoundCount: number } | null {
        return this._winFreeGameData;
    }
    /**
     * 設定免費遊戲彈窗資料並發 WIN_FREE_GAME_DATA_CHANGED；傳 null 等於收掉。
     *
     * @param winFreeGameData 免費局數，收掉時傳 null。
     */
    setWinFreeGameData(winFreeGameData: { freeRoundCount: number } | null): void {
        this._winFreeGameData = winFreeGameData;
        gameRuntimeEventBus.emit(GAME_EVENT_TYPE.WIN_FREE_GAME_DATA_CHANGED, {
            eventId: GAME_EVENT_ID.WIN_FREE_GAME_DATA_CHANGED,
            data: winFreeGameData,
        });
    }

    private _winAnimResolve: (() => void) | null = null;
    private _bonusResultResolve: (() => void) | null = null;
    private _jackpotResolve: (() => void) | null = null;
    private _hsTransitionResolve: (() => void) | null = null;
    private _winFreeGameResolve: (() => void) | null = null;

    /**
     * 保留建構子參數是為了相容 StoreManager 裡 `new GameStore({})` 的舊呼叫方式。
     *
     * @param _props 不使用。
     */
    constructor(_props?: unknown) {}

    /**
     * 取得目前幣別對應的金額格式化函式。
     *
     * GC（currency 為 '2'）用 K／M／B 縮寫，其餘幣別用固定小數位。
     * 每次讀都重算，因為幣別是開局資料回來之後才確定的。
     *
     * @returns 吃 (金額, 小數位) 的格式化函式。
     */
    get formatAmount(): (value: number, dp?: number) => string {
        const isGC = this.gameInitData?.['game']?.currency == '2';
        return isGC ? (v: number, dp: number = 2) => AppUtility.formatCompact(v, dp) : (v: number, dp: number = 2) => AppUtility.formatDecimal(v, dp);
    }

    /**
     * 轉之前檢查餘額夠不夠扣這一注。
     *
     * 不夠時會直接彈儲值提示（1102），呼叫端只要看回傳值決定要不要往下走。
     *
     * @returns 餘額足夠時 true；不足時彈完提示回 false。
     */
    spinCheck() {
        const kystore = AppStore.getCurrent()!;
        if (kystore.getModel<UserStore>('store/UserStore')!.balance - kystore.getModel<TemplateStore>('store/TemplateStore')!.betBalance < 0) {
            kystore.getModel<ViewStore>('store/ViewStore')!.showStoreAlertView('', getLocalizedString('1102'));
            return false;
        }
        return true;
    }

    /**
     * 存下這一轉的結果並發 GAME_SPIN_DATA_CHANGED。同一份物件重複設定會被略過。
     *
     * @param spinData 這一轉轉好的結果。
     */
    setSpinData(spinData: SlotRoundResult): void {
        if (this._spinData === spinData) return;
        this._spinData = spinData;
        gameRuntimeEventBus.emit(GAME_EVENT_TYPE.GAME_SPIN_DATA_CHANGED, {
            eventId: GAME_EVENT_ID.GAME_SPIN_DATA_CHANGED,
            spinData,
        });
    }

    /**
     * 存下進場回應。不發事件——這份資料是開局流程同步讀的。
     *
     * @param entryData 進場回應。
     */
    setEntryData(entryData: SlotApiEntry): void {
        this._entryData = entryData;
    }

    /**
     * 存下開局回應的 extra 區塊並發 GAME_INIT_EXTRA_CHANGED。
     *
     * @param initExtra extra 原始資料。
     */
    setInitExtra(initExtra: Object): void {
        if (this._initExtra === initExtra) return;
        this._initExtra = initExtra;
        gameRuntimeEventBus.emit(GAME_EVENT_TYPE.GAME_INIT_EXTRA_CHANGED, {
            eventId: GAME_EVENT_ID.GAME_INIT_EXTRA_CHANGED,
            initExtra,
        });
    }

    /**
     * 存下遊戲設定檔並發 GAME_CONFIG_DATA_CHANGED。
     *
     * @param configData 設定檔原始資料。
     */
    setConfigData(configData: Object): void {
        if (this._configData === configData) return;
        this._configData = configData;
        gameRuntimeEventBus.emit(GAME_EVENT_TYPE.GAME_CONFIG_DATA_CHANGED, {
            eventId: GAME_EVENT_ID.GAME_CONFIG_DATA_CHANGED,
            configData,
        });
    }

    /**
     * 存下開局資料並發 GAME_INIT_DATA_CHANGED。幣別等顯示設定都從這裡推導。
     *
     * @param gameInitData 開局回應原始資料。
     */
    setGameInitData(gameInitData: Object): void {
        if (this._gameInitData === gameInitData) return;
        this._gameInitData = gameInitData;
        gameRuntimeEventBus.emit(GAME_EVENT_TYPE.GAME_INIT_DATA_CHANGED, {
            eventId: GAME_EVENT_ID.GAME_INIT_DATA_CHANGED,
            gameInitData,
        });
    }

    /**
     * 推進 Spin 流程狀態，並把「前一個狀態」一起發出去。
     *
     * 事件帶 previousStatus 是因為有些轉場只在特定的前後組合才成立
     * （例如只有從 SPINNING 進 END 才播停輪音），只看新狀態分不出來。
     *
     * @param status GAMESTOREMAP 的其中一個值；跟目前相同時直接略過不發事件。
     */
    setSpinStatus(status: string): void {
        const previousStatus = this._spinStatus;
        if (previousStatus === status) return;

        this._spinStatus = status;

        gameRuntimeEventBus.emit(GAME_EVENT_TYPE.SPIN_STATUS_CHANGED, {
            eventId: GAME_EVENT_ID.SPIN_STATUS_CHANGED,
            previousStatus,
            status,
        });
    }

    /**
     * 播報獎，等 View 那邊呼叫 completeWinAnimation() 才結束。
     *
     * @param totalWin 這一局的總贏分。
     * @param bet 下注額，報獎等級靠它換算倍數。
     * @returns 報獎被收掉之後 resolve。
     */
    playWinAnimation(totalWin: number, bet: number): Promise<void> {
        this.setWinAnimationData({ totalWin, bet });
        return new Promise<void>((resolve) => {
            this._winAnimResolve = resolve;
        });
    }

    /**
     * 由報獎 View 回呼，收掉資料並讓 playWinAnimation() 的 promise resolve。
     */
    completeWinAnimation(): void {
        this.setWinAnimationData(null);
        const r = this._winAnimResolve;
        this._winAnimResolve = null;
        r?.();
    }

    /**
     * 播 Bonus 結算，等 completeBonusResult() 才結束。
     *
     * @param totalWin Bonus 的總贏分。
     * @returns 結算被收掉之後 resolve。
     */
    playBonusResult(totalWin: number): Promise<void> {
        this.setBonusResultData({ totalWin });
        return new Promise<void>((resolve) => {
            this._bonusResultResolve = resolve;
        });
    }

    /**
     * 由 Bonus 結算 View 回呼，收掉資料並讓 playBonusResult() resolve。
     */
    completeBonusResult(): void {
        this.setBonusResultData(null);
        const r = this._bonusResultResolve;
        this._bonusResultResolve = null;
        r?.();
    }

    /**
     * 播 Jackpot 中獎表演，等 completeJackpot() 才結束。
     *
     * @param jpType Jackpot 種類（Grand／Major…）。
     * @param amount 中獎金額。
     * @returns 表演被收掉之後 resolve。
     */
    playJackpot(jpType: string, amount: number): Promise<void> {
        this.setJackpotData({ jpType, amount });
        return new Promise<void>((resolve) => {
            this._jackpotResolve = resolve;
        });
    }

    /**
     * 由 Jackpot View 回呼，收掉資料並讓 playJackpot() resolve。
     */
    completeJackpot(): void {
        this.setJackpotData(null);
        const r = this._jackpotResolve;
        this._jackpotResolve = null;
        r?.();
    }

    /**
     * 播主遊戲與免費遊戲之間的轉場，等 completeHsTransition() 才結束。
     *
     * @param basePrefix 轉場素材的檔名前綴。
     * @returns 轉場播完之後 resolve。
     */
    playHsTransition(basePrefix: string): Promise<void> {
        this.setHsTransitionData({ basePrefix });
        return new Promise<void>((resolve) => {
            this._hsTransitionResolve = resolve;
        });
    }

    /**
     * 由轉場 View 回呼，收掉資料並讓 playHsTransition() resolve。
     */
    completeHsTransition(): void {
        this.setHsTransitionData(null);
        const r = this._hsTransitionResolve;
        this._hsTransitionResolve = null;
        r?.();
    }
    /**
     * 播「恭喜獲得 X 局免費遊戲」彈窗，等玩家點擊或倒數逾時關閉後才 resolve。
     *
     * 注意這個 promise 是靠彈窗回呼 completeWinFreeGame() 才 settle：彈窗本身
     * 載入失敗的話它永遠不會 settle，整條任務佇列會吊死（見 agent-pitfalls.md 坑 #35）。
     *
     * @param freeRoundCount 這次拿到的免費局數。
     * @returns 彈窗關閉之後 resolve。
     */
    playWinFreeGame(freeRoundCount: number): Promise<void> {
        this.setWinFreeGameData({ freeRoundCount });
        return new Promise<void>((resolve) => {
            this._winFreeGameResolve = resolve;
        });
    }

    /**
     * 由免費遊戲彈窗回呼，收掉資料並讓 playWinFreeGame() resolve。
     */
    completeWinFreeGame(): void {
        this.setWinFreeGameData(null);
        const r = this._winFreeGameResolve;
        this._winFreeGameResolve = null;
        r?.();
    }
}
