import { _decorator, Node, Size, tween, Tween, type TweenEasing, UIOpacity, UITransform, Vec3 } from 'cc';
import { ReelView } from './ReelView';
import type { SlotMachineView } from './SlotMachineView';
import { ReelState } from '../model/ReelModel';
import { SymbolCell } from '../symbol/SymbolCell';
import { SymbolImageManager } from '../symbol/SymbolImageManager';
import { SymbolState, SymbolStateLevel } from '../symbol/SymbolState';
import type { SymbolOverlayLayer } from './SymbolOverlayLayer';
import { goldenSymbolIdOf, SLOT_GAME_DEFINITION, SYMBOL_IDS } from '../../config/SlotGameDefinition';

const { ccclass, property } = _decorator;

/**
 * 補牌落下前的全盤抖動，照參考影片（2026-10-19 的錄影）逐格量出來：盤面上每顆牌各自往隨機方向
 * 小幅位移，換 4 次位置、每次約 0.04 秒，最後回到格位。背景不動，牌也不縮放、不旋轉。
 * 幅度以格距的比例表示，水平量到最多約 1.2%、垂直約 0.85%。
 */
const PRE_DROP_SHAKE = {
    /** 換幾次位置 */
    steps: 4,
    /** 每個位置停多久（秒） */
    stepTime: 0.04,
    /** 水平最大位移，佔格距的比例 */
    xRatio: 0.012,
    /** 垂直最大位移，佔格距的比例 */
    yRatio: 0.0085,
};

@ccclass('1003/ReelView_1003')
export class ReelView_1003 extends ReelView {
    /** posList 可視格上下各留幾格緩衝，讓符號有畫面外的進出空間；可見列 row 對應的 posList 索引是 row + BUFFER_SLOTS */
    static readonly BUFFER_SLOTS = 2;

    // 不規則輪帶（葫蘆型盤面）各欄可視列數可能不同：用可視列數、符號尺寸與 centerY 動態產生 posList，
    // 不用再手動擺放/刪除位置標記節點；base class 繼承來的 posList 欄位仍會顯示在 Inspector，
    // 但內容一律由這裡的 onLoad() 覆蓋產生，手動填的值不會被使用。
    @property({ tooltip: '這一欄可視列數，也就是吃後端資料的列數（葫蘆型盤面：中間 3 欄填 5、兩側 2 欄填 4）' })
    private configuredVisibleRowCount: number = 5;

    @property({ tooltip: '可視區垂直置中的 Y 座標，5 欄應共用同一個值，讓不同列數的欄自動上下對齊置中' })
    private centerY: number = 0;

    /** 一格的寬×高，onLoad 時從所屬機台的 {@link SlotMachineView.symbolSize} 讀進來 */
    private readonly cellSize = new Size();

    /** 列與列之間的間距，onLoad 時從所屬機台的 {@link SlotMachineView.symbolSpacing} 的 y 讀進來 */
    private rowSpacing: number = 0;

    /**
     * 讀機台的符號尺寸與間距，套到這一欄的尺寸上，再依可視列數 / 列距 / centerY 動態產生 posList。
     *
     * 葫蘆型盤面各欄可視列數不同（中間 3 欄 5 列、兩側 2 欄 4 列），手動擺位置標記節點
     * 太容易漏，所以這裡一律覆蓋掉 Inspector 上繼承來的 posList。
     * 上下各多留 {@link ReelView_1003.BUFFER_SLOTS} 格緩衝，讓符號有畫面外的進出空間。兩側欄只有 4 列，
     * 緊貼資料列的那兩格緩衝會落在盤面四個角的框內、看得到，顯示的就是輪帶本來的內容（見
     * {@link reviveEdgeBufferCells}）。2026-10-14 前那兩格是另外設的「裝飾格」，已拿掉。
     *
     * 列距是符號高加上列間距；緩衝格也照同一個列距排，轉動時每一格的位移才一致。
     */
    protected override onLoad(): void {
        const machine = this.resolveMachine();
        if (!machine) {
            console.error(`[ReelView_1003] ${this.node.name} 往上找不到 SlotMachineView，讀不到 symbolSize，所有格位會疊在同一個 Y`);
        }
        this.cellSize.set(machine?.symbolSize ?? Size.ZERO);
        this.rowSpacing = machine?.symbolSpacing.y ?? 0;
        this.applyColumnSize();

        const pitch = this.cellSize.height + this.rowSpacing;
        const totalSlots = this.configuredVisibleRowCount + ReelView_1003.BUFFER_SLOTS * 2; // 上緩衝 + N 格可視 + 下緩衝
        const posList: Node[] = [];
        for (let i = 0; i < totalSlots; i++) {
            const marker = new Node(`pos_${i}`);
            const y = this.centerY + ((totalSlots - 1) / 2 - i) * pitch;
            marker.setPosition(0, y, 0);
            this.node.addChild(marker);
            posList.push(marker);
        }
        this.posList = posList;

        // init() 收到後端輪帶時就要用名稱換 frameIdx，所以對照表在這裡建，不等 initSymbols()
        this.buildFrameTables();
    }

    /**
     * 往上找所屬機台。
     *
     * 用 ccclass 名稱字串查，不直接 import `SlotMachineView`：那支本來就 import 這支（`reelViews` 的型別），
     * 互相 import 會形成循環，Cocos 載入時 `@property([ReelView_1003])` 有機會拿到 undefined。
     *
     * @returns 所屬機台；往上找不到時為 null。
     */
    private resolveMachine(): SlotMachineView | null {
        for (let node = this.node.parent; node; node = node.parent) {
            const machine = node.getComponent('1003/SlotMachineView') as SlotMachineView | null;
            if (machine) return machine;
        }
        return null;
    }

    /**
     * 欄節點與 Container 的尺寸跟著符號尺寸走：寬＝符號寬，高＝這一欄的可視列數 × 符號高，
     * 再加上列與列之間的間距（最上、最下不加）。
     *
     * 機台排欄（`SlotMachineView.layoutReelColumns`）讀的是欄節點的寬，欄與欄之間的間距由機台自己加。
     * 高度目前只影響 Editor 裡的框與特殊符號容器的尺寸——盤面裁切靠的是機台 `Layer_Reels` 上的 Mask。
     */
    private applyColumnSize(): void {
        const rows = this.configuredVisibleRowCount;
        const width = this.cellSize.width;
        const height = rows * this.cellSize.height + Math.max(0, rows - 1) * this.rowSpacing;
        this.node.getComponent(UITransform)?.setContentSize(width, height);
        this.container?.getComponent(UITransform)?.setContentSize(width, height);
    }

    @property({
        type: SymbolImageManager,
        tooltip: '符號顯示物件的物件池。留空時自動往上找最近的一顆（通常掛在 SlotMachineView 上）'
    })
    public symbolManager: SymbolImageManager = null!;

    /**
     * frameIdx → 符號 id 的對照。
     *
     * 外部（CascadeReelsTask、base ReelView 的輪帶邏輯）仍然以 frameIdx 溝通，但 {@link SymbolCell}
     * 認的是符號 id。這張表在 {@link buildFrameTables} 一次建好，避免每次換符號都做字串比對。
     *
     * 金牌 id（101–109）**也在這張表裡**：它有自己的圖名（底牌圖名加 `_g`，例如 `H1_g`）與自己的
     * prefab，跟其他符號沒有兩樣。這是金牌能在掉落途中就是金的關鍵——詳見 {@link buildFrameTables}。
     */
    private frameIdxToSymbolId: number[] = [];

    /** {@link convertToGolden} 換掉之前的輪帶；下一次 {@link startSpin} 一開始還原，沒換過時為 null */
    private stripBeforeGolden: number[] | null = null;

    /**
     * 特殊符號層裡屬於這一欄的兩個容器，由 {@link SlotMachineView} 在 init 時配發。
     *
     * 盤面只有機台 `Layer_Reels` 上一個 Mask，各欄之間是依序整欄疊上去的——右欄的一般符號會蓋住左欄
     * 的 Scatter。所以 Scatter／Wild 的格子會整顆搬進這兩個容器：它們排在所有欄之後（全部 Wild
     * 容器在前、全部 Scatter 容器在後），做出 Scatter > Wild > 一般符號的疊放順序，而且仍在
     * `Layer_Reels` 底下，被同一個 Mask 裁切。
     *
     * 搬的是**格子節點本身**而不是租來的符號圖：容器跟本欄的 Container 世界座標一致，格子的本地
     * 座標不用換算，轉動、落下、金牌翻面、透明度這些套在格子上的 tween 全部照舊。
     *
     * 沒配發（例如單獨測試一欄）時一律留在 Container，行為跟改版前一樣。
     */
    private specialContainers: { wild: Node; scatter: Node } | null = null;

    /** 上次對齊特殊容器時 Container 的世界座標，用來判斷要不要重新對齊 */
    private readonly lastContainerWorldPos = new Vec3(Number.NaN, Number.NaN, Number.NaN);

    /**
     * 機台的覆蓋層（`Layer_Win`），由 {@link SlotMachineView} 在 init 時配發，見 {@link attachOverlayView}。
     * 沒配發時（例如單獨測試一欄）顯示物件一律留在格子底下。
     */
    private overlayLayer: SymbolOverlayLayer | null = null;

    /** 這一欄是機台的第幾欄（0 起算），覆蓋層的疊放鍵要用它重建「右欄蓋左欄」 */
    private columnIndex: number = 0;

    /**
     * 拿到後端輪帶設定前的預設輪帶，值是 frameIdx（0–8 為 H1–H4、L1–L5，9 scatter，
     * 10 wild，11–19 為對應的金牌版，見 {@link buildFrameTables}）。
     * 原本的 9–16 指向 1001 的倍率球圖，2026-09-14 隨素材刪除改成只含一般符號。
     */
    public override strip: number[] = [2, 2, 2, 5, 6, 7, 8, 0, 1, 3, 4, 5, 6, 7];

    /**
     * 這一轉的下注額。1003 已經沒有程式讀它（原本給 coin 符號算假金額，2026-09-14 隨 Jackpot 移除），
     * 保留只因為共用的 SlotGameMain 會對每個 reelView 寫入這個欄位。
     */
    public spinBet: number = 0;

    /**
     * 接上特殊符號層的兩個容器，並立刻對齊到本欄 Container 的世界座標。
     *
     * 要在 {@link init} 之前呼叫——建格子時就會依符號種類把格子放進對應容器。
     *
     * @param wild 放 Wild 格子的容器。
     * @param scatter 放 Scatter 格子的容器。
     */
    public attachSpecialContainers(wild: Node, scatter: Node): void {
        this.specialContainers = { wild, scatter };
        const size = this.container.getComponent(UITransform)?.contentSize;
        for (const node of [wild, scatter]) {
            if (size) (node.getComponent(UITransform) ?? node.addComponent(UITransform)).setContentSize(size);
        }
        this.lastContainerWorldPos.set(Number.NaN, Number.NaN, Number.NaN);
        this.syncSpecialContainers();
    }

    /**
     * 讓特殊容器的世界座標、旋轉、縮放跟 Container 一致，Container 沒動就什麼都不做。
     *
     * 目前沒有任何程式會在執行期移動欄節點或 Container，對齊一次就夠；每幀檢查是保險——
     * 哪天有人替整欄加了彈跳或位移，特殊符號才不會默默偏離自己的格位。
     */
    private syncSpecialContainers(): void {
        const sc = this.specialContainers;
        if (!sc) return;

        const pos = this.container.worldPosition;
        if (Vec3.equals(pos, this.lastContainerWorldPos)) return;
        this.lastContainerWorldPos.set(pos);

        for (const node of [sc.wild, sc.scatter]) {
            node.setWorldPosition(pos);
            node.setWorldRotation(this.container.worldRotation);
            node.setWorldScale(this.container.worldScale);
        }
    }

    /** 每幀檢查特殊容器要不要重新對齊；放在 lateUpdate，讀到的是這一幀所有 update 跑完之後 Container 的位置。 */
    protected override lateUpdate(): void {
        this.syncSpecialContainers();
    }

    /**
     * 符號的疊放順位，數字大的蓋在上面：Scatter 2、Wild 1、其他 0（金牌的 kind 是 normal，算其他）。
     *
     * @param symbolId 符號 id；-1（還沒設定）視為一般符號。
     * @returns 疊放順位。
     */
    private static drawRankOf(symbolId: number): number {
        if (symbolId < 0) return 0;
        const kind = SLOT_GAME_DEFINITION.symbols.resolve(symbolId).kind;
        if (kind === 'scatter') return 2;
        if (kind === 'wild') return 1;
        return 0;
    }

    /**
     * 依格子目前的符號，把格子節點放進 Container、Wild 容器或 Scatter 容器。
     *
     * 本地座標保持不變（容器之間世界座標一致），換了父節點之後重排一次疊放順序。
     *
     * @param symbolIdx 這一欄裡的符號索引。
     */
    private placeCell(symbolIdx: number): void {
        const node = this.symbolNodes[symbolIdx];
        const cell = this.symbolCells[symbolIdx];
        if (!node || !cell) return;

        const sc = this.specialContainers;
        const rank = ReelView_1003.drawRankOf(cell.getSymbolId());
        const target = !sc ? this.container : rank === 2 ? sc.scatter : rank === 1 ? sc.wild : this.container;
        if (node.parent === target) return;

        node.setParent(target);
        this.updateDrawOrder();
    }

    /**
     * 每個容器各自依格位排序：越下面的格子疊在越上層。
     *
     * 基底只處理 Container 一個父節點；格子分散到三個容器之後，要對各自的父節點排，
     * 否則搬進特殊容器的格子會拿 Container 的子節點數去設 sibling index。
     */
    protected override updateDrawOrder(): void {
        const order = this.symbolNodes.map((_, i) => i).sort((a, b) => this.posIndexes[a] - this.posIndexes[b]);
        for (const i of order) {
            const node = this.symbolNodes[i];
            node.setSiblingIndex((node.parent?.children.length ?? 1) - 1);
        }
    }

    /** 覆蓋層疊放鍵的權重：符號種類 > 欄 > 格位。一欄的格位不到 100、欄不到 100，各占兩位數不會互相進位 */
    private static readonly OVERLAY_KEY_RANK = 10000;
    private static readonly OVERLAY_KEY_COLUMN = 100;

    /** {@link SymbolCell.keepCurrentViewFor} 留下來的物件用的種類順位，高於所有符號（Scatter 是 2） */
    private static readonly LINGERING_RANK = 3;

    /**
     * 接上機台的覆蓋層，並記下這一欄是第幾欄。要在 {@link init} 之前呼叫。
     *
     * @param layer 覆蓋層（`Layer_Win`），放狀態來自中獎層與聽牌層的物件；沒有時傳 null。
     * @param columnIndex 這一欄在機台裡的索引（0 起算）。
     */
    public attachOverlayLayer(layer: SymbolOverlayLayer | null, columnIndex: number): void {
        this.overlayLayer = layer;
        this.columnIndex = columnIndex;
    }

    /**
     * `ISymbolCellHost` 的實作：中獎層的狀態與聽牌層的狀態（聽牌中已落定的 Scatter）都放 `Layer_Win`，
     * 其他層不收。同一顆 Scatter 從聽牌轉成中獎時物件留在同一層，不換層。
     *
     * 放進覆蓋層的物件不受 `Layer_Reels` 的 Mask 裁切、畫在壓黑、聚焦的那一軸與外框之上（層級見 `SlotMachineView`），
     * 也不再被右邊那欄蓋住。疊放順序照盤面重建，見 {@link overlayDrawKey}。
     *
     * @param level 這顆物件的狀態是哪一層設的。
     * @param cell 這顆物件所屬的格子節點。
     * @param view 要放進去的顯示物件節點。
     * @param lingering 是不是 `keepCurrentViewFor()` 留下來的那顆。
     * @returns 有放進覆蓋層為 true；這一層沒有對應的覆蓋層時為 false。
     */
    public attachOverlayView(level: SymbolStateLevel, cell: Node, view: Node, lingering: boolean): boolean {
        const layer = this.overlayLayerOf(level);
        if (!layer) return false;
        this.detachOverlayView(view);
        layer.add(view, this.overlayDrawKey(cell, lingering));
        return true;
    }

    /**
     * `ISymbolCellHost` 的實作：讓覆蓋層不再管這顆物件。
     *
     * @param view 物件節點。
     */
    public detachOverlayView(view: Node): void {
        this.overlayLayer?.remove(view);
    }

    /**
     * 狀態來源層對應的覆蓋層：中獎層與聽牌層的物件放覆蓋層，其他層留在格子底下。
     *
     * @param level 狀態來源層。
     * @returns 覆蓋層；這一層的物件留在格子底下、或沒配發覆蓋層時為 null。
     */
    private overlayLayerOf(level: SymbolStateLevel): SymbolOverlayLayer | null {
        if (level === SymbolStateLevel.Win || level === SymbolStateLevel.Tenpai) return this.overlayLayer;
        return null;
    }

    /**
     * 覆蓋層的疊放鍵，重建盤面上的順序：符號種類（Scatter > Wild > 一般牌，對應特殊符號層）優先，
     * 再來是欄（右欄蓋左欄，對應各欄依序疊上去），最後是格位（下排蓋上排，對應 {@link updateDrawOrder}）。
     *
     * @param cell 格子節點。
     * @param lingering 是不是 `keepCurrentViewFor()` 留下來的那顆；是的話種類順位用 {@link LINGERING_RANK}。
     * @returns 疊放鍵，越大畫越上面。
     */
    private overlayDrawKey(cell: Node, lingering: boolean): number {
        const idx = this.symbolNodes.indexOf(cell);
        const rank = lingering ? ReelView_1003.LINGERING_RANK : ReelView_1003.drawRankOf(this.symbolCells[idx]?.getSymbolId() ?? -1);
        const pos = idx >= 0 ? this.posIndexes[idx] : 0;
        return rank * ReelView_1003.OVERLAY_KEY_RANK + this.columnIndex * ReelView_1003.OVERLAY_KEY_COLUMN + pos;
    }

    /**
     * 建立這一欄的格子。
     *
     * 基底原本是 `instantiate(symbolPrefab)`，整顆格子連同全部美術一起複製；改版後格子本身是**沒有
     * 任何美術的空殼**（只有 UITransform／UIOpacity／{@link SymbolCell}），要顯示什麼由 cell 向
     * {@link symbolManager} 租。所以連 prefab 都不需要，直接 `new Node()` 建出來最乾淨，也少一份要
     * 維護的資產。
     *
     * 節點數量等於 posList 長度而不是可視列數：頭尾各留緩衝格，轉動時是搬位置而不是生成銷毀。
     */
    protected override initSymbols(): void {
        this.symbolManager ??= this.findManagerInParents();
        this.symbolManager?.init();

        for (let i = 0; i < this.posList.length; i++) {
            const node = new Node(`cell_${i}`);
            node.layer = this.node.layer; // 坑 #3：程式建出來的節點 layer 不會自動修正，Camera 遮罩會整個擋掉
            const ui = node.addComponent(UITransform);
            ui.setContentSize(this.cellSize.width, this.cellSize.height);
            ui.setAnchorPoint(0.5, 0.5);

            node.setPosition(this.posList[i].position);
            this.container.addChild(node);

            const cell = node.addComponent(SymbolCell);
            cell.setup(this.symbolManager, this);

            this.symbolNodes.push(node);
            this.symbolCells.push(cell);
            this.symbolOpacities.push(node.addComponent(UIOpacity));
            this.posIndexes.push(i);

            const stripIdx = (this.model.currentRng + i) % this.strip.length;
            this.setSymbolDisplay(i, this.strip[stripIdx]);
        }
        this.updateDrawOrder();
    }

    /**
     * 往上找最近的一顆 {@link SymbolImageManager}。
     *
     * Inspector 上那個欄位目前是有填的（SlotMachineView_1003.prefab 的五欄各有一筆
     * propertyOverride 指向根節點上的池子），這一支是保險：巢狀 prefab instance 的
     * propertyOverride 在重新套用 prefab、或把某一欄搬進搬出時很容易掉，掉了的症狀是整欄默默沒有
     * 任何符號。往上找一次就補回來，Inspector 的欄位留給「這一欄要用別顆池子」這種例外情況覆寫。
     *
     * Cocos 3.8 沒有 `getComponentInParent`，所以自己走一遍父鏈。
     *
     * @returns 找到的池子；整條父鏈都沒有時為 null。
     */
    private findManagerInParents(): SymbolImageManager {
        for (let node = this.node.parent; node; node = node.parent) {
            const manager = node.getComponent(SymbolImageManager);
            if (manager) return manager;
        }
        console.warn(`[ReelView_1003] ${this.node.name} 找不到 SymbolImageManager，這一欄不會有任何符號`);
        return null!;
    }

    /**
     * 依符號定義排出 frameIdx 對照表：{@link frameIdxToSymbolId}（frameIdx → 符號 id）與基底的
     * `frameNames`（frameIdx → 圖名）。
     *
     * 順序固定是一般 1–9、scatter、wild、金牌 101–109，跟改版前 `spriteFrames` 上那 20 張圖的順序
     * 一樣，預設輪帶 {@link strip} 與任何寫死的 frameIdx 意義都不變。原本是走訪這些 id、回頭到
     * `spriteFrames` 裡找同名的圖；靜態圖刪掉之後圖名全變空字串，每一格都對不到符號，盤面整個是空的。
     *
     * **金牌一定要納入。** 它有自己的圖名（`H1_g` 這種底牌圖名加 `_g`）也有自己的 prefab，納入之後金牌 id
     * 就能跟著 strip 流動，掉落途中租到的直接是 `Symbol_XX_Golden`；不納入的話只能等落地再補旗標，
     * 玩家會看到牌落下時是一般牌、落定才變金。
     */
    private buildFrameTables(): void {
        const ids: number[] = [];
        for (let id = SYMBOL_IDS.normalMin; id <= SYMBOL_IDS.normalMax; id++) ids.push(id);
        ids.push(SYMBOL_IDS.scatter, SYMBOL_IDS.wild);
        for (let id = SYMBOL_IDS.normalMin; id <= SYMBOL_IDS.normalMax; id++) ids.push(goldenSymbolIdOf(id));

        this.frameIdxToSymbolId = ids;
        this.frameNames = ids.map((id) => SLOT_GAME_DEFINITION.symbols.frameName(id));
    }

    /**
     * 取某個格子的 {@link SymbolCell}。
     *
     * @param symbolIdx 這一欄裡的符號索引。
     * @returns 對應的 cell；索引越界時為 null。
     */
    private cellAt(symbolIdx: number): SymbolCell | null {
        return this.symbolCells[symbolIdx] ?? null;
    }

    /**
     * 取目前停在某個可見列上的 {@link SymbolCell}。
     *
     * @param row 可見列（0 起算，由上往下）。
     * @returns 對應的 cell；那一列沒有格子時為 null。
     */
    private cellAtRow(row: number): SymbolCell | null {
        const idx = this.symbolIdxAtRow(row);
        return idx < 0 ? null : this.cellAt(idx);
    }

    /**
     * 找出目前停在某個可見列上的符號節點。
     *
     * @param row 可見列（0 起算，由上往下）。
     * @returns 符號節點在這一欄的索引；找不到時為 -1。
     */
    private symbolIdxAtRow(row: number): number {
        return this.findSymbolNodeAtPosIndex(row + this.rowToPosOffset);
    }

    /**
     * 這一欄有幾個資料列（後端給牌的列數，不含上下的裝飾格），給外部演出逐列處理用。
     *
     * @returns 資料列數。
     */
    public getDataRowCount(): number {
        return this.dataRowCount;
    }

    /**
     * 某個資料列格位的世界座標，跟目前轉到哪一格無關。
     *
     * 外部演出要對準「那一列的位置」而不是某一顆格子時用：FG 第三軸的金牌飛入時第三軸正在轉，
     * 格子一直在動，要對的是格位本身。換算用格子所在的容器，跟格子停好時的位置一致。
     *
     * @param row 資料列（0 起算，由上往下）。
     * @param out 寫入結果的向量。
     * @returns 同一個 `out`；那一列沒有格位時不改動。
     */
    public rowSlotWorldPosition(row: number, out: Vec3): Vec3 {
        const slot = this.posList[row + this.rowToPosOffset];
        if (slot && this.container?.isValid) Vec3.transformMat4(out, slot.position, this.container.worldMatrix);
        return out;
    }

    /**
     * 目前的輪轉速度，外部演出要跟著轉輪節奏移動時用。
     *
     * @returns 每秒轉幾格。
     */
    public getCellsPerSecond(): number {
        return this.loopTime > 0 ? 1 / this.loopTime : 0;
    }

    /**
     * 目前停在某個資料列上的符號 id。
     *
     * @param row 資料列（0 起算，由上往下）。
     * @returns 符號 id；那一列沒有格子時為 -1。
     */
    public symbolIdAtRow(row: number): number {
        return this.cellAtRow(row)?.getSymbolId() ?? -1;
    }

    /**
     * 把這一欄換成只轉得出金牌：輪帶上的一般符號（白牌）全部換成對應的金牌，Wild／Scatter 不動；
     * 目前所有格子（含上下緩衝格）也當幀換掉。
     *
     * 給 mock 的 FG 第三軸用：mock 引擎在 FG 第三軸只出金牌，金牌飛入演完之後輪帶也只出金牌，畫面才跟結果
     * 對得上（見 `MiGoldIntro.playMiGoldIntro()` 的 `goldenStrip`）。換之前的輪帶記下來，下一次 {@link startSpin}
     * 一開始還原，FG 結束回到主遊戲時這一欄又會出白牌；重複呼叫不會蓋掉備份。
     */
    public convertToGolden(): void {
        const toGolden = (frameIdx: number): number => {
            const id = this.frameIdxToSymbolId[frameIdx] ?? -1;
            if (id < SYMBOL_IDS.normalMin || id > SYMBOL_IDS.normalMax) return frameIdx;
            const golden = this.frameIdxToSymbolId.indexOf(goldenSymbolIdOf(id));
            return golden >= 0 ? golden : frameIdx;
        };

        this.stripBeforeGolden ??= [...this.strip];
        for (let i = 0; i < this.strip.length; i++) this.strip[i] = toGolden(this.strip[i]);

        this.symbolCells.forEach((cell, i) => {
            const frame = this.frameIdxToSymbolId.indexOf(cell?.getSymbolId() ?? -1);
            if (frame < 0) return;
            const golden = toGolden(frame);
            if (golden === frame) return;
            this.setSymbolDisplay(i, golden);
            cell.flush();
        });
    }

    /**
     * 把緊貼資料列上下的兩格緩衝補回來：連鎖補牌之後如果是看不見的空格，照輪帶補上符號。
     *
     * 兩側欄只有 4 列，這兩格緩衝落在盤面四個角的框內、看得到。base 的補牌會把上方的緩衝一路往下
     * 補進資料列：同一欄消掉 2 格以上時，緊貼資料列的那格上緣緩衝也被拿去補，空出來的位置留著一顆
     * 消除時藏起來（opacity 0）的格子，角落就整個空掉。補的內容跟 base 補緩衝格的算法一樣——
     * 補牌後的輪帶位置加上格位——也就是「這一欄繼續轉會出現什麼」。
     *
     * 下緣那格在所有資料列之下，補牌不會動到它，通常不需要補；一樣檢查只是保險。中間三欄的緩衝在
     * `Layer_Reels` 的 Mask 外面，補了也看不到，不影響。
     */
    private reviveEdgeBufferCells(): void {
        const len = this.strip.length;
        if (len === 0) return;

        for (const posIdx of [this.rowToPosOffset - 1, this.rowToPosOffset + this.dataRowCount]) {
            const symIdx = this.findSymbolNodeAtPosIndex(posIdx);
            if (symIdx < 0 || this.symbolOpacities[symIdx].opacity > 0) continue;

            const node = this.symbolNodes[symIdx];
            node.setScale(1, 1, 1);
            node.setPosition(0, this.posList[posIdx].position.y, 0);
            this.symbolOpacities[symIdx].opacity = 255;
            const stripIdx = (((this.model.currentRng + posIdx) % len) + len) % len;
            this.setSymbolDisplay(symIdx, this.strip[stripIdx]);
        }
    }

    /**
     * 連鎖補牌：交給 base 跑完，再把四個角的緩衝格補回來（見 {@link reviveEdgeBufferCells}）。
     *
     * @param toMapCol 補牌後這一欄由上而下的 frameIdx。
     * @param elimRows 這一輪被消除的可視列。
     * @param fillTime 掉落時長（秒）。
     * @param dropRowDelay 逐列延遲（秒）。
     * @param onBottomLanded 該欄最下面那顆移動的符號到達 targetY 時呼叫（停輪音）。
     * @param fillEase 補間曲線。
     * @param cornerFrame 補完之後上緣角落要顯示的牌：這一欄下一次消除時，角落那顆會落成的 frameIdx
     *                    （見 {@link setTopCornerFrame}）；之後不再消除時不給，照輪帶顯示。
     * @returns 補牌演出結束後 resolve。
     */
    override async cascadeFill(
        toMapCol: number[],
        elimRows: number[],
        fillTime: number,
        dropRowDelay: number,
        onBottomLanded?: () => void,
        fillEase: TweenEasing = 'quadIn',
        cornerFrame?: number
    ): Promise<void> {
        // base 的同步段已經排好每顆格子的去向與顯示，tween 還沒走、畫面還沒畫——在這裡換角落那顆才看不到換牌
        const done = super.cascadeFill(toMapCol, elimRows, fillTime, dropRowDelay, onBottomLanded, fillEase);
        if (cornerFrame !== undefined) this.setTopCornerFrame(cornerFrame);
        await done;
        this.reviveEdgeBufferCells();
    }

    /**
     * 讓上緣角落那格（緊貼資料列上方的緩衝格）顯示指定的牌。
     *
     * 角落那顆在下一次消除時會第一個掉進盤面，base 的補牌在它落進資料列時把它換成後端給的新牌
     * （一定是 `toMap[消除數 − 1]`，也就是新補的牌裡最下面那張）。角落事先顯示的如果不是那張，玩家就會
     * 看到它掉下來時變牌。所以由呼叫端預先算好那張牌（`CascadeReelsTask.planCornerDrops`），停輪與每次
     * 補牌之後都換到這一格上，掉下去時就是同一張牌。
     *
     * 這一格在補牌後可能是消除時藏起來的空格（同一欄消掉 2 格以上），那就順便讓它重新顯示。
     *
     * @param frame 要顯示的 frameIdx。
     */
    private setTopCornerFrame(frame: number): void {
        const posIdx = this.rowToPosOffset - 1;
        const symIdx = this.findSymbolNodeAtPosIndex(posIdx);
        if (symIdx < 0) return;

        const opacity = this.symbolOpacities[symIdx];
        if (opacity.opacity === 0) {
            this.symbolNodes[symIdx].setScale(1, 1, 1);
            opacity.opacity = 255;
        }
        this.setSymbolDisplay(symIdx, frame);
    }

    /**
     * 起轉：先把畫面上的資料列寫回輪帶，再進入加速。
     *
     * 寫回是為了中途取消：spin 失敗時 {@link stopSpin} 不帶盤面、直接停在輪帶位置 0，停下來就是
     * 起轉前那一盤。連鎖消除之後畫面早就跟輪帶對不上，不能只靠上一局寫進去的初盤。
     *
     * 上一局留下的 tween（補牌落地彈跳等）一併停掉、格子對齊回自己的格位，免得跟轉動搶同一個 position。
     * 上一局被 {@link convertToGolden} 換成金牌的輪帶也在這裡還原，再寫回畫面上的資料列。
     *
     * @param delay 原地等幾秒才開始加速（起轉間隔 × 欄序）；這段時間 model 已經是轉動中，
     *              重複呼叫不會再起轉一次。
     * @returns 這一欄真的起轉時為 true；已經在轉、或輪帶比停輪助跑還短時為 false。
     */
    public startSpin(delay: number = 0): boolean {
        if (this.model.state !== ReelState.IDLE) return false;

        if (this.strip.length < this.stopRunUp) {
            console.warn(`[ReelView_1003] ${this.node.name} 輪帶只有 ${this.strip.length} 格，比停輪助跑的 ${this.stopRunUp} 格短，這一欄不轉`);
            return false;
        }

        if (this.stripBeforeGolden) {
            this.strip.splice(0, this.strip.length, ...this.stripBeforeGolden);
            this.stripBeforeGolden = null;
        }
        this.patchVisibleStrip(this.visibleDataFrames());
        for (let i = 0; i < this.symbolNodes.length; i++) {
            const node = this.symbolNodes[i];
            Tween.stopAllByTarget(node);
            node.setScale(1, 1, 1);
            node.setPosition(0, this.posList[this.posIndexes[i]].position.y, 0);
        }
        this.startDelay = Math.max(0, delay);
        this.model.spin();
        return true;
    }

    /**
     * 停輪：把這一欄的終盤寫進輪帶，倒數 `delay` 秒後下停輪指令，依落定曲線停到定位，再播落地回彈。
     *
     * 終盤固定停在輪帶位置 0：{@link patchVisibleStrip} 寫的就是位置 0 起算的資料段，上下的緩衝格
     * 照輪帶原本的內容接上，所以兩側欄四個角看到的是「這一欄繼續轉會出現什麼」。給了 `cornerFrame`
     * 時，資料段正上方那一格（上緣角落）先寫成它：那是這一欄第一次消除時角落那顆會落成的牌，跟著輪帶
     * 自然轉進來，掉下去時就不會變牌（見 {@link setTopCornerFrame}）。
     *
     * 停輪後原本還接一段寫死的落地彈跳（往下衝 5% 格高再彈回），2026-10-14 拿掉、改由回彈曲線決定；
     * 2026-10-22 照原版參考影片改回「落定後往上彈再落回」，高度與時長在 reelConfig.json 的
     * `stopBounce*`，由 `ReelView.updateStopBounce()` 播。
     *
     * - 還沒起轉（例如沒經過 spin 按鈕就直接補播）：先起轉再停；輪帶太短轉不起來時直接換圖。
     * - 上一次的停輪還沒跑完（spin 失敗的原地停輪）：等它停好再重轉，新盤面才不會混進舊的減速段。
     *
     * @param frames 這一欄資料列由上而下的 frameIdx；null 代表不換盤面，停回起轉前那一盤。
     * @param onLanded 第一次碰到定位時呼叫（停輪音）；早於停輪結束，中間隔著落地回彈。
     * @param delay 倒數幾秒才下停輪指令，見 {@link scheduleStop}。
     * @param cornerFrame 上緣角落要停在哪張牌（frameIdx）；不給時照輪帶原本的內容。
     * @param onLandingSoon 碰到定位之前 `scatterSoundLead` 秒呼叫（Scatter 落地音效），見 `ReelView.onLandingSoon()`；
     *                      沒有停輪段可走時跟 `onLanded` 同一刻、排在它前面。
     * @returns 停輪結束（回彈演完）後 resolve；不帶盤面又沒在轉時立即 resolve。
     */
    public async stopSpin(frames: number[] | null, onLanded?: () => void, delay: number = 0, cornerFrame?: number, onLandingSoon?: () => void): Promise<void> {
        if (this.model.state === ReelState.STOPPING || this.model.state === ReelState.END) {
            await this.waitStopped();
        }
        if (this.model.state === ReelState.IDLE) {
            if (!frames) return;
            if (!this.startSpin()) {
                this.showDataFrames(frames);
                onLandingSoon?.();
                onLanded?.();
                return;
            }
        }

        if (frames) this.patchVisibleStrip(frames);
        if (frames && cornerFrame !== undefined && this.strip.length > 0) {
            // 停在輪帶位置 0 時，posIdx p 顯示的就是 strip[p]，上緣角落是 rowToPosOffset - 1
            this.strip[(this.rowToPosOffset - 1 + this.strip.length) % this.strip.length] = cornerFrame;
        }
        // 還在倒數的上一個停輪被這一次蓋掉時，先放掉它在等的那一刻，免得它永遠等不到（坑 #35）
        this.pendingStopReached?.();
        this.pendingLandingSoon = onLandingSoon ?? null;
        const reached = new Promise<void>((resolve) => (this.pendingStopReached = resolve));
        const stopped = this.waitStopped();
        this.scheduleStop(0, delay);
        await reached;
        onLanded?.();
        await stopped;
    }

    /**
     * 把這一欄直接擺成指定的盤面，不轉、不播落下（進場還原用，見 `GameMain_1003.drawBoard()`）。
     *
     * 擺完的狀態跟 {@link stopSpin} 停好時一樣：資料段寫進輪帶位置 0 起算的那一段（{@link patchVisibleStrip}），
     * 轉輪位置設 0，每一格照它目前的格位重畫（停在位置 0 時格位 p 顯示 `strip[p]`）。上下緩衝格與兩側欄的
     * 角落照輪帶原本的內容接上，下一轉起轉時跟畫面接得上。照格位而不是照格子索引重畫（`refreshDisplay()` 是後者），
     * 轉過幾局、格子輪替過位置之後呼叫也對。
     *
     * @param frames 這一欄資料列由上而下的 frameIdx，長度要等於 {@link getDataRowCount}。
     * @returns 有擺上為 true；這一欄正在轉、輪帶還沒建好或長度不對時為 false，畫面不動。
     */
    public snapToBoard(frames: number[]): boolean {
        if (this.model.state !== ReelState.IDLE || this.strip.length === 0 || frames.length !== this.dataRowCount) return false;
        this.patchVisibleStrip(frames);
        this.model.setCurrentRng(0);
        for (let i = 0; i < this.symbolNodes.length; i++) {
            this.setSymbolDisplay(i, this.strip[this.posIndexes[i] % this.strip.length]);
        }
        return true;
    }

    /** {@link stopSpin} 在等的「第一次碰到定位」，由 {@link onStopReached} 放行 */
    private pendingStopReached: (() => void) | null = null;

    /** {@link stopSpin} 給的落定前通知，由 {@link onLandingSoon} 呼叫一次 */
    private pendingLandingSoon: (() => void) | null = null;

    /** 停輪快要碰到定位：呼叫 {@link stopSpin} 給的 `onLandingSoon`（Scatter 落地音效）。 */
    protected override onLandingSoon(): void {
        const callback = this.pendingLandingSoon;
        this.pendingLandingSoon = null;
        callback?.();
    }

    /** 停輪第一次碰到定位：放行 {@link stopSpin} 播停輪音。 */
    protected override onStopReached(): void {
        const resolve = this.pendingStopReached;
        this.pendingStopReached = null;
        resolve?.();
    }

    /**
     * 等這一欄下一次停好（`ReelModel` 發 `stopped`）。
     *
     * @returns 停好時 resolve。
     */
    private waitStopped(): Promise<void> {
        return new Promise<void>((resolve) => {
            this.model.events.once('stopped', () => resolve());
        });
    }

    /**
     * 目前畫面上各資料列顯示的 frameIdx，由上而下。對不到的格子沿用輪帶在那個位置原本的值。
     *
     * 外部演出換掉整欄的牌之前，也用它記下原本那一盤，演完再停回去（例如 DebugPanel 的金牌飛入治具）。
     *
     * @returns 長度等於 {@link dataRowCount} 的 frameIdx 陣列。
     */
    public visibleDataFrames(): number[] {
        const frames: number[] = [];
        for (let row = 0; row < this.dataRowCount; row++) {
            const symbolId = this.cellAtRow(row)?.getSymbolId() ?? -1;
            const frameIdx = symbolId < 0 ? -1 : this.frameIdxToSymbolId.indexOf(symbolId);
            frames.push(frameIdx >= 0 ? frameIdx : this.strip[(this.rowToPosOffset + row) % this.strip.length]);
        }
        return frames;
    }

    /**
     * 不轉動，直接把資料列換成指定的 frameIdx。只在輪帶太短、轉不起來時當退路。
     *
     * @param frames 資料列由上而下的 frameIdx。
     */
    private showDataFrames(frames: number[]): void {
        for (let row = 0; row < frames.length; row++) {
            const symbolIdx = this.symbolIdxAtRow(row);
            if (symbolIdx >= 0) this.setSymbolDisplay(symbolIdx, frames[row]);
        }
    }

    /**
     * 把某一格換成指定的符號，並清掉上一個符號留下的附加狀態。
     *
     * 外部仍以 frameIdx 溝通（base 的輪帶邏輯與 CascadeReelsTask 都是），這裡翻譯成符號 id 交給
     * {@link SymbolCell}。換符號時一律先清金牌、中獎層與聽牌層的強制狀態——否則上一顆的金色、中獎演出
     * 或聽牌狀態會殘留在後來掉進這一格的一般牌上。
     *
     * @param symbolIdx 這一欄裡的符號索引。
     * @param frameIdx 要顯示的符號的 frameIdx。
     */
    override setSymbolDisplay(symbolIdx: number, frameIdx: number): void {
        const cell = this.cellAt(symbolIdx);
        if (!cell) return;

        cell.clearState(SymbolStateLevel.Win);
        cell.clearState(SymbolStateLevel.High);
        cell.clearState(SymbolStateLevel.Tenpai);

        const symbolId = this.frameIdxToSymbolId[frameIdx] ?? -1;
        if (symbolId < 0) {
            console.warn(`[ReelView_1003] frameIdx=${frameIdx} 對不到任何符號 id，該格不會換圖`);
            return;
        }
        cell.setSymbolId(symbolId);
        this.placeCell(symbolIdx);
    }

    /**
     * 消除收尾：把中獎演出播完的格子藏起來（opacity 歸零、scale 復位），交給補牌重複使用。
     *
     * 2026-10-14 起所有符號的 Erase 都併進 WinAnimation——一般牌由 spine 自己壓扁、爆破，wild 由
     * {@link playWinFx} 用程式壓扁——進到這裡時演出都已經在 {@link playWinFx} 裡演完了，畫面停在
     * WinAnimation 的最後一格，所以不再切任何狀態、也不播動畫，當下就藏好。原本是呼叫 base 的
     * `explode()` 跑一段 0 秒的縮小 tween，多等一幀，base 那支已經刪掉。
     *
     * @param rows 要消除的可見列。
     */
    explode(rows: number[]): void {
        const targets = new Set(rows.map((row) => row + this.rowToPosOffset));
        for (let i = 0; i < this.symbolNodes.length; i++) {
            if (!targets.has(this.posIndexes[i])) continue;
            this.symbolOpacities[i].opacity = 0;
            this.symbolNodes[i].setScale(1, 1, 1);
        }
    }

    /**
     * 補牌落下前的抖動：這一欄看得到的格子各自往隨機方向小幅位移，換 {@link PRE_DROP_SHAKE} 的次數後
     * 對齊回格位。
     *
     * 每顆的位移各自隨機，不是整欄一起晃。只動 opacity > 0 的格子——消除後藏起來的格子接著就會被
     * 補牌搬走。位移是直接跳過去、不補間：參考影片裡就是一格畫面一個位置。
     *
     * @returns 抖完、格子都回到格位後 resolve。
     */
    async shakeBeforeDrop(): Promise<void> {
        const pitch = this.cellHeightAbs();
        const maxX = pitch * PRE_DROP_SHAKE.xRatio;
        const maxY = pitch * PRE_DROP_SHAKE.yRatio;
        const jitter = (max: number): number => (Math.random() * 2 - 1) * max;

        const shakes: Promise<void>[] = [];
        for (let i = 0; i < this.symbolNodes.length; i++) {
            if (this.symbolOpacities[i].opacity === 0) continue;

            const node = this.symbolNodes[i];
            const homeY = this.posList[this.posIndexes[i]].position.y;
            shakes.push(
                new Promise<void>((resolve) => {
                    let t = tween(node);
                    for (let step = 0; step < PRE_DROP_SHAKE.steps; step++) {
                        t = t.call(() => node.setPosition(jitter(maxX), homeY + jitter(maxY), 0)).delay(PRE_DROP_SHAKE.stepTime);
                    }
                    t.call(() => {
                        node.setPosition(0, homeY, 0);
                        resolve();
                    }).start();
                })
            );
        }
        await Promise.all(shakes);
    }

    /**
     * 治具：這一欄所有可玩列照正式流程演一次中獎消除（WinAnimation，含壓扁與爆破），播完還原成原本
     * 的盤面，不消除、不記帳、不補牌。
     *
     * 只涵蓋可玩列（{@link dataRowCount}），兩側欄四個角的緩衝格不算：它們不吃後端資料，正式
     * 流程裡從來不會被消除。播完逐格讓出中獎狀態並立刻 flush。
     *
     * @param winFxTime 中獎演出的速度基準（秒），與正式流程的 `cascadeTiming().winFx` 相同。
     * @returns 演完並還原後 resolve。
     */
    async previewEliminate(winFxTime?: number): Promise<void> {
        const rows = Array.from({ length: this.dataRowCount }, (_, row) => row);
        await this.playWinFx(rows, winFxTime);

        for (const row of rows) {
            const cell = this.cellAtRow(row);
            cell?.clearState(SymbolStateLevel.Win);
            cell?.flush();
        }
    }

    /** 中獎消除演出的速度基準（秒）；timeScale ＝ 這個值 ÷ `cascadeTiming().winFx` */
    private static readonly WIN_FX_BASE_TIME = 1.6;

    /**
     * 中獎演出裡麻將牌開始翻轉的時刻（原速，秒，從 WinAnimation 開始算）。
     *
     * h1～h4、l1 用 `symbol_p.json`：`normal`／`golden` 的 `tu` 骨骼從 1.2 秒開始橫向壓扁，`mahjong_a`
     * 翻牌序列也從這裡開始。l2～l5 用 `symbol.json`：動畫本身 0.2 秒開始翻，但 prefab 上主軌延後 1 秒
     * 才播，合起來一樣是 1.2 秒。Wild 的 `win` 沒有翻轉。美術重出動畫改了這個時間點要跟著改。
     */
    private static readonly TILE_FLIP_AT = 1.2;

    /**
     * 中獎演出開始後，過多久麻將牌開始翻轉（實際秒數）。
     *
     * 跟 {@link playWinFx} 用同一套速度換算，演出被 `winFx` 加速或放慢時跟著縮放。
     *
     * @param winFxTime 速度基準（秒），跟同一次 {@link playWinFx} 傳的值一樣。
     * @returns 實際秒數。
     */
    static tileFlipDelay(winFxTime = ReelView_1003.WIN_FX_BASE_TIME): number {
        const speed = ReelView_1003.WIN_FX_BASE_TIME / Math.max(winFxTime, 0.05);
        return ReelView_1003.TILE_FLIP_AT / speed;
    }

    /**
     * 中獎消除演出：對指定列各播一次 {@link SymbolState.WinAnimation}，等它整段播完。
     *
     * 狀態設在 {@link SymbolStateLevel.Win} 層——高於轉動邏輯的 `Reel` 層，所以不管輪軸當下
     * 在算什麼狀態都會被蓋過去；也因為只設這一層，中獎演出結束時只要 `clearState(Win)`
     * 就能乾淨退場，不影響別的系統設過的狀態。
     *
     * **2026-10-14 起 Erase 併進這裡，所有符號都只剩這一段演出。** 一般牌的 WinAnimation 由 spine
     * 自己壓扁、`symbol_frame` 從第 1 秒開始爆破，原速大約 2 秒。Wild 原本另外用程式把圖面橫向翻掉
     * （`scaleTarget`），2026-10-19 拿掉，所有符號都只播 spine 本身的演出。
     *
     * **一定要等整段播完。** 保底計時取「基準時長」「演出總長（`getAnimDuration()`，含額外軌的開始／
     * 結束秒數）÷ 速度」較長的那個。只給基準時長的話會在爆破中途切掉。
     *
     * @param rows 中獎的可見列。
     * @param winFxTime 速度基準（秒）：timeScale ＝ {@link WIN_FX_BASE_TIME} ÷ 這個值，預設原速。
     * @returns 全部播完後 resolve。
     */
    playWinFx(rows: number[], winFxTime = ReelView_1003.WIN_FX_BASE_TIME): Promise<void> {
        const duration = Math.max(winFxTime, 0.05);
        const speed = ReelView_1003.WIN_FX_BASE_TIME / duration;
        const promises: Promise<void>[] = [];

        for (const row of rows) {
            const cell = this.cellAtRow(row);
            if (!cell) continue;
            cell.setState(SymbolState.WinAnimation, SymbolStateLevel.Win);
            cell.flush();
            cell.setTimeScale(speed);
            const animTime = cell.getAnimDuration() / speed;
            promises.push(cell.playCurrentStateOnce(Math.max(duration, animTime)));
        }

        return Promise.all(promises).then(() => undefined);
    }

    /**
     * 把某一列切到中獎狀態，供共用的 `SlotMachineView.playSymbolWins()` 連線演出路徑使用。
     *
     * 1003 自己的消除流程走的是 {@link playWinFx}，不經過這裡；這一支是為了讓那條共用路徑仍然
     * 可用而保留（見 `.docs/1003-symbol-system-gap-analysis.md` 第四節：那套框架目前沒接）。
     *
     * @param row 可見列（0 起算，由上往下）。
     * @param _animName 保留參數，改版後動畫由 prefab 上的 `SymbolViewSpine` 決定。
     * @param loop 是否循環；false 時才會觸發 `onComplete`。
     * @param onComplete 播完的回呼。
     * @returns 有成功切到中獎狀態為 true；那一列沒有格子時為 false。
     */
    playWinAnim(row: number, _animName: string, loop: boolean = true, onComplete?: () => void): boolean {
        const cell = this.cellAtRow(row);
        if (!cell) return false;

        cell.setState(SymbolState.WinAnimation, SymbolStateLevel.Win);
        cell.flush();

        if (!loop && onComplete) {
            void cell.playCurrentStateOnce(ReelView_1003.WIN_FX_BASE_TIME).then(onComplete);
        }
        return true;
    }

    /**
     * DebugPanel「Symbol 縮放」呼叫，套用到這一欄目前所有的格子。
     *
     * @param scale 縮放倍率，1 為原始大小。
     */
    setSymbolScale(scale: number): void {
        for (const cell of this.symbolCells) cell?.setScaleMultiplier(scale);
    }

    /**
     * 調整這一欄所有格子的動畫播放速度。
     *
     * @param scale 倍率，1 為原速、0 為凍結。
     */
    setSymbolSpinesTimeScale(scale: number): void {
        for (const cell of this.symbolCells) cell?.setTimeScale(scale);
    }

    /**
     * 結束中獎演出：把 {@link SymbolStateLevel.Win} 層讓出來，格子自動回到預設狀態。
     *
     * 改版前是逐格把 spine 切回各自的 `*stop` 動畫（需要一張 `SPINE_STOP_ANIM` 對照表）；
     * 現在不需要——退出 `WinAnimation` 狀態時物件池會把中獎用的顯示物件收回去、換回 `Normal`
     * 那一顆，靜止外觀本來就是它。
     */
    stopAllWinAnims(): void {
        for (const cell of this.symbolCells) cell?.clearState(SymbolStateLevel.Win);
    }

    /** 金牌翻成 Wild 時，Wild 換上去當下先播的開場動畫（`symbol_wild` 的 `begin`，原速 1.5 秒） */
    private static readonly WILD_REVEAL_ANIM = 'begin';

    /** 蓋牌那顆顯示物件在爆破播完之後再多留的秒數，確保它的 complete 事件先到、才被歸還 */
    private static readonly GOLDEN_LINGER_MARGIN = 0.1;

    /**
     * 金牌翻成 Wild：在金牌主軌結束那一刻接上 Wild，播它的開場動畫，跟其他牌的爆破同時進行。
     *
     * 金牌的 WinAnimation 由主軌 `golden` 把牌蓋掉（1.2～1.43 秒）、1.5 秒格子就空了，爆破
     * `symbol_frame` 卻要播到第 2 秒多。原本翻 Wild 排在消除階段——要等每一顆中獎牌都演完——
     * 而且還先把一個已經空掉的格子壓到 0 才換，中間空了大約 0.65 秒。所以改成：
     *
     * 1. 中獎階段一開始就排好，時間點是這一格主軌結束（`getMainEndTime()`，乘上速度倍率）；
     *    查不到主軌時退回整段演出的長度。
     * 2. 時間到先 `keepCurrentViewFor()`：蓋牌那顆留在原地把爆破播完再歸還，畫在 Wild 上面
     *    （兩顆都在 `Layer_Win`，留下來的那顆排在該層所有符號之上）。
     * 3. 換成 Wild，主軌先播一次 {@link WILD_REVEAL_ANIM}（`begin`）再接回 `idle`，用原速播、不跟中獎演出
     *    調速。2026-10-19 前是顯示物件的 scale.x 從 0 展開（0.12 秒）。
     * 4. 中獎期間整台壓黑（`Layer_Black/Black` 蓋在盤面上）；翻出來的 Wild 屬於這次中獎，在 Win 層設
     *    Normal，物件因此放在壓黑之上的 `Layer_Win`、保持亮的，等爆破與 `begin` 都播完（那時壓黑已經解除）
     *    才讓出來。讓出 Win 層時物件搬回格子、重播一次動畫（同一顆物件會 `resetAni`），更早讓出會把還沒
     *    播完的 `begin` 切掉。
     * 5. 嚴格分段：回傳的 Promise 也等 `begin` 播完才 resolve，連鎖要等它結束才進抖動與補牌。補牌搬動
     *    格子時會清掉中獎層、重播動畫，跟 `begin` 重疊就會把它切掉。有金牌翻 Wild 的那一步因此比較長：
     *    `begin` 用原速播 1.5 秒，以目前的中獎演出速度（`winFx` 2 秒）比蓋牌那顆的爆破晚結束約 0.73 秒。
     *
     * 必須在 {@link playWinFx} 之後呼叫：那時這一格已經切到 WinAnimation，讀得到主軌長度。
     *
     * @param row 可見列（0 起算，由上往下）。
     * @param wildFrameIdx Wild 的 frameIdx。
     * @param winFxTime 速度基準（秒），跟同一次 {@link playWinFx} 傳的值一樣。
     * @returns 蓋牌那顆的爆破與 Wild 的 `begin` 都播完、讓出中獎層之後 resolve；找不到格子時立即 resolve。
     */
    revealGoldenAsWild(row: number, wildFrameIdx: number, winFxTime = ReelView_1003.WIN_FX_BASE_TIME): Promise<void> {
        const idx = this.symbolIdxAtRow(row);
        const cell = this.cellAt(idx);
        if (!cell?.node?.isValid) return Promise.resolve();

        const speed = ReelView_1003.WIN_FX_BASE_TIME / Math.max(winFxTime, 0.05);
        const total = cell.getAnimDuration() / speed;
        const mainEnd = cell.getMainEndTime() / speed;
        const revealAt = mainEnd > 0 ? mainEnd : total;
        const linger = Math.max(0, total - revealAt) + ReelView_1003.GOLDEN_LINGER_MARGIN;

        return new Promise<void>((resolve) => {
            this.scheduleOnce(() => {
                if (!cell.node?.isValid) {
                    resolve();
                    return;
                }
                cell.keepCurrentViewFor(linger);
                this.setSymbolDisplay(idx, wildFrameIdx);
                cell.setState(SymbolState.Normal, SymbolStateLevel.Win);
                cell.flush();
                const introSec = cell.playIntro(ReelView_1003.WILD_REVEAL_ANIM);

                this.scheduleOnce(() => {
                    cell.clearState(SymbolStateLevel.Win);
                    resolve();
                }, Math.max(linger, introSec));
            }, revealAt);
        });
    }

    /**
     * 聽牌：這一軸資料列上的 Scatter 切到聽牌狀態，或全部放回。
     *
     * 狀態設在聽牌層（`SymbolStateLevel.Tenpai`），物件換成 `Symbol_scatter.prefab` 的 `Tenpai` 節點，
     * 放進 `Layer_Win`、畫在壓黑與聚焦的那一軸之上（見 {@link attachOverlayView}）。放回只清聽牌層，之後設在中獎層的
     * Scatter 中獎演出不受影響。
     *
     * @param on true 是切到聽牌狀態（只動資料列上的 Scatter），false 是這一軸每一格都清掉聽牌層。
     */
    setLandedScattersTenpai(on: boolean): void {
        if (!on) {
            for (const cell of this.symbolCells) cell?.clearState(SymbolStateLevel.Tenpai);
            return;
        }
        for (let row = 0; row < this.dataRowCount; row++) {
            const cell = this.cellAtRow(row);
            if (!cell || ReelView_1003.drawRankOf(cell.getSymbolId()) !== 2) continue;
            cell.setState(SymbolState.Tenpai, SymbolStateLevel.Tenpai);
            cell.flush();
        }
    }

    /**
     * 播 scatter 中獎演出。
     *
     * scatter 沒有專屬狀態——它的中獎演出跟一般符號一樣是 `WinAnimation`，差別只在資產不同，
     * 而資產差異已經由「每個符號一支 prefab」吸收掉了。
     *
     * @param row 可見列。
     */
    playScatterWin(row: number): void {
        const cell = this.cellAtRow(row);
        if (!cell) return;
        cell.setState(SymbolState.WinAnimation, SymbolStateLevel.Win);
        cell.flush();
    }

    /**
     * scatter 落定時的顯示。
     *
     * 改版後 scatter 的靜止外觀就是它自己 prefab 的 `Normal` 節點，落定時不需要另外切換任何
     * 東西，所以這支只保留空實作維持呼叫端相容。等 scatter 有專屬的落定演出時再填。
     *
     * @param _row 可見列（0 起算，由上往下）。
     */
    revealScatter(_row: number): void {
        // scatter 的靜止外觀即 Normal 狀態，落定不需額外處理
    }

    /**
     * 取某個格位的世界座標，飄分數字要用它定位。
     *
     * @param posIdx posList 的索引（可見列 + {@link ReelView_1003.BUFFER_SLOTS}）。
     * @returns 該格位的世界座標。
     */
    getCellWorldPosition(posIdx: number): Vec3 {
        return this.posList[posIdx].getWorldPosition();
    }
}
