import { Tween } from 'cc';
import { GameTask } from './GameTask';
import { SlotMachineState } from '../reel/model/SlotMachineModel';
import type { SlotFreeMultiplierStep, SlotRoundStep } from '../models/SlotRound';
import { FG_RETRIGGER_HOLD, matchMinWinTier } from '../config/GameConst';
import PresentationStore from '../config/PresentationStore';
import { runCascadeReels } from './CascadeReelsTask';
import { playAddFlyForCells, type AddFlyCell } from '../ui/AddFlyEffect';
import { playFgReelFxRetrigger, stopFgReelFxRetrigger, stopFgReelFxWin } from '../ui/FgReelFx';
import { TemplateView } from '../ui/TemplateView/TemplateView';
import { WinAnimationView } from '../ui/WinAnimationView';
import type { ISlotGameMain } from '../types/ISlotGameMain';
import type { GameViewAdapter } from '../ui/GameViewAdapter';

/** 轉輪開始前的緩衝，讓 win bar 歸零與扣局的畫面先套用（原本是寫死在 run() 裡的 0.25） */
const SPIN_START_DELAY = 0.25;

/**
 * 把總數平均分成幾份，除不盡的餘數放在最後一份。例：10 分 3 份是 `[3, 3, 4]`。
 *
 * @param total 要分的總數。
 * @param parts 份數，至少 1。
 * @returns 每一份的數量，加總等於 `total`。
 */
function splitEvenly(total: number, parts: number): number[] {
    const base = Math.floor(total / parts);
    const shares = new Array<number>(parts).fill(base);
    shares[parts - 1] += total - base * parts;
    return shares;
}

/**
 * 免費遊戲單局動畫段：
 * 轉輪邏輯直接呼叫 runCascadeReels()（與主流程的 CascadeReelsTask 共用同一份實作，不重複寫）。
 * rollWinBalance() 仍留在 GameMain_1003（它的 debounce 計時器欄位跨多次呼叫共用同一顆，
 * 屬於 GameMain 狀態，不宜搬進每局都重新建立的 Task 實體）。
 *
 * 加局（GDD 4.3）也在這裡收尾。局數的兩次變動刻意落在不同時間點：**扣局**跟著本局轉輪一起發生
 * （`run()` 開頭），**加局**排在本局演出的最後——它是本局盤面再湊滿 Scatter 的結果。這樣畫面上
 * 才看得出「先少一格、打完又多了幾局」，而不是併成一個「+N −1」的淨值；玩家也是跑到這一局才知道
 * 多出局數，不是進場就看到總數。
 */
export class PlayFreeRoundTask extends GameTask {
    /**
     * 只記下參數；扣局、轉輪與加局都在任務佇列輪到這一筆時依序發生。
     *
     * @param game 遊戲主體。
     * @param steps 這一局的連鎖步驟。
     * @param freeMul 這一局的倍數結算；有 `win` 時以它當本局贏分，沒有時加總各步驟。
     * @param awardedRounds 這一局再觸發拿到的加局數（GDD 4.3）；沒加局是 0。
     */
    constructor(
        private readonly game: ISlotGameMain<GameViewAdapter>,
        private readonly steps: readonly SlotRoundStep[],
        private readonly freeMul: SlotFreeMultiplierStep | undefined,
        /** 這一局再觸發拿到的加局數（GDD 4.3）；沒加局是 0 */
        private readonly awardedRounds: number = 0
    ) {
        super();
    }

    /** Task 進入點：播免費遊戲的一局，結束後通知框架。每一局各自開關快停窗口，失敗也會關。 */
    protected onStart(): void {
        this.game.openSpinWindow();
        this.run()
            .catch((error) => console.warn('[PlayFreeRoundTask] failed', error))
            .finally(() => {
                this.game.closeSpinWindow();
                this.finish();
            });
    }

    /**
     * 播完免費遊戲的一局：扣局、重置 win bar、跑消去落下、報獎、加局，最後結算贏分。
     *
     * 操作列 Win 是整轉的累計（從觸發 FG 那一轉的 MG 贏分接著加）：消除迴圈在盤面贏分條歸零時把那一筆移進來
     * （下一落開始、連鎖結束時），局末再捲到「這局開始時的 Win ＋ 這局贏分」。這局贏分（`free_multipliers.win`）套了累積倍率，可能比各步加總多，
     * 局末這一下就是在補那段差額。2026-10-29 前 Win 在局中不動，局末捲到 FG 累計（不含 MG 那一轉）。
     *
     * @returns 這一局演出結束後 resolve；失敗由呼叫端的 catch 記錄，不往外拋。
     */
    private async run(): Promise<void> {
        const game = this.game;
        const winBefore = Number(game.storeManager.getModel('TemplateStore').winBalance) || 0;
        // 上一局加局播的 fg_win_sc_plus 只播一次、早就接回 fg_idle；保險起見還停在那支的切回去
        stopFgReelFxRetrigger(game.allViews);
        game.slotMachineModel.setState(SlotMachineState.IDLE);
        game.onNormalSpin();
        // 扣局跟轉輪同時發生：轉這一局的當下數字就少一格，不另外停頓
        game.freeSpinsRemaining = Math.max(0, game.freeSpinsRemaining - 1);
        game.updateFgUi();
        Tween.stopAllByTarget(game.winBarProxy);
        game.winBarValue = 0;
        game.winBarProxy.v = 0;
        game.setWinBarNum(0);
        // 上一局報獎時收起來的數字，這一局開始時打開回來
        game.showWinBarNum();
        await this.wait(SPIN_START_DELAY);
        await runCascadeReels(game, this.steps);
        // 該局贏分：free_multipliers[i].win（已套累積倍率）優先，否則該局各 step win 加總
        const fm = this.freeMul;
        const roundWin = fm?.win !== undefined ? Number(fm.win) || 0 : this.steps.reduce((s, st) => s + (Number(st.win) || 0), 0);
        await this.playRoundWinAnimation(roundWin);
        // 轉輪兩側霓虹框的 fg_win 每段中獎播一次、播完自己接回 fg_idle；保險起見還停在那支的切回去再進加局
        stopFgReelFxWin(game.allViews);

        game.fgTotalWin += roundWin;
        // 加局排在本局演出的最後：它是本局盤面的結果
        await this.playRetrigger();
        await game.rollWinBalance(winBefore + roundWin, roundWin > 0 ? 0.4 : 0);
    }

    /**
     * 播這一局的加局（GDD 4.3）：特效從每顆 Scatter 飛到 FGCounter，每到一發就把局數加上一份、
     * FGCounter 播一次按下縮放，最後一次縮放播完再停一下才接下一局。沒有加局就直接 resolve。
     *
     * 排在本局演出的最後，因為加局是這一局盤面再湊滿 Scatter 的結果；本局的扣除則是跟著
     * **下一局的轉輪**一起發生（見 {@link run} 開頭），兩者自然落在不同時間點，
     * 畫面上不會併成一個「+N −1」的淨值。
     *
     * @returns 加局演出與其後的停頓結束時 resolve；`run()` 被 task queue await，所以下一局會等它。
     */
    private async playRetrigger(): Promise<void> {
        if (this.awardedRounds <= 0) return;
        const game = this.game;
        console.log(`[FG] 再觸發加局 +${this.awardedRounds} 局`);

        // 等的是「每一發該飛多久」而不是特效的回呼，理由見 playAddFlyForCells()
        const arrivals = playAddFlyForCells(game.viewH, this.resolveScatterCells());
        const shares = splitEvenly(this.awardedRounds, Math.max(1, arrivals.length));
        let elapsed = 0;
        for (let i = 0; i < shares.length; i++) {
            const arrival = arrivals[i] ?? 0;
            if (arrival > elapsed) await this.wait(arrival - elapsed);
            elapsed = Math.max(elapsed, arrival);
            this.addRounds(shares[i]);
        }

        playFgReelFxRetrigger(game.allViews); // 轉輪兩側霓虹框在最後一發抵達時播加局
        const pressSec = TemplateView.findActive()?.fgCounterPressDuration ?? 0;
        await this.wait(pressSec + FG_RETRIGGER_HOLD);
    }

    /**
     * 把一份加局補上去並更新 FGCounter；數字跳的同時 FGCounter 播按下縮放。
     *
     * @param rounds 這一份的局數；0 時什麼都不做（加局數比飛行發數少時會分到 0）。
     */
    private addRounds(rounds: number): void {
        if (rounds <= 0) return;
        const game = this.game;
        game.freeSpinsTotal += rounds;
        game.freeSpinsRemaining += rounds;
        game.updateFgUi(rounds);
    }

    /**
     * 收集這一局每顆 Scatter 的盤面座標，當加局特效的起點。
     *
     * 取**最後一個 step** 的盤面而不是初盤：Scatter 不參與連線消除（awards 會把它濾掉），但下方
     * 格子被消掉時它會跟著往下掉，所以演出當下的位置只有終盤那張盤面才算數。
     *
     * 回傳盤面座標而不是世界座標，比照 1001 的 `CollectMulFlyCell`——特效那邊除了位置還要拿該格
     * 當下的貼圖，兩者都得由欄列反查。
     *
     * @returns 每顆 Scatter 的欄列；這一局沒有 Scatter 時是空陣列。
     */
    private resolveScatterCells(): AddFlyCell[] {
        const game = this.game;
        const grid = this.steps[this.steps.length - 1]?.grid;
        if (!grid) return [];

        const cells: AddFlyCell[] = [];

        for (let col = 0; col < grid.columns.length; col++) {
            const ids = grid.columns[col].symbolIds;
            for (let row = 0; row < ids.length; row++) {
                if (game.definition.symbols.resolve(ids[row]).kind === 'scatter') cells.push({ col, row });
            }
        }

        return cells;
    }

    /**
     * 等待指定秒數。
     *
     * @param seconds 要等多久。
     * @returns 時間到之後 resolve。
     */
    private wait(seconds: number): Promise<void> {
        return new Promise<void>((resolve) => this.game.scheduleOnce(resolve, seconds));
    }

    /**
     * 依門檻跳報獎彈窗，未達標不報獎。開彈窗時收起盤面上贏分條的數字，由彈窗的跑分數字取代。
     *
     * @param roundWin 這一局的贏分。
     * @returns 報獎彈窗關閉後 resolve；沒開彈窗時立即 resolve。
     */
    private async playRoundWinAnimation(roundWin: number): Promise<void> {
        const game = this.game;
        const config = PresentationStore.getInstance().config;
        if (!config.featureRoundWinPresentationEnabled || roundWin <= 0) return;
        const bet = game.storeManager.getModel('TemplateStore').betBalance;
        const tier = WinAnimationView.getWinKey(roundWin, bet);
        if (!matchMinWinTier(tier, config.featureRoundWinPresentationMinTier)) return;
        game.hideWinBarNum();
        await game.popups.showWinAnimation(roundWin, bet);
    }
}
