import { _decorator, Color, Component, sp, Sprite } from 'cc';
import { SymbolState } from './SymbolState';

const { ccclass } = _decorator;

/**
 * 顯示層基底：一顆「某個符號的某個狀態」的畫面物件，由 {@link SymbolImageManager} 租借與回收。
 *
 * 設計依據：entry repo `docs/SlotSymbolSystem_設計參考.md` §5.1。
 *
 * **這一層只暴露四個動作**——`onRent` / `onReturn` / `resetAni` / `setColor`——而且刻意不知道
 * 自己是用 Sprite、Spine 還是別的技術畫出來的。規格書 §15.1 第 4 點把這件事列為整套架構能同時
 * 支援多種美術管線的關鍵：邏輯層只會呼叫這四個，換渲染方案不必動任何遊戲邏輯。
 *
 * 基底版本負責靜態圖：節點上有 `Sprite` 就套顏色，沒有就什麼都不做。需要播動畫的狀態由
 * {@link SymbolViewSpine} 之類的子類接手。
 */
@ccclass('1003/SymbolView')
export class SymbolView extends Component {
    /** 這顆物件屬於哪個符號 id，由 manager 在租借時寫入 */
    public symbolId: number = 0;

    /** 這顆物件代表哪個狀態，由 manager 在租借時寫入 */
    public state: SymbolState = SymbolState.None;

    /**
     * 回收時要放回哪個池。
     *
     * 用模板節點的 uuid 而不是 `symbolId × 1000 + state` 當歸還鍵，是因為 fallback 會讓多個狀態
     * 共用同一份模板（例如 `Blur` 缺項時頂替 `Normal`）。若照租借時的狀態歸還，同一份模板做出來的
     * 物件會被拆進不同的池，池與池之間互相要不到對方閒置的物件，數量只增不減。
     */
    public poolKey: string = '';

    /**
     * 這顆物件底下所有的 Sprite 與 Skeleton，`setColor` 要一次套到全部。
     *
     * 一個狀態節點通常不只一個繪製元件——例如中獎狀態同時有「符號本體的 Sprite」與
     * 「火焰框的 Skeleton」，調色時兩者都要一起變。在 {@link initImage} 抓一次存起來，
     * 不要每次 `setColor` 都重新 `getComponentsInChildren`（調色補間期間會每幀跑）。
     */
    protected sprites: Sprite[] = [];
    protected skeletons: sp.Skeleton[] = [];

    /**
     * 第一次被 instantiate 出來時呼叫一次，之後租借／回收都不會再進來。
     *
     * 抓元件這類只需要做一次的事放這裡，不要放 `onRent`——後者每次租借都會跑。
     */
    public initImage(): void {
        this.sprites = this.getComponentsInChildren(Sprite);
        this.skeletons = this.getComponentsInChildren(sp.Skeleton);
        this.onInit();
    }

    /**
     * 從池裡被租出去、掛到格子上時呼叫。
     *
     * @param symbolId 這次要顯示哪個符號。
     */
    public onRent(symbolId: number): void {
        this.symbolId = symbolId;
        this.node.active = true;
        this.setColor(Color.WHITE);
        this.resetAni();
    }

    /** 被歸還回池裡時呼叫，子類要在這裡把動畫、計時器、tween 全部停掉 */
    public onReturn(): void {
        this.node.active = false;
    }

    /** 重播動畫。靜態圖沒有動畫可播，子類覆寫 */
    public resetAni(): void {
        // 基底無動畫
    }

    /**
     * 播一次並在結束時回呼。
     *
     * 基底是靜態圖，沒有「播完」這回事，所以立刻回呼——呼叫端（`SymbolCell.playCurrentStateOnce`）
     * 另外掛了保底計時器，兩邊都會呼叫同一個只生效一次的收尾函式。
     *
     * @param onComplete 播完時呼叫。
     */
    public playOnce(onComplete: () => void): void {
        onComplete();
    }

    /**
     * 調整動畫播放速度。靜態圖沒有速度可調，子類覆寫。
     *
     * @param _scale 倍率，1 為原速。
     */
    public setTimeScale(_scale: number): void {
        // 基底無動畫
    }

    /**
     * 目前這顆物件的動畫在原速下要播多久。供呼叫端換算 timeScale，把動畫塞進指定的演出時長。
     *
     * @returns 秒數；靜態圖沒有動畫，回 0。
     */
    public getAnimDuration(): number {
        return 0;
    }

    /**
     * 主軌在原速下第幾秒結束（從這個狀態開始播起算）。靜態圖沒有主軌動畫，回 0。
     *
     * @returns 秒數；靜態圖回 0。
     */
    public getMainEndTime(): number {
        return 0;
    }

    /**
     * 主軌先播一次開場動畫，播完接回原本的動畫。靜態圖沒有動畫可播，回 0。
     *
     * @param _anim 開場動畫名稱。
     * @returns 開場動畫在原速下的秒數；基底回 0。
     */
    public playIntro(_anim: string): number {
        return 0;
    }

    /**
     * 套用相乘顏色。
     *
     * 所有調色都必須走這裡，不可以在外面直接寫 `Sprite.color`——那正是盤點文件
     * （`.docs/1003-symbol-system-gap-analysis.md` 第二節第 6 條）記錄的「一個通道兩個主人」問題。
     *
     * 目前除了 {@link onRent} 重設成白色，沒有程式呼叫它：原本唯一的用途是壓黑，2026-10-20 改成機台的
     * `Layer_Black/Black` 遮罩。它是規格書 §5.1 顯示層四個動作之一，所以保留。
     *
     * @param color 目標顏色。
     */
    public setColor(color: Color): void {
        for (const sprite of this.sprites) sprite.color = color;
        for (const skeleton of this.skeletons) skeleton.color = color;
    }

    /** 子類的一次性初始化掛點，由 {@link initImage} 呼叫 */
    protected onInit(): void {
        // 子類覆寫
    }
}
