import { GameTaskFn } from './GameTask';
import type { SlotRoundResult } from '../models/SlotRound';
import type { ISlotGameMain } from '../types/ISlotGameMain';
import type { GameViewAdapter } from '../ui/GameViewAdapter';

/**
 * Spin 結算：把操作列 Win 校正成伺服器的總贏分，並套用伺服器回的餘額。
 *
 * Win 平常由消除迴圈在盤面贏分條歸零時把那一筆移進來（`WinBarController.clearWinBarScore()`，連鎖結束時也會
 * 歸零一次），這裡用伺服器的數字校正一次，避免跟 WinAnimationView 用的 spinWin 對不起來（例如 FG 結算的總贏分
 * 含累積倍率）。用 `rollWinBalance(…, 0)` 而不是直接寫值：萬一還有捲動沒跑完，直接寫的話它下一幀又會蓋回去。
 * 盤面贏分條不再改成總贏分（2026-10-29 前會）。免費遊戲結束時 `ExitFreeGameTask` 也走這裡。
 *
 * 贏分顯示音效（win_show）2026-10-30 起改在消除迴圈裡贏分條跳分時播（`CascadeReelsTask` 的 `addStepScore()`），
 * 這裡不再播。
 *
 * @param game 遊戲主體。
 * @param result 這一局的結果；餘額取 `balanceAfter`，不是數字時不動餘額。
 * @param spinWin 這一局的總贏分。
 */
export function finishSpin(game: ISlotGameMain<GameViewAdapter>, result: SlotRoundResult, spinWin: number): void {
    const finalWin = Number(spinWin.toFixed(2));
    void game.rollWinBalance(finalWin, 0);
    const serverBalance = Number(result.balanceAfter);
    if (!isNaN(serverBalance)) {
        game.storeManager.getModel('UserStore').setBalance(serverBalance);
    }
}

/** 薄殼 GameTaskFn：addTask() 到頂層佇列時使用。 */
export class FinishSpinTask extends GameTaskFn {
    /**
     * 參數原樣轉給 {@link finishSpin}，排進頂層佇列輪到時才執行。
     *
     * @param game 要操作的遊戲主體。
     * @param result 這一局的結果。
     * @param spinWin 這一轉的贏分。
     */
    constructor(game: ISlotGameMain<GameViewAdapter>, result: SlotRoundResult, spinWin: number) {
        super(() => finishSpin(game, result, spinWin));
    }
}
