// ============================================================
// engines/types.ts
// 每款遊戲的假資料「玩法引擎」介面。
//
// slot-api-mock.ts 只負責玩家端 API 的傳輸與帳務（步驟協定、餘額、注單），
// 真正決定盤面長相與中獎規則的部分由這個介面切開，引擎只產出 v8.1 的盤面（渲染契約格式），
// 金額一律用底注倍數，換成錢由傳輸層照這一局的底注算。
// ============================================================

import type { SlotApiBoard } from '../SlotApiTypes';

/** 引擎產出的一張盤面，連同這張盤面實付的贏分（撞單局上限時可能比 `bm` 少） */
export interface MockBoard {
    board: SlotApiBoard;
    /** 實付贏分，單位是底注的百分之一（整數，避免浮點誤差） */
    paidCents: number;
}

/** 一轉：初盤加上它的所有連消盤面，最後一張是終盤 */
export interface MockSpin {
    boards: MockBoard[];
    /** 這一轉授的免費遊戲轉數（主遊戲是 `FE` 的 `rd`，免費遊戲是 `RT` 的 `awd`），放在終盤那一步 */
    awarded: number;
}

/** 一整局：第一轉是主遊戲，其餘依序是免費遊戲各轉 */
export interface MockRound {
    spins: MockSpin[];
}

export interface MockRoundEngine {
    /** 玩家端 API 的遊戲代號（entry 的 `gid`） */
    readonly gameId: string;
    /** 盤面結果的 schema 版本（`r.ver`） */
    readonly resultVersion: number;
    /** Base Bet：每單位幾幣（entry 的 `bb`） */
    readonly baseBet: number;
    /** 方案宣告的 RTP（entry 的 `rtp`） */
    readonly rtp: string;
    /** 單局上限，底注倍數（entry 的 `maxwm`） */
    readonly maxWinMultiple: number;
    /** 沒玩過時 entry 的 `ls.r` 要畫的預設盤面：沒有中獎、沒有事件 */
    makeDefaultBoard(): SlotApiBoard;
    /** 產生一整局 */
    makeRound(): MockRound;
}
