import type { sp } from 'cc';
import type { GameViewAdapter } from './GameViewAdapter';
import { trySetAnimation } from '../utils/SpineSafe';
import { waitSeconds, type TimerHost } from '../utils/Wait';

/**
 * 盤面旁的人物表演：主遊戲是 `GameViewH/mg_man`，免費遊戲是 `GameViewH/fg_man`。
 *
 * | 時機 | mg_man | fg_man | 呼叫端 |
 * |---|---|---|---|
 * | 切到該模式（進場、進 FG、出 FG） | MG 顯示並循環 idle，FG 隱藏 | FG 顯示並循環 idle，MG 隱藏 | `GameMain_1003.applyGameModeUi()` |
 * | 消除連鎖每一段演出中獎符號 | win → idle | win → idle | `CascadeReelsTask.runCascadeReels()` |
 * | 進 FG（跟過場同時開始） | trans（退場），播完才隱藏 | — | `EnterFreeGameTask` |
 *
 * 兩個節點跟 `NG`／`FG` 同層，不會跟著 `ngNode`／`fgNode` 開關（2026-10-13 從底下移出來），
 * 所以顯示哪一位由 {@link showCharacterForMode} 自己開關節點。`trans` 是人物退場：第 1.0 秒人物消失、
 * 變成金幣轉到 1.667 秒，再淡出到 1.833 秒，播完 `mg_man` 就是空的——下次回到主遊戲時重播 idle 把人叫回來。
 *
 * 進 FG 在過場全黑時（1.7 秒，見 `EnterFreeGameTask` 的 `SWITCH_TO_FREE_AT_SEC`）切模式，那時金幣還沒
 * 淡完，所以 trans 播放中切到 FG **不藏 mg_man**，改由 trans 播完時藏（見 {@link mgManExiting}）。
 *
 * **只有橫版有人物**（直版沒有這兩個節點），單一個 view 沒接是正常的；每一個 view 都沒接才是漏接，
 * 那種情況印一次警告。
 */

/** 常駐動畫 */
const IDLE_ANIM = 'idle';
/** 中獎動畫，單次，播完接回 idle */
const WIN_ANIM = 'win';
/** mg_man 進 FG 前的退場動畫 */
const TRANS_ANIM = 'trans';
/** 讀不到 trans 長度時的保底秒數（mg_man.json 的 trans 是 1.833 秒） */
const TRANS_FALLBACK_SEC = 1.833;

/** 漏接警告只印一次：每次切模式、每段中獎都會走到，每次印會把 console 洗掉 */
let warnedMissing = false;

/** mg_man 的 trans 還在播：這段期間切到 FG 先不藏它，由 trans 播完時藏；沒在播時是 null */
let mgManExiting: Promise<void> | null = null;

/** 最後一次切到的是不是 FG；trans 播完時用它決定要不要藏 mg_man（期間又切回 MG 就不藏） */
let showingFree = false;

/**
 * 取這個 view 上指定模式的人物 spine。
 *
 * @param view 要查的 view。
 * @param isFg true 取 fg_man，false 取 mg_man。
 * @returns 有接且有效的 spine；沒接時回 null。
 */
function characterOf(view: GameViewAdapter, isFg: boolean): sp.Skeleton | null {
    const skeleton = isFg ? view.fgManSkel : view.mgManSkel;
    return skeleton?.isValid ? skeleton : null;
}

/**
 * 收集所有 view 上指定模式的人物，每一個 view 都沒接時警告一次。
 *
 * @param views 通常是 `game.allViews`。
 * @param isFg true 取 fg_man，false 取 mg_man。
 * @returns 每一個有接的 view 與它的人物。
 */
function collectCharacters(views: readonly GameViewAdapter[], isFg: boolean): { view: GameViewAdapter; skeleton: sp.Skeleton }[] {
    const found: { view: GameViewAdapter; skeleton: sp.Skeleton }[] = [];
    for (const view of views) {
        const skeleton = characterOf(view, isFg);
        if (skeleton) found.push({ view, skeleton });
    }
    if (found.length === 0 && !warnedMissing) {
        warnedMissing = true;
        console.warn(`[CharacterPerformance] 沒有任何 view 接上人物：Game.prefab 的 GameViewAdapter 上 ${isFg ? 'fgManSkel' : 'mgManSkel'} 是空的`);
    }
    return found;
}

/**
 * 切到指定模式的人物：這個模式的那位顯示並從頭循環播 idle，另一位隱藏。
 *
 * 一律重新 `setAnimation()`：mg_man 播完 trans 之後是空的（人物已經變成金幣淡出），回到主遊戲時
 * 要靠這裡把人叫回來；而節點被關掉期間 spine 不會更新，不重播的話會接在離開前的進度上。
 *
 * 切到 FG 時 mg_man 若還在播 trans，先不藏，等 trans 播完再藏（見 {@link playMgManTrans}）。
 *
 * @param views 通常是 `game.allViews`。
 * @param isFg true 顯示 fg_man，false 顯示 mg_man。
 */
export function showCharacterForMode(views: readonly GameViewAdapter[], isFg: boolean): void {
    showingFree = isFg;
    const keepExitingMgMan = isFg && mgManExiting !== null;
    for (const view of views) {
        const hidden = characterOf(view, !isFg);
        if (hidden && !keepExitingMgMan) hidden.node.active = false;
    }
    for (const { skeleton } of collectCharacters(views, isFg)) {
        skeleton.node.active = true;
        trySetAnimation(skeleton, IDLE_ANIM, true, 'CharacterPerformance.idle');
    }
}

/**
 * 讓指定模式的人物播一次 win，播完接回 idle。
 *
 * 連鎖下一段中獎時 win 還沒播完，就從頭再播一次，不排隊——人物的反應跟著盤面走。
 *
 * @param views 通常是 `game.allViews`。
 * @param isFg true 是 fg_man，false 是 mg_man。
 */
export function playCharacterWin(views: readonly GameViewAdapter[], isFg: boolean): void {
    for (const { skeleton } of collectCharacters(views, isFg)) {
        if (!trySetAnimation(skeleton, WIN_ANIM, false, 'CharacterPerformance.win')) continue;
        try {
            skeleton.addAnimation(0, IDLE_ANIM, true, 0);
        } catch (error) {
            console.warn('[CharacterPerformance] win 之後接不回 idle', error);
        }
    }
}

/**
 * mg_man 播 trans 退場，等它播完才 resolve。
 *
 * 用動畫長度計時，不掛播完事件：被關掉的節點上 spine 不會更新，事件可能永遠不來（踩坑 #35 的吊死形狀）。
 *
 * 計時掛在呼叫端傳進來的 `host` 上，**不能掛在人物所在的 view**：直式畫面時 `GameViewH` 是關著的，
 * 關著的元件排的計時會被暫停、永遠不觸發，進 FG 的流程就卡死了（2026-10-13 第一版就是這樣寫）。
 * 人物所在的 view 沒顯示時（直式畫面，人物只有橫版有）根本看不到退場，直接 resolve，不白等。
 * turbo 的全域倍率會讓 spine 與計時一起變快。
 *
 * 播放期間登記在 {@link mgManExiting}：這段時間切到 FG 時 {@link showCharacterForMode} 不會藏 mg_man，
 * 播完時如果目前是 FG 才在這裡藏；期間又切回 MG（或按了 mg_man idle）就保持顯示。
 *
 * @param views 通常是 `game.allViews`。
 * @param host 用來排計時的元件，必須是一直開著的那一個（例如 `game`）。
 * @returns trans 播完（需要時已藏起 mg_man）後 resolve；沒有任何顯示中的 mg_man 時立即 resolve。
 */
export function playMgManTrans(views: readonly GameViewAdapter[], host: TimerHost): Promise<void> {
    const characters = collectCharacters(views, false).filter(({ skeleton }) => skeleton.node.activeInHierarchy);
    if (characters.length === 0) return Promise.resolve();

    let duration = 0;
    for (const { skeleton } of characters) {
        if (!trySetAnimation(skeleton, TRANS_ANIM, false, 'CharacterPerformance.trans')) continue;
        duration = Math.max(duration, skeleton.findAnimation(TRANS_ANIM)?.duration ?? TRANS_FALLBACK_SEC);
    }
    if (duration <= 0) return Promise.resolve();

    const exiting = waitSeconds(host, duration).then(() => {
        if (mgManExiting === exiting) mgManExiting = null;
        if (!showingFree) return;
        for (const { skeleton } of characters) {
            if (skeleton.isValid) skeleton.node.active = false;
        }
    });
    mgManExiting = exiting;
    return exiting;
}
