import type { Node } from 'cc';
import type { GameViewAdapter } from './GameViewAdapter';
import type { TimerHost } from '../utils/Wait';
import { trySetAnimation } from '../utils/SpineSafe';

/**
 * MG↔FG 切換的全螢幕轉場 spine（`GameViewAdapter.transitionSkel`）。
 *
 * 正式流程由 `GameMain_1003.playTransition()` 跟轉場音效一起呼叫；DebugPanel 的治具只呼叫這一支，
 * 不切模式、不播音效。兩邊共用同一份，治具看到的就是正式流程播的那一段。
 */

/** 進 FG 依序嘗試的動畫名（`spine/transition.json`）。舊版直版的 `tofg` 已隨資產於 2026-10-29 移除 */
const TO_FREE_ANIMS = ['mg_to_fg'];
/** 回主遊戲依序嘗試的動畫名 */
const TO_BASE_ANIMS = ['fg_to_mg'];

/**
 * 播一次轉場：進 FG 播 `mg_to_fg`、回主遊戲播 `fg_to_mg`。
 *
 * 動畫名與長度從骨架資料查（`getRuntimeData()`），不用 `sp.Skeleton.findAnimation()`——隱藏中的那個 view
 * 元件可能還沒初始化，查不到。等待時間取各自動畫的實際長度（新版 1.633／2.167 秒），全部播完才關掉節點；
 * 隱藏中的 spine 不會 update、completeListener 不會觸發，所以用時長收尾。計時掛在 `host` 上，
 * 不掛在 view 上：關著的 view 排的計時會被暫停。
 *
 * @param views 要播的 view，正式流程是 `game.allViews`。
 * @param toFree true = 進免費遊戲。
 * @param host 用來排計時的元件，必須是一直開著的那一個。
 * @returns 播完並關掉節點後 resolve；沒有任何 view 接上 transition 時立即 resolve。
 */
export function playTransitionSpine(views: readonly GameViewAdapter[], toFree: boolean, host: TimerHost): Promise<void> {
    const candidates = toFree ? TO_FREE_ANIMS : TO_BASE_ANIMS;
    const nodes: Node[] = [];
    let duration = 0;

    for (const v of views) {
        const sk = v.transitionSkel;
        if (!sk?.isValid) continue;
        const data = sk.skeletonData?.getRuntimeData(true);
        const anim = candidates.find((name) => data?.findAnimation(name));
        if (!anim) {
            console.warn(`[TransitionEffect] ${v.node.name} 的 transition spine 沒有 ${candidates.join('／')}，略過轉場`);
            continue;
        }
        sk.node.active = true;
        trySetAnimation(sk, anim, false, 'TransitionEffect.playTransitionSpine');
        duration = Math.max(duration, data?.findAnimation(anim)?.duration ?? 0);
        nodes.push(sk.node);
    }

    if (nodes.length === 0) {
        console.warn('[TransitionEffect] 沒有任何 view 接上 transitionSkel，略過轉場');
        return Promise.resolve();
    }
    return new Promise<void>((resolve) => {
        host.scheduleOnce(() => {
            for (const n of nodes) {
                if (n.isValid) n.active = false;
            }
            resolve();
        }, duration);
    });
}
