import { Vec3 } from 'cc';
import type { GameViewAdapter } from './GameViewAdapter';
import { TemplateView } from './TemplateView/TemplateView';
import { ReelView_1003 } from '../reel/view/ReelView_1003';
import {
    createVisualNode,
    findActiveFrame,
    flyAlongArc,
    GLOW_DELAY,
    playBurstGroup,
    resolveArcDuration,
    resolveFlyContainer,
    resolveScale,
} from './FlyArc';

/**
 * 免費遊戲加局時，從 Scatter 飛向 Spin 鈕的特效。
 *
 * **完全照 1001 `CollectMulEffect` 的做法**：飛行體是程式 `new Node()` 生的貼圖（要幾顆生幾顆、
 * 飛完銷毀），路徑走共用的 {@link flyAlongArc} 曲射，發射兩層光暈、抵達閃光、沿途殘影，一顆
 * Scatter 一發、依序錯開。**不播 spine**——`AddNode` 底下那顆 `free_num` 只負責在 Editor 裡擺位，
 * 執行期一律關著。
 *
 * 貼圖留空時取該顆 Scatter 當下亮著的那張圖，跟倍率飛行留空時取階梯那一階的圖是同一套退路，
 * 所以不接任何素材也能跑。
 *
 * **終點是跨 prefab 的，只能在執行期查。** Spin 鈕是 `TemplateView.spinBtn`，住在
 * `TemplateViewH/V.prefab`，跟 `Game.prefab` 是兩份獨立 prefab，Inspector 上拉不到對方。查的是
 * **元件型別**不是節點名稱——名稱推斷正是踩坑 #45 連帶踩過的那條路。
 */

/** 特效容器節點名稱 */
const CONTAINER_NODE_NAME = 'addFly';

/** 盤面格子座標，比照 1001 的 `CollectMulFlyCell` */
export interface AddFlyCell {
    col: number;
    row: number;
}

/**
 * 找目前顯示中的那個 `TemplateView` 的 Spin 鈕世界座標。
 *
 * @returns Spin 鈕的世界座標；場景還沒好或找不到時回 null。
 */
export function resolveSpinButtonWorldPosition(): Vec3 | null {
    const node = TemplateView.findActive()?.spinBtn?.node;

    return node?.isValid ? node.getWorldPosition() : null;
}

/**
 * 從每一顆 Scatter 各飛一發到 Spin 鈕，依序錯開。
 *
 * **不回傳 Promise。** 呼叫端要等的是「每一發該飛多久」這些時間，而不是特效自己的回呼——節點在
 * 飛行途中被銷毀（例如玩家離開遊戲）時 tween 不會回呼，掛在它上面的 promise 永遠不 settle，整條
 * 免費遊戲流程會無聲吊死（踩坑 #35）。這跟 `CascadeReelsTask` 等倍率飛行的做法一致。
 *
 * 回傳的時間有排序：飛行時間依距離而定，抵達順序不一定等於發射順序。
 *
 * @param adapter 目標 view。
 * @param cells 每顆 Scatter 的盤面座標，依盤面順序。
 * @returns 每一發抵達終點的秒數，由早到晚；取不到貼圖而略過的那幾發不算。空陣列代表什麼都沒播，呼叫端不用等。
 */
export function playAddFlyForCells(adapter: GameViewAdapter, cells: readonly AddFlyCell[]): number[] {
    if (cells.length === 0) return [];

    const to = resolveSpinButtonWorldPosition();
    if (!to) {
        console.warn('[AddFlyEffect] 找不到 Spin 鈕（場景裡沒有 active 的 TemplateView 或它沒接 spinBtn），略過加局特效');
        return [];
    }

    const reels = adapter.slotMachineView?.reelViews ?? [];
    const container = resolveFlyContainer(adapter.node, CONTAINER_NODE_NAME);
    const stagger = Math.max(0, adapter.addFlyStagger);
    const arrivals: number[] = [];

    cells.forEach((cell, index) => {
        const reel = reels[cell.col];
        if (!reel) return;

        const posIdx = cell.row + ReelView_1003.BUFFER_SLOTS;
        const from = reel.getCellWorldPosition(posIdx);
        const symbol = reel.getVisibleSymbol(cell.row);
        const frame = adapter.addFlyFrame ?? (symbol ? findActiveFrame(symbol) : null);

        if (!frame) {
            console.warn(`[AddFlyEffect] 第 ${cell.col} 欄第 ${cell.row} 列取不到貼圖，略過這一發`);
            return;
        }

        const delay = index * stagger;
        const duration = resolveArcDuration(adapter.addFlyDuration, from, to);
        arrivals.push(delay + duration);

        const launch = (): void => {
            const scale = resolveScale(from, to);
            const node = createVisualNode('addFly', container, frame);
            node.setWorldPosition(from);
            node.setScale(scale, scale, 1);

            // 發射瞬間的兩層光暈，用加局自己那組素材
            playBurstGroup(container, from, adapter.addFlyAuraFrames);
            adapter.scheduleOnce(() => playBurstGroup(container, from, adapter.addFlyGlowFrames), GLOW_DELAY);

            void flyAlongArc(node, {
                from,
                to,
                duration,
                moveCurve: adapter.mulFlyMoveCurve,
                heightCurve: adapter.mulFlyHeightCurve,
                faceDirection: true,
                ghostFrame: frame,
                ghostParent: container,
            }).then(() => {
                playBurstGroup(container, to, adapter.addFlyFlareFrames, adapter.addFlyRemoveBlackBgMaterial);
                if (node.isValid) node.destroy();
            });
        };

        if (delay > 0) adapter.scheduleOnce(launch, delay);
        else launch();
    });

    return arrivals.sort((a, b) => a - b);
}

/**
 * 關掉 `AddNode`（那顆只在 Editor 裡擺位用的 spine）。
 *
 * prefab 上它是 active 而且 skeleton 設了 loop，不先關就會一直播在畫面上（比照 `transition`、
 * 瞇牌與 collect 的做法）。飛出去的是程式另外生的貼圖節點，各自銷毀，不用這支收。
 *
 * @param adapter 目標 view；沒接節點時什麼都不做。
 */
export function hideAddFly(adapter: GameViewAdapter): void {
    const node = adapter.addFlyNode ?? adapter.addFlySkel?.node ?? null;
    if (node?.isValid) node.active = false;
}
