import { GameTask } from './GameTask';
import { GameStateKey } from '../states/GameStateKey';
import type { ISlotGameMain } from '../types/ISlotGameMain';
import type { GameViewAdapter } from '../ui/GameViewAdapter';
import { VOICEMAP } from '../audio/AudioConfig';
import { playVoice } from '../audio/VoiceLine';
import { playMgManTrans } from '../ui/CharacterPerformance';
import { MgManTransZoom } from '../ui/MgManTransZoom';
import StoreManager from '../store/StoreManager';
import { waitSeconds } from '../utils/Wait';

/**
 * 過場開始後第幾秒切到免費遊戲。
 *
 * 照美術動效清單（巨亨麻將_動效清單 #36，10/28 修改切換背景時間點）：`mg_to_fg` 播到第 1700ms 切換新背景。
 * 這時過場 `transition.json` 的 `black` 約 99% 不透明（1.333 秒開始淡入，1.667～1.833 秒全黑）。
 * 換轉場資源時要跟美術確認新的時間點。2026-10-29 前是 1.0 秒（mg_man 的 trans 人物變成金幣那一刻），
 * 那時還沒黑，背景切換會被看到。
 *
 * 切的時候 mg_man 還在播 trans（播到 1.833 秒），不跟著藏，等 trans 播完才藏（見
 * `CharacterPerformance.playMgManTrans()`），那時畫面仍是全黑。
 */
const SWITCH_TO_FREE_AT_SEC = 1.7;

/**
 * 免費遊戲進場設置：
 * 這裡用到的方法（updateFgUi/applyGameModeUi/resetWinBar/
 * playTransition）都同時也被 GameMain_1003 自己的生命週期方法
 * （enterGame 等）呼叫，屬於共用能力，留在 GameMain_1003 上，此處僅透過 game 呼叫。
 */
export class EnterFreeGameTask extends GameTask {
    /** 畫面跟著 mg_man 的 root 縮放（每個有 mg_man 的 view 一份），切到 FG 時結束 */
    private zooms: MgManTransZoom[] = [];

    /**
     * 只記下參數，進場演出要等任務佇列輪到這一筆才開始。
     *
     * @param game 遊戲主體，提供過場、模式切換與各 view。
     * @param freeRoundsCount 這次獲得的免費遊戲局數。
     */
    constructor(
        private readonly game: ISlotGameMain<GameViewAdapter>,
        private readonly freeRoundsCount: number
    ) {
        super();
    }

    /**
     * Task 進入點：過場（`mg_to_fg`）與 mg_man 的 trans 同時開始，第 {@link SWITCH_TO_FREE_AT_SEC} 秒切到
     * 免費遊戲。過場播完、也已經切過去之後，再停轉輪節奏的 `fgEnterDelay` 秒（DebugPanel 可調，預設 0.5），
     * 階梯面板（`TimesPanel`）才播換表演出 `levelup`（`ui_mul`），播放中由下往上一階一階換成免費遊戲的表；
     * 它與 trans 都播完才結束，接著就是 FG 第一轉。進 FG 的語音在一開始就播。
     *
     * 2026-10-20 前 `levelup` 是切模式當下播的、跟過場重疊，結束前另外停 0.6 秒；現在由 `levelup`
     * 取代那段停頓。2026-10-28 前階梯數字在切模式當下就換了，比 `levelup` 早約 0.6 秒；之後改成跟 `levelup`
     * 同時一次換完，2026-10-29 再改成 `levelup` 起播後 0.2～0.666 秒由下往上逐階換（見 `TimesController`）。
     *
     * trans 播放期間整個畫面跟著 mg_man 的 `root` 拉近（美術動效清單 #49，見 `MgManTransZoom`），切到 FG 的那一刻
     * （過場全黑時）還原。
     *
     * 所有計時都掛在 `game` 上：它一定開著，turbo 的全域倍率也會讓 spine 與計時一起變快，切換點不會跑掉。
     * 直式畫面看不到階梯面板，不等 levelup，見 {@link switchToFreeLadder}；直式也沒有 mg_man，畫面不拉近。
     */
    protected onStart(): void {
        const game = this.game;
        playVoice(VOICEMAP.ENTER_FREE_GAME);
        const trans = playMgManTrans(game.allViews, game);
        const isPortrait = StoreManager.getInstance().getDeviceStore().isPortrait;
        this.zooms = game.allViews.map((v) => MgManTransZoom.start(v, isPortrait)).filter((z): z is MgManTransZoom => z !== null);
        const transition = game.playTransition('enter');
        const switched = waitSeconds(this.game, SWITCH_TO_FREE_AT_SEC).then(() => {
            this.stopZooms();
            this.switchToFreeGame();
        });
        const levelUp = Promise.all([transition, switched])
            .then(() => waitSeconds(game, game.cascadeTiming().fgEnterDelay))
            .then(() => this.switchToFreeLadder());
        Promise.all([trans, levelUp])
            .catch((error) => console.warn('[EnterFreeGameTask] failed', error))
            .finally(() => {
                // 正常流程在切 FG 時就結束了；中途出錯沒走到那一步時，這裡把畫面還原
                this.stopZooms();
                this.finish();
            });
    }

    /** 結束畫面跟隨、還原 view；重複呼叫無害。 */
    private stopZooms(): void {
        for (const zoom of this.zooms) zoom.stop();
        this.zooms = [];
    }

    /**
     * 有階梯面板的 view（目前只有橫版）換成免費遊戲的表並播換表演出 `levelup`，只等目前顯示的那份播完。
     *
     * 直式畫面時橫版 view 只是被移到畫面外（`OrientationController.applyOrientation()`），節點還開著，
     * `activeInHierarchy` 分不出來，所以用 `DeviceStore.isPortrait` 判斷顯示的是哪一份。沒顯示的那份照樣
     * 換表、照播，轉回來時面板狀態才一致，但不等它——不然直式玩家要白等 1.5 秒看不到的演出才開始第一轉。
     *
     * @returns 顯示中的那份播完時 resolve；它沒有階梯面板時立即 resolve。
     */
    private switchToFreeLadder(): Promise<void> {
        const game = this.game;
        const shown = StoreManager.getInstance().getDeviceStore().isPortrait ? game.viewV : game.viewH;
        const plays = game.allViews.map((v) => {
            const play = v.timesPanel?.switchToFreeLadder(game) ?? Promise.resolve();
            return v === shown ? play : Promise.resolve();
        });
        return Promise.all(plays).then(() => undefined);
    }

    /** 切到免費遊戲：狀態（含背景音樂）、FG 局數、NG／FG 節點與人物、win bar。 */
    private switchToFreeGame(): void {
        const game = this.game;
        game.changeState(GameStateKey.FG);
        game.freeSpinsTotal = this.freeRoundsCount;
        game.freeSpinsRemaining = this.freeRoundsCount;
        game.fgTotalWin = 0;
        game.updateFgUi();
        game.applyGameModeUi(true);
        game.resetWinBar();
    }
}
