import { director, Director, Node, Vec3, type sp } from 'cc';
import type { GameViewAdapter } from './GameViewAdapter';
import { currentBoneTransform, setupBoneTransform } from './SpineBoneFollow';

/**
 * 進 FG 時 `mg_man` 播 `trans`，整個遊戲畫面跟著它的 `root` 骨骼縮放、位移（美術動效清單 #49：
 * 「全畫面需跟隨 bone: root 做縮放位移」）。
 *
 * `trans` 在 0.333～1.5 秒把 `root` 移動約 (1828, −11357)、放大到 19 倍，等於鏡頭整個鑽進金幣裡。這支每一幀把
 * `root` 相對初始姿勢的位移與縮放套到 view 節點（`GameViewH`），以 `mg_man` 為基準縮放，背景、盤面、階梯、
 * Logo、贏分條都一起被拉近；Canvas 上另一層的操作列不在 view 底下，不跟著動。
 *
 * **反向補償**：`mg_man` 自己也在 view 底下，它在 spine 裡已經被 `root` 放大了，view 再放大一次就變兩倍；轉場
 * `transition` 的黑幕與光芒要維持貼齊螢幕。所以這兩顆節點每一幀套上 view 變換的反向，畫面上維持原樣。
 *
 * **時機**：由 `EnterFreeGameTask` 跟 `trans` 一起開始，在切到 FG 的那一刻（過場全黑時）結束，view 與兩顆補償
 * 節點還原成開始時的位置與縮放。同步掛在 `Director.EVENT_BEFORE_DRAW`，理由見 `SpineBoneFollow` 檔頭。
 *
 * **只在橫式畫面做**：直式時 `GameViewH` 被移到畫面外（`OrientationController`），直版也沒有 `mg_man`。
 * 已知限制：這段期間切換直橫式，還原時會蓋掉方向切換對 view 的移動。
 */

/** `mg_man` 裡驅動整個畫面的骨骼 */
const ROOT_BONE = 'root';

/** 一顆節點開始時的位置與縮放，結束時照這個還原 */
interface SavedTransform {
    node: Node;
    position: Vec3;
    scale: Vec3;
}

/**
 * 記下一顆節點目前的位置與縮放。
 *
 * @param node 要記的節點。
 * @returns 位置與縮放的副本。
 */
function save(node: Node): SavedTransform {
    return { node, position: node.position.clone(), scale: node.scale.clone() };
}

/**
 * 一段進行中的畫面跟隨。用 {@link MgManTransZoom.start} 建立，{@link stop} 結束並還原。
 */
export class MgManTransZoom {
    private running = true;

    /**
     * 只記下參數，請用 {@link MgManTransZoom.start}。
     *
     * @param skeleton 正在播 `trans` 的 `mg_man`。
     * @param setupScale `root` 初始姿勢的世界縮放。
     * @param setupX `root` 初始姿勢的世界 x（骨架座標）。
     * @param setupY `root` 初始姿勢的世界 y（骨架座標）。
     * @param screen 被拉近的 view 節點開始時的變換。
     * @param mgMan `mg_man` 節點開始時的變換（同時是縮放基準）。
     * @param counters 要反向補償的節點（`mg_man` 與 `transition`）開始時的變換。
     */
    private constructor(
        private readonly skeleton: sp.Skeleton,
        private readonly setupScale: number,
        private readonly setupX: number,
        private readonly setupY: number,
        private readonly screen: SavedTransform,
        private readonly mgMan: SavedTransform,
        private readonly counters: readonly SavedTransform[]
    ) {}

    /**
     * 開始讓 view 跟著 `mg_man` 的 `root`。
     *
     * @param view 要拉近的 view；直式畫面時傳進來也不做。
     * @param isPortrait 目前是不是直式畫面。
     * @returns 進行中的跟隨；直式、沒有 `mg_man`、`mg_man` 不是 view 的直屬子節點或骨架沒有 `root` 時是 null。
     */
    public static start(view: GameViewAdapter, isPortrait: boolean): MgManTransZoom | null {
        if (isPortrait) return null;
        const skeleton = view.mgManSkel;
        if (!skeleton?.isValid) return null;
        const mgManNode = skeleton.node;
        if (mgManNode.parent !== view.node) {
            console.warn(`[MgManTransZoom] ${mgManNode.name} 不是 ${view.node.name} 的直屬子節點，畫面不跟著 root 縮放`);
            return null;
        }
        const setup = setupBoneTransform(skeleton, ROOT_BONE);
        if (!setup || setup.scale === 0) {
            console.warn(`[MgManTransZoom] ${mgManNode.name} 的骨架找不到 "${ROOT_BONE}"，畫面不跟著縮放`);
            return null;
        }

        const counters = [save(mgManNode)];
        const transitionNode = view.transitionSkel?.node;
        if (transitionNode?.isValid && transitionNode.parent === view.node) counters.push(save(transitionNode));

        const zoom = new MgManTransZoom(skeleton, setup.scale, setup.x, setup.y, save(view.node), save(mgManNode), counters);
        director.on(Director.EVENT_BEFORE_DRAW, zoom.sync, zoom);
        return zoom;
    }

    /** 結束跟隨，view 與補償節點還原成開始時的位置與縮放；重複呼叫無害。 */
    public stop(): void {
        if (!this.running) return;
        this.running = false;
        director.off(Director.EVENT_BEFORE_DRAW, this.sync, this);
        for (const saved of [this.screen, ...this.counters]) {
            if (!saved.node.isValid) continue;
            saved.node.setPosition(saved.position);
            saved.node.setScale(saved.scale);
        }
    }

    /**
     * 照 `root` 這一幀的變化套用 view 變換與反向補償。
     *
     * `root` 相對初始姿勢放大 k 倍、位移 T（骨架座標），`mg_man` 節點在 view 裡的位置 M、縮放 m，則 view 裡任一點
     * Q 要搬到 kQ + (1 − k)M + mT。換到 view 的父節點座標：縮放乘上 k、位置加上 S0 ×（(1 − k)M + mT）。補償節點
     * 原本在 p、縮放 s，改成 (p − ((1 − k)M + mT)) ÷ k、s ÷ k，世界變換就跟開始時一樣。
     */
    private sync(): void {
        if (!this.skeleton.isValid || !this.screen.node.isValid) {
            this.stop();
            return;
        }
        const bone = currentBoneTransform(this.skeleton, ROOT_BONE);
        if (!bone) return;

        const k = bone.scale / this.setupScale;
        if (k <= 0) return;
        const m = this.mgMan.scale;
        const shiftX = (1 - k) * this.mgMan.position.x + m.x * (bone.x - this.setupX);
        const shiftY = (1 - k) * this.mgMan.position.y + m.y * (bone.y - this.setupY);

        const s0 = this.screen.scale;
        const p0 = this.screen.position;
        this.screen.node.setScale(s0.x * k, s0.y * k, s0.z);
        this.screen.node.setPosition(p0.x + s0.x * shiftX, p0.y + s0.y * shiftY, p0.z);

        for (const saved of this.counters) {
            if (!saved.node.isValid) continue;
            saved.node.setPosition((saved.position.x - shiftX) / k, (saved.position.y - shiftY) / k, saved.position.z);
            saved.node.setScale(saved.scale.x / k, saved.scale.y / k, saved.scale.z);
        }
    }
}
