import { Node, Vec3 } from 'cc';
import { GameViewAdapter } from './GameViewAdapter';
import { tryClearAnimation, trySetAnimation } from '../utils/SpineSafe';
import {
    createVisualNode,
    findActiveFrame,
    flyAlongArc,
    GLOW_DELAY,
    playBurstGroup,
    resolveArcDuration,
    resolveFlyContainer,
    resolveScale,
} from './FlyArc';

/**
 * 階梯倍數飛向中獎累計條的特效（GDD 4.1／4.3 的階梯倍數）。
 *
 * 從 1001 的 `CollectMulEffect.ts`（倍率球收球曲射）移植，起訖點換成 1003 自己的兩端：
 * 起點是階梯倍數面板上目前點亮那一階（`TimesController.currentRungNode`），終點是中獎
 * 累計條的數字（`winBarNumLabel` 那顆節點）。
 *
 * **這支不碰任何數字。** 每個 step 的 `win` 伺服器／mock 已經乘過階梯倍數
 * （見 `net/mocks/mahjong-ways.ts` 的 `stepWin = rawWin * multiplier`），客戶端只負責演出；
 * 呼叫端是在特效抵達終點之後才呼叫 `addWinBarScore()`，讓分數看起來是被這一下乘上去的。
 *
 * 貼圖預設直接取那一階自己亮著的圖，所以不接任何素材也能跑；要換成專用素材就填
 * `GameViewAdapter.mulFlyFrame`。光暈／閃光三組圖留空就整段跳過。
 */

/**
 * 貼圖殘影打開，跟 1001 的 `CollectMulEffect` 一致。
 *
 * 2026-10-06 一度依參考影片 `win_bar.mp4` 關掉，因為影片裡的尾巴是 collect spine 的 `tail_0~7`
 * 骨骼在畫的，兩條尾巴疊起來會糊。現在兩個飛行特效都不播 spine 了，尾巴只剩殘影這一條，所以
 * 打開才有拖尾。
 */
const ENABLE_GHOST = true;
/** 特效統一掛在這個容器節點底下（飛行本體、殘影、光暈都是），不要散在 adapter.node 底下 */
const CONTAINER_NODE_NAME = 'multiplierFly';

/** collect 特效的動畫名（`resources/spine/collect` 只有這一支） */
const COLLECT_ANIM = 'animation';

/**
 * 這是第幾次飛行的 collect 特效。
 *
 * 收尾的保底計時器有可能跨到下一次飛行才執行（collect 的動畫 1.33 秒，比連續兩個 step 的間隔
 * 還長），那會把新一輪剛開始的特效關掉。每次起飛遞增、執行時比對一次，過期的自己放棄。
 */
let collectFlightToken = 0;

/**
 * 讓 collect 特效加入這次飛行：搬進特效容器、打開、從頭播一次。
 *
 * **會把節點搬進特效容器，而且不搬回去。** `TimesPanel` 的 sibling 順序排在 `Reel_mask` 之前，
 * 留在原地的話飛到盤面上方那一段會被遮罩與盤面蓋住；而它每一幀的位置都是從階梯那一階的世界
 * 座標算出來的，原本掛在哪完全不影響結果。兩邊的世界縮放也一樣（都在 `GameViewH` 底下、自身
 * scale 1），所以搬家不需要補等效 transform（踩坑 #10 的情況不適用）。
 *
 * @param adapter 目標 view。
 * @param container 特效容器節點。
 * @param from 起點世界座標。
 * @returns 要跟著飛行移動的節點；開關關著或沒接 spine 時回 null。
 */
function startCollect(adapter: GameViewAdapter, container: Node, from: Vec3): Node | null {
    if (!adapter.mulFlyCollectEnabled) {
        // 在 preview 裡中途關掉時，把上一次還亮著的那顆一併收乾淨
        hideMulFlyCollect(adapter);
        return null;
    }

    const skeleton = adapter.mulFlyCollectSpine;
    if (!skeleton?.isValid) return null;

    collectFlightToken++;

    const node = skeleton.node;
    if (node.parent !== container) container.addChild(node);

    node.active = true;
    node.setWorldPosition(from);

    skeleton.setCompleteListener(null!);
    skeleton.clearTracks();
    skeleton.loop = false;
    trySetAnimation(skeleton, COLLECT_ANIM, false, 'MulFlyCollect');

    return node;
}

/**
 * 飛行抵達終點之後，再留 {@link GameViewAdapter.mulFlyCollectTail} 秒就收掉 collect 特效。
 *
 * **不等動畫播完。** `collect/animation` 有 1.33 秒，但參考影片裡飛行體在抵達後約 0.04 秒就不見
 * 了，之後那 0.45 秒是贏分數字自己在發光——那是落地 spine（`win_bar`，2026-11-05 移除）的演出，
 * 不是 collect 的。讓 collect 整支播完會變成兩個東西同時在終點搶戲。
 *
 * 帶飛行編號是因為這個收尾是排程的：動畫比連續兩個 step 的間隔短得多，但使用者把尾巴調長時
 * 還是可能跨到下一次飛行，過期的排程要自己放棄。
 *
 * @param adapter 目標 view。
 */
function finishCollect(adapter: GameViewAdapter): void {
    const skeleton = adapter.mulFlyCollectSpine;
    if (!skeleton?.isValid) return;

    const token = collectFlightToken;
    const hide = (): void => {
        if (token !== collectFlightToken) return;
        hideMulFlyCollect(adapter);
    };

    const tail = Math.max(0, adapter.mulFlyCollectTail);
    if (tail > 0) adapter.scheduleOnce(hide, tail);
    else hide();
}

/**
 * 立刻關掉 collect 特效。
 *
 * prefab 上它是 active 而且 skeleton 設了 loop，所以進遊戲時要先關一次，否則會一直播在階梯
 * 面板上（比照 `transition` 與瞇牌特效的做法）。
 *
 * @param adapter 目標 view；沒接 spine 時什麼都不做。
 */
export function hideMulFlyCollect(adapter: GameViewAdapter): void {
    const skeleton = adapter.mulFlyCollectSpine;
    if (!skeleton?.isValid) return;

    skeleton.setCompleteListener(null!);
    tryClearAnimation(skeleton, 'MulFlyCollect');
    if (skeleton.node.isValid) skeleton.node.active = false;
}

/**
 * 取得（必要時建立）特效容器節點。
 *
 * @param adapter 目標 view。
 * @returns 容器節點。
 */
function resolveContainer(adapter: GameViewAdapter): Node {
    return resolveFlyContainer(adapter.node, CONTAINER_NODE_NAME);
}


/**
 * 取飛行起點：階梯倍數面板上目前點亮那一階。
 *
 * @param adapter 目標 view。
 * @returns 起點世界座標；沒有階梯面板（直版）或還沒點亮任何一階時是 null。
 */
function resolveFromWorld(adapter: GameViewAdapter): Vec3 | null {
    return adapter.timesPanel?.currentRungNode?.getWorldPosition() ?? null;
}

/**
 * 取飛行終點：中獎累計條的數字那顆節點（`num`）。
 *
 * 瞄準 `num` 而不是它的容器：容器底下還有別的東西（直版的 `mul`、橫版的跑馬燈底板），中心點
 * 不在數字上，特效會落在數字旁邊。`winBarNumLabel` 在 `Game.prefab` 上橫直版都正確接著
 * `num` 那顆 Label，所以直接取它的節點。
 *
 * **沒有退路是故意的。** 原本退路是 `winBarNode`，但橫版的那個欄位已經指到落地特效節點
 * 自己（2026-10-05 `win_bar` 改名 `WinNode` 之後），拿它當終點會把分數特效丟到特效頭上。
 * 寧願不播也不要落錯位置。
 *
 * @param adapter 目標 view。
 * @returns 終點節點；`winBarNumLabel` 沒接時是 null。
 */
function resolveTargetNode(adapter: GameViewAdapter): Node | null {
    const node = adapter.winBarNumLabel?.node ?? null;

    return node?.isValid ? node : null;
}

/**
 * 依起訖距離換算飛行時間：距離近的自動變快，並夾在下限與設定值之間。
 *
 * @param adapter 目標 view，提供 `mulFlyDuration` 當參考距離下的時間。
 * @param from 起點世界座標。
 * @param to 終點世界座標。
 * @returns 秒數。
 */
function resolveDuration(adapter: GameViewAdapter, from: Vec3, to: Vec3): number {
    return resolveArcDuration(adapter.mulFlyDuration, from, to);
}

/**
 * 算出這次飛行會花多少秒，給呼叫端排節奏用（不會真的播）。
 *
 * @param adapter 目標 view。
 * @returns 秒數；起訖點缺一邊時是 0。
 */
export function resolveMultiplierFlyDuration(adapter: GameViewAdapter): number {
    const from = resolveFromWorld(adapter);
    const target = resolveTargetNode(adapter);

    if (!from || !target) return 0;

    // 一定要含發射延遲：呼叫端是拿這個數字排「抵達才加分」的，少算就會比閃光早到
    return Math.max(0, adapter.mulFlyLaunchDelay) + resolveDuration(adapter, from, target.getWorldPosition());
}

/**
 * 播一次倍率飛行：從點亮那一階曲射到中獎累計條。
 *
 * 起訖點都是當下才取世界座標，所以階梯面板因為 `cc.Layout` 重排而位移、或累計條數字位數
 * 變多而改變寬度，都會自動跟上。
 *
 * @param adapter 目標 view；沒有階梯面板（直版）時直接 resolve，不印 warn。
 * @returns 抵達終點後 resolve。
 */
export function playMultiplierFly(adapter: GameViewAdapter): Promise<void> {
    const rung = adapter.timesPanel?.currentRungNode ?? null;
    if (!rung) return Promise.resolve();

    const from = rung.getWorldPosition();
    const target = resolveTargetNode(adapter);
    const frame = adapter.mulFlyFrame ?? findActiveFrame(rung);

    if (!target || !frame) {
        console.warn('[MultiplierFlyEffect] 缺少終點節點或貼圖，略過倍率飛行特效');
        return Promise.resolve();
    }

    const to = target.getWorldPosition();
    const duration = resolveDuration(adapter, from, to);
    const scale = resolveScale(from, to);

    const container = resolveContainer(adapter);
    const node = createVisualNode('multiplierFly', container, frame);
    node.setWorldPosition(from);
    node.setScale(scale, scale, 1);

    // 發射瞬間的兩層光暈。光暈先播、飛行體晚 mulFlyLaunchDelay 才出發，蓄力感就來自這一下停頓
    playBurstGroup(container, from, adapter.mulFlyAuraFrames);
    adapter.scheduleOnce(() => {
        playBurstGroup(container, from, adapter.mulFlyGlowFrames);
    }, GLOW_DELAY);

    return new Promise<void>((resolve) => {
        // 起飛本身延後，但飛行體在這段期間就停在起點上（它疊在那一階上，看起來就是蓄力中的那顆）
        const launch = (): void => {
            // 從頂端那一階（x5／x10）飛出來時，那一階同時重播發光；停在頂端之後不會再升階，靠這裡每次連續消除都亮
            adapter.timesPanel?.replayTopGlow();
            // collect 特效跟著這次飛行一起走（美術擺在 TimesPanel 底下的那顆）
            const collectNode = startCollect(adapter, container, from);

            void flyAlongArc(node, {
                from,
                to,
                duration,
                moveCurve: adapter.mulFlyMoveCurve,
                heightCurve: adapter.mulFlyHeightCurve,
                // 貼圖要轉向飛行方向；collect 只跟位置，它的尾巴是照固定方向畫的，跟著轉會扭成一團
                faceDirection: true,
                ghostFrame: ENABLE_GHOST ? frame : null,
                ghostParent: container,
                onStep: (pos) => {
                    if (collectNode?.isValid) collectNode.setWorldPosition(pos);
                },
            }).then(() => {
                // 抵達終點的閃光
                playBurstGroup(container, to, adapter.mulFlyFlareFrames, adapter.mulFlyRemoveBlackBgMaterial);
                // collect 再留一小段就收，終點那段持續發光交給落地 spine
                finishCollect(adapter);
                node.isValid && node.destroy();
                resolve();
            });
        };

        const launchDelay = Math.max(0, adapter.mulFlyLaunchDelay);
        if (launchDelay > 0) adapter.scheduleOnce(launch, launchDelay);
        else launch();
    });
}
