import { Label, Node, tween, Tween } from "cc";
import StoreManager from "../store/StoreManager";

/**
 * 贏分條數字跑到新分數、操作列 Win 跑到新累計的秒數（{@link WinBarController.addWinBarScore}／
 * {@link WinBarController.addWinBalance}）；結算要等它跑完才收數字
 */
export const WIN_BAR_ROLL_SEC = 0.3;

/**
 * WinBarController（盤面贏分條與操作列 Win 的跑分）
 *
 * 1001/1002 逐字相同，只有 View 具體型別不同。負責：
 * - 盤面贏分條（`WinNode`）：**只顯示這一落的分數**（包含金牌翻成 Wild、沒有落下的那一落）。每一落開始前
 *   與整串連鎖結束時 {@link clearWinBarScore} 歸零，addWinBarScore 用 tween 從 0 滾到這一筆；setWinBarNum 直接設值、
 *   resetWinBar 整組歸零（不移進 Win）。
 *   2026-10-29 前是整轉的累計，結算時再校正成總贏分。
 * - 操作列 Win（`TemplateStore.winBalance`）：**這一轉的累計**。WinNode 歸零的那一刻把它原本那一筆移進來
 *   （{@link clearWinBarScore} → {@link addWinBalance}），總得分就是 Win。rollWinBalance 捲到指定值
 *   （FG 局末補差額、結算校正）。
 *
 * 2026-10-29 移除從 1001 帶來、1003 沒有呼叫端的倍率演出（setWinBarMul／showWinBarMul／playWinBarAdd、
 * winBarSkel 的 add／mul／mul2 spine）與 FG 累積倍率計數器（setTotalMultiplierLabel）；1003 的倍率是階梯面板
 * （TimesController）。
 */

/** WinBarController 只需要用到的 View 子集合，各遊戲自己的 GameViewAdapter 結構相容即可傳入 */
export interface WinBarView {
    bg: Node | null;
    /** 中獎累計數字 Label */
    winBarNumLabel: Label | null;
}

export interface WinBarDeps {
    getViews: () => WinBarView[];
    storeManager: StoreManager;
}

/** 盤面贏分條與操作列 Win 的跑分，見檔頭說明 */
export class WinBarController {
    winBarValue = 0;
    winBarProxy = { v: 0 };

    private rollActive = false;
    private rollFrom = 0;
    private rollTarget = 0;
    private rollElapsed = 0;
    private rollDuration = 0;
    private rollResolve: (() => void) | null = null;

    /**
     * 只記下依賴，不碰任何節點；View 每次用到時才透過 `deps.getViews()` 取。
     *
     * @param deps 取得 View 與 store 的依賴集合。
     */
    constructor(private deps: WinBarDeps) { }

    /**
     * 直接寫入贏分條的數字（不播演出），格式依目前幣別。
     *
     * @param val 數字。
     */
    setWinBarNum(val: number): void {
        const s = this.deps.storeManager.getGameStore().formatAmount(val);
        for (const v of this.deps.getViews()) {
            if (v.winBarNumLabel) v.winBarNumLabel.string = s;
        }
    }

    /**
     * 把贏分條歸零，並停掉進行中的跑分 tween。
     *
     * tween 一定要先停：不停的話它下一幀還會把舊的目標值寫回去，看起來像歸零失敗。
     * 報獎時被 {@link hideWinBarNum} 關掉的數字也在這裡打開回來。
     */
    resetWinBar(): void {
        Tween.stopAllByTarget(this.winBarProxy);
        this.winBarValue = 0;
        this.winBarProxy.v = 0;
        this.setWinBarNum(0);
        this.showWinBarNum();
    }

    /**
     * 關掉贏分條的數字（橫直版都關）。報獎時收起來：大獎由報獎彈窗的數字取代，小獎改由操作列的 Win
     * 顯示這局總贏分。下一局 {@link showWinBarNum} 打開回來。
     */
    hideWinBarNum(): void {
        for (const v of this.deps.getViews()) {
            if (v.winBarNumLabel) v.winBarNumLabel.node.active = false;
        }
    }

    /**
     * 打開贏分條的數字（橫直版都開）。主遊戲在 {@link resetWinBar} 裡開，免費遊戲每局開始時開。
     */
    showWinBarNum(): void {
        for (const v of this.deps.getViews()) {
            if (v.winBarNumLabel) v.winBarNumLabel.node.active = true;
        }
    }

    /**
     * 盤面贏分條歸零，同時把它原本那一筆移進操作列 Win（{@link addWinBalance}）。
     *
     * 移進去的是目標值 {@link winBarValue}，不是畫面上的數字：數字還在滾時歸零也不會少算。tween 一定要先停，
     * 不停的話它下一幀還會把上一筆的目標值寫回去。
     *
     * @returns Win 捲完之後 resolve；贏分條原本就是 0 時立即 resolve。
     */
    clearWinBarScore(): Promise<void> {
        const moved = this.winBarValue;
        Tween.stopAllByTarget(this.winBarProxy);
        this.winBarValue = 0;
        this.winBarProxy.v = 0;
        this.setWinBarNum(0);
        return this.addWinBalance(moved);
    }

    /**
     * 把一筆贏分加進盤面贏分條，用 {@link WIN_BAR_ROLL_SEC} 秒的 tween 跑到新的值；delta 不是正數時直接略過。
     *
     * 每一筆開始前呼叫端會先 {@link clearWinBarScore}，所以畫面上是從 0 跑到這一筆的分數。
     *
     * @param delta 這次要加上去的分數。
     */
    addWinBarScore(delta: number): void {
        if (delta <= 0) return;
        this.winBarValue += delta;
        const to = this.winBarValue;
        Tween.stopAllByTarget(this.winBarProxy);
        tween(this.winBarProxy)
            .to(WIN_BAR_ROLL_SEC, { v: to }, { onUpdate: () => this.setWinBarNum(this.winBarProxy.v) })
            .call(() => this.setWinBarNum(to))
            .start();
    }

    /**
     * 把一筆贏分疊到操作列 Win 上，用 {@link WIN_BAR_ROLL_SEC} 秒捲到新的累計；delta 不是正數時直接略過。
     *
     * 由 {@link clearWinBarScore} 在贏分條歸零時呼叫。上一筆還沒捲完時接在它的目標值後面加，不從畫面上捲到
     * 一半的值算，不然連續兩筆會少算一截。
     *
     * @param delta 這次要加上去的分數。
     * @returns 捲完之後 resolve。
     */
    addWinBalance(delta: number): Promise<void> {
        if (delta <= 0) return Promise.resolve();
        const templateStore = this.deps.storeManager.getModel('TemplateStore');
        const base = this.rollActive ? this.rollTarget : Number(templateStore.winBalance) || 0;
        return this.rollWinBalance(base + delta, WIN_BAR_ROLL_SEC);
    }

    // 用 dt 累加 不用固定間隔 setTimeout 累加寫法能吃到 director hook 的加速縮放
    /**
     * 每幀推進餘額捲動；沒有在捲動時直接返回。
     *
     * 用 dt 累加而不是 tween，是為了吃得到 director hook 的整體加速縮放。
     *
     * @param dt 距離上一幀的秒數。
     */
    update(dt: number): void {
        if (!this.rollActive) return;
        this.rollElapsed += dt;
        const ratio = this.rollDuration <= 0 ? 1 : Math.min(this.rollElapsed / this.rollDuration, 1);
        const templateStore = this.deps.storeManager.getModel('TemplateStore');
        templateStore.setWinBalance(Number((this.rollFrom + (this.rollTarget - this.rollFrom) * ratio).toFixed(2)));
        if (ratio >= 1) {
            this.rollActive = false;
            const resolve = this.rollResolve;
            this.rollResolve = null;
            resolve?.();
        }
    }

    /**
     * 把操作列 Win 從目前值捲動到目標值。重複呼叫會取消上一次，被取消的那一次當下就 resolve——
     * 不放行的話等它的人會永遠卡住（坑 #35）；{@link addWinBalance} 連續疊加時常常會取消上一筆。
     *
     * @param to 目標金額。
     * @param duration 捲動秒數；0 以下代表立刻跳到目標值。
     * @returns 捲完（或被下一次取消）之後 resolve。
     */
    rollWinBalance(to: number, duration: number): Promise<void> {
        this.rollActive = false;
        const cancelled = this.rollResolve;
        this.rollResolve = null;
        cancelled?.();
        const templateStore = this.deps.storeManager.getModel('TemplateStore');
        this.rollFrom = Number(templateStore.winBalance) || 0;
        this.rollTarget = Number(to.toFixed(2));
        this.rollDuration = duration;
        this.rollElapsed = 0;

        return new Promise<void>((resolve) => {
            if (duration <= 0) {
                templateStore.setWinBalance(this.rollTarget);
                resolve();
                return;
            }
            this.rollResolve = resolve;
            this.rollActive = true;
        });
    }
}
