import GameConfigManager from '../../config/GameConfigManager';
import { createSlotGridLayout, getBoardDamp, getSlotLayoutSource } from '../GridLayoutConfig';

// 測試到頂的情況 main 主遊戲到頂又觸發免費遊戲 free 免費遊戲中途到頂
export type MaxWinCase = 'main' | 'free';

export type SlotApiDebugResultControl = {
    symbol_control?: { symbol: number; count: number; line?: number };
    win?: { min: number; max: number };
    max_win?: MaxWinCase;
    jackpot?: Partial<Record<'mini' | 'minor' | 'major' | 'grand', boolean>>;
    /**
     * 免費遊戲的驗證治具，**不是玩法設定**，只改 mock 產生的資料、目前只有 1003 的引擎會讀：
     * - 加局（retrigger）自然發生率只有每局幾個百分點，手動玩幾乎碰不到，開這個才驗得到演出與局數顯示
     * - 進入機率（trigger_chance）讓測試不必轉幾十局才進一次 FG，也能壓到 0 專測主遊戲
     */
    free_game?: {
        /**
         * 加局治具：`'never'` 免費遊戲中一律不加局（驗沒有加局時的流程與局數倒數用）；
         * `'first'` 只有第 1 局加（驗演出與局數跳號用，一次 FG 剛好看到一次）；
         * `'every'` 每局都加（壓力測試，會一路加到局數安全閥才停）。
         */
        retrigger?: 'never' | 'first' | 'every';
        /** 加局時初盤要放幾顆 Scatter（決定加幾局）；不給就隨機 */
        retrigger_scatters?: number;
        /**
         * 主遊戲每局進入免費遊戲的機率（0～1），超出範圍會被夾住；不給就用引擎自己的預設值。
         */
        trigger_chance?: number;
    };
    /**
     * 連續消除的驗證治具，**不是玩法設定**，只改 mock 產生的資料、目前只有 1003 的引擎會讀：
     * 自然情況下一轉連續中獎 5 次以上只有約 5%，手動玩很難碰到「倍數停在頂端還一直消」的演出。
     */
    cascade?: {
        /** 主遊戲與免費遊戲的每一轉，都重骰到連續中獎至少這麼多次（中獎的盤面張數，不含最後的終盤） */
        min_wins?: number;
    };
};
/**
 * 讀出 DebugPanel 目前寫在 `globalThis.__slotApiDebugControl__` 的驗證治具設定。
 *
 * 每局產生結果時才呼叫，不要在 module 載入時存起來——面板隨時會改這個值。
 *
 * @returns 治具設定；面板沒開任何治具時為 null。
 */
export const getSlotApiDebugControl = (): SlotApiDebugResultControl | null => (globalThis as any).__slotApiDebugControl__ ?? null;

/**
 * 盤面形狀依當下的 GAMEID 取，不能在 module 載入時就算好——GAMEID 是進遊戲場景才寫入
 * globalThis 的，此檔被 import 的時機比那更早，先算會一律拿到預設的盤面。
 * 每次呼叫重建物件，切換子遊戲時不會殘留上一款的形狀。
 *
 * @returns 可見盤的形狀。
 */
export const mockLayout = () => createSlotGridLayout(getSlotLayoutSource(GameConfigManager.GAMEID));

/**
 * 盤面上下的 damp 格數，跟 {@link mockLayout} 一樣每次依當下的 GAMEID 取。
 *
 * @returns 上下的 damp 格數。
 */
export const mockDamp = () => getBoardDamp(GameConfigManager.GAMEID);

/**
 * 取 0 到 max−1 的隨機整數。
 *
 * @param max 上界（不含）。
 * @returns 0 到 max−1 的整數；max 為 0 時回 0。
 */
export function randomInt(max: number): number {
    return Math.floor(Math.random() * max);
}
