import { Constructor, instantiate, Node, Prefab } from 'cc';
import { PopupBase } from './PopupBase';

/**
 * PopupManager（模組級單例）
 *
 * 統一開關所有繼承 PopupBase 的彈窗，取代各遊戲各自手刻的開關邏輯
 * （比照 lobby ViewManager 的 Stack 模式精神，但只服務 PopupBase 這條線，
 * 不是完整的 view/singleton 管理系統，那是 lobby 專用的，游戲端不需要那麼複雜）。
 *
 * - `open()` 從 prefab 產生一個新彈窗實例，掛進指定層（或 setLayer() 設定的
 *   預設層），push 進堆疊最上層。
 * - 每個彈窗一律是堆疊模式：`close()` 直接銷毀節點並移出堆疊，沒有 lobby
 *   ViewManager 那種 Singleton（只隱藏不銷毀）模式——PopupBase 系列彈窗
 *   本來就是「開一次、關掉就沒了」，不需要重用節點快取。
 * - `PopupBase.close()`／關閉鈕／背景遮罩點擊關閉，最終都會呼叫這裡的
 *   `closeNode()`，堆疊狀態永遠正確，不用另外同步。
 */
export class PopupManager {
    private static defaultLayer: Node | null = null;
    private static readonly stack: PopupBase[] = [];

    /** 進場景/遊戲時呼叫一次，指定彈窗預設要掛在哪個節點底下（例如 popupRoot） */
    static setLayer(node: Node): void {
        this.defaultLayer = node;
    }

    /**
     * 從 prefab 開一個彈窗，疊在堆疊最上層。popupClass 是要拿的元件類別
     * （例如 AutoPlayPopup），prefab 根節點上要掛著這個元件，找不到就直接
     * 銷毀節點並回傳 null（同 lobby ViewManager.showPrefab() 的錯誤處理）。
     */
    static open<T extends PopupBase>(prefab: Prefab, popupClass: Constructor<T>, layer?: Node): T | null {
        const node = instantiate(prefab);
        const popup = node.getComponent(popupClass);
        if (!popup) {
            console.warn(`[PopupManager] prefab "${prefab.name}" 上找不到 ${popupClass.name} 元件`);
            node.destroy();
            return null;
        }

        // defaultLayer 存的是場景節點，切場景後會失效，這裡要一併擋掉（否則會 addChild 到已銷毀的節點上）
        const mountLayer = layer ?? this.defaultLayer;
        if (!mountLayer || !mountLayer.isValid) {
            console.warn('[PopupManager] 沒有可掛載的層級（尚未呼叫 setLayer()、沒有傳入 layer 參數，或掛載層已被銷毀），彈窗不會顯示');
            node.destroy();
            return null;
        }
        mountLayer.addChild(node);

        this.stack.push(popup);
        return popup;
    }

    /** PopupBase.close() 內部呼叫，同時負責從堆疊移除、銷毀節點——不要直接呼叫 node.destroy() 略過這裡 */
    static closeNode(node: Node): void {
        this.detach(node);
        if (node.isValid) node.destroy();
    }

    /**
     * 只把節點移出堆疊，不銷毀它。由 PopupBase.onDestroy() 呼叫，
     * 處理「彈窗不是走 close() 而是被整層一起銷毀」（例如切場景）的情況——
     * 沒有這一步的話堆疊會留下指向已銷毀節點的殘留項目，count／getTop() 都會失準。
     */
    static detach(node: Node): void {
        const index = this.stack.findIndex((p) => p.node === node);
        if (index !== -1) this.stack.splice(index, 1);
    }

    /** 關閉堆疊最上層彈窗（走 closeNode()，不會經過子類別覆寫的 close()，所以不會播關閉動畫） */
    static closeTop(): void {
        const top = this.stack[this.stack.length - 1];
        if (top) this.closeNode(top.node);
    }

    /** 關閉所有目前開著的彈窗（同 closeTop()，一律走 closeNode()，不播子類別的關閉動畫；
     *  這是刻意的：動畫版 close() 不會同步移出堆疊，會讓下面這個迴圈跑不完） */
    static closeAll(): void {
        while (this.stack.length > 0) {
            this.closeNode(this.stack[this.stack.length - 1].node);
        }
    }

    /** 目前堆疊最上層的彈窗實例，沒有開任何彈窗則為 null */
    static getTop(): PopupBase | null {
        return this.stack[this.stack.length - 1] ?? null;
    }

    /** 目前開著的彈窗數量 */
    static get count(): number {
        return this.stack.length;
    }
}
