import { _decorator, Component, Label, Material, Node, RealCurve, RealInterpolationMode, sp, SpriteFrame, sys, UITransform, Vec3, view } from 'cc';
import { SlotMachineView } from '../reel/view/SlotMachineView';
import type { SlotMachineModel } from '../reel/model/SlotMachineModel';
import { TimesController } from './TimesController';

const { ccclass, property } = _decorator;

/**
 * 把介面根節點撐成安全區大小 子節點的 Widget 才會貼著安全區的邊
 * 橫版只套用左右 上下不內縮
 *
 * @param node 介面根節點 父節點的縮放會被扣掉 讓縮放後剛好等於安全區
 */
export function fitViewToSafeArea(node: Node): void {
    const transform = node.getComponent(UITransform);
    const scale = node.parent?.worldScale;
    if (!transform || !scale || scale.x === 0 || scale.y === 0) return;
    const rawSafe = sys.getSafeAreaRect();
    const visible = view.getVisibleSize();
    // 桌面黑邊不算安全區 與設計區域取交集
    const safeLeft = Math.max(rawSafe.x, 0);
    const safeBottom = Math.max(rawSafe.y, 0);
    const safe = {
        x: safeLeft,
        y: safeBottom,
        width: Math.min(rawSafe.x + rawSafe.width, visible.width) - safeLeft,
        height: Math.min(rawSafe.y + rawSafe.height, visible.height) - safeBottom,
    };
    // 橫版只避開左右 上下維持貼邊
    const landscape = visible.width > visible.height;
    const safeY = landscape ? 0 : safe.y;
    const safeHeight = landscape ? visible.height : safe.height;
    const width = safe.width / scale.x;
    const height = safeHeight / scale.y;
    transform.setContentSize(width, height);
    // 安全區中心偏移時用錨點補償 沒加 Widget 的子節點位置不動
    const offsetX = (safe.x + safe.width / 2 - visible.width / 2) / scale.x;
    const offsetY = (safeY + safeHeight / 2 - visible.height / 2) / scale.y;
    transform.setAnchorPoint(0.5 - offsetX / width, 0.5 - offsetY / height);
}

@ccclass('1003/GameViewAdapter')
export class GameViewAdapter extends Component {
    // runtime model（各 view 各自持有）
    slotMachineModel: SlotMachineModel = null!;

    // 原本給 DebugPanel 的「Spine 預覽」掛預覽用的 spine，那個功能 2026-10-29 拿掉之後已經沒有程式讀它；
    // Game.prefab 上還接著，要刪得連 prefab 一起處理
    @property(Node)
    popupRoot: Node = null!;

    // 各彈窗的 prefab 路徑（留空則 fallback 到 PopupManager 的預設路徑）
    @property({ tooltip: 'WinAnimationView prefab 路徑（留空用預設）' })
    winAnimationPrefabPath: string = '';

    // === 彈窗節點 transform 覆寫（給直版微調用，留 (0,0,0) 表示不覆寫）===
    @property({ tooltip: 'WinAnimationView 內容子節點位置覆寫（(0,0,0) = 不覆寫）' })
    winAnimationContentLpos: Vec3 = new Vec3(0, 0, 0);

    @property({ tooltip: 'WinAnimationView 內容子節點縮放覆寫（(0,0,0) = 不覆寫）' })
    winAnimationContentScale: Vec3 = new Vec3(0, 0, 0);

    @property({ tooltip: 'WinFreeGamePopupView backgroundSpine 位置覆寫（(0,0,0) = 不覆寫）' })
    winFreeGamePopupBgSpineLpos: Vec3 = new Vec3(0, 0, 0);

    @property({ tooltip: 'WinFreeGamePopupView backgroundSpine 縮放覆寫（(0,0,0) = 不覆寫）' })
    winFreeGamePopupBgSpineScale: Vec3 = new Vec3(1, 1, 1);

    // 背景
    @property(Node)
    bg: Node = null!;

    @property(Node)
    fgNode: Node | null = null;

    @property(Node)
    ngNode: Node | null = null;

    // 轉輪
    @property(SlotMachineView)
    slotMachineView: SlotMachineView = null!;

    // === win_bar（中獎累計條）===
    // 2026-10-29 移除 1001 帶來、1003 沒在用的 winBarSkel（add／mul／mul2 spine）與倍率 winBarMulNode／Label／Opacity
    @property(Label)
    winBarNumLabel: Label = null!;

    /**
     * 捲軸上方的階梯倍數面板（GDD 4.1 主遊戲 x1/x2/x3/x5、4.3 免費遊戲 x2/x4/x6/x10）。
     *
     * 只有橫版有這個節點，直版是 null——呼叫端一律用 `?.` 保護，不要假設它存在。
     */
    @property(TimesController)
    timesPanel: TimesController | null = null;

    // 瞇牌／聽牌框（slowmotion）與 FG 金牌轉換前的龍（dragon）在機台 prefab 的 Layer_Mi／Layer_Dragon，
    // 由 SlotMachineView 的 miSkel／miGoldSkel 接（2026-11-03 從這裡搬過去）

    // === 人物表演（CharacterPerformance）===

    /**
     * 主遊戲的人物（`mg_man`）：常駐 idle、中獎 win、進 FG 前播 trans 退場。
     *
     * 只有橫版有，直版是 null。跟 `NG` 同層、不受 `ngNode` 開關影響，FG 期間由
     * `CharacterPerformance.showCharacterForMode()` 隱藏。
     */
    @property({ type: sp.Skeleton, tooltip: '主遊戲的人物 spine（mg_man）：idle／win／trans，FG 時自動隱藏；直版留空' })
    mgManSkel: sp.Skeleton | null = null;

    /**
     * 免費遊戲的人物（`fg_man`）：常駐 idle、中獎 win。
     *
     * 只有橫版有，直版是 null。跟 `FG` 同層、不受 `fgNode` 開關影響，MG 期間由
     * `CharacterPerformance.showCharacterForMode()` 隱藏。
     */
    @property({ type: sp.Skeleton, tooltip: '免費遊戲的人物 spine（fg_man）：idle／win，MG 時自動隱藏；直版留空' })
    fgManSkel: sp.Skeleton | null = null;

    /**
     * 免費遊戲轉輪兩側的霓虹框（`FG/skeleton`）：進 FG 循環 `fg_idle`、贏分 `fg_win`、加局 `fg_win_sc_plus`。
     *
     * 只有橫版有，直版是 null。節點在 `FG` 底下，跟著 `fgNode` 開關；播放時機見 `FgReelFx`。
     */
    @property({ type: sp.Skeleton, tooltip: '免費遊戲轉輪兩側霓虹框的 spine：fg_idle／fg_win／fg_win_sc_plus；直版留空' })
    fgReelFxSkel: sp.Skeleton | null = null;

    /**
     * MG↔FG 切換的全螢幕轉場 spine（`transition`）。
     *
     * 以前靠 `bg.parent.getChildByName('transition')` 找，但橫版的 `bg` 是空的，橫版的轉場從來沒播過；
     * 改成直接接。只有橫版接 `spine/transition.json`（`mg_to_fg`／`fg_to_mg`）；直版從 10-13 起就沒接，
     * 留空即不播，舊的 `spine/transition/transition.json` 於 2026-10-29 連同節點移除。
     */
    @property({ type: sp.Skeleton, tooltip: 'MG↔FG 全螢幕轉場的 spine（transition）；平常關著，切換時才開' })
    transitionSkel: sp.Skeleton | null = null;

    // === 階梯倍數飛向中獎累計條的特效（MultiplierFlyEffect）===
    // 全部可選：一個都不接也能跑，貼圖會自動取那一階自己亮著的圖。

    @property({ type: SpriteFrame, tooltip: '倍率飛行用的圖；留空則取階梯面板上點亮那一階自己的圖' })
    mulFlyFrame: SpriteFrame | null = null;

    @property({ type: [SpriteFrame], tooltip: '發射瞬間光暈 疊播圖片 全部拖進來即可' })
    mulFlyAuraFrames: SpriteFrame[] = [];

    @property({ type: [SpriteFrame], tooltip: '發射瞬間第二層光暈 疊播圖片 緊接在 aura 之後播' })
    mulFlyGlowFrames: SpriteFrame[] = [];

    @property({ type: [SpriteFrame], tooltip: '抵達終點閃光 疊播圖片 黑底圖需搭配 mulFlyRemoveBlackBgMaterial' })
    mulFlyFlareFrames: SpriteFrame[] = [];

    @property({ type: Material, tooltip: '閃光黑底圖去背用材質 套用在 mulFlyFlareFrames 全部圖片上 留空則照原本混合模式顯示' })
    mulFlyRemoveBlackBgMaterial: Material | null = null;

    @property({ type: RealCurve, tooltip: '倍率飛行：時間 0~1 對應沿起訖連線的移動進度 0~1' })
    mulFlyMoveCurve: RealCurve = (() => {
        const curve = new RealCurve();
        curve.assignSorted([
            [0, { value: 0 }],
            [1, { value: 1 }],
        ]);
        return curve;
    })();

    /*
     * 預設值抄自 1001 橫版 `Game.prefab` 上手畫的那條（`collectHeightCurve`）。
     *
     * 鍵值看起來很怪（首尾是 -1、峰值只有 0.65），但那是因為 `buildHeightEvaluator()` 會先扣掉首尾
     * 的直線趨勢、再除以取樣到的峰值——首尾畫在哪、峰值多大都不影響結果，只有「形狀」有意義。
     * 正規化後它是「一出發就把高度拉起來、中段幾乎平頂滑行、最後才收」：
     *
     *   t      0.1    0.2    0.3    0.5    0.7    0.9
     *   這條   0.438  0.726  0.895  1.000  0.884  0.413
     *   三角形 0.200  0.400  0.600  1.000  0.600  0.200   ← 原本的預設，尖角折返
     *
     * 切線權重沒帶（`tangentWeightMode` 是 None），所以 prefab 裡存的那幾個 weight 值不會被讀，
     * 這裡也不用寫。直版在 prefab 上有自己另一條，不是套這份。
     */
    @property({ type: RealCurve, tooltip: '倍率飛行：時間 0~1 對應垂直於連線的抬高比例，首尾值畫在哪都不影響落點' })
    mulFlyHeightCurve: RealCurve = (() => {
        const curve = new RealCurve();
        const cubic = RealInterpolationMode.CUBIC;
        curve.assignSorted([
            [0, { value: -1, interpolationMode: cubic, leftTangent: 8.6525974025974, rightTangent: 8.6525974025974 }],
            [0.5024390243902439, { value: 0.6515151515151515, interpolationMode: cubic, leftTangent: 0.09706439393939384, rightTangent: 0.09706439393939384 }],
            [1, { value: -1, interpolationMode: cubic, leftTangent: -7.9377104377104315, rightTangent: -7.9377104377104315 }],
        ]);
        return curve;
    })();

    @property({ tooltip: '倍率飛行：參考距離下的飛行時間（秒），實際時間會依起訖距離自動縮放，距離近的自動變快' })
    mulFlyDuration: number = 0.25;

    // 2026-11-05 移除抵達終點的落地 spine（win_bar）與贏分數字跟著它放大的演出：
    // mulFlyLandSpine／mulFlyLandAnim／mulFlyLandSkin／mulFlyNumBounce

    /**
     * 跟著倍率飛行一起走的 collect 特效（`TimesPanel/collect`）。
     *
     * 只有橫版有，直版是 null。執行期這顆節點會被搬進飛行特效的容器（見 `startCollect()` 的註解），
     * 所以它在 prefab 上掛在哪只影響編輯時好不好找，不影響演出結果。
     */
    /**
     * 倍率飛行要不要帶上 collect 特效。
     *
     * **2026-10-06 起預設關閉**：兩個飛行特效都改成完全照 1001 `CollectMulEffect` 的做法——飛行體
     * 是貼圖、尾巴是殘影，不播 spine。欄位與綁定都留著，要回頭試隨時打開。
     */
    @property({ tooltip: '倍率飛行：要不要播 collect 特效（關掉時 spine 欄位照樣留著綁定）' })
    mulFlyCollectEnabled: boolean = false;

    @property({ type: sp.Skeleton, tooltip: '倍率飛行：跟著一起飛的 collect spine（TimesPanel/collect）；留空則不播' })
    mulFlyCollectSpine: sp.Skeleton | null = null;

    /**
     * 發射光暈播完多久才真的出發（秒）。
     *
     * 參考影片 `win_bar.mp4` 實測：階梯那一格先閃白爆星約 0.05～0.1 秒，飛行體才進到盤面。
     * 蓄力感就來自這一下停頓，填 0 等於光暈與出發同時。
     */
    @property({ tooltip: '倍率飛行：發射光暈播完多久才出發（秒）；0 = 同時' })
    mulFlyLaunchDelay: number = 0.08;

    /**
     * 抵達終點後 collect 特效再留幾秒（秒）。
     *
     * 參考影片裡飛行體在抵達後約 0.04 秒就不見了，接著是贏分數字自己發光約 0.45 秒——那一段原本是
     * 落地 spine（`win_bar`，2026-11-05 移除）的工作，不是 collect 的。所以這裡是個小尾巴，不是整支動畫的長度。
     */
    @property({ tooltip: '倍率飛行：抵達後 collect 特效再留幾秒；0 = 抵達當下收掉' })
    mulFlyCollectTail: number = 0.1;

    // === 免費遊戲加局：從 Scatter 飛向 Spin 鈕的特效（AddNode / free_num）===

    /**
     * `AddNode`：加局特效在 Editor 裡擺位用的那顆。
     *
     * **執行期不播它。** 飛行體是程式照 1001 的做法 `new Node()` 生的貼圖，這顆只是美術對位置與
     * 大小的參考，進遊戲時會被關掉（它在 prefab 上是 active ＋ loop，不關會一直播）。
     */
    @property({ type: Node, tooltip: '加局特效的容器（AddNode）；留空則用 addFlySkel 自己的節點' })
    addFlyNode: Node | null = null;

    /**
     * `AddNode` 底下那顆 spine（資產是 `free_num`），同樣只在 Editor 裡擺位用。
     *
     * 接著它只是為了讓 {@link hideAddFly} 在 `addFlyNode` 留空時也關得掉。
     */
    @property({ type: sp.Skeleton, tooltip: '加局特效的 spine（AddNode 底下那顆，資產是 free_num）' })
    addFlySkel: sp.Skeleton | null = null;

    /**
     * 加局特效的參考飛行秒數。
     *
     * 跟倍率飛行同一套算法：這是參考距離（600px）下的秒數，實際時間依起訖距離縮放，近的自動變快。
     * 跟動畫長度（1.27 秒）各自獨立——飛完之後動畫還會在 Spin 鈕上演完才銷毀。
     */
    @property({ tooltip: '加局特效：參考距離下的飛行秒數，實際時間依距離縮放' })
    addFlyDuration: number = 0.5;

    /**
     * 多顆 Scatter 之間的發射間隔（秒）。
     *
     * 比照 1001 `CollectMulEffect` 的收球節奏（`DEFAULT_BALL_STAGGER` 0.15）：一顆一顆送出去，
     * 不是整批同時飛。
     */
    @property({ tooltip: '加局特效：每顆 Scatter 之間錯開幾秒發射' })
    addFlyStagger: number = 0.15;

    /**
     * 加局特效飛行體的貼圖。
     *
     * 留空時取該顆 Scatter 當下亮著的那張圖——跟倍率飛行留空時取階梯那一階的圖是同一套退路，
     * 所以不接任何素材也能跑。
     */
    @property({ type: SpriteFrame, tooltip: '加局特效：飛行體的貼圖；留空則取該顆 Scatter 自己的圖' })
    addFlyFrame: SpriteFrame | null = null;

    /*
     * 加局特效自己的起飛／抵達光效。
     *
     * 原本這三組與材質是跟倍率飛行共用 `mulFly*` 那一份的，2026-10-07 拆開——兩支飛行的飛行體
     * 來自不同的 spine（倍率是 collect、加局是 free_num），共用光效配不起來。**路徑曲線仍然共用
     * `mulFlyMoveCurve`／`mulFlyHeightCurve`**：那是軌跡形狀，兩支本來就該一致。
     *
     * 空陣列就是不播，沒有「退回去用倍率那組」的隱性退路——悄悄沿用別人的素材比沒有特效更難查。
     */
    @property({ type: [SpriteFrame], tooltip: '加局特效：發射瞬間光暈 疊播圖片 全部拖進來即可' })
    addFlyAuraFrames: SpriteFrame[] = [];

    @property({ type: [SpriteFrame], tooltip: '加局特效：發射瞬間第二層光暈 疊播圖片 緊接在 aura 之後播' })
    addFlyGlowFrames: SpriteFrame[] = [];

    @property({ type: [SpriteFrame], tooltip: '加局特效：抵達終點閃光 疊播圖片 黑底圖需搭配 addFlyRemoveBlackBgMaterial' })
    addFlyFlareFrames: SpriteFrame[] = [];

    @property({ type: Material, tooltip: '加局特效：閃光黑底圖去背用材質 套用在 addFlyFlareFrames 全部圖片上 留空則照原本混合模式顯示' })
    addFlyRemoveBlackBgMaterial: Material | null = null;
}
